function firebaseConfigFilled(){
  return !!(firebaseConfig.apiKey && firebaseConfig.projectId && firebaseConfig.appId && firebaseConfig.authDomain);
}

async function tryInitFirebase(){
  try{
    if(window.firebase && firebase.apps && firebase.apps.length){
      await firebase.app().delete();
    }
  }catch(e){}
  try{
    firebase.initializeApp(firebaseConfig);
    db = firebase.firestore();
    // Кэш на устройстве: чаты, сообщения, профили, истории открываются мгновенно и не скачиваются заново
    try{ db.settings({cacheSizeBytes: 150 * 1024 * 1024, merge: true}); }catch(e){}
    /* ROUND 86: кэш Firestore в IndexedDB выключен. Каждое пришедшее и отправленное сообщение сначала
       записывалось в базу браузера (вместе со старыми фото внутри сообщений — до мегабайта каждое), и только
       потом показывалось или уходило на сервер; при нескольких открытых вкладках связь с сервером держала
       одна «главная» вкладка, даже если она в фоне. Отсюда задержки сообщений, звонков и статуса.
       Работа без сети не пострадала: переписка, список чатов и вложения хранятся собственным кэшем (раунды 70–71). */
    if(localStorage.getItem('fsPersistence') === '1'){ try{ db.enablePersistence({synchronizeTabs: true}).catch(()=>{}); }catch(e){} }
    else if(!localStorage.getItem('fsCacheDropped')){
      try{ localStorage.setItem('fsCacheDropped', '1'); indexedDB.deleteDatabase('firestore/[DEFAULT]/' + firebaseConfig.projectId + '/main'); }catch(e){}
    }
    firebase.auth();
    return {ok:true};
  }catch(e){
    return {ok:false, error: (e && e.message) ? e.message : 'Не удалось подключиться к Firebase.'};
  }
}

function authErrorMessage(e){
  const code = (e && e.code) || '';
  const map = {
    'auth/email-already-in-use':'Пользователь с таким email уже зарегистрирован.',
    'auth/invalid-email':'Некорректный email.',
    'auth/weak-password':'Пароль должен быть не короче 6 символов.',
    'auth/user-not-found':'Пользователь с таким email не найден.',
    'auth/wrong-password':'Неверный пароль.',
    'auth/invalid-credential':'Неверный email или пароль.',
    'auth/too-many-requests':'Слишком много попыток. Попробуйте позже.',
    'auth/user-disabled':'Этот аккаунт отключён.',
    'auth/network-request-failed':'Нет связи с сервером. Проверьте подключение.',
    'auth/requires-recent-login':'Для этого действия нужно заново подтвердить пароль.',
  };
  return map[code] || (e && e.message) || 'Произошла ошибка.';
}

