function toast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toast._h);
  toast._h = setTimeout(()=>t.classList.remove('show'), 2800);
}
function normEmail(e){ return (e||'').trim().toLowerCase(); }
function normUser(u){ return (u||'').trim().toLowerCase(); }
function normPhone(p){
  let digits = (p||'').replace(/\D/g,'');
  if(digits.length === 11 && digits[0] === '8') digits = '7'+digits.slice(1);
  return digits;
}
function initials(name){ return (name||'?').trim().slice(0,2).toUpperCase(); }
function escapeHtml(s){ const d=document.createElement('div'); d.textContent=s; return d.innerHTML; }
function validEmail(e){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e); }
function validUsername(u){ return /^[a-zA-Z0-9_]{3,20}$/.test(u); }
async function sha256hex(str){
  const enc = new TextEncoder().encode(str);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}
function randomSalt(){
  const arr = new Uint8Array(16);
  crypto.getRandomValues(arr);
  return Array.from(arr).map(b=>b.toString(16).padStart(2,'0')).join('');
}
function fmtDate(ts){ return new Date(ts).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}); }
function fmtTime(ts){
  const d = new Date(ts); const now = new Date();
  if(d.toDateString() === now.toDateString()) return d.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
  return d.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit'});
}

