async function doRegister(data){
 try{
  const email = normEmail(data.email);
  const username = normUser(data.username);
  if(!validEmail(email)) return {error:'Введите корректный email.'};
  if(!validUsername(username)) return {error:'Ник: 3–20 символов, латиница, цифры, "_".'};
  if(data.password.length < 6) return {error:'Пароль должен быть не короче 6 символов.'};
  if(data.password !== data.password2) return {error:'Пароли не совпадают.'};
  if(!data.firstName || !data.firstName.trim()) return {error:'Укажите имя.'};
  if(!data.lastName || !data.lastName.trim()) return {error:'Укажите фамилию.'};
  if(!data.location || !data.location.trim()) return {error:'Укажите местоположение.'};
  const ageNum = parseInt(data.age, 10);
  if(!data.age || isNaN(ageNum)) return {error:'Укажите возраст.'};
  if(ageNum < 18) return {error:'Регистрация доступна только с 18 лет.'};
  if(ageNum > 120) return {error:'Проверьте указанный возраст.'};

  const unameSnap = await db.collection('usernames').doc(username).get();
  if(unameSnap.exists) return {error:'Такой ник уже занят.'};
  const emailSnap = await db.collection('emails').doc(email).get();
  if(emailSnap.exists) return {error:'Пользователь с таким email уже зарегистрирован.'};

  let cred;
  try{
    cred = await firebase.auth().createUserWithEmailAndPassword(email, data.password);
  }catch(e){
    return {error: authErrorMessage(e)};
  }
  const uid = cred.user.uid;
  const pinSalt = randomSalt();
  const pinHash = await sha256hex(pinSalt+':0000');
  const rec = {
    uid, email, username, createdAt: Date.now(), isAdmin:false, blocked:false,
    firstName: data.firstName.trim(), lastName: data.lastName.trim(), age: ageNum,
    location: data.location.trim(), phone: data.phone || '', socialLinks: data.socialLinks || [],
    emailVisible: false, showOnline: true, discoverable: true,
    pinHash, pinSalt, pinEnabled: false
  };
  try{
    await db.collection('users').doc(uid).set(rec);
    await db.collection('usernames').doc(username).set({uid});
    await db.collection('emails').doc(email).set({uid});
  }catch(e){
    return {error:'Аккаунт создан, но профиль не сохранён: '+e.message};
  }
  return {ok:true, user:{uid, email, username, isAdmin:false}};
 }catch(e){
  return {error: 'Ошибка сервера: ' + (e && e.message ? e.message : String(e))};
 }
}

async function doLogin(email, password){
 try{
  email = normEmail(email);
  let cred;
  try{
    cred = await firebase.auth().signInWithEmailAndPassword(email, password);
  }catch(e){
    return {error: authErrorMessage(e)};
  }
  const uid = cred.user.uid;
  const snap = await db.collection('users').doc(uid).get();
  if(!snap.exists){
    await firebase.auth().signOut();
    return {error:'Профиль не найден. Возможно, аккаунт был удалён администратором.'};
  }
  const rec = snap.data();
  if(rec.blocked){
    await firebase.auth().signOut();
    return {error:'Этот аккаунт заблокирован администратором.'};
  }
  const needsPin = !!rec.pinHash && rec.pinEnabled !== false;
  return {ok:true, user:{uid, email: rec.email, username: rec.username, isAdmin: !!rec.isAdmin}, needsPin};
 }catch(e){
  return {error: 'Ошибка сервера: ' + (e && e.message ? e.message : String(e))};
 }
}

async function verifyPin(uid, pin){
  try{
    const snap = await db.collection('users').doc(uid).get();
    if(!snap.exists) return {ok:false};
    const rec = snap.data();
    if(!rec.pinHash || rec.pinEnabled === false) return {ok:true, matched:'none'};
    const hash = await sha256hex(rec.pinSalt+':'+pin);
    if(hash === rec.pinHash) return {ok:true, matched:'normal'};
    if(rec.duressPinHash && rec.duressPinEnabled !== false){
      const dhash = await sha256hex(rec.duressPinSalt+':'+pin);
      if(dhash === rec.duressPinHash) return {ok:true, matched:'duress'};
    }
    return {ok:false};
  }catch(e){ return {ok:false}; }
}

async function wipeOwnAccountAndData(uid){
  try{
    const chatsSnap = await db.collection('chats').where('participants','array-contains',uid).get();
    for(const doc of chatsSnap.docs){
      await deleteChatCompletely(doc.id);
    }
  }catch(e){}
  let uname=null, email=null;
  try{
    const uSnap = await db.collection('users').doc(uid).get();
    if(uSnap.exists){ uname = uSnap.data().username; email = uSnap.data().email; }
  }catch(e){}
  try{ await db.collection('contacts').doc(uid).delete(); }catch(e){}
  try{ await db.collection('users').doc(uid).delete(); }catch(e){}
  if(uname){ try{ await db.collection('usernames').doc(uname).delete(); }catch(e){} }
  if(email){ try{ await db.collection('emails').doc(email).delete(); }catch(e){} }
  try{ if(firebase.auth().currentUser) await firebase.auth().currentUser.delete(); }catch(e){}
}

async function doSendReset(email){
  email = normEmail(email);
  if(!validEmail(email)) return {error:'Введите корректный email.'};
  try{ await firebase.auth().sendPasswordResetEmail(email); }
  catch(e){ }
  return {ok:true};
}

async function findUsers(query){
 try{
  const q = query.trim();
  if(!q) return {error:'Введите email, ник, имя, фамилию или телефон.'};
  const myUid = state.currentUser.uid;
  // Email — самый однозначный случай, точное совпадение через отдельную коллекцию-указатель
  if(q.includes('@')){
    const snap = await db.collection('emails').doc(normEmail(q)).get();
    if(!snap.exists) return {error:'Пользователь не найден.'};
    const uSnap = await db.collection('users').doc(snap.data().uid).get();
    if(!uSnap.exists) return {error:'Пользователь не найден.'};
    const found = uSnap.data();
    if(found.discoverable === false && found.uid !== myUid) return {error:'Пользователь не найден.'};
    return {ok:true, users: [found]};
  }
  // Дальше — не «сначала точное, а если не нашли, тогда остальное», а сразу оба пути одновременно:
  // точное совпадение по нику и поиск по имени/фамилии/телефону, с объединением результатов
  const byUid = new Map();
  try{
    const unameSnap = await db.collection('usernames').doc(normUser(q)).get();
    if(unameSnap.exists){
      const uSnap = await db.collection('users').doc(unameSnap.data().uid).get();
      if(uSnap.exists){
        const found = uSnap.data();
        if(!(found.discoverable === false && found.uid !== myUid)) byUid.set(found.uid, found);
      }
    }
  }catch(e){}
  try{
    const qLower = q.toLowerCase();
    const qPhone = normPhone(q);
    const snap = await db.collection('users').get();
    snap.docs.forEach(d=>{
      const u = d.data();
      if(u.discoverable === false && u.uid !== myUid) return;
      const nameMatch = (u.firstName && u.firstName.toLowerCase().includes(qLower)) || (u.lastName && u.lastName.toLowerCase().includes(qLower));
      const phoneMatch = qPhone.length >= 5 && u.phone && normPhone(u.phone).includes(qPhone);
      if(nameMatch || phoneMatch) byUid.set(u.uid, u);
    });
  }catch(e){}
  const users = Array.from(byUid.values());
  if(!users.length) return {error:'Пользователь не найден.'};
  return {ok:true, users: users.slice(0,20)};
 }catch(e){
  return {error: 'Ошибка сервера: ' + (e && e.message ? e.message : String(e))};
 }
}

