function chatIdFor(a,b){ return [a,b].sort().join('__'); }
async function pushNotification(toUid, type, data){
  if(!toUid || toUid === state.currentUser.uid) return;
  try{
    await db.collection('notifications').add({
      toUid, type, data: data||{}, timestamp: Date.now(), read: false
    });
  }catch(e){ console.error('pushNotification failed for type='+type, e); }
}
async function getMyFriendUids(){
  const myUid = state.currentUser.uid;
  try{
    const [sentSnap, gotSnap] = await Promise.all([
      db.collection('friendRequests').where('fromUid','==',myUid).get(),
      db.collection('friendRequests').where('toUid','==',myUid).get()
    ]);
    const uids = new Set();
    sentSnap.docs.forEach(d=>{ const r=d.data(); if(r.status==='accepted') uids.add(r.toUid); });
    gotSnap.docs.forEach(d=>{ const r=d.data(); if(r.status==='accepted') uids.add(r.fromUid); });
    return Array.from(uids);
  }catch(e){ return []; }
}
async function notifyFriendsOfProfileChange(type, extraData){
  const friendUids = await getMyFriendUids();
  if(!friendUids.length) return;
  const myName = await myDisplayName();
  friendUids.forEach(uid=> pushNotification(uid, type, Object.assign({fromUid: state.currentUser.uid, fromName: myName}, extraData||{})));
}

// ===== Центр уведомлений (колокольчик) =====
let notifListenerUnsub = null;
let allNotifications = [];
let notifFirstSnapshot = true;
function startNotificationsListener(){
  if(notifListenerUnsub) notifListenerUnsub();
  notifFirstSnapshot = true;
  notifListenerUnsub = db.collection('notifications')
    .where('toUid','==',state.currentUser.uid)
    .orderBy('timestamp','desc')
    .onSnapshot(snap=>{
      const isFirst = notifFirstSnapshot;
      notifFirstSnapshot = false;
      let hasNewUnread = false;
      if(!isFirst){
        snap.docChanges().forEach(ch=>{
          if(ch.type === 'added') hasNewUnread = true;
        });
      }
      allNotifications = snap.docs.map(d=>Object.assign({id:d.id}, d.data()));
      updateNotifBadge();
      if(document.getElementById('notif-panel-overlay').style.display !== 'none'){
        renderNotifPanel();
      }
      if(hasNewUnread && state.notifPrefs.notificationSoundEnabled !== false && state.notifPrefs.bellSoundEnabled !== false){
        playNotificationSound(state.notifPrefs.notificationMelody, state.notifPrefs.notificationVolume);
      }
    }, err=>{ console.error('notifications listener failed', err); });
}
function updateNotifBadge(){
  const badge = document.getElementById('notif-bell-badge');
  const count = allNotifications.filter(n=>!n.read).length;
  if(count > 0){ badge.textContent = count > 99 ? '99+' : String(count); badge.style.display = 'flex'; }
  else{ badge.style.display = 'none'; }
}
function notifTypeInfo(n){
  const name = escapeHtml((n.data && n.data.fromName) || 'Пользователь');
  const map = {
    friend_request: {icon:'👤', text: `${name} хочет добавить вас в друзья`},
    friend_accepted: {icon:'✅', text: `${name} принял(а) вашу заявку в друзья`},
    profile_like: {icon:'❤️', text: `${name} отметил(а) симпатию к вашему профилю`},
    photo_like: {icon:'📸', text: `${name} поставил(а) лайк вашему фото`},
    community_invite: {icon:'👥', text: `${name} пригласил(а) вас в сообщество «${escapeHtml((n.data&&n.data.communityName)||'')}»`},
    missed_call: {icon:'📞', text: `Пропущенный ${(n.data&&n.data.callType==='video')?'видео':'аудио'}звонок от ${name}`},
    friend_photo_change: {icon:'🖼️', text: `${name} обновил(а) фото профиля`},
    friend_status_change: {icon:'💬', text: `${name} изменил(а) статус: «${escapeHtml((n.data&&n.data.statusText)||'')}»`},
    mutual_like: {icon:'💞', text: `Взаимная симпатия с ${name}!`},
  };
  return map[n.type] || {icon:'🔔', text:'Новое уведомление'};
}
function renderNotifPanel(){
  const list = document.getElementById('notif-panel-list');
  if(!allNotifications.length){
    list.innerHTML = `<div class="empty-list">Уведомлений пока нет.</div>`;
    return;
  }
  list.innerHTML = allNotifications.map(n=>{
    const info = notifTypeInfo(n);
    const fromUid = n.data && n.data.fromUid;
    const photoUrl = n.data && n.data.photoUrl;
    const avatarHtml = photoUrl
      ? `<img src="${escapeHtml(photoUrl)}" class="avatar" style="object-fit:cover;">`
      : (fromUid ? `<div class="avatar" data-avatar-uid="${escapeHtml(fromUid)}">${info.icon}</div>` : `<div class="avatar">${info.icon}</div>`);
    return `<div class="notif-row ${n.read?'':'unread'}" data-notif-id="${escapeHtml(n.id)}" ${fromUid?`data-notif-open-uid="${escapeHtml(fromUid)}" style="cursor:pointer;"`:''}>
      ${avatarHtml}
      <div class="notif-row-body">
        <div class="notif-row-text">${info.text}</div>
        <div class="notif-row-time">${fmtTime(n.timestamp)}</div>
      </div>
      <button type="button" class="notif-row-del" data-notif-del="${escapeHtml(n.id)}" title="Удалить"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>
    </div>`;
  }).join('');
  list.querySelectorAll('[data-notif-open-uid]').forEach(row=>{
    row.addEventListener('click', (ev)=>{
      if(ev.target.closest('[data-notif-del]')) return;
      openUserInfo(row.getAttribute('data-notif-open-uid'));
    });
  });
  const fromUids = allNotifications.map(n=>n.data && n.data.fromUid).filter(Boolean);
  if(fromUids.length) enrichAvatars(list, fromUids);
  list.querySelectorAll('[data-notif-del]').forEach(btn=>{
    btn.onclick = async (ev)=>{
      ev.stopPropagation();
      const id = btn.getAttribute('data-notif-del');
      try{ await db.collection('notifications').doc(id).delete(); }catch(e){ toast('Не удалось удалить'); }
    };
  });
}
async function markAllNotificationsRead(){
  const unread = allNotifications.filter(n=>!n.read);
  if(!unread.length) return;
  try{
    const batch = db.batch();
    unread.forEach(n=> batch.update(db.collection('notifications').doc(n.id), {read:true}));
    await batch.commit();
  }catch(e){}
}
function openNotifPanel(){
  document.getElementById('notif-panel-overlay').style.display = 'block';
  updateNotifSoundBtn();
  renderNotifPanel();
  markAllNotificationsRead();
}
function closeNotifPanel(){
  document.getElementById('notif-panel-overlay').style.display = 'none';
}
function updateNotifSoundBtn(){
  const btn = document.getElementById('notif-sound-toggle');
  const on = state.notifPrefs.bellSoundEnabled !== false;
  btn.innerHTML = on
    ? '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polygon points="4 9 8 9 12 5 12 19 8 15 4 15 4 9"/><path d="M16.5 8.5a5 5 0 0 1 0 7"/></svg>'
    : '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polygon points="4 9 8 9 12 5 12 19 8 15 4 15 4 9"/><line x1="17" y1="9" x2="22" y2="14"/><line x1="22" y1="9" x2="17" y2="14"/></svg>';
  btn.title = on ? 'Звук уведомлений включён' : 'Звук уведомлений выключен';
}
document.getElementById('notif-bell-btn').onclick = openNotifPanel;
document.getElementById('notif-panel-close').onclick = closeNotifPanel;
document.getElementById('notif-panel-overlay').addEventListener('click', (ev)=>{
  if(ev.target.id === 'notif-panel-overlay') closeNotifPanel();
});
document.getElementById('notif-clear-all-btn').onclick = ()=>{
  if(!allNotifications.length) return;
  openDeleteActionSheet(async ()=>{
    try{
      const batch = db.batch();
      allNotifications.forEach(n=> batch.delete(db.collection('notifications').doc(n.id)));
      await batch.commit();
    }catch(e){ toast('Не удалось очистить'); }
  });
};
document.getElementById('notif-sound-toggle').onclick = async ()=>{
  const newVal = state.notifPrefs.bellSoundEnabled === false;
  state.notifPrefs.bellSoundEnabled = newVal;
  updateNotifSoundBtn();
  try{ await db.collection('users').doc(state.currentUser.uid).update({bellSoundEnabled: newVal}); }
  catch(e){ toast('Не удалось сохранить'); }
};
function attachCityAutocomplete(inputId, suggestionsId, onSelect){
  const input = document.getElementById(inputId);
  const box = document.getElementById(suggestionsId);
  if(!input || !box) return;
  function renderMatches(matches){
    if(!matches.length){
      box.innerHTML = `<div class="city-suggestion-empty">Город не найден в списке</div>`;
      box.classList.add('open');
      return;
    }
    box.innerHTML = matches.map(c=>`<div class="city-suggestion-item" data-city="${escapeHtml(c)}">${escapeHtml(c)}</div>`).join('');
    box.classList.add('open');
    box.querySelectorAll('.city-suggestion-item').forEach(item=>{
      item.onmousedown = (ev)=>{
        ev.preventDefault();
        const city = item.getAttribute('data-city');
        input.value = city;
        box.classList.remove('open');
        if(onSelect) onSelect(city);
      };
    });
  }
  function showSuggestions(){
    const q = input.value.trim().toLowerCase();
    if(!q){ box.classList.remove('open'); box.innerHTML=''; return; }
    const starts = RU_CITIES.filter(c=>c.toLowerCase().startsWith(q));
    const matches = starts.length ? starts.slice(0,8) : RU_CITIES.filter(c=>c.toLowerCase().includes(q)).slice(0,8);
    renderMatches(matches);
  }
  input.addEventListener('input', showSuggestions);
  input.addEventListener('focus', showSuggestions);
  input.addEventListener('blur', ()=>{ setTimeout(()=>box.classList.remove('open'), 150); });
}

function callDisplayInfo(entry, myUid){
  const isOutgoing = entry.callerUid === myUid;
  const otherUid = (entry.participants||[]).find(p=>p!==myUid) || myUid;
  const otherName = (entry.names && entry.names[otherUid]) || otherUid;
  let statusText, isMissed = false;
  if(entry.outcome === 'ended'){
    const d = entry.duration||0;
    statusText = (isOutgoing?'Исходящий':'Входящий')+' · '+Math.floor(d/60)+':'+String(d%60).padStart(2,'0')+' мин';
  }else if(entry.outcome === 'cancelled'){
    statusText = 'Отменённый';
  }else if(entry.outcome === 'declined'){
    statusText = isOutgoing ? 'Отклонён' : 'Вы отклонили';
  }else{
    statusText = isOutgoing ? 'Нет ответа' : 'Пропущенный';
    isMissed = !isOutgoing;
  }
  return {isOutgoing, otherUid, otherName, statusText, isMissed};
}
function callTypeIconSvg(isVideo){
  return isVideo
    ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="6.5" width="13" height="11" rx="2.5"/><path d="M15.5 10.8l5-3v8.4l-5-3z"/></svg>'
    : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4.5 4h3.5l1.5 4.5-2.2 1.8a13 13 0 0 0 6.4 6.4l1.8-2.2 4.5 1.5v3.5a1.5 1.5 0 0 1-1.6 1.5A17.5 17.5 0 0 1 3 5.6 1.5 1.5 0 0 1 4.5 4z"/></svg>';
}
function listenCallLogs(){
  if(state.unsubCallLogs) state.unsubCallLogs();
  state.unsubCallLogs = db.collection('callLogs').where('participants','array-contains', state.currentUser.uid)
    .orderBy('timestamp','desc').limit(40).onSnapshot(snap=>{
      const myUid = state.currentUser.uid;
      state.callLogs = snap.docs.map(d=>({id:d.id, ...d.data()})).filter(c=>!(c.hiddenFor||[]).includes(myUid));
      renderCallsList();
    }, err=>{
      const list = document.getElementById('calls-list');
      if(list) list.innerHTML = `<div class="error-box">Не удалось загрузить: ${escapeHtml(err.message)}</div>`;
    });
}
function renderCallsList(){
  updateCallsBadge();
  const list = document.getElementById('calls-list');
  if(!list) return;
  const myUid = state.currentUser.uid;
  const searchEl = document.getElementById('calls-search-input');
  const q = searchEl ? searchEl.value.trim().toLowerCase() : '';

  // Активный звонок, свёрнутый кнопкой «Свернуть» — показываем первой строкой,
  // независимо от того, есть ли вообще история звонков. Набор кнопок разный: для ещё
  // не принятого входящего — ответить/отклонить, для уже идущего разговора — развернуть/отключить.
  let incomingRowHtml = '';
  if((state.activeCallState === 'incoming' || state.activeCallState === 'connected' || state.activeCallState === 'dialing') && state.incomingCallDismissed){
    const isVideo = callType === 'video';
    const isIncoming = state.activeCallState === 'incoming';
    let statusLabel;
    if(isIncoming) statusLabel = isVideo ? 'Входящий видеозвонок…' : 'Входящий звонок…';
    else if(state.activeCallState === 'dialing') statusLabel = 'Вызов…';
    else statusLabel = 'Разговор идёт…';
    const actionsHtml = isIncoming
      ? `<button class="calls-tab-round-btn" style="background:var(--danger);" id="calls-tab-incoming-decline" title="Отклонить"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 9c-1.6 0-3.15.25-4.6.72v3.1c0 .39-.23.74-.56.9-.98.49-1.87 1.12-2.66 1.85-.18.18-.43.28-.7.28-.28 0-.53-.11-.71-.29L.29 13.08a.996.996 0 0 1-.29-.7c0-.28.11-.53.29-.71C3.34 8.78 7.46 7 12 7s8.66 1.78 11.71 4.67c.18.18.29.43.29.71 0 .28-.11.53-.29.71l-2.48 2.48c-.18.18-.43.29-.71.29-.27 0-.52-.1-.7-.28-.79-.73-1.68-1.36-2.66-1.85-.33-.16-.56-.51-.56-.9v-3.1C15.15 9.25 13.6 9 12 9z"/></svg></button>
         <button class="calls-tab-round-btn" style="background:var(--ok);" id="calls-tab-incoming-accept" title="Ответить">${callTypeIconSvg(isVideo)}</button>`
      : `<button class="calls-tab-round-btn" style="background:var(--danger);" id="calls-tab-incoming-hangup" title="Отключить"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 9c-1.6 0-3.15.25-4.6.72v3.1c0 .39-.23.74-.56.9-.98.49-1.87 1.12-2.66 1.85-.18.18-.43.28-.7.28-.28 0-.53-.11-.71-.29L.29 13.08a.996.996 0 0 1-.29-.7c0-.28.11-.53.29-.71C3.34 8.78 7.46 7 12 7s8.66 1.78 11.71 4.67c.18.18.29.43.29.71 0 .28-.11.53-.29.71l-2.48 2.48c-.18.18-.43.29-.71.29-.27 0-.52-.1-.7-.28-.79-.73-1.68-1.36-2.66-1.85-.33-.16-.56-.51-.56-.9v-3.1C15.15 9.25 13.6 9 12 9z"/></svg></button>
         <button class="calls-tab-round-btn" style="background:#2E7DF7;" id="calls-tab-incoming-expand" title="Развернуть"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"/><polyline points="6 11 12 5 18 11"/></svg></button>`;
    incomingRowHtml = `<div class="chat-item" id="calls-tab-incoming-row" style="cursor:default;background:var(--bubble-in);">
      <div class="avatar" id="calls-tab-incoming-avatar">${initials(callDisplayName || state.activeCallOtherName || '?')}</div>
      <div class="info"><div class="name">${escapeHtml(callDisplayName || state.activeCallOtherName || '')}</div><div class="preview" style="color:var(--accent);"><span class="calls-tab-type-icon">${callTypeIconSvg(isVideo)}</span><span style="margin-left:5px;">${statusLabel}</span></div></div>
      <div style="display:flex;gap:6px;">
        ${actionsHtml}
      </div>
    </div>`;
  }

  const allEntries = state.callLogs || [];
  const entries = q ? allEntries.filter(entry=>callDisplayInfo(entry, myUid).otherName.toLowerCase().includes(q)) : allEntries;
  if(!allEntries.length){
    list.innerHTML = incomingRowHtml + `<div class="empty-list">Звонков пока не было.</div>`;
    wireIncomingCallsTabRow();
    return;
  }
  if(!entries.length){
    list.innerHTML = incomingRowHtml + `<div class="empty-list">Ничего не найдено.</div>`;
    wireIncomingCallsTabRow();
    return;
  }
  list.innerHTML = incomingRowHtml + entries.map(entry=>{
    const info = callDisplayInfo(entry, myUid);
    const isVideo = entry.callType === 'video';
    const typeIcon = callTypeIconSvg(isVideo);
    const dirArrow = info.statusText.startsWith('Исходящий') ? '↗ ' : info.statusText.startsWith('Входящий') ? '↙ ' : '';
    const color = info.isMissed ? 'var(--danger)' : 'var(--text-muted)';
    const checked = state.selectedCallLogs.has(entry.id);
    const dot = state.callLogSelectMode ? `<div class="select-dot ${checked?'checked':''}">${checked?'✓':''}</div>` : '';
    return `<div class="chat-item call-log-row" data-uid="${escapeHtml(info.otherUid)}" data-name="${escapeHtml(info.otherName)}" data-calltype="${entry.callType}" data-log-id="${escapeHtml(entry.id)}">
      ${dot}
      <div class="avatar" data-avatar-uid="${escapeHtml(info.otherUid)}" ${state.callLogSelectMode?'':'data-info-btn="1"'}>${initials(info.otherName)}</div>
      <div class="info">
        <div class="top-row"><div class="name" style="${info.isMissed?'color:var(--danger);':''}"><span data-name-uid="${escapeHtml(info.otherUid)}">${escapeHtml(info.otherName)}</span></div><div class="time">${fmtTime(entry.timestamp)}</div></div>
        <div class="preview" style="color:${color};"><span class="preview-icon" style="color:inherit;">${typeIcon}</span>${dirArrow}${escapeHtml(info.statusText)}</div>
      </div>
      ${state.callLogSelectMode ? '' : `<div style="display:flex;gap:6px;" onclick="event.stopPropagation();">
        <button class="calls-tab-round-btn" style="background:var(--bubble-in);color:var(--accent);" data-callback-audio="1" title="Аудиозвонок"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4.5 4h3.5l1.5 4.5-2.2 1.8a13 13 0 0 0 6.4 6.4l1.8-2.2 4.5 1.5v3.5a1.5 1.5 0 0 1-1.6 1.5A17.5 17.5 0 0 1 3 5.6 1.5 1.5 0 0 1 4.5 4z"/></svg></button>
        <button class="calls-tab-round-btn" style="background:var(--bubble-in);color:var(--accent);" data-callback-video="1" title="Видеозвонок"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="6.5" width="13" height="11" rx="2.5"/><path d="M15.5 10.8l5-3v8.4l-5-3z"/></svg></button>
      </div>`}
    </div>`;
  }).join('');
  enrichAvatars(list, entries.map(e=>callDisplayInfo(e, myUid).otherUid));
  enrichDisplayNames(list, entries.map(e=>callDisplayInfo(e, myUid).otherUid));
  list.querySelectorAll('[data-callback-audio]').forEach(btn=>{
    btn.onclick = ()=>{
      const row = btn.closest('.call-log-row');
      callBackFromLog(row.getAttribute('data-uid'), row.getAttribute('data-name'), 'audio');
    };
  });
  list.querySelectorAll('[data-callback-video]').forEach(btn=>{
    btn.onclick = ()=>{
      const row = btn.closest('.call-log-row');
      callBackFromLog(row.getAttribute('data-uid'), row.getAttribute('data-name'), 'video');
    };
  });
  list.querySelectorAll('.avatar[data-info-btn]').forEach(el=>{
    el.style.cursor = 'pointer';
    el.addEventListener('click', (ev)=>{ ev.stopPropagation(); openUserInfo(el.getAttribute('data-avatar-uid')); });
  });
  list.querySelectorAll('.call-log-row').forEach(el=>{
    el.addEventListener('click', ()=>{
      if(state.callLogSelectMode){
        const id = el.getAttribute('data-log-id');
        if(state.selectedCallLogs.has(id)) state.selectedCallLogs.delete(id); else state.selectedCallLogs.add(id);
        renderCallsList();
        return;
      }
      callBackFromLog(el.getAttribute('data-uid'), el.getAttribute('data-name'), el.getAttribute('data-calltype'));
    });
    if(!state.callLogSelectMode){
      false && attachLongPress(el, ()=>{
        openDeleteActionSheet(async ()=>{
          state.selectedCallLogs = new Set([el.getAttribute('data-log-id')]);
          await deleteSelectedCallLogs();
        });
      });
    }
  });
  if(state.callLogSelectMode){
    document.getElementById('call-log-select-count').textContent = 'Выбрано: '+state.selectedCallLogs.size;
  }
  wireIncomingCallsTabRow();
}
function wireIncomingCallsTabRow(){
  const row = document.getElementById('calls-tab-incoming-row');
  if(!row) return;
  const avatarEl = document.getElementById('calls-tab-incoming-avatar');
  if(avatarEl && state.activeCallOtherUid){
    getUserProfile(state.activeCallOtherUid).then(p=>{ if(p && p.avatarUrl) applyAvatarImg(avatarEl, p.avatarUrl); });
  }
  const acceptBtn = document.getElementById('calls-tab-incoming-accept');
  const declineBtn = document.getElementById('calls-tab-incoming-decline');
  if(acceptBtn) acceptBtn.onclick = ()=>{ state.incomingCallDismissed = false; expandCall(); acceptIncomingCall(); };
  if(declineBtn) declineBtn.onclick = ()=> declineIncomingCall();
  const expandBtn = document.getElementById('calls-tab-incoming-expand');
  const hangupBtn = document.getElementById('calls-tab-incoming-hangup');
  if(expandBtn) expandBtn.onclick = ()=>{ state.incomingCallDismissed = false; expandCall(); };
  if(hangupBtn) hangupBtn.onclick = ()=> endCall('ended');
}
function enterCallLogSelectMode(){
  state.callLogSelectMode = true; state.selectedCallLogs = new Set();
  document.getElementById('calls-header-normal').style.display = 'none';
  document.getElementById('calls-header-select').style.display = 'flex';
  renderCallsList();
}
function exitCallLogSelectMode(){
  state.callLogSelectMode = false; state.selectedCallLogs = new Set();
  document.getElementById('calls-header-normal').style.display = 'flex';
  document.getElementById('calls-header-select').style.display = 'none';
  renderCallsList();
}
document.getElementById('call-log-select-toggle').onclick = enterCallLogSelectMode;
document.getElementById('call-log-select-cancel').onclick = exitCallLogSelectMode;
document.getElementById('call-log-select-all').onclick = ()=>{
  const searchEl = document.getElementById('calls-search-input');
  const q = searchEl ? searchEl.value.trim().toLowerCase() : '';
  const myUid = state.currentUser.uid;
  const visible = q ? (state.callLogs||[]).filter(e=>callDisplayInfo(e, myUid).otherName.toLowerCase().includes(q)) : (state.callLogs||[]);
  visible.forEach(e=>state.selectedCallLogs.add(e.id));
  renderCallsList();
};
async function deleteSelectedCallLogs(){
  if(!state.selectedCallLogs.size) return;
  if(!await uiConfirm('Удалить выбранные записи о звонках ('+state.selectedCallLogs.size+')? Удалятся полностью — и у вас, и у собеседника.')) return;
  const ids = Array.from(state.selectedCallLogs);
  for(const id of ids){
    try{ await db.collection('callLogs').doc(id).delete(); }
    catch(e){}
  }
  toast('Удалено: '+ids.length);
  exitCallLogSelectMode();
}
document.getElementById('call-log-select-delete').onclick = deleteSelectedCallLogs;
document.getElementById('calls-search-input').addEventListener('input', renderCallsList);
async function createCommunity(name){
  const myUid = state.currentUser.uid;
  const ref = db.collection('communities').doc();
  const id = ref.id;
  await ref.set({
    id, name, creatorUid: myUid, members: [myUid], admins: [myUid], createdAt: Date.now()
  });
  await db.collection('chats').doc(id).set({
    id, participants: [myUid],
    usernames: {[myUid]: state.currentUser.username},
    emails: {[myUid]: state.currentUser.email},
    isCommunity: true, communityName: name,
    createdAt: Date.now(), lastMessage: '', lastType: 'text',
    lastTimestamp: Date.now(), lastFrom: '', messageCount: 0, hiddenFor: []
  });
  return id;
}
async function inviteToCommunity(communityId, communityName, targetUid){
  const myUid = state.currentUser.uid;
  const inviteId = communityId+'__'+targetUid;
  try{
    const displayName = await myDisplayName();
    await db.collection('communityInvites').doc(inviteId).set({
      communityId, communityName, fromUid: myUid, fromName: displayName,
      toUid: targetUid, status: 'pending', timestamp: Date.now()
    });
    pushNotification(targetUid, 'community_invite', {communityId, communityName, fromUid: myUid, fromName: displayName});
    toast('Приглашение отправлено');
    return true;
  }catch(e){ console.error('inviteToCommunity failed', e); toast('Не удалось пригласить: '+(e&&e.message?e.message:'см. консоль')); return false; }
}
async function acceptCommunityInvite(inviteId, communityId){
  const myUid = state.currentUser.uid;
  try{
    await db.collection('communities').doc(communityId).update({members: firebase.firestore.FieldValue.arrayUnion(myUid)});
    await db.collection('chats').doc(communityId).update({
      participants: firebase.firestore.FieldValue.arrayUnion(myUid),
      ['usernames.'+myUid]: state.currentUser.username,
      ['emails.'+myUid]: state.currentUser.email
    });
    await db.collection('communityInvites').doc(inviteId).delete();
    toast('Вы вступили в сообщество');
    return true;
  }catch(e){ console.error('acceptCommunityInvite failed', e); toast('Не удалось принять приглашение: '+(e&&e.message?e.message:'см. консоль')); return false; }
}
async function declineCommunityInvite(inviteId){
  try{ await db.collection('communityInvites').doc(inviteId).delete(); return true; }
  catch(e){ console.error('declineCommunityInvite failed', e); toast('Не удалось отклонить: '+(e&&e.message?e.message:'см. консоль')); return false; }
}
