async function restoreFromBlacklist(uid){
  const c = state.blacklist.find(x=>x.uid===uid);
  if(!c) return;
  if(!await uiConfirm('Восстановить '+c.username+' из чёрного списка? Он снова появится в контактах.')) return;
  try{
    await db.collection('contacts').doc(state.currentUser.uid).set({
      blacklist: firebase.firestore.FieldValue.arrayRemove(c),
      list: firebase.firestore.FieldValue.arrayUnion({uid:c.uid, username:c.username, email:c.email})
    }, {merge:true});
    toast('Восстановлено из чёрного списка');
  }catch(e){ toast('Не удалось восстановить'); }
}

async function renderPresenceLists(){
  const visible = state.contacts;
  const results = await Promise.all(visible.map(async c=>{
    const p = await getUserProfile(c.uid);
    return {c, online: isUserOnline(p)};
  }));
  const onlineList = results.filter(r=>r.online).map(r=>r.c);
  const offlineList = results.filter(r=>!r.online).map(r=>r.c);
  renderPresenceSubList('online-list', onlineList, 'Никого нет в сети.');
  renderPresenceSubList('offline-list', offlineList, 'Все контакты сейчас в сети.');
  const countOnlineEl = document.getElementById('subtab-count-online');
  const countOfflineEl = document.getElementById('subtab-count-offline');
  if(countOnlineEl) countOnlineEl.textContent = onlineList.length ? `(${onlineList.length})` : '';
  if(countOfflineEl) countOfflineEl.textContent = offlineList.length ? `(${offlineList.length})` : '';
}
