async function renderDiscoveryTab(){
  const myUid = state.currentUser.uid;
  document.getElementById('discovery-online-list').innerHTML = `<div class="search-note">Загрузка…</div>`;
  let allUsers = [];
  try{
    /* ROUND 85: только нужные поля и отдельным HTTP-запросом — раньше качались все профили целиком */
    let rows = null;
    try{ rows = await fsRestQuery('users', ['uid','username','firstName','lastName','age','location','relationshipStatus','lastActive','showOnline','visibleInDiscovery','phone','nameStyle']); }catch(e){}
    if(!rows){ const snap = await db.collection('users').get(); rows = snap.docs.map(d=> d.data()); }
    allUsers = rows.filter(u=>u.uid && u.uid!==myUid && u.visibleInDiscovery!==false);
  }catch(e){
    document.getElementById('discovery-online-list').innerHTML = `<div class="error-box">Не удалось загрузить список.</div>`;
    return;
  }
  state.discoveryUsers = allUsers;
  renderDiscoveryLists();
}
function applyDiscoveryFilters(users){
  const q = document.getElementById('discovery-search-input').value.trim().toLowerCase();
  const qPhone = normPhone(q);
  const loc = document.getElementById('discovery-filter-location').value;
  const ageRange = document.getElementById('discovery-filter-age').value;
  const status = document.getElementById('discovery-filter-status').value;
  const blacklistedUids = new Set((state.blacklist||[]).map(c=>c.uid));
  return users.filter(u=>{
    if(blacklistedUids.has(u.uid)) return false;
    if(q){
      const nickMatch = (u.username||'').toLowerCase().includes(q);
      const nameMatch = (u.firstName||'').toLowerCase().includes(q) || (u.lastName||'').toLowerCase().includes(q);
      const phoneMatch = qPhone.length >= 5 && u.phone && normPhone(u.phone).includes(qPhone);
      if(!nickMatch && !nameMatch && !phoneMatch) return false;
    }
    if(loc && u.location !== loc) return false;
    if(status && u.relationshipStatus !== status) return false;
    if(ageRange){
      const parts = ageRange.split('-').map(Number);
      if(!u.age || u.age < parts[0] || u.age > parts[1]) return false;
    }
    return true;
  });
}
const DISCOVERY_RS_LABELS = {searching:'В активном поиске', relationship:'В отношениях', married:'Замужем / Женат'};
function renderDiscoveryLists(){
  const users = applyDiscoveryFilters(state.discoveryUsers || []);
  const online = users.filter(u=>isUserOnline(u));
  const offline = users.filter(u=>!isUserOnline(u));
  renderDiscoveryUserList('discovery-all-list', online.concat(offline), 'Никого не найдено по заданным условиям.');
  renderDiscoveryUserList('discovery-online-list', online, 'Никого не найдено по заданным условиям.');
  renderDiscoveryUserList('discovery-offline-list', offline, 'Никого не найдено по заданным условиям.');
  const countAllEl = document.getElementById('dsubtab-count-all');
  const countOnlineEl = document.getElementById('dsubtab-count-online');
  const countOfflineEl = document.getElementById('dsubtab-count-offline');
  if(countAllEl) countAllEl.textContent = users.length ? `(${users.length})` : '';
  if(countOnlineEl) countOnlineEl.textContent = online.length ? `(${online.length})` : '';
  if(countOfflineEl) countOfflineEl.textContent = offline.length ? `(${offline.length})` : '';
}
function renderDiscoveryUserList(containerId, users, emptyText){
  const el = document.getElementById(containerId);
  if(!el) return;
  if(!users.length){ el.innerHTML = `<div class="empty-list">${escapeHtml(emptyText)}</div>`; return; }
  el.innerHTML = users.map(u=>{
    const bits = [];
    if(u.age) bits.push(u.age+' лет');
    if(u.location) bits.push(escapeHtml(u.location));
    if(u.relationshipStatus) bits.push(DISCOVERY_RS_LABELS[u.relationshipStatus]||'');
    const shown = realNameOf(u) || u.username;
    return `<div class="chat-item" data-uid="${escapeHtml(u.uid)}" style="cursor:pointer;">
      <div class="avatar" data-avatar-uid="${escapeHtml(u.uid)}">${initials(shown)}</div>
      <div class="info"><div class="name">${escapeHtml(shown)}</div><div class="preview">${bits.join(' · ') || '—'}</div></div>
    </div>`;
  }).join('');
  enrichAvatars(el, users.map(u=>u.uid));
  el.querySelectorAll('.chat-item[data-uid]').forEach(row=>{
    row.onclick = ()=> openUserInfo(row.getAttribute('data-uid'));
  });
}
