document.getElementById('discovery-filter-status').addEventListener('change', renderDiscoveryLists);
async function renderReactionsSubtab(){
  const el = document.getElementById('discovery-reactions-list');
  el.innerHTML = `<div class="search-note">Загрузка…</div>`;
  const myUid = state.currentUser.uid;
  let likedMe = [], iLiked = [], photoLikedMe = [], myPhotos = [];
  try{
    /* ROUND 92: три запроса разом, а не по очереди */
    const [gotSnap, sentSnap, photoSnap] = await Promise.all([
      db.collection('profileLikes').where('toUid','==',myUid).get(),
      db.collection('profileLikes').where('fromUid','==',myUid).get(),
      db.collection('photoLikes').where('ownerUid','==',myUid).get()]);
    likedMe = gotSnap.docs.map(d=>({id:d.id, ...d.data()}));
    iLiked = sentSnap.docs.map(d=>({id:d.id, ...d.data()}));
    photoLikedMe = photoSnap.docs.map(d=>({id:d.id, ...d.data()})).sort((a,b)=>b.timestamp-a.timestamp);
    const myProfile = await getUserProfile(myUid);          // ROUND 92: свой профиль — из памяти, не качаем заново каждый раз
    myPhotos = (myProfile && myProfile.photos) || [];
  }catch(e){
    el.innerHTML = `<div class="error-box">Не удалось загрузить.</div>`;
    return;
  }
  const iLikedUids = new Set(iLiked.map(l=>l.toUid));
  let mutual = likedMe.filter(l=>iLikedUids.has(l.fromUid)).sort((a,b)=>b.timestamp-a.timestamp);
  let onlyLikedMe = likedMe.filter(l=>!iLikedUids.has(l.fromUid)).sort((a,b)=>b.timestamp-a.timestamp);
  let photoLiked = photoLikedMe;
  if(!mutual.length && !onlyLikedMe.length && !photoLiked.length){
    el.innerHTML = `<div class="empty-list">Пока никто не поставил вам лайк.</div>`;
    document.getElementById('reactions-clear-all-btn').style.display = 'none';
    return;
  }
  // Общий лимит в 40 строк по всем трём категориям вместе — сначала объединяем с меткой типа,
  // сортируем по свежести и берём первые 40, затем снова раскладываем по разделам.
  const REACTIONS_LIMIT = 40;
  const combined = [
    ...mutual.map(l=>({...l, _kind:'mutual'})),
    ...onlyLikedMe.map(l=>({...l, _kind:'profile'})),
    ...photoLiked.map(l=>({...l, _kind:'photo'})),
  ].sort((a,b)=>b.timestamp-a.timestamp).slice(0, REACTIONS_LIMIT);
  mutual = combined.filter(l=>l._kind==='mutual');
  onlyLikedMe = combined.filter(l=>l._kind==='profile');
  photoLiked = combined.filter(l=>l._kind==='photo');
  let html = '';
  if(mutual.length){
    html += `<div class="discovery-section-label">💞 Взаимная симпатия</div>`;
    html += mutual.map(l=>reactionRowHtml(l, 'mutual')).join('');
  }
  if(onlyLikedMe.length){
    html += `<div class="discovery-section-label">Лайкнули вас</div>`;
    html += onlyLikedMe.map(l=>reactionRowHtml(l, 'profile')).join('');
  }
  if(photoLiked.length){
    html += `<div class="discovery-section-label">Лайкнули ваши фото</div>`;
    html += photoLiked.map(l=>reactionRowHtml(l, 'photo', myPhotos[l.photoIndex])).join('');
  }
  el.innerHTML = html;
  enrichAvatars(el, likedMe.concat(photoLikedMe).map(l=>l.fromUid));
  enrichDisplayNames(el, likedMe.concat(photoLikedMe).map(l=>l.fromUid));
  el.querySelectorAll('[data-view-uid]').forEach(av=>{
    av.addEventListener('click', (ev)=>{ ev.stopPropagation(); openUserInfo(av.getAttribute('data-view-uid')); });
  });
  el.querySelectorAll('[data-reciprocate-photo-uid]').forEach(btn=>{
    btn.onclick = async (ev)=>{
      ev.stopPropagation();
      const fromUid = btn.getAttribute('data-reciprocate-photo-uid');
      btn.disabled = true;
      const p = await getUserProfile(fromUid);
      btn.disabled = false;
      const theirPhotos = (p && p.photos && p.photos.length) ? p.photos : (p && p.avatarUrl ? [p.avatarUrl] : []);
      if(!theirPhotos.length){ toast('У этого пользователя нет фото'); return; }
      openPhotoGallery(fromUid, theirPhotos, 0);
    };
  });
  el.querySelectorAll('[data-reciprocate-uid]').forEach(btn=>{
    btn.onclick = async (ev)=>{
      ev.stopPropagation();
      btn.disabled = true;
      const result = await toggleProfileLike(btn.getAttribute('data-reciprocate-uid'), btn.getAttribute('data-reciprocate-name'));
      if(result === true) renderReactionsSubtab();
      else btn.disabled = false;
    };
  });
  el.querySelectorAll('[data-reaction-id]').forEach(row=>{
    false && attachLongPress(row, ()=>{
      openDeleteActionSheet(async ()=>{
        try{
          await db.collection(row.getAttribute('data-reaction-kind')).doc(row.getAttribute('data-reaction-id')).delete();
          renderReactionsSubtab();
        }catch(e){ toast('Не удалось удалить'); }
      });
    });
  });
  const clearAllBtn = document.getElementById('reactions-clear-all-btn');
  const totalCount = mutual.length + onlyLikedMe.length + photoLiked.length;
  clearAllBtn.style.display = totalCount ? 'block' : 'none';
  clearAllBtn.onclick = ()=>{
    openDeleteActionSheet(async ()=>{
      const toDelete = combined.map(l=>({id:l.id, kind:l._kind==='photo'?'photoLikes':'profileLikes'}));
      await Promise.all(toDelete.map(x=> db.collection(x.kind).doc(x.id).delete().catch(()=>{})));
      renderReactionsSubtab();
    });
  };
}
function reactionRowHtml(like, type, photoUrl){
  const when = fmtTime(like.timestamp);
  const previewText = type==='mutual' ? '💞 Взаимно' : type==='photo' ? `📸 Лайкнул(а) фото №${(like.photoIndex||0)+1}` : '❤️ Лайкнул(а) вас';
  const thumbHtml = (type==='photo' && photoUrl) ? `<img src="${photoUrl}" class="reaction-photo-thumb" data-view-uid="${escapeHtml(like.fromUid)}" style="cursor:pointer;">` : '';
  return `<div class="chat-item" data-reaction-id="${escapeHtml(like.id)}" data-reaction-kind="${type==='photo'?'photoLikes':'profileLikes'}" style="cursor:default;">
    <div class="avatar" data-avatar-uid="${escapeHtml(like.fromUid)}" data-view-uid="${escapeHtml(like.fromUid)}" style="cursor:pointer;">${initials(like.fromName||'?')}</div>
    <div class="info"><div class="name"><span data-name-uid="${escapeHtml(like.fromUid)}">${escapeHtml(like.fromName||'Пользователь')}</span></div><div class="preview">${previewText} · ${when}</div></div>
    ${thumbHtml}
    ${type==='profile' ? `<button class="mini-btn" data-reciprocate-uid="${escapeHtml(like.fromUid)}" data-reciprocate-name="${escapeHtml(like.fromName||'')}">Ответить</button>` : ''}
    ${type==='photo' ? `<button class="mini-btn" data-reciprocate-photo-uid="${escapeHtml(like.fromUid)}">Ответить</button>` : ''}
  </div>`;
}
function renderDiscoveryBlacklist(){
  const el = document.getElementById('discovery-blacklist-list');
  const items = state.blacklist || [];
  if(!items.length){ el.innerHTML = `<div class="empty-list">Чёрный список пуст.</div>`; return; }
  el.innerHTML = items.map(c=>`
    <div class="chat-item" style="cursor:default;">
      <div class="avatar" data-avatar-uid="${escapeHtml(c.uid)}" data-view-uid="${escapeHtml(c.uid)}" style="cursor:pointer;">${initials(c.username)}</div>
      <div class="info"><div class="name">${escapeHtml(c.username)}</div><div class="preview">@${escapeHtml(c.username)}</div></div>
      <button class="mini-btn" style="background:var(--ok);" data-restore-uid="${escapeHtml(c.uid)}">Восстановить</button>
    </div>`).join('');
  enrichAvatars(el, items.map(c=>c.uid));
  el.querySelectorAll('[data-view-uid]').forEach(av=>{
    av.addEventListener('click', (ev)=>{ ev.stopPropagation(); openUserInfo(av.getAttribute('data-view-uid')); });
  });
  el.querySelectorAll('[data-restore-uid]').forEach(btn=>{
    btn.onclick = ()=> restoreFromBlacklist(btn.getAttribute('data-restore-uid'));
  });
}

