    const p2 = document.getElementById('set-pin-new2').value.trim();
    const msg = document.getElementById('pin-set-msg');
    msg.innerHTML = '';
    if(!/^\d{4}$/.test(p1)){ msg.innerHTML = `<div class="error-box">PIN должен состоять ровно из 4 цифр.</div>`; return; }
    if(p1 !== p2){ msg.innerHTML = `<div class="error-box">PIN не совпадает.</div>`; return; }
    btn.disabled = true; btn.textContent = 'Сохраняем…';
    try{
      const salt = randomSalt();
      const hash = await sha256hex(salt+':'+p1);
      await db.collection('users').doc(state.currentUser.uid).update({pinHash:hash, pinSalt:salt, pinEnabled:true});
      msg.innerHTML = `<div class="info-box">PIN сохранён.</div>`;
      document.getElementById('set-pin-new').value=''; document.getElementById('set-pin-new2').value='';
      document.getElementById('pin-enabled-switch').checked = true;
    }catch(e){ msg.innerHTML = `<div class="error-box">Не удалось сохранить.</div>`; }
    btn.disabled = false; btn.textContent = 'Сохранить PIN';
