  document.getElementById('duress-pin-save').onclick = async ()=>{
    const btn = document.getElementById('duress-pin-save');
    const p1 = document.getElementById('duress-pin-new').value.trim();
    const p2 = document.getElementById('duress-pin-new2').value.trim();
    const msg = document.getElementById('duress-pin-msg');
    msg.innerHTML = '';
    if(!/^\d{4}$/.test(p1)){ msg.innerHTML = `<div class="error-box">PIN должен состоять ровно из 4 цифр.</div>`; return; }
    if(p1 !== p2){ msg.innerHTML = `<div class="error-box">PIN не совпадает.</div>`; return; }
    btn.disabled = true; btn.textContent = 'Проверяем…';
    try{
      const uSnap = await db.collection('users').doc(state.currentUser.uid).get();
      const rec = uSnap.data();
      if(rec.pinSalt){
        const normalHash = await sha256hex(rec.pinSalt+':'+p1);
        if(normalHash === rec.pinHash){
          msg.innerHTML = `<div class="error-box">Этот PIN совпадает с обычным — выберите другой.</div>`;
          btn.disabled = false; btn.textContent = 'Сохранить';
          return;
        }
      }
      const salt = randomSalt();
      const hash = await sha256hex(salt+':'+p1);
      await db.collection('users').doc(state.currentUser.uid).update({duressPinHash:hash, duressPinSalt:salt, duressPinEnabled:true});
      msg.innerHTML = `<div class="info-box">PIN для экстренного удаления сохранён.</div>`;
      document.getElementById('duress-pin-new').value=''; document.getElementById('duress-pin-new2').value='';
      const sw = document.getElementById('duress-pin-enabled-switch');
      sw.disabled = false; sw.checked = true;
    }catch(e){ msg.innerHTML = `<div class="error-box">Не удалось сохранить.</div>`; }
    btn.disabled = false; btn.textContent = 'Сохранить';
  };
  document.getElementById('retention-toggle-row').onclick = ()=>{
    const f = document.getElementById('retention-form');
    const opening = (f.style.display==='none' || !f.style.display);
    if(opening){
      const mins = state.retentionMinutes || 10080;
      let value, unit;
      if(mins % (24*60) === 0){ value = mins/(24*60); unit = 'days'; }
      else if(mins % 60 === 0){ value = mins/60; unit = 'hours'; }
      else { value = mins; unit = 'minutes'; }
      document.getElementById('retention-value').value = value;
      document.getElementById('retention-unit').value = unit;
    }
    f.style.display = opening ? 'block' : 'none';
  };
  document.getElementById('retention-save').onclick = async ()=>{
    const btn = document.getElementById('retention-save');
    const msg = document.getElementById('retention-msg');
    msg.innerHTML = '';
    const val = parseFloat(document.getElementById('retention-value').value);
    const unit = document.getElementById('retention-unit').value;
    if(!val || val <= 0){ msg.innerHTML = `<div class="error-box">Введите значение больше нуля.</div>`; return; }
    let mins = unit==='days' ? val*24*60 : unit==='hours' ? val*60 : val;
    mins = Math.round(mins);
    const MAX_MIN = 7*24*60;
    if(mins > MAX_MIN){ msg.innerHTML = `<div class="error-box">Максимум — 7 дней (168 часов / 10080 минут).</div>`; return; }
    btn.disabled = true; btn.textContent = 'Сохраняем…';
    try{
      await db.collection('users').doc(state.currentUser.uid).update({retentionMinutes: mins});
      state.retentionMinutes = mins;
      msg.innerHTML = `<div class="info-box">Сохранено. Действует для новых сообщений.</div>`;
    }catch(e){ msg.innerHTML = `<div class="error-box">Не удалось сохранить.</div>`; }
    btn.disabled = false; btn.textContent = 'Сохранить';
  };
  document.getElementById('retention-disable').onclick = async ()=>{
    if(!await uiConfirm('Отключить пользовательское автоудаление? Останется базовый предел — 7 дней.')) return;
    try{
      await db.collection('users').doc(state.currentUser.uid).update({retentionMinutes: 10080});
      state.retentionMinutes = 10080;
      document.getElementById('retention-value').value = 7;
      document.getElementById('retention-unit').value = 'days';
      document.getElementById('retention-msg').innerHTML = `<div class="info-box">Сброшено на 7 дней.</div>`;
    }catch(e){ toast('Не удалось сохранить'); }
  };
  const PATTERN_OPACITY_FIELD = {chatBackground:'chatPatternOpacity', sidebarBackground:'sidebarPatternOpacity'};
  function renderBgRow(containerId, field, current){
    const wrap = document.getElementById(containerId);
    const isCustomColor = current && current.startsWith && current.startsWith('#');
    const opField = PATTERN_OPACITY_FIELD[field];
    wrap.innerHTML = BG_PRESETS.map(b=>{
      const previewCss = isPatternId(b.id) ? patternCss(b.id, 45) : b.css;
      const sizeStyle = isPatternId(b.id) ? 'background-size:16px 16px, cover;' : '';
      return `<button type="button" class="bg-swatch ${b.id===current?'active-bg':''}" data-bg="${b.id}" style="background:${previewCss};${sizeStyle}" title="${escapeHtml(b.label)}"></button>`;
    }).join('')
      + `<input type="color" class="custom-color-swatch" id="${containerId}-picker" title="Свой цвет" value="${isCustomColor?current:'#4C6EF5'}">`;
    const opacityRow = document.getElementById(containerId+'-opacity-row');
    function refreshOpacityRow(){
      if(!opacityRow) return;
      opacityRow.style.display = isPatternId(p[field]) ? 'flex' : 'none';
      const slider = document.getElementById(containerId+'-opacity-slider');
      if(slider) slider.value = p[opField]!=null ? p[opField] : 45;
    }
    refreshOpacityRow();
    wrap.querySelectorAll('.bg-swatch').forEach(btn=>{
      btn.onclick = async ()=>{
        const bgId = btn.getAttribute('data-bg');
        wrap.querySelectorAll('.bg-swatch').forEach(b=>b.classList.toggle('active-bg', b===btn));
        p[field] = bgId;
        applyAppearance(p);
        refreshOpacityRow();
        try{ await db.collection('users').doc(state.currentUser.uid).update({[field]: bgId}); }
        catch(e){ toast('Не удалось сохранить'); }
      };
    });
    document.getElementById(containerId+'-picker').addEventListener('input', (ev)=>{
      wrap.querySelectorAll('.bg-swatch').forEach(b=>b.classList.remove('active-bg'));
      p[field] = ev.target.value;
      applyAppearance(p);
      refreshOpacityRow();
    });
    document.getElementById(containerId+'-picker').addEventListener('change', async (ev)=>{
      try{ await db.collection('users').doc(state.currentUser.uid).update({[field]: ev.target.value}); }
      catch(e){ toast('Не удалось сохранить'); }
    });
    if(opacityRow){
      const slider = document.getElementById(containerId+'-opacity-slider');
      slider.addEventListener('input', (ev)=>{
        p[opField] = parseInt(ev.target.value,10);
        applyAppearance(p);
      });
      slider.addEventListener('change', async (ev)=>{
        try{ await db.collection('users').doc(state.currentUser.uid).update({[opField]: parseInt(ev.target.value,10)}); }
        catch(e){ toast('Не удалось сохранить'); }
      });
    }
  }
