const NOTIF_MELODIES = {
  chime: {label:'Перезвон', notes:[{freq:880, dur:0.12},{freq:1175, dur:0.2}]},
  ding: {label:'Динь', notes:[{freq:1046, dur:0.16}]},
  pop: {label:'Поп', notes:[{freq:600, dur:0.06},{freq:900, dur:0.09}]},
  bell: {label:'Колокольчик', notes:[{freq:784, dur:0.1},{freq:988, dur:0.1},{freq:1318, dur:0.22}]},
  marimba: {label:'Маримба', notes:[{freq:523, dur:0.1},{freq:659, dur:0.1},{freq:784, dur:0.16}]},
  drop: {label:'Капля', notes:[{freq:1400, dur:0.05},{freq:900, dur:0.12}]},
  xylo: {label:'Ксилофон', notes:[{freq:698, dur:0.08},{freq:932, dur:0.08},{freq:1174, dur:0.08},{freq:1568, dur:0.18}]},
  soft: {label:'Мягкий сигнал', notes:[{freq:660, dur:0.18},{freq:880, dur:0.28}]},
  // Длинные мелодии — специально для рингтонов звонка, с паузами (freq:0) для настоящего рисунка «дзынь-дзынь...тишина»
  classic_ring: {label:'Классический звонок', notes:[
    {freq:480,dur:0.35},{freq:0,dur:0.18},{freq:480,dur:0.35},{freq:0,dur:0.18},{freq:480,dur:0.35},{freq:0,dur:0.6},
    {freq:480,dur:0.35},{freq:0,dur:0.18},{freq:480,dur:0.35},{freq:0,dur:0.18},{freq:480,dur:0.35}
  ]},
  melodic_ring: {label:'Мелодичный звонок', notes:[
    {freq:659,dur:0.22},{freq:784,dur:0.22},{freq:988,dur:0.22},{freq:1318,dur:0.32},{freq:0,dur:0.35},
    {freq:988,dur:0.22},{freq:1175,dur:0.22},{freq:1318,dur:0.22},{freq:1568,dur:0.4}
  ]},
  electro_ring: {label:'Электро звонок', notes:[
    {freq:523,dur:0.1},{freq:659,dur:0.1},{freq:523,dur:0.1},{freq:659,dur:0.1},{freq:0,dur:0.15},
    {freq:523,dur:0.1},{freq:659,dur:0.1},{freq:523,dur:0.1},{freq:659,dur:0.1},{freq:0,dur:0.3},
    {freq:784,dur:0.28}
  ]},
  warm_ring: {label:'Тёплый звонок', notes:[
    {freq:392,dur:0.3},{freq:494,dur:0.3},{freq:587,dur:0.4},{freq:0,dur:0.3},
    {freq:392,dur:0.3},{freq:494,dur:0.3},{freq:587,dur:0.5}
  ]},
};
function playNotificationSound(melodyId, volumePercent){
  try{
    const ctx = getSharedAudioContext();
    if(!ctx) return;
    if(ctx.state === 'suspended'){ ctx.resume().catch(()=>{}); }
    const melody = NOTIF_MELODIES[melodyId] || NOTIF_MELODIES.chime;
    const vol = Math.max(0, Math.min(1, (volumePercent!=null?volumePercent:70)/100)) * 0.32;
    let t = ctx.currentTime;
    melody.notes.forEach(note=>{
      if(!note.freq){ t += note.dur; return; }
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.frequency.value = note.freq;
      osc.type = 'sine';
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.linearRampToValueAtTime(vol, t+0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, t+note.dur);
      osc.connect(gain); gain.connect(ctx.destination);
      osc.start(t); osc.stop(t+note.dur+0.03);
      t += note.dur*0.82;
    });
  }catch(e){}
}
async function requestNotificationPermission(){
  if(!('Notification' in window)) return false;
  if(Notification.permission === 'granted') return true;
  if(Notification.permission === 'denied') return false;
  try{ const res = await Notification.requestPermission(); return res === 'granted'; }catch(e){ return false; }
}
function showBrowserNotification(title, body){
  if(!('Notification' in window) || Notification.permission !== 'granted') return;
  if(navigator.serviceWorker && navigator.serviceWorker.controller){
    navigator.serviceWorker.ready
      .then(reg=> reg.showNotification(title, {body: body || '', icon: 'icon-192.png', badge: 'icon-192.png', lang: 'ru'}))
      .catch(()=>{});
    return;
  }
  try{
    const n = new Notification(title, {body: body || ''});
    n.onclick = ()=>{ window.focus(); n.close(); };
    setTimeout(()=>{ try{ n.close(); }catch(e){} }, 7000);
  }catch(e){}
}
const knownChatLastTimestamps = {};
function checkForNewMessageNotifications(chats){
  const myUid = state.currentUser.uid;
  const prefs = state.notifPrefs || {};
  chats.forEach(meta=>{
    const prevTs = knownChatLastTimestamps[meta.id];
    knownChatLastTimestamps[meta.id] = meta.lastTimestamp || 0;
    if(prevTs === undefined) return;
    if(!meta.lastTimestamp || meta.lastTimestamp <= prevTs) return;
    if(meta.lastFrom === myUid) return;
    if(prefs.notificationsEnabled === false) return;
    const muteLevel = (meta.mutedBy && meta.mutedBy[myUid]) || 'none';
    if(muteLevel === 'all') return;
    const other = otherOf(meta);
    if(muteLevel !== 'sound' && prefs.notificationSoundEnabled !== false && !meta.lastSilent){
      playNotificationSound(prefs.notificationMelody, prefs.notificationVolume);
    }
    showBrowserNotification(other.displayName, meta.lastMessage || 'Новое сообщение');
  });
}
function isChatUnread(meta){
  if(!meta.lastTimestamp) return false;
  if(meta.lastType === 'call') return false;
  const myUid = state.currentUser.uid;
  if(meta.lastFrom === myUid) return false;
  const myLastRead = (meta.lastReadBy && meta.lastReadBy[myUid]) || 0;
  return meta.lastTimestamp > myLastRead;
}
function updateChatsBadge(){
  const count = (state.chats||[]).filter(c=>isChatUnread(c)).length;
  const badge = document.getElementById('nav-badge-chats');
  if(badge){
    badge.textContent = count > 99 ? '99+' : String(count);
    badge.style.display = count > 0 ? 'flex' : 'none';
  }
}
function updateCallsBadge(){
  const myUid = state.currentUser.uid;
  const lastViewed = state.lastViewedCallsTab || 0;
  const count = (state.callLogs||[]).filter(c=>c.outcome==='missed' && c.callerUid!==myUid && c.timestamp > lastViewed).length;
  const badge = document.getElementById('nav-badge-calls');
  if(badge){
    badge.textContent = count > 99 ? '99+' : String(count);
    badge.style.display = count > 0 ? 'flex' : 'none';
  }
}
let cachedLikesToMe = [];
function updateDiscoveryBadge(){
  const lastViewed = state.lastViewedReactionsTab || 0;
  const count = cachedLikesToMe.filter(l=>l.timestamp > lastViewed).length + cachedPhotoLikesToMe.filter(l=>l.timestamp > lastViewed).length;
  const subBadge = document.getElementById('subtab-badge-reactions');
  if(subBadge){
    subBadge.textContent = count > 99 ? '99+' : String(count);
    subBadge.style.display = count > 0 ? 'inline-flex' : 'none';
  }
  updateMainDiscoveryBadge();
}
function updateMainDiscoveryBadge(){
  const lastViewed = state.lastViewedReactionsTab || 0;
  const likesCount = cachedLikesToMe.filter(l=>l.timestamp > lastViewed).length + cachedPhotoLikesToMe.filter(l=>l.timestamp > lastViewed).length;
  const friendsCount = cachedPendingFriendRequests.filter(r=>r.timestamp > (state.lastViewedFriendRequestsTab||0)).length;
  const total = likesCount + friendsCount;
  const badge = document.getElementById('nav-badge-discovery');
  if(badge){
    badge.textContent = total > 99 ? '99+' : String(total);
    badge.style.display = total > 0 ? 'flex' : 'none';
  }
}
const chatPreviewRefreshInFlight = new Set();
function renderChatList(){
  updateChatsBadge();
  // Самовосстановление: если кэшированное превью чата ссылается на уже истёкшее сообщение
  // (а сам чат при этом не открыт — иначе оно бы уже обновилось своим путём), пересчитываем
  // его здесь же, не дожидаясь, пока пользователь случайно откроет именно этот чат
  const nowTs = Date.now();
  (state.chats||[]).forEach(meta=>{
    const needsRefresh = meta.lastMessage && (
      (meta.lastMessageExpireAt && meta.lastMessageExpireAt <= nowTs) || // истекло по новому полю
      (meta.lastMessageExpireAt === undefined) // поля ещё нет вовсе — чат из тех, что были до этого исправления
    );
    if(needsRefresh && meta.id !== state.activeChatId && !chatPreviewRefreshInFlight.has(meta.id)){
      chatPreviewRefreshInFlight.add(meta.id);
      refreshChatPreview(meta.id).finally(()=> chatPreviewRefreshInFlight.delete(meta.id));
    }
  });
  const list = document.getElementById('chat-list');
  const searchEl = document.getElementById('chat-list-search');
  const q = searchEl ? searchEl.value.trim().toLowerCase() : '';
  let source = state.chats.slice();
  const me = state.currentUser.uid;
  const hiddenContactUids = new Set(state.contacts.filter(c=>c.hidden).map(c=>c.uid));
  source = source.filter(meta => meta.isCommunity || !hiddenContactUids.has(otherOf(meta).uid));
  if(q) source = source.filter(meta => {
    const o = otherOf(meta) || {};
    const uid = o.uid;
    const c = (state.contacts || []).find(x=> x.uid === uid) || {};
    const p = (typeof storyState !== 'undefined' && storyState.profiles && storyState.profiles[uid]) || {};
    const alias = (state.contactAliasMap && state.contactAliasMap[uid]) || '';
    /* ROUND 74: имя и фамилия берутся отовсюду, где они уже известны: профили, память устройства */
    const up = (state.userProfileCache && state.userProfileCache[uid]) || {};
    const lp = (window.cachedProfile && window.cachedProfile(uid)) || {};
    const norm = (x)=> String(x || '').toLowerCase().replace(/ё/g, 'е');
    const hay = norm([o.displayName, o.username, c.firstName, c.lastName, c.username, p.firstName, p.lastName, p.username,
                 up.firstName, up.lastName, up.username, lp.firstName, lp.lastName, lp.username,
                 [up.firstName, up.lastName].filter(Boolean).join(' '), [lp.firstName, lp.lastName].filter(Boolean).join(' '),
                 [lp.lastName, lp.firstName].filter(Boolean).join(' '),
                 alias, meta.communityName].filter(Boolean).join(' | '));
    return norm(q).split(/\s+/).filter(Boolean).every(w=> hay.includes(w));
  });
  source = source.slice().sort((a,b)=> ((b.pinnedBy||[]).includes(me)?1:0) - ((a.pinnedBy||[]).includes(me)?1:0));
  if(!source.length){
    list.innerHTML = q
      ? `<div class="empty-list">Никого не найдено по «${escapeHtml(q)}».</div>`
      : `<div class="empty-list">Пока нет ни одного чата.<br>Найдите пользователя во вкладке «Контакты».</div>`;
    if(state.chatSelectMode) updateChatSelectCount();
    return;
  }
  list.innerHTML = source.map(meta=>{
    const other = otherOf(meta);
    const active = meta.id === state.activeChatId ? 'active' : '';
    const previewIcons = {image:ICON_IMAGE, file:ICON_FILE, voice:ICON_MIC, contact:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="8" r="3.5"/><path d="M5 20c0-3.5 3-6 7-6s7 2.5 7 6" stroke-linecap="round"/></svg>', call:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4.5 4h3.5l1.5 4.5-2.2 1.8a13 13 0 0 0 6.4 6.4l1.8-2.2 4.5 1.5v3.5a1.5 1.5 0 0 1-1.6 1.5A17.5 17.5 0 0 1 3 5.6 1.5 1.5 0 0 1 4.5 4z"/></svg>'};
    const previewIcon = meta.lastMessage && previewIcons[meta.lastType] ? `<span class="preview-icon">${previewIcons[meta.lastType]}</span>` : '';
    const preview = meta.lastMessage ? previewIcon+escapeHtml(meta.lastMessage) : 'Нет сообщений';
    const checked = state.selectedChats.has(meta.id);
    const dot = state.chatSelectMode ? `<div class="select-dot ${checked?'checked':''}">${checked?'✓':''}</div>` : '';
    const unread = isChatUnread(meta);
    const showLastSeen = other.uid && other.uid !== 'support' && other.uid !== state.currentUser.uid;
    return `<div class="chat-item ${active} ${unread?'unread':''}" data-id="${meta.id}">
      ${dot}
      <div class="avatar" data-avatar-uid="${other.uid}" ${other.isCommunity?'':'data-info-btn="1"'}>${initials(other.displayName)}</div>
      <div class="info">
        <div class="top-row"><div class="name">${(meta.pinnedBy||[]).includes(me)?'📌 ':''}<span data-name-uid="${escapeHtml(other.uid)}">${escapeHtml(other.displayName)}</span></div><div class="time">${meta.lastTimestamp ? fmtTime(meta.lastTimestamp) : ''}</div></div>
        <div class="preview">${preview}${unread?'<span class="unread-dot"></span>':''}</div>
        ${showLastSeen ? `<div class="preview" data-lastseen-slot="${escapeHtml(other.uid)}" style="margin-top:1px;"></div>` : ''}
      </div></div>`;
  }).join('');
  enrichAvatars(list, source.map(meta=>otherOf(meta).uid));
  source.forEach(meta=>{
    if(meta.isCommunity && meta.communityAvatarUrl){
      const row = list.querySelector(`[data-id="${meta.id}"] .avatar`);
      if(row) applyAvatarImg(row, meta.communityAvatarUrl);
    }
    if(meta.isCommunity){
      const av = list.querySelector(`[data-id="${meta.id}"] .avatar`);
      if(av){
        av.style.cursor = 'pointer';
        av.addEventListener('click', (ev)=>{ ev.stopPropagation(); openCommunityMembers(meta.id); });
      }
    }
  });
  enrichLastSeenSlots(list, source.filter(meta=>otherOf(meta).uid!=='support' && otherOf(meta).uid!==state.currentUser.uid).map(meta=>otherOf(meta).uid));
  const aliasedUids = new Set(Object.keys(state.contactAliasMap).filter(uid=>state.contactAliasMap[uid]));
  enrichDisplayNames(list, source.map(meta=>otherOf(meta).uid), aliasedUids);
  list.querySelectorAll('.avatar[data-info-btn]').forEach(el=>{
    el.style.cursor = 'pointer';
    el.addEventListener('click', (ev)=>{ ev.stopPropagation(); openUserInfo(el.getAttribute('data-avatar-uid')); });
  });
  list.querySelectorAll('.chat-item').forEach(el=>{
    el.onclick = ()=>{
      const id = el.getAttribute('data-id');
      if(state.chatSelectMode){
        if(state.selectedChats.has(id)) state.selectedChats.delete(id); else state.selectedChats.add(id);
        renderChatList();
      }else{
        openChat(id);
      }
    };
    if(!state.chatSelectMode){
      false && attachLongPress(el, ()=>{
        openDeleteActionSheet(async ()=>{
          state.selectedChats = new Set([el.getAttribute('data-id')]);
          await deleteSelectedChats();
        });
      });
    }
  });
  if(state.chatSelectMode) updateChatSelectCount();
}

function enterChatSelectMode(action){
  state.chatSelectMode = true; state.selectedChats = new Set();
  state.chatSelectAction = action || 'delete';
  document.getElementById('chats-header-normal').style.display = 'none';
  document.getElementById('chats-header-select').style.display = 'flex';
  document.getElementById('chat-select-pin').style.display = state.chatSelectAction==='pin' ? 'flex' : 'none';
  document.getElementById('chat-select-delete').style.display = state.chatSelectAction==='delete' ? 'flex' : 'none';
  renderChatList();
}
function exitChatSelectMode(){
  state.chatSelectMode = false; state.selectedChats = new Set();
  document.getElementById('chats-header-normal').style.display = 'flex';
  document.getElementById('chats-header-select').style.display = 'none';
  renderChatList();
}
function updateChatSelectCount(){
  const el = document.getElementById('chat-select-count');
  if(el) el.textContent = 'Выбрано: '+state.selectedChats.size;
}
function enterContactSelectMode(action){
  state.contactSelectMode = true; state.selectedContacts = new Set();
  state.contactSelectAction = action || 'delete';
  document.getElementById('contacts-header-normal').style.display = 'none';
  document.getElementById('contacts-header-select').style.display = 'flex';
  document.getElementById('contact-select-pin').style.display = state.contactSelectAction==='pin' ? 'flex' : 'none';
  document.getElementById('contact-select-delete').style.display = state.contactSelectAction==='delete' ? 'flex' : 'none';
  renderContacts();
}
function exitContactSelectMode(){
  state.contactSelectMode = false; state.selectedContacts = new Set();
  document.getElementById('contacts-header-normal').style.display = 'flex';
  document.getElementById('contacts-header-select').style.display = 'none';
  renderContacts();
}
function updateContactSelectCount(){
  const el = document.getElementById('contact-select-count');
  if(el) el.textContent = 'Выбрано: '+state.selectedContacts.size;
}
async function deleteSelectedContacts(){
  if(!state.selectedContacts.size) return;
  if(!await uiConfirm('Удалить выбранные контакты ('+state.selectedContacts.size+')?')) return;
  const uids = Array.from(state.selectedContacts);
  const newList = state.contacts.filter(c=>!uids.includes(c.uid));
  try{
    await db.collection('contacts').doc(state.currentUser.uid).set({list: newList});
    toast('Удалено: '+uids.length);
  }catch(e){ toast('Не удалось удалить'); }
  exitContactSelectMode();
}
async function toggleSelectedContactsPin(){
  if(!state.selectedContacts.size) return;
  const uids = Array.from(state.selectedContacts);
  const allPinned = uids.every(uid=>{
    const c = state.contacts.find(x=>x.uid===uid);
    return c && c.pinned;
  });
  const newList = state.contacts.map(c=> uids.includes(c.uid) ? Object.assign({}, c, {pinned: !allPinned}) : c);
  try{
    await db.collection('contacts').doc(state.currentUser.uid).set({list: newList});
    toast(allPinned ? 'Откреплено' : 'Закреплено');
  }catch(e){ toast('Не удалось сохранить'); }
  exitContactSelectMode();
}
document.getElementById('contact-select-toggle').onclick = ()=>enterContactSelectMode('delete');
document.getElementById('contact-select-pin-toggle').onclick = ()=>enterContactSelectMode('pin');
document.getElementById('contact-select-cancel').onclick = exitContactSelectMode;
document.getElementById('contact-select-pin').onclick = toggleSelectedContactsPin;
document.getElementById('contact-select-delete').onclick = deleteSelectedContacts;
document.getElementById('contact-select-all').onclick = ()=>{
  const visible = state.contacts;
  visible.forEach(c=>state.selectedContacts.add(c.uid));
  renderContacts();
};
async function deleteSelectedChats(){
  if(!state.selectedChats.size) return;
  if(!await uiConfirm('Удалить выбранные чаты ('+state.selectedChats.size+')? Переписка удалится полностью — и у вас, и у собеседника.')) return;
  const ids = Array.from(state.selectedChats);
  for(const id of ids){
    await deleteChatCompletely(id);
  }
  exitChatSelectMode();
}
async function toggleSelectedChatsPin(){
  if(!state.selectedChats.size) return;
  const ids = Array.from(state.selectedChats);
  const me = state.currentUser.uid;
  const allPinned = ids.every(id=>{
    const meta = state.chats.find(c=>c.id===id);
    return meta && (meta.pinnedBy||[]).includes(me);
  });
  for(const id of ids){
    try{
      await db.collection('chats').doc(id).update({
        pinnedBy: allPinned ? firebase.firestore.FieldValue.arrayRemove(me) : firebase.firestore.FieldValue.arrayUnion(me)
      });
    }catch(e){}
  }
  toast(allPinned ? 'Откреплено' : 'Закреплено');
  exitChatSelectMode();
}
document.getElementById('chat-select-toggle').onclick = ()=>enterChatSelectMode('delete');
