/* ============================================================
   ОТКРЫТИЕ ЧАТА
============================================================ */
async function openChat(chatId){
  state.activeChatId = chatId;
  state.knownMsgIds = new Set();
  state.knownReactionsSig = {};
  state.reactionFlashUntil = {};
  state.msgsInitialLoad = true;
  clearReplyContext();
  document.getElementById('msg-input').value = '';
  updateSendBtnVisibility();
  if(state.msgSelectMode) exitMsgSelectMode();
  let snap;
  /* ROUND 71: чат из списка открывается сразу, без ожидания сервера (и без интернета);
     свежие данные чата подтягиваются в фоне */
  const knownMeta = (state.chats || []).find(c=> c.id === chatId);
  if(knownMeta){
    snap = {exists: true, data: ()=> Object.assign({id: chatId}, knownMeta)};
    db.collection('chats').doc(chatId).get().then(s=>{
      if(s.exists && state.activeChatId === chatId) state.activeChatMeta = Object.assign({}, state.activeChatMeta || {}, s.data(), {id: chatId});
    }).catch(()=>{});
  }else{
    try{
      snap = await db.collection('chats').doc(chatId).get();
    }catch(e){
      toast('Не удалось открыть чат: ' + (e && e.message ? e.message : 'ошибка сервера'));
      return;
    }
  }
  if(!snap.exists) return;
  state.activeChatMeta = snap.data();
  markActiveChatRead(chatId);
  const other = otherOf(state.activeChatMeta);
  document.getElementById('no-chat-block').style.display = 'none';
  document.getElementById('active-chat-block').style.display = 'flex';
  const avatarEl = document.getElementById('chat-avatar');
  avatarEl.style.padding = ''; avatarEl.textContent = initials(other.displayName);
  document.getElementById('call-btn-header').style.display = other.isCommunity ? 'none' : '';
  document.getElementById('videocall-btn-header').style.display = other.isCommunity ? 'none' : '';
  if(other.isCommunity && state.activeChatMeta.communityAvatarUrl){
    applyAvatarImg(avatarEl, state.activeChatMeta.communityAvatarUrl);
  }
  avatarEl.style.cursor = 'pointer';
  avatarEl.onclick = other.isCommunity ? (()=> openCommunityMembers(chatId)) : (()=> openUserInfo(other.uid));
  document.getElementById('chat-header-name').textContent = other.displayName;
  if(!state.contactAliasMap[other.uid]){
    getUserProfile(other.uid).then(p=>{
      const realName = realNameOf(p);
      if(realName && state.activeChatId === chatId) document.getElementById('chat-header-name').textContent = realName;
    });
  }
  document.getElementById('chat-header-sub').textContent = '';
  document.getElementById('chat-area').classList.add('mobile-open');
  if(window.innerWidth <= 780) document.getElementById('notif-bell-btn').style.display = 'none';
  updateMuteIcon();
  renderChatList();
  listenActiveMessages(chatId);
  delete state.userProfileCache[other.uid];
  getUserProfile(other.uid).then(p=>{
    if(!p || state.activeChatId!==chatId) return;
    if(p.avatarUrl) applyAvatarImg(avatarEl, p.avatarUrl);
    applyStatusDot(avatarEl, p);
    const lastSeen = fmtLastSeen(p);
    const email = canSeeEmail(p, other.uid) ? p.email : '';
    document.getElementById('chat-header-sub').textContent = lastSeen || email || '';
    document.getElementById('call-btn-header').style.display = p.allowAudioCalls === false ? 'none' : 'flex';
    document.getElementById('videocall-btn-header').style.display = p.allowVideoCalls === false ? 'none' : 'flex';
  });
}

/* ============================================================
   СООБЩЕНИЯ + ВЫДЕЛЕНИЕ
============================================================ */
function seededWaveform(seed, count){
  let s = 0;
  const str = String(seed||'x');
  for(let i=0;i<str.length;i++){ s = (s*31 + str.charCodeAt(i)) & 0xffffffff; }
  if(s===0) s = 42;
  const heights = [];
  for(let i=0;i<count;i++){
    s ^= s << 13; s &= 0xffffffff;
    s ^= s >>> 17;
    s ^= s << 5; s &= 0xffffffff;
    heights.push(26 + (Math.abs(s) % 100) * 0.62);
  }
  return heights;
}
function msgPreviewText(m){
  if(m.type==='image') return '📷 Изображение';
  if(m.type==='file') return '📎 '+(m.fileName||'Файл');
  if(m.type==='voice') return '🎤 Голосовое сообщение';
  if(m.type==='roundvideo') return '🎥 Видеосообщение';
  if(m.type==='contact') return '👤 Контакт';
  return (m.content||'').slice(0,60);
}
function aggregateReactions(reactions){
  const map = {};
  (reactions||[]).forEach(r=>{
    if(!map[r.emoji]) map[r.emoji] = [];
    map[r.emoji].push(r.uid);
  });
  return map;
}
function messageTickStatus(m, otherUid, meta){
  if(!otherUid || otherUid==='support' || !meta) return null;
  const readTs = meta.lastReadBy && meta.lastReadBy[otherUid];
  const deliveredTs = meta.lastDeliveredTo && meta.lastDeliveredTo[otherUid];
  if(readTs && m.timestamp <= readTs) return 'read';
  if(deliveredTs && m.timestamp <= deliveredTs) return 'delivered';
  return 'sent';
}
function renderMessages(msgs){
  const box = document.getElementById('messages');
  const wasNearBottom = (box.scrollHeight - box.scrollTop - box.clientHeight) < 150;
  const skipAnim = state.msgsInitialLoad;
  const prevScrollTop = box.scrollTop;
  const lastMsgR = msgs[msgs.length-1];
  const lastIsNewMine = !!(lastMsgR && lastMsgR.from === state.currentUser.uid && !state.knownMsgIds.has(lastMsgR.id));
  const lastIsNewIncoming = !!(lastMsgR && !skipAnim && lastMsgR.from !== state.currentUser.uid && !state.knownMsgIds.has(lastMsgR.id));
  let lastDay = null, html = '';
  for(const m of msgs){
    const d = new Date(m.timestamp);
    const dayLabel = d.toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
    if(dayLabel !== lastDay){ html += `<div class="day-divider">${dayLabel}</div>`; lastDay = dayLabel; }
    const out = m.from === state.currentUser.uid;
    const time = d.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
    const otherUidForTick = out && state.activeChatMeta && !state.activeChatMeta.isSupport ? otherOf(state.activeChatMeta).uid : null;
    const tickStatus = out ? messageTickStatus(m, otherUidForTick, state.activeChatMeta) : null;
    const tickIcon = tickStatus==='read' ? ICON_ENVELOPE_CLOSED : tickStatus==='delivered' ? ICON_ENVELOPE_CLOSED : tickStatus==='sent' ? ICON_TICK_SENT : '';
    const tickHtml = tickStatus ? `<span class="msg-tick" data-tick-status="${tickStatus}" data-tick-other="${escapeHtml(otherUidForTick||'')}">${tickIcon}</span>` : '';
    const isNew = !skipAnim && !state.knownMsgIds.has(m.id);
    const checked = state.selectedMessages.has(m.id);
    const dot = state.msgSelectMode ? `<div class="select-dot ${checked?'checked':''}">${checked?'✓':''}</div>` : '';
    let bubbleInner;
    if(m.type === 'image'){
      bubbleInner = `<img src="${m.content}" data-full="${m.content}" class="msg-img"><span class="time">${time}${tickHtml}</span>`;
    }else if(m.type === 'video'){
      bubbleInner = `<div class="mv-wrap" data-mv-id="${m.id}">
        <video class="msg-video" src="${m.content}" ${m.thumbnail ? `poster="${m.thumbnail}"` : ''} playsinline preload="metadata"></video>
        <button type="button" class="mv-play" data-mv="play" aria-label="Смотреть"><svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5.5v13a1 1 0 0 0 1.5.9l10.2-6.5a1 1 0 0 0 0-1.8L9.5 4.6A1 1 0 0 0 8 5.5z"/></svg></button>
        <div class="mv-tools">
          <button type="button" data-mv="full" aria-label="На весь экран"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg></button>
          <button type="button" data-mv="dl" aria-label="Скачать"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v11"/><polyline points="7 10 12 15 17 10"/><path d="M5 20h14"/></svg></button>
        </div>
        <div class="mv-bar"><i></i></div>
        <span class="mv-dur">${m.duration ? Math.floor(m.duration / 60) + ':' + String(Math.round(m.duration % 60)).padStart(2, '0') : ''}</span>
      </div><span class="time">${time}${tickHtml}</span>`;
    }else if(m.type === 'file'){
      bubbleInner = `<a href="${m.content}" download="${escapeHtml(m.fileName||'file')}" class="file-msg">📄 ${escapeHtml(m.fileName||'Файл')}</a><span class="time">${time}${tickHtml}</span>`;
    }else if(m.type === 'voice'){
      const dur = m.duration || 0;
      const durLabel = Math.floor(dur/60)+':'+String(dur%60).padStart(2,'0');
      const bars = (Array.isArray(m.waveform) && m.waveform.length >= 8) ? resampleWave(m.waveform, 27) : seededWaveform(m.id, 27);
      const barsHtml = bars.map((h,i)=>`<span class="voice-bar-seg" data-idx="${i}" style="height:${h}%"></span>`).join('');
      bubbleInner = `<div class="voice-msg" data-src="${m.content}" data-dur="${Number(m.duration)||''}">
          <button class="voice-play-btn" type="button">${ICON_PLAY}</button>
          <div class="voice-bar">${barsHtml}</div>
          <span class="voice-time">${durLabel}</span>
          <button class="voice-speed-btn" type="button" title="Скорость воспроизведения">${voiceRateLabel()}</button>
          ${aiEnabled() ? `<button class="voice-stt-btn" type="button" title="Расшифровать в текст">Aa</button>` : ''}
        </div><span class="time">${time}${tickHtml}</span>`;
    }else if(m.type === 'roundvideo'){
      const rvDur = m.duration || 0;
      const rvDurLabel = Math.floor(rvDur/60)+':'+String(rvDur%60).padStart(2,'0');
      bubbleInner = `<div class="roundvideo-msg" data-src="${m.content}">
          <video class="roundvideo-bubble-video" playsinline muted ${m.thumbnail?`poster="${m.thumbnail}"`:''}></video>
          <button class="roundvideo-play-overlay" type="button">${ICON_PLAY}</button>
          <span class="roundvideo-duration">${rvDurLabel}</span>
        </div><span class="time rv-time-chip">${time}${tickHtml}</span>`;
    }else if(m.type === 'call'){
      const isVideoCall = m.callType === 'video';
      const callIcon = isVideoCall
        ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="6.5" width="13" height="11" rx="2.5"/><path d="M15.5 10.8l5-3v8.4l-5-3z"/></svg>'
        : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4.5 4h3.5l1.5 4.5-2.2 1.8a13 13 0 0 0 6.4 6.4l1.8-2.2 4.5 1.5v3.5a1.5 1.5 0 0 1-1.6 1.5A17.5 17.5 0 0 1 3 5.6 1.5 1.5 0 0 1 4.5 4z"/></svg>';
      const iSent = m.from === state.currentUser.uid;
      let label;
      if(m.callOutcome === 'missed') label = iSent ? 'Нет ответа' : 'Пропущенный '+(isVideoCall?'видеозвонок':'звонок');
      else if(m.callOutcome === 'declined') label = iSent ? 'Вы отклонили звонок' : 'Звонок отклонён';
      else if(m.callOutcome === 'cancelled') label = iSent ? 'Вы отменили звонок' : 'Звонок отменён';
      else{
        const d = m.callDuration||0;
        label = (isVideoCall?'Видеозвонок':'Звонок')+', '+Math.floor(d/60)+':'+String(d%60).padStart(2,'0');
      }
      const okCall = !m.callOutcome || m.callOutcome === 'completed' || m.callOutcome === 'ended';
      const kindWord = isVideoCall ? 'видеозвонок' : 'звонок';
      const title = okCall ? (iSent ? 'Исходящий ' : 'Входящий ') + kindWord : label;
      const dur = m.callDuration || 0;
      const durTxt = okCall && dur > 0 ? Math.floor(dur/60)+':'+String(dur%60).padStart(2,'0') : (okCall ? '' : (iSent ? 'Исходящий' : 'Входящий'));
      const arrow = iSent
        ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"/><polyline points="8 7 17 7 17 16"/></svg>'
        : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><line x1="17" y1="7" x2="7" y2="17"/><polyline points="16 17 7 17 7 8"/></svg>';
      bubbleInner = `<div class="call-msg tg"><div class="call-msg-text"><div class="call-msg-title">${escapeHtml(title)}</div><div class="call-msg-sub ${okCall?'ok':'bad'}">${arrow}<span>${escapeHtml(durTxt)}</span></div></div><button type="button" class="call-msg-btn" data-callback-kind="${isVideoCall?'video':'audio'}" title="Позвонить снова">${callIcon}</button></div><span class="time">${time}${tickHtml}</span>`;
    }else if(m.type === 'contact'){
      let cd = {};
      try{ cd = JSON.parse(m.content); }catch(e){}
      bubbleInner = `<div class="contact-card" data-cuid="${escapeHtml(cd.uid||'')}">
          <div class="avatar" data-avatar-uid="${escapeHtml(cd.uid||'')}">${initials(cd.username||'?')}</div>
          <div class="contact-card-info">
            <div class="contact-card-name">${escapeHtml(cd.username||'Контакт')}</div>
            <div class="contact-card-email">${escapeHtml(cd.email||'')}</div>
          </div>
        </div><span class="time">${time}${tickHtml}</span>`;
    }else{
      bubbleInner = `${animateLiveEmojisInText(m.content).replace(/\n/g,'<br>')}<span class="time">${m.edited?'<span class="edited-tag">изменено</span> ':''}${time}${tickHtml}</span>`;
    }
    let replyHtml = '';
    if(m.replyTo){
      replyHtml = `<div class="reply-quote"><b>${escapeHtml(m.replyTo.fromUsername||'')}</b>${escapeHtml(m.replyTo.preview||'')}</div>`;
    }
    const sig = JSON.stringify(m.reactions||[]);
    const reactionChanged = !skipAnim && state.knownReactionsSig[m.id]!==undefined && state.knownReactionsSig[m.id]!==sig;
    state.knownReactionsSig[m.id] = sig;
    const hasReactions = (m.reactions||[]).length > 0;
    if(hasReactions && state.reactionFlashUntil[m.id] === undefined){
      const chatIdAtSchedule = state.activeChatId;
      state.reactionFlashUntil[m.id] = Date.now() + 120000;
      setTimeout(()=>{ if(state.activeChatId === chatIdAtSchedule) renderMessages(state.currentMessages); }, 120000);
    }
    const longFlash = hasReactions && state.reactionFlashUntil[m.id] && Date.now() < state.reactionFlashUntil[m.id];
    const reactionMap = aggregateReactions(m.reactions);
    const emojiKeys = Object.keys(reactionMap);
    let reactionsHtml = '';
    if(emojiKeys.length){
      reactionsHtml = `<div class="reaction-chips">` + emojiKeys.map(e=>{
        const mine = reactionMap[e].includes(state.currentUser.uid);
        const count = reactionMap[e].length;
        return `<button type="button" class="reaction-chip ${mine?'mine':''} ${reactionChanged?'bump':''}" data-react-toggle-msg="${m.id}" data-react-toggle-emoji="${e}">${maybeLiveEmoji(e)}${count>1?' '+count:''}</button>`;
      }).join('') + `</div>`;
    }
    const isMediaBubble = (m.type === 'image' || m.type === 'roundvideo' || m.type === 'video') && !replyHtml;
    const bubbleHtml = `<div class="bubble ${isMediaBubble?'media-bubble':''} ${reactionChanged?'reaction-flash':''} ${longFlash?'reaction-flash-long':''}">${replyHtml}${bubbleInner}</div>`;
    const isCommunityChat = !!(state.activeChatMeta && state.activeChatMeta.isCommunity);
    const senderLabelHtml = (isCommunityChat && !out) ? `<div class="msg-sender-label" style="display:flex;align-items:center;gap:6px;"><div class="avatar" data-avatar-uid="${escapeHtml(m.from)}" data-sender-uid="${escapeHtml(m.from)}" style="width:30px;height:30px;font-size:13.5px;cursor:pointer;flex-shrink:0;">${initials(m.from)}</div><span data-sender-uid="${escapeHtml(m.from)}" data-name-uid="${escapeHtml(m.from)}" style="cursor:pointer;">${escapeHtml((state.activeChatMeta.usernames&&state.activeChatMeta.usernames[m.from])||m.from)}</span></div>` : '';
    const bubbleCol = `<div class="bubble-col">${senderLabelHtml}${bubbleHtml}${reactionsHtml}</div>`;
    const iconsHtml = state.msgSelectMode ? '' : `<div class="msg-icons">
        <button type="button" class="reply-icon-btn" data-reply-id="${m.id}" title="Ответить">${ICON_REPLY}</button>
        <button type="button" class="react-icon-btn" data-react-id="${m.id}" title="Реакция">${ICON_SMILEY}</button>
      </div>`;
    html += `<div class="msg-row ${out?'out':'in'} ${isNew?'new-msg':''}" data-id="${m.id}">${out ? bubbleCol+iconsHtml+dot : dot+iconsHtml+bubbleCol}</div>`;
  }
  box.innerHTML = html || `<div class="empty-list">Сообщений пока нет. Напишите первое!</div>`;
  if(state.activeChatMeta && state.activeChatMeta.isCommunity){
    const senderUids = msgs.filter(m=>m.from!==state.currentUser.uid).map(m=>m.from);
    enrichDisplayNames(box, senderUids);
    enrichAvatars(box, senderUids);
    box.querySelectorAll('[data-sender-uid]').forEach(el=>{
      el.addEventListener('click', (ev)=>{ ev.stopPropagation(); openUserInfo(el.getAttribute('data-sender-uid')); });
    });
  }
  const readTicks = box.querySelectorAll('.msg-tick[data-tick-status="read"]');
  if(readTicks.length){
    const otherUidForTicks = readTicks[0].getAttribute('data-tick-other');
    if(otherUidForTicks){
      getUserProfile(otherUidForTicks).then(p=>{
        if(p && p.readReceiptsEnabled === false){
          box.querySelectorAll('.msg-tick[data-tick-status="read"]').forEach(el=>{
            el.setAttribute('data-tick-status','delivered');
            el.innerHTML = ICON_ENVELOPE_CLOSED;
          });
        }
      });
    }
  }
  msgs.forEach(m=>state.knownMsgIds.add(m.id));
  state.msgsInitialLoad = false;
  box.querySelectorAll('.msg-row').forEach(row=>{
    row.addEventListener('click', (ev)=>{
      if(!state.msgSelectMode) return;
      ev.preventDefault();
      const id = row.getAttribute('data-id');
      if(state.selectedMessages.has(id)) state.selectedMessages.delete(id); else state.selectedMessages.add(id);
      renderMessages(msgs);
    });
    if(!state.msgSelectMode){
      attachLongPress(row, ()=>{ openMsgActionSheet(row.getAttribute('data-id')); });
    }
  });
  if(!state.msgSelectMode){
    const imageGallery = msgs.filter(m=>m.type==='image').map(m=>m.content);
    box.querySelectorAll('.msg-img').forEach(img=>{
      img.addEventListener('click', (ev)=>{
        ev.stopPropagation();
        const src = img.getAttribute('data-full');
        const idx = imageGallery.indexOf(src);
        openLightbox(imageGallery, idx >= 0 ? idx : 0);
      });
    });
    box.querySelectorAll('.voice-msg').forEach(el=>{
      const btn = el.querySelector('.voice-play-btn');
      const wave = el.querySelector('.voice-bar');
      const timeLabel = el.querySelector('.voice-time');
      const src = el.getAttribute('data-src');
      if(activeVoiceAudio && activeVoiceSrc === src){
        activeVoiceBtn = btn; activeVoiceWave = wave; activeVoiceLabel = timeLabel;
        btn.innerHTML = activeVoiceAudio.paused ? ICON_PLAY : ICON_PAUSE;
      }
      const speedBtn = el.querySelector('.voice-speed-btn');
      if(speedBtn) speedBtn.addEventListener('click', (ev)=>{ ev.stopPropagation(); cycleVoiceRate(); });
      const sttBtn = el.querySelector('.voice-stt-btn');
      if(sttBtn){
        const rowEl = el.closest('.msg-row');
        const mid = rowEl && rowEl.getAttribute('data-id');
        sttBtn.addEventListener('click', (ev)=>{
          ev.stopPropagation();
          const msg = (state.currentMessages||[]).find(x=> x.id === mid);
          if(msg) transcribeMessage(msg);
        });
      }
      btn.addEventListener('click', (ev)=>{
        ev.stopPropagation();
        toggleVoicePlayback(src, btn, wave, timeLabel);
      });
      wave.addEventListener('click', (ev)=>{
        ev.stopPropagation();
        const dur = activeVoiceAudio ? voiceDur(activeVoiceAudio) : 0;
        if(activeVoiceAudio && activeVoiceWave === wave && dur > 0){
          const rect = wave.getBoundingClientRect();
          const frac = Math.min(1, Math.max(0, (ev.clientX-rect.left)/rect.width));
          activeVoiceAudio.currentTime = frac*dur;
        }
      });
    });
    box.querySelectorAll('.roundvideo-msg').forEach(el=>{
      const video = el.querySelector('.roundvideo-bubble-video');
      const overlay = el.querySelector('.roundvideo-play-overlay');
      const src = el.getAttribute('data-src');
      let loaded = false, loading = false;
      video.addEventListener('loadedmetadata', ()=>{
        if(!isFinite(video.duration)){
          video.currentTime = 1e101;
          const fixDuration = ()=>{ video.removeEventListener('timeupdate', fixDuration); video.currentTime = 0; };
          video.addEventListener('timeupdate', fixDuration);
        }
      });
      video.addEventListener('playing', ()=>{
        video.muted = false;
        overlay.classList.add('hidden');
      });
      video.addEventListener('pause', ()=>{ overlay.classList.remove('hidden'); });
      video.addEventListener('ended', ()=>{ overlay.classList.remove('hidden'); });
      video.addEventListener('error', ()=>{
        console.error('roundvideo load error', video.error);
        toast('Не удалось загрузить видео');
      });
      function tryPlay(){
        video.muted = true;
        const p = video.play();
        if(p && p.catch) p.catch((err)=>{
          console.error('roundvideo play failed', err);
          toast('Не удалось воспроизвести видео');
        });
      }
      el.addEventListener('click', async (ev)=>{
        ev.stopPropagation();
        document.querySelectorAll('.roundvideo-bubble-video').forEach(v=>{ if(v!==video && !v.paused){ v.pause(); } });
        if(!video.paused){ video.pause(); return; }
        if(loaded){ tryPlay(); return; }
        if(loading) return;
        loading = true;
        try{
          // Переводим data URL обратно в blob-ссылку — это единственный путь, который
          // подтверждённо работает (то же самое использует экран предпросмотра перед отправкой),
          // вместо прямого присваивания длинной строки data URL в src.
          const resp = await fetch(src);
          const blob = await resp.blob();
          video.src = URL.createObjectURL(blob);
          loaded = true; loading = false;
          tryPlay();
        }catch(err){
          loading = false;
          console.error('roundvideo blob conversion failed', err);
          toast('Не удалось загрузить видео');
        }
      });
    });
    box.querySelectorAll('.contact-card').forEach(el=>{
      const cuid = el.getAttribute('data-cuid');
      if(!cuid) return;
      el.addEventListener('click', (ev)=>{
        ev.stopPropagation();
        openUserInfo(cuid);
      });
    });
    box.querySelectorAll('.reply-icon-btn').forEach(btn=>{
      btn.addEventListener('click', (ev)=>{
        ev.stopPropagation();
        const id = btn.getAttribute('data-reply-id');
        const m = state.currentMessages.find(x=>x.id===id);
        if(m) setReplyContext(m);
      });
    });
    box.querySelectorAll('.react-icon-btn').forEach(btn=>{
      btn.addEventListener('click', (ev)=>{
        ev.stopPropagation();
        openReactionPopup(btn.getAttribute('data-react-id'), btn);
      });
    });
    box.querySelectorAll('.reaction-chip').forEach(chip=>{
      chip.addEventListener('click', (ev)=>{
        ev.stopPropagation();
        toggleReaction(chip.getAttribute('data-react-toggle-msg'), chip.getAttribute('data-react-toggle-emoji'));
      });
    });
  }
  if(wasNearBottom || skipAnim || lastIsNewMine){
    box.scrollTop = box.scrollHeight;
    msgStickBottom = true;           // держим низ, пока догружаются фото, голосовые, группировка
    scheduleStickToBottom();
  }else{
    box.scrollTop = prevScrollTop;
    if(lastIsNewIncoming) markScrollDownNew();
  }
  if(wasNearBottom || skipAnim){
    box.querySelectorAll('.msg-img').forEach(img=>{
      if(!img.complete){
        img.addEventListener('load', ()=>{ box.scrollTop = box.scrollHeight; }, {once:true});
      }
    });
  }
  if(state.msgSelectMode) updateMsgSelectCount();
}

function enterMsgSelectMode(){
  if(!state.activeChatId) return;
  state.msgSelectMode = true; state.selectedMessages = new Set();
  document.getElementById('chat-header-normal').style.display = 'none';
  document.getElementById('chat-header-select').style.display = 'flex';
  renderMessages(state.currentMessages);
}
function exitMsgSelectMode(){
  state.msgSelectMode = false; state.selectedMessages = new Set();
  document.getElementById('chat-header-normal').style.display = 'flex';
  document.getElementById('chat-header-select').style.display = 'none';
  renderMessages(state.currentMessages);
}
function updateMsgSelectCount(){
  const el = document.getElementById('msg-select-count');
  if(el) el.textContent = 'Выбрано: '+state.selectedMessages.size;
}
async function refreshChatPreview(chatId){
  try{
    // Порядок по возрастанию — переиспользует уже существующий индекс (chatId + timestamp asc),
    // созданный для самой переписки. Запрос по убыванию требовал бы отдельного, ещё не
    // созданного индекса и раньше тихо проваливался каждый раз — превью из-за этого никогда
    // не обновлялось при удалении сообщения, при том что сама функция вызывалась исправно
    const snap = await db.collection('messages').where('chatId','==',chatId).orderBy('timestamp','asc').get();
    if(snap.empty){
      await db.collection('chats').doc(chatId).update({lastMessage:'', lastType:'text', lastFrom:'', lastMessageExpireAt: null});
    }else{
      const m = snap.docs[snap.docs.length-1].data();
      await db.collection('chats').doc(chatId).update({
        lastMessage: m.type==='image' ? 'Изображение' : m.type==='video' ? 'Видео' : m.type==='file' ? (m.fileName||'Файл') : m.type==='voice' ? 'Голосовое сообщение' : m.type==='roundvideo' ? 'Видеосообщение' : m.type==='contact' ? 'Контакт' : m.type==='call' ? callPreviewText({callOutcome:m.callOutcome, callType:m.callType}) : (m.content||'').slice(0,80),
        lastType: m.type, lastTimestamp: m.timestamp, lastFrom: m.from, lastMessageExpireAt: m.expireAt||null
      });
    }
  }catch(e){ console.error('refreshChatPreview failed for chatId='+chatId, e); }
}
async function deleteSelectedMessages(){
  if(!state.selectedMessages.size) return;
  if(!await uiConfirm('Удалить выбранные сообщения ('+state.selectedMessages.size+')? Удалятся полностью — и у вас, и у собеседника.')) return;
  const ids = Array.from(state.selectedMessages);
  const chatId = state.activeChatId;
  for(const id of ids){
    try{ await db.collection('messages').doc(id).delete(); }catch(e){}
  }
  if(chatId) await refreshChatPreview(chatId);
  exitMsgSelectMode();
}
document.getElementById('msg-select-toggle').onclick = enterMsgSelectMode;
document.getElementById('msg-select-cancel').onclick = exitMsgSelectMode;
document.getElementById('msg-select-all').onclick = ()=>{
  state.currentMessages.forEach(m=>state.selectedMessages.add(m.id));
  renderMessages(state.currentMessages);
};
document.getElementById('msg-select-forward').onclick = openForwardMessagesPicker;
document.getElementById('msg-select-delete').onclick = deleteSelectedMessages;

