function clearReplyContext(){
  state.replyingTo = null;
  const bar = document.getElementById('reply-preview-bar');
  if(bar) bar.style.display = 'none';
}
document.getElementById('reply-cancel-btn').onclick = clearReplyContext;

const REACTION_EMOJIS = ['👍','👎','❤️','🧡','💛','💚','💙','💜','🖤','🤍','💔','💕','💞','💓','💗','💖','😀','😁','😂','🤣','😊','😇','🙂','😉','😍','🥰','😘','😋','😎','🥳','😏','🙄','😴','🤔','🤗','🤭','🤫','🤥','😐','😯','😦','😮','😲','🥺','😢','😭','😡','🤬','🤯','😳','🥵','🥶','😱','😨','😷','🤒','🤕','🤑','😈','👻','🙈','👋','✌️','🤞','👊','👏','🙌','🙏','🔥','💯'];
// Живые эмодзи — обычные символы, но каждый с закреплённым типом CSS-анимации, применяется
// как в самом попапе выбора (превью двигается прямо в кнопке), так и при показе уже отправленных
const LIVE_EMOJIS = [
  {e:'❤️', a:'live-pulse'}, {e:'😍', a:'live-pulse'}, {e:'🙏', a:'live-pulse'},
  {e:'🥰', a:'live-pulse'}, {e:'😘', a:'live-pulse'}, {e:'💕', a:'live-pulse'},
  {e:'💞', a:'live-pulse'}, {e:'💓', a:'live-pulse'}, {e:'💗', a:'live-pulse'}, {e:'💖', a:'live-pulse'},
  {e:'🧡', a:'live-pulse'}, {e:'💛', a:'live-pulse'}, {e:'💚', a:'live-pulse'}, {e:'💙', a:'live-pulse'}, {e:'💜', a:'live-pulse'},
  {e:'🔥', a:'live-flicker'}, {e:'⚡', a:'live-flicker'},
  {e:'⭐', a:'live-twinkle'}, {e:'✨', a:'live-twinkle'}, {e:'🌟', a:'live-twinkle'}, {e:'💫', a:'live-twinkle'},
  {e:'🎉', a:'live-bounce'}, {e:'🥳', a:'live-bounce'}, {e:'💯', a:'live-bounce'},
  {e:'🙌', a:'live-bounce'}, {e:'👏', a:'live-bounce'}, {e:'🎈', a:'live-bounce'},
  {e:'👍', a:'live-tilt'}, {e:'💪', a:'live-tilt'}, {e:'✌️', a:'live-tilt'}, {e:'🤞', a:'live-tilt'}, {e:'👊', a:'live-tilt'},
  {e:'😂', a:'live-shake'}, {e:'💔', a:'live-shake'}, {e:'🤣', a:'live-shake'},
  {e:'😱', a:'live-shake'}, {e:'😨', a:'live-shake'}, {e:'🤬', a:'live-shake'},
  {e:'🎊', a:'live-spin-bounce'}, {e:'🎆', a:'live-spin-bounce'},
  {e:'😢', a:'live-drip'}, {e:'😭', a:'live-drip'}, {e:'🥺', a:'live-drip'},
  {e:'😉', a:'live-wobble'}, {e:'😏', a:'live-wobble'}, {e:'🙂', a:'live-wobble'}, {e:'😜', a:'live-wobble'},
  {e:'🍀', a:'live-float'}, {e:'🌈', a:'live-float'}, {e:'☁️', a:'live-float'},
  {e:'😮', a:'live-jump'}, {e:'😲', a:'live-jump'}, {e:'🤯', a:'live-jump'}, {e:'👻', a:'live-jump'},
];
function liveEmojiSpan(item){
  return `<span class="live-emoji ${item.a}">${item.e}</span>`;
}
const LIVE_EMOJI_MAP = Object.fromEntries(LIVE_EMOJIS.map(item=>[item.e, item.a]));
function maybeLiveEmoji(char){
  const anim = LIVE_EMOJI_MAP[char];
  return anim ? `<span class="live-emoji ${anim}">${char}</span>` : char;
}
function animateLiveEmojisInText(text){
  // Заменяет в обычном тексте сообщения символы живых эмодзи на анимированные —
  // работает для любого текста независимо от того, откуда взялся эмодзи (клавиатура, вставка, подвкладка «Живые»)
  let result = escapeHtml(text);
  LIVE_EMOJIS.forEach(item=>{
    if(text.includes(item.e)){
      const escaped = escapeHtml(item.e);
      result = result.split(escaped).join(`<span class="live-emoji ${item.a}">${escaped}</span>`);
    }
  });
  return result;
}
let reactionPopupTab = 'normal';
function renderReactionPopupGrid(){
  const popup = document.getElementById('reaction-popup');
  const grid = popup.querySelector('#reaction-popup-grid');
  if(!grid) return;
  grid.innerHTML = reactionPopupTab === 'live'
    ? LIVE_EMOJIS.map(item=>`<button type="button" data-pick-emoji="${item.e}">${liveEmojiSpan(item)}</button>`).join('')
    : REACTION_EMOJIS.map(e=>`<button type="button" data-pick-emoji="${e}">${e}</button>`).join('');
}
function openReactionPopup(msgId, anchorEl){
  const popup = document.getElementById('reaction-popup');
  reactionPopupTab = 'normal';
  popup.innerHTML = `
    <div class="reaction-popup-tabs">
      <button type="button" class="active" data-rp-tab="normal">Обычные</button>
      <button type="button" data-rp-tab="live">✨ Живые</button>
    </div>
    <div id="reaction-popup-grid" class="reaction-popup-grid"></div>`;
  renderReactionPopupGrid();
  popup.style.display = 'flex';
  const rect = anchorEl.getBoundingClientRect();
  const popupWidth = popup.offsetWidth || 300;
  const popupHeight = popup.offsetHeight || 150;
  let left = rect.left - popupWidth/2 + rect.width/2;
  left = Math.max(8, Math.min(left, window.innerWidth - popupWidth - 8));
  popup.style.left = left + 'px';
  popup.style.top = Math.max(8, rect.top - popupHeight - 10) + 'px';
  popup.querySelectorAll('[data-rp-tab]').forEach(tabBtn=>{
    tabBtn.onclick = (ev)=>{
      ev.stopPropagation();
      reactionPopupTab = tabBtn.getAttribute('data-rp-tab');
      popup.querySelectorAll('[data-rp-tab]').forEach(b=> b.classList.toggle('active', b===tabBtn));
      renderReactionPopupGrid();
      wireReactionPopupEmojiButtons(msgId, popup);
    };
  });
  wireReactionPopupEmojiButtons(msgId, popup);
}
function wireReactionPopupEmojiButtons(msgId, popup){
  popup.querySelectorAll('[data-pick-emoji]').forEach(btn=>{
    btn.onclick = (ev)=>{
      ev.stopPropagation();
      toggleReaction(msgId, btn.getAttribute('data-pick-emoji'));
      popup.style.display = 'none';
    };
  });
}
document.addEventListener('click', (ev)=>{
  const popup = document.getElementById('reaction-popup');
  if(popup.style.display!=='none' && !popup.contains(ev.target) && !ev.target.classList.contains('react-icon-btn')){
    popup.style.display = 'none';
  }
});
async function toggleReaction(msgId, emoji){
  const mine = state.currentUser.uid;
  try{
    const ref = db.collection('messages').doc(msgId);
    const snap = await ref.get();
    if(!snap.exists) return;
    let reactions = snap.data().reactions || [];
    const idx = reactions.findIndex(r=>r.emoji===emoji && r.uid===mine);
    if(idx >= 0) reactions = reactions.filter((_,i)=>i!==idx);
    else reactions = reactions.concat([{emoji, uid: mine}]);
    await ref.update({reactions});
  }catch(e){ toast('Не удалось поставить реакцию'); }
}

async function doSend(){
  if(!state.activeChatId) return;
  document.getElementById('emoji-panel').style.display = 'none';
  document.getElementById('attach-menu').style.display = 'none';
  const input = document.getElementById('msg-input');
  const text = input.value.trim();
  if(state.editingMessageId){
    if(!text){ toast('Введите текст сообщения'); return; }
    const sendBtn = document.getElementById('send-btn');
    sendBtn.disabled = true;
    try{
      await db.collection('messages').doc(state.editingMessageId).update({content: text, edited: true});
      await refreshChatPreview(state.activeChatId);
      input.value = ''; input.style.height = 'auto'; updateSendBtnVisibility();
      clearEditContext();
    }catch(e){ toast('Не удалось сохранить изменения'); }
    sendBtn.disabled = false;
    return;
  }
  const images = state.pendingImages.slice();
  const files = state.pendingFiles.slice();
  if(!text && images.length === 0 && files.length === 0) return;
  const sendBtn = document.getElementById('send-btn');
  sendBtn.disabled = true;
  let replyExtra = state.replyingTo ? {replyTo: state.replyingTo} : undefined;
  try{
    if(text){ await sendMessage(state.activeChatId, 'text', text, null, replyExtra); replyExtra = undefined; }
    for(const im of images){ await sendMessage(state.activeChatId, 'image', im.dataUrl, im.name, replyExtra); replyExtra = undefined; }
    for(const f of files){ await sendMessage(state.activeChatId, 'file', f.dataUrl, f.name, replyExtra); replyExtra = undefined; }
    input.value = ''; input.style.height = 'auto'; updateSendBtnVisibility();
    state.pendingImages = []; renderImgPreviews();
    state.pendingFiles = []; renderFilePreviews();
    clearReplyContext();
  }catch(e){
    toast('Не удалось отправить: возможно, аккаунт заблокирован');
  }
  sendBtn.disabled = false;
}

/* ============================================================
   АДМИН-ПАНЕЛЬ
============================================================ */
function openAdmin(){
  document.getElementById('admin-overlay').style.display = 'flex';
  switchAdminTab('users');
}
function closeAdmin(){
  document.getElementById('admin-overlay').style.display = 'none';
  if(state.unsubAdminUsers) state.unsubAdminUsers();
  if(state.unsubAdminChats) state.unsubAdminChats();
  if(state.unsubAdminSupport) state.unsubAdminSupport();
}
function switchAdminTab(tab){
  state.adminTab = tab;
  document.querySelectorAll('.admin-tab-btn').forEach(b=>b.classList.toggle('active', b.getAttribute('data-tab')===tab));
  if(state.unsubAdminUsers){ state.unsubAdminUsers(); state.unsubAdminUsers=null; }
  if(state.unsubAdminChats){ state.unsubAdminChats(); state.unsubAdminChats=null; }
  if(state.unsubAdminSupport){ state.unsubAdminSupport(); state.unsubAdminSupport=null; }
  if(tab === 'users') renderAdminUsers();
  else if(tab === 'chats') renderAdminChats();
  else if(tab === 'support') renderAdminSupport();
  else if(tab === 'broadcast') renderAdminBroadcast();
  else renderAdminServer();
}

function renderAdminUsers(){
  const body = document.getElementById('admin-body');
  body.innerHTML = `
    <div class="search-note" style="margin-bottom:10px;">Пароли хранит и защищает сам сервис Firebase Authentication отдельно от этой базы — их не может увидеть даже администратор.</div>
    <input type="text" id="admin-users-search" placeholder="Поиск по нику или email..." style="width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:10px;font-size:calc(13.5px * var(--font-scale));background:#FAFBFD;margin-bottom:8px;">
    <div id="admin-users-count" style="font-size:calc(12.5px * var(--font-scale));color:var(--text-muted);margin-bottom:10px;"></div>
    <div id="admin-users-list"></div>`;
  let allUsers = [];
  function renderFilteredUsers(){
    const q = document.getElementById('admin-users-search').value.trim().toLowerCase();
    const users = q ? allUsers.filter(u => (u.username||'').toLowerCase().includes(q) || (u.email||'').toLowerCase().includes(q)) : allUsers;
    document.getElementById('admin-users-count').textContent = 'Всего зарегистрировано: '+allUsers.length + (q ? ' · найдено: '+users.length : '');
    const list = document.getElementById('admin-users-list');
    if(!list) return;
    if(!allUsers.length){ list.innerHTML = `<div class="empty-list">Пользователей пока нет.</div>`; return; }
    if(!users.length){ list.innerHTML = `<div class="empty-list">Никого не найдено.</div>`; return; }
    list.innerHTML = users.map(u=>{
      const uRealName = realNameOf(u);
      const shownTitle = uRealName ? `${escapeHtml(uRealName)} (${escapeHtml(u.username)})` : escapeHtml(u.username);
      return `
      <div class="row-card">
        <div class="avatar" data-avatar-uid="${escapeHtml(u.uid)}" data-info-btn="1" style="cursor:pointer;">${initials(uRealName || u.username)}</div>
        <div class="info">
          <div class="title">${shownTitle} ${u.isAdmin ? '<span class="badge admin">админ</span>' : ''} ${u.blocked ? '<span class="badge blocked">заблокирован</span>' : '<span class="badge active">активен</span>'}</div>
          <div class="meta">${escapeHtml(u.email)} · регистрация: ${fmtDate(u.createdAt)} · была(о) в сети: ${u.lastActive ? fmtDate(u.lastActive) : '—'}</div>
        </div>
        <div class="row-actions">
          ${u.isAdmin ? '' : `<button class="btn-sm secondary" data-act="block" data-uid="${escapeHtml(u.uid)}" data-username="${escapeHtml(u.username)}" data-val="${!u.blocked}">${u.blocked?'Разблокировать':'Заблокировать'}</button>`}
          ${u.isAdmin ? '' : `<button class="btn-sm danger" data-act="delete" data-uid="${escapeHtml(u.uid)}" data-username="${escapeHtml(u.username)}" data-email="${escapeHtml(u.email)}">Удалить</button>`}
        </div>
      </div>`;
    }).join('');
    enrichAvatars(list, users.map(u=>u.uid));
    list.querySelectorAll('.avatar[data-info-btn]').forEach(el=>{
      el.addEventListener('click', (ev)=>{ ev.stopPropagation(); openUserInfo(el.getAttribute('data-avatar-uid')); });
    });
    list.querySelectorAll('[data-act="block"]').forEach(btn=>{
      btn.onclick = async ()=>{
        const uid = btn.getAttribute('data-uid');
        const uname = btn.getAttribute('data-username');
        const val = btn.getAttribute('data-val') === 'true';
        if(!await uiConfirm((val?'Заблокировать ':'Разблокировать ')+uname+'?')) return;
        try{
          await db.collection('users').doc(uid).update({blocked: val});
          toast(val ? 'Пользователь заблокирован' : 'Пользователь разблокирован');
        }catch(e){ toast('Действие отклонено сервером: недостаточно прав'); }
      };
    });
    list.querySelectorAll('[data-act="delete"]').forEach(btn=>{
      btn.onclick = async ()=>{
        const uid = btn.getAttribute('data-uid');
        const username = btn.getAttribute('data-username');
        const email = btn.getAttribute('data-email');
        if(!await uiConfirm(`Удалить аккаунт ${username} (${email})? Профиль и переписка станут недоступны. Действие необратимо.`)) return;
        try{
          await adminDeleteUserRecord(uid, username, email);
          toast('Аккаунт удалён из базы. Учтите: запись в Firebase Authentication нужно дополнительно удалить в консоли (Authentication → Users) — это делает только владелец проекта.');
        }catch(e){ toast('Действие отклонено сервером: недостаточно прав'); }
      };
    });
  }
  document.getElementById('admin-users-search').addEventListener('input', renderFilteredUsers);
  state.unsubAdminUsers = db.collection('users').orderBy('createdAt','desc').onSnapshot(snap=>{
    allUsers = snap.docs.map(d=>d.data());
    renderFilteredUsers();
  });
}
async function adminDeleteUserRecord(uid, username, email){
  await db.collection('users').doc(uid).delete();
  await db.collection('usernames').doc(normUser(username)).delete();
  await db.collection('emails').doc(normEmail(email)).delete();
}

function renderAdminSupport(){
  const body = document.getElementById('admin-body');
  body.innerHTML = `<div class="search-note" style="margin-bottom:10px;">Обращения пользователей в поддержку. Нажмите на человека, чтобы открыть и ответить как в обычном чате.</div>
    <input type="text" id="admin-support-search" placeholder="Поиск по нику..." style="width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:10px;font-size:calc(13.5px * var(--font-scale));background:#FAFBFD;margin-bottom:10px;">
    <div class="chat-list" id="admin-support-list" style="padding:0;"></div>`;
  let allChats = [];
  function renderFilteredSupport(){
    const q = document.getElementById('admin-support-search').value.trim().toLowerCase();
    const list = document.getElementById('admin-support-list');
    if(!list) return;
    if(!allChats.length){ list.innerHTML = `<div class="empty-list">Пока никто не писал в поддержку.</div>`; return; }
    const chats = q ? allChats.filter(c=>{
      const ownerUid = c.participants[0];
      const uname = (c.usernames && c.usernames[ownerUid]) || ownerUid;
      return uname.toLowerCase().includes(q);
    }) : allChats;
    if(!chats.length){ list.innerHTML = `<div class="empty-list">Никого не найдено.</div>`; return; }
    list.innerHTML = chats.map(c=>{
      const ownerUid = c.participants[0];
      const uname = (c.usernames && c.usernames[ownerUid]) || ownerUid;
      const unread = isChatUnread(c);
      const preview = c.lastMessage ? escapeHtml(c.lastMessage) : 'Нет сообщений';
      return `<div class="chat-item ${unread?'unread':''}" data-chat-id="${escapeHtml(c.id)}">
        <div class="avatar" data-avatar-uid="${escapeHtml(ownerUid)}">${initials(uname)}</div>
        <div class="info">
          <div class="top-row"><div class="name">${escapeHtml(uname)}</div><div class="time">${c.lastTimestamp ? fmtTime(c.lastTimestamp) : ''}</div></div>
          <div class="preview">${preview}${unread?'<span class="unread-dot"></span>':''}</div>
        </div>
      </div>`;
    }).join('');
    enrichAvatars(list, chats.map(c=>c.participants[0]));
    list.querySelectorAll('.chat-item').forEach(el=>{
      el.onclick = ()=>{
        const chatId = el.getAttribute('data-chat-id');
        closeAdmin();
        switchTab('chats');
        openChat(chatId);
      };
    });
  }
  document.getElementById('admin-support-search').addEventListener('input', renderFilteredSupport);
  state.unsubAdminSupport = db.collection('chats').where('isSupport','==',true).onSnapshot(snap=>{
    allChats = snap.docs.map(d=>d.data()).sort((a,b)=>(b.lastTimestamp||0)-(a.lastTimestamp||0));
    renderFilteredSupport();
  }, err=>{
    document.getElementById('admin-support-list').innerHTML = `<div class="error-box">Не удалось загрузить: ${escapeHtml(err.message)}</div>`;
  });
}

function renderAdminBroadcast(){
  const body = document.getElementById('admin-body');
  body.innerHTML = `
    <div class="search-note" style="margin-bottom:10px;">Сообщение придёт получателям в «Поддержку» — отправитель будет обозначен как «Поддержка».</div>
    <input type="text" id="bc-search" placeholder="Поиск по нику или email..." style="width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:10px;font-size:calc(13.5px * var(--font-scale));background:#FAFBFD;margin-bottom:8px;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
      <button class="btn-link" id="bc-select-all">Выбрать всех</button>
      <div id="bc-count" style="font-size:calc(12.5px * var(--font-scale));color:var(--text-muted);">Выбрано: 0</div>
    </div>
    <div class="chat-list" id="bc-user-list" style="padding:0;max-height:260px;overflow-y:auto;border:1px solid var(--border);border-radius:10px;margin-bottom:14px;"></div>
    <div class="field"><label>Текст сообщения</label><textarea id="bc-text" rows="3" style="width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:10px;font-size:calc(13.5px * var(--font-scale));background:#FAFBFD;resize:vertical;"></textarea></div>
    <div class="field"><label>Изображение (необязательно)</label><input type="file" id="bc-image-input" accept="image/*"></div>
    <div id="bc-image-preview"></div>
    <button class="btn-primary" id="bc-send">Отправить</button>
    <div id="bc-msg"></div>
  `;
  let allUsers = [];
  const selected = new Set();
  let pendingImage = null;
  function renderBcList(){
    const q = document.getElementById('bc-search').value.trim().toLowerCase();
    const users = q ? allUsers.filter(u=>(u.username||'').toLowerCase().includes(q) || (u.email||'').toLowerCase().includes(q)) : allUsers;
    const list = document.getElementById('bc-user-list');
    if(!users.length){ list.innerHTML = `<div class="empty-list">Никого не найдено.</div>`; }
    else{
      list.innerHTML = users.map(u=>{
        const checked = selected.has(u.uid);
        return `<div class="chat-item" style="cursor:pointer;margin-bottom:0;border-radius:0;border-bottom:1px solid var(--border);" data-uid="${escapeHtml(u.uid)}">
          <div class="select-dot ${checked?'checked':''}">${checked?'✓':''}</div>
          <div class="avatar" data-avatar-uid="${escapeHtml(u.uid)}">${initials(u.username)}</div>
          <div class="info"><div class="name">${escapeHtml(u.username)}</div><div class="preview">${escapeHtml(u.email)}</div></div>
        </div>`;
      }).join('');
      enrichAvatars(list, users.map(u=>u.uid));
      list.querySelectorAll('.chat-item').forEach(el=>{
        el.onclick = ()=>{
          const uid = el.getAttribute('data-uid');
          if(selected.has(uid)) selected.delete(uid); else selected.add(uid);
          renderBcList();
        };
      });
    }
    document.getElementById('bc-count').textContent = 'Выбрано: '+selected.size;
  }
  document.getElementById('bc-search').addEventListener('input', renderBcList);
  document.getElementById('bc-select-all').onclick = ()=>{
    const q = document.getElementById('bc-search').value.trim().toLowerCase();
    const users = q ? allUsers.filter(u=>(u.username||'').toLowerCase().includes(q) || (u.email||'').toLowerCase().includes(q)) : allUsers;
    const allSel = users.length>0 && users.every(u=>selected.has(u.uid));
    if(allSel) users.forEach(u=>selected.delete(u.uid));
    else users.forEach(u=>selected.add(u.uid));
    renderBcList();
  };
  document.getElementById('bc-image-input').addEventListener('change', async (e)=>{
    const f = e.target.files[0];
    if(!f) return;
    try{
      pendingImage = await resizeImageFile(f);
      document.getElementById('bc-image-preview').innerHTML = `<img src="${pendingImage}" style="max-width:120px;border-radius:8px;margin:6px 0;">`;
    }catch(err){ toast('Не удалось загрузить изображение'); }
  });
  document.getElementById('bc-send').onclick = async ()=>{
    const text = document.getElementById('bc-text').value.trim();
    const msgEl = document.getElementById('bc-msg');
    if(!selected.size){ msgEl.innerHTML = `<div class="error-box">Выберите хотя бы одного получателя.</div>`; return; }
    if(!text && !pendingImage){ msgEl.innerHTML = `<div class="error-box">Введите текст или прикрепите изображение.</div>`; return; }
    if(!await uiConfirm('Отправить сообщение выбранным пользователям ('+selected.size+')?')) return;
    const btn = document.getElementById('bc-send');
    btn.disabled = true; btn.textContent = 'Отправляем…';
    const uids = Array.from(selected);
    let ok = 0;
    for(const uid of uids){
      try{
        const meta = await ensureSupportChat(uid, false);
        if(text) await sendMessage(meta.id, 'text', text);
        if(pendingImage) await sendMessage(meta.id, 'image', pendingImage, 'broadcast.jpg');
        ok++;
      }catch(e){}
    }
    btn.disabled = false; btn.textContent = 'Отправить';
    msgEl.innerHTML = `<div class="info-box">Отправлено: ${ok} из ${uids.length}.</div>`;
    document.getElementById('bc-text').value = '';
    document.getElementById('bc-image-preview').innerHTML = '';
    document.getElementById('bc-image-input').value = '';
    pendingImage = null;
  };
  db.collection('users').orderBy('username').get().then(snap=>{
    allUsers = snap.docs.map(d=>d.data());
    renderBcList();
  }).catch(()=>{
    document.getElementById('bc-user-list').innerHTML = `<div class="error-box">Не удалось загрузить список пользователей.</div>`;
  });
}

function renderAdminChats(){
  const body = document.getElementById('admin-body');
  body.innerHTML = `<div class="search-note" style="margin-bottom:10px;">Кто с кем и когда переписывался. Содержимое сообщений отсюда недоступно даже администратору — это ограничено правилами Firestore на сервере.</div>
    <input type="text" id="admin-chats-search" placeholder="Поиск по нику или email участника..." style="width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:10px;font-size:calc(13.5px * var(--font-scale));background:#FAFBFD;margin-bottom:10px;">
    <div id="admin-chats-list"></div>`;
  let allChats = [];
  function renderFilteredChats(){
    const q = document.getElementById('admin-chats-search').value.trim().toLowerCase();
    const chats = q ? allChats.filter(c=>{
      const names = (c.participants||[]).map(p => ((c.usernames && c.usernames[p]) || '').toLowerCase());
      const mails = (c.participants||[]).map(p => ((c.emails && c.emails[p]) || '').toLowerCase());
      return names.some(n=>n.includes(q)) || mails.some(m=>m.includes(q));
    }) : allChats;
    const list = document.getElementById('admin-chats-list');
    if(!list) return;
    if(!allChats.length){ list.innerHTML = `<div class="empty-list">Чатов пока нет.</div>`; return; }
    if(!chats.length){ list.innerHTML = `<div class="empty-list">Никого не найдено.</div>`; return; }
    list.innerHTML = chats.map(c=>{
      const names = (c.participants||[]).map(p => (c.usernames && c.usernames[p]) || p);
      const mails = (c.participants||[]).map(p => (c.emails && c.emails[p]) || '').filter(Boolean);
      return `<div class="row-card">
        <div class="info">
          <div class="title">${c.isSupport ? '☎ Поддержка · '+escapeHtml(names[0]) : escapeHtml(names[0])+' ↔ '+escapeHtml(names[1]||'—')}</div>
          <div class="meta">${escapeHtml(mails.join(' · '))}</div>
          <div class="meta">создан: ${fmtDate(c.createdAt)} · последнее сообщение: ${c.lastTimestamp ? fmtDate(c.lastTimestamp) : '—'} · сообщений: ${c.messageCount||0}</div>
        </div>
      </div>`;
    }).join('');
  }
  document.getElementById('admin-chats-search').addEventListener('input', renderFilteredChats);
  state.unsubAdminChats = db.collection('chats').orderBy('lastTimestamp','desc').onSnapshot(snap=>{
    allChats = snap.docs.map(d=>d.data());
    renderFilteredChats();
  }, err=>{
    document.getElementById('admin-chats-list').innerHTML = `<div class="error-box">Не удалось загрузить: ${escapeHtml(err.message)}</div>`;
  });
}

function renderAdminServer(){
  const body = document.getElementById('admin-body');
  body.innerHTML = `
    <div class="server-status ok">Подключено к проекту: ${escapeHtml(firebaseConfig.projectId)}</div>
    <div class="field"><label>apiKey</label><input id="as-apiKey" value="${escapeHtml(firebaseConfig.apiKey)}"></div>
    <div class="field"><label>authDomain</label><input id="as-authDomain" value="${escapeHtml(firebaseConfig.authDomain)}"></div>
    <div class="field"><label>projectId</label><input id="as-projectId" value="${escapeHtml(firebaseConfig.projectId)}"></div>
    <div class="field"><label>storageBucket</label><input id="as-storageBucket" value="${escapeHtml(firebaseConfig.storageBucket)}"></div>
    <div class="field"><label>messagingSenderId</label><input id="as-messagingSenderId" value="${escapeHtml(firebaseConfig.messagingSenderId)}"></div>
    <div class="field"><label>appId</label><input id="as-appId" value="${escapeHtml(firebaseConfig.appId)}"></div>
    <button class="btn-primary" id="as-save">Сохранить и переподключиться</button>
    <p class="hint">Изменения действуют до перезагрузки страницы. Чтобы сохранить насовсем — впишите те же значения в объект firebaseConfig в начале файла.</p>
    <div id="as-msg"></div>
  `;
  document.getElementById('as-save').onclick = async ()=>{
    const btn = document.getElementById('as-save');
    btn.disabled = true; btn.textContent = 'Подключаемся…';
    firebaseConfig = {
      apiKey: document.getElementById('as-apiKey').value.trim(),
      authDomain: document.getElementById('as-authDomain').value.trim(),
      projectId: document.getElementById('as-projectId').value.trim(),
      storageBucket: document.getElementById('as-storageBucket').value.trim(),
      messagingSenderId: document.getElementById('as-messagingSenderId').value.trim(),
      appId: document.getElementById('as-appId').value.trim(),
    };
    const res = await tryInitFirebase();
    btn.disabled = false; btn.textContent = 'Сохранить и переподключиться';
    const msg = document.getElementById('as-msg');
    msg.innerHTML = res.ok ? `<div class="info-box">Подключение обновлено.</div>` : `<div class="error-box">${escapeHtml(res.error)}</div>`;
  };

  const inviteWrap = document.createElement('div');
  inviteWrap.style.marginTop = '22px';
  inviteWrap.style.borderTop = '1px solid var(--border)';
  inviteWrap.style.paddingTop = '16px';
  inviteWrap.innerHTML = `
    <div class="field"><label>Ссылка-приглашение (видна пользователям в профиле, если заполнена)</label>
      <input id="as-invite" value="${escapeHtml((state.appConfig && state.appConfig.inviteLink) || '')}" placeholder="https://…"></div>
    <button class="btn-primary" id="as-invite-save">Сохранить ссылку</button>
    <div id="as-invite-msg"></div>
  `;
  body.appendChild(inviteWrap);
  document.getElementById('as-invite-save').onclick = async ()=>{
    const btn = document.getElementById('as-invite-save');
    const link = document.getElementById('as-invite').value.trim();
    btn.disabled = true; btn.textContent = 'Сохраняем…';
    try{
      await db.collection('config').doc('app').set({inviteLink: link}, {merge:true});
      state.appConfig = Object.assign({}, state.appConfig, {inviteLink: link});
      document.getElementById('as-invite-msg').innerHTML = `<div class="info-box">Сохранено.</div>`;
      renderProfile();
    }catch(e){
      document.getElementById('as-invite-msg').innerHTML = `<div class="error-box">Не удалось сохранить.</div>`;
    }
    btn.disabled = false; btn.textContent = 'Сохранить ссылку';
  };

  const callMethodWrap = document.createElement('div');
  callMethodWrap.style.marginTop = '22px';
  callMethodWrap.style.borderTop = '1px solid var(--border)';
  callMethodWrap.style.paddingTop = '16px';
  const turnOn = state.appConfig && state.appConfig.useTurnServer !== false;
  callMethodWrap.innerHTML = `
    <div style="font-size:calc(14px * var(--font-scale));font-weight:600;margin-bottom:4px;">Способ соединения звонков</div>
    <p class="hint" style="margin-bottom:10px;">При включённом — новый метод: перед каждым звонком запрашиваются свежие данные TURN-сервера (Metered), помогает на мобильном интернете, но расходует бесплатную квоту трафика. При выключенном — старый метод: только STUN-серверы, без TURN, квота не расходуется вовсе, но на мобильном интернете с жёстким NAT звонок может не пройти.</p>
    <div style="display:flex;align-items:center;gap:10px;">
      <label class="toggle-switch"><input type="checkbox" id="as-call-method" ${turnOn?'checked':''}><span class="toggle-slider"></span></label>
      <span id="as-call-method-label" style="font-size:calc(13px * var(--font-scale));">${turnOn ? 'Новый метод (с TURN-сервером)' : 'Старый метод (только STUN)'}</span>
    </div>
    <div id="as-call-method-msg" style="margin-top:8px;"></div>
  `;
  body.appendChild(callMethodWrap);
  document.getElementById('as-call-method').addEventListener('change', async (ev)=>{
    const enabled = ev.target.checked;
    document.getElementById('as-call-method-label').textContent = enabled ? 'Новый метод (с TURN-сервером)' : 'Старый метод (только STUN)';
    try{
      await db.collection('config').doc('app').set({useTurnServer: enabled}, {merge:true});
      state.appConfig = Object.assign({}, state.appConfig, {useTurnServer: enabled});
      cachedIceServers = null; // сбрасываем кэш — при следующем звонке метод выбирается заново
      document.getElementById('as-call-method-msg').innerHTML = `<div class="info-box">Сохранено. Действует со следующего звонка.</div>`;
    }catch(e){
      ev.target.checked = !enabled;
      document.getElementById('as-call-method-label').textContent = !enabled ? 'Новый метод (с TURN-сервером)' : 'Старый метод (только STUN)';
      document.getElementById('as-call-method-msg').innerHTML = `<div class="error-box">Не удалось сохранить.</div>`;
    }
  });

  const aiWrap = document.createElement('div');
  aiWrap.style.marginTop = '22px';
  aiWrap.style.borderTop = '1px solid var(--border)';
  aiWrap.style.paddingTop = '16px';
  aiWrap.innerHTML = `
    <div style="font-size:calc(14px * var(--font-scale));font-weight:600;margin-bottom:4px;">Перевод и расшифровка голосовых (ИИ)</div>
    <p class="hint" style="margin-bottom:10px;">Адрес вашего Cloudflare Worker, например https://chat-ai.ваш-логин.workers.dev. Пусто — функции скрыты у всех пользователей. Инструкция по настройке — в README.</p>
    <div class="field"><input id="as-ai-endpoint" value="${escapeHtml((state.appConfig && state.appConfig.aiEndpoint) || '')}" placeholder="https://…workers.dev"></div>
    <div style="display:flex;gap:8px;">
      <button class="btn-sm secondary" id="as-ai-check" style="flex:1;">Проверить</button>
      <button class="btn-primary" id="as-ai-save" style="flex:1;margin:0;">Сохранить</button>
    </div>
    <div id="as-ai-msg" style="margin-top:8px;"></div>
  `;
  body.appendChild(aiWrap);
  document.getElementById('as-ai-check').onclick = async ()=>{
    const url = document.getElementById('as-ai-endpoint').value.trim().replace(/\/+$/,'');
    const out = document.getElementById('as-ai-msg');
    if(!url){ out.innerHTML = `<div class="error-box">Введите адрес.</div>`; return; }
    out.innerHTML = `<div class="info-box">Проверяем…</div>`;
    try{
      const r = await fetch(url + '/');
      const j = await r.json();
      if(!j.ok) throw new Error('bad');
      const problems = [];
      if(!j.ai) problems.push('не добавлена привязка Workers AI с именем AI');
      if(!j.project) problems.push('не задана переменная FIREBASE_PROJECT_ID');
      out.innerHTML = problems.length
        ? `<div class="error-box">Сервер отвечает, но ${problems.join(' и ')}.</div>`
        : `<div class="info-box">Сервер работает и настроен правильно.</div>`;
    }catch(e){
      out.innerHTML = `<div class="error-box">Сервер не отвечает. Проверьте адрес и что Worker развёрнут.</div>`;
    }
  };
  document.getElementById('as-ai-save').onclick = async ()=>{
    const url = document.getElementById('as-ai-endpoint').value.trim().replace(/\/+$/,'');
    const out = document.getElementById('as-ai-msg');
    if(url && !/^https:\/\//.test(url)){ out.innerHTML = `<div class="error-box">Адрес должен начинаться с https://</div>`; return; }
    try{
      await db.collection('config').doc('app').set({aiEndpoint: url}, {merge:true});
      state.appConfig = Object.assign({}, state.appConfig, {aiEndpoint: url});
      out.innerHTML = `<div class="info-box">Сохранено. ${url ? 'Перевод и расшифровка появятся у всех после обновления страницы.' : 'Функции ИИ скрыты.'}</div>`;
    }catch(e){ out.innerHTML = `<div class="error-box">Не удалось сохранить.</div>`; }
  };

  const pushWrap = document.createElement('div');
  pushWrap.style.marginTop = '22px';
  pushWrap.style.borderTop = '1px solid var(--border)';
  pushWrap.style.paddingTop = '16px';
  const puc = state.appConfig || {};
  pushWrap.innerHTML = `
    <div style="font-size:calc(14px * var(--font-scale));font-weight:600;margin-bottom:4px;">Push-уведомления (когда приложение закрыто)</div>
    <p class="hint" style="margin-bottom:10px;">Ключ из Firebase: Настройки проекта → Cloud Messaging → Web Push certificates → «Пара ключей». Инструкция — в README, раздел «Push-уведомления».</p>
    <div class="field"><input id="as-vapid" value="${escapeHtml(puc.vapidKey || '')}" placeholder="B... (Web Push certificate)"></div>
    <label class="proxy-opt"><input type="checkbox" id="as-local-notifs" ${puc.localNotifsEnabled === false ? '' : 'checked'}> Локальные уведомления у всех пользователей (фоновый режим)</label>
    <div style="display:flex;gap:8px;margin-top:10px;">
      <button class="btn-sm secondary" id="as-push-test" style="flex:1;">Проверить на этом устройстве</button>
      <button class="btn-primary" id="as-push-save" style="flex:1;margin:0;">Сохранить</button>
    </div>
    <div id="as-push-msg" style="margin-top:8px;"></div>
  `;
  body.appendChild(pushWrap);
  document.getElementById('as-push-save').onclick = async ()=>{
    const key = document.getElementById('as-vapid').value.trim();
    const out = document.getElementById('as-push-msg');
    try{
      const localOn = document.getElementById('as-local-notifs').checked;
      await db.collection('config').doc('app').set({vapidKey: key, localNotifsEnabled: localOn}, {merge: true});
      state.appConfig = Object.assign({}, state.appConfig, {vapidKey: key, localNotifsEnabled: localOn});
      if(!localOn && typeof stopBackgroundMode === 'function') stopBackgroundMode();
      out.innerHTML = `<div class="info-box">Сохранено. Устройства зарегистрируются при следующем входе.</div>`;
      if(key) registerPushToken(true);
    }catch(e){ out.innerHTML = `<div class="error-box">Не удалось сохранить.</div>`; }
  };
  document.getElementById('as-push-test').onclick = async ()=>{
    const out = document.getElementById('as-push-msg');
    out.innerHTML = `<div class="info-box">Запрашиваю разрешение и токен…</div>`;
    const res = await registerPushToken(true);
    out.innerHTML = res.ok
      ? `<div class="info-box">✅ Устройство зарегистрировано.<br>Токен: <code style="font-size:11px;word-break:break-all;">${escapeHtml(res.token.slice(0, 40))}…</code><br>Теперь push может отправлять сервер (Cloud Function или прокси).</div>`
      : `<div class="error-box">${escapeHtml(res.error || 'Не удалось получить токен')}</div>`;
  };

  const proxyWrap = document.createElement('div');
  proxyWrap.style.marginTop = '22px';
  proxyWrap.style.borderTop = '1px solid var(--border)';
  proxyWrap.style.paddingTop = '16px';
  const pc = state.appConfig || {};
  proxyWrap.innerHTML = `
    <div style="font-size:calc(14px * var(--font-scale));font-weight:600;margin-bottom:4px;">Прокси для музыки и ИИ</div>
    <p class="hint" style="margin-bottom:10px;">Свой сервер-посредник: через него каталог треков и расшифровка голосовых работают без VPN. Как поставить — в README, раздел «Прокси».</p>
    <div class="field"><input id="as-proxy-url" value="${escapeHtml(pc.proxyUrl || '')}" placeholder="https://ваш-домен.duckdns.org"></div>
    <label class="proxy-opt"><input type="checkbox" id="as-proxy-music" ${pc.proxyMusic === false ? '' : 'checked'}> Музыка через прокси (треки, поиск, скачивание)</label>
    <label class="proxy-opt"><input type="checkbox" id="as-proxy-ai" ${pc.proxyAi === false ? '' : 'checked'}> ИИ через прокси (расшифровка и перевод)</label>
    <div style="display:flex;gap:8px;margin-top:10px;">
      <button class="btn-sm secondary" id="as-proxy-check" style="flex:1;">Проверить</button>
      <button class="btn-primary" id="as-proxy-save" style="flex:1;margin:0;">Сохранить</button>
    </div>
    <div id="as-proxy-msg" style="margin-top:8px;"></div>
  `;
  body.appendChild(proxyWrap);
  document.getElementById('as-proxy-check').onclick = async ()=>{
    const url = document.getElementById('as-proxy-url').value.trim().replace(/\/+$/,'');
    const out = document.getElementById('as-proxy-msg');
    if(!url){ out.innerHTML = `<div class="error-box">Введите адрес прокси.</div>`; return; }
    out.innerHTML = `<div class="info-box">Проверяем связь с прокси и что видит сервер…</div>`;
    try{
      const ctl = new AbortController(); const t = setTimeout(()=> ctl.abort(), 20000);
      const r = await fetch(url + '/health', {signal: ctl.signal}); clearTimeout(t);
      const j = await r.json();
      if(!j.ok) throw new Error('bad');
      const line = (name, x, hint)=> `<div class="proxy-line ${x && x.ok ? 'ok' : 'bad'}">${x && x.ok ? '✅' : '❌'} ${name}${x && x.ok ? ` — ${x.ms} мс` : (hint ? ` — ${hint}` : '')}</div>`;
      out.innerHTML = `<div class="proxy-report"><div class="proxy-line ok">✅ Прокси доступен с этого устройства</div>
        ${line('Каталог треков (Audius)', j.audius, 'сервер не видит каталог — нужен сервер в другой стране')}
        ${line('Каталог радио', j.radio, 'не критично: встроенное радио работает и так')}
        ${line('ИИ (ваш Worker)', j.ai, j.aiConfigured ? 'сервер не достучался до Worker' : 'на сервере не задан адрес Worker (AI_UPSTREAM)')}</div>`;
    }catch(e){
      out.innerHTML = `<div class="error-box">Прокси не отвечает. Проверьте адрес (с https://), что сервер запущен и в нём указан адрес этого сайта (ALLOWED_ORIGIN).</div>`;
    }
  };
  document.getElementById('as-proxy-save').onclick = async ()=>{
    const url = document.getElementById('as-proxy-url').value.trim().replace(/\/+$/,'');
    const out = document.getElementById('as-proxy-msg');
    if(url && !/^https:\/\//.test(url)){ out.innerHTML = `<div class="error-box">Адрес должен начинаться с https://</div>`; return; }
    const upd = {proxyUrl: url, proxyMusic: document.getElementById('as-proxy-music').checked, proxyAi: document.getElementById('as-proxy-ai').checked};
    try{
      await db.collection('config').doc('app').set(upd, {merge: true});
      state.appConfig = Object.assign({}, state.appConfig, upd);
      applyProxyRouting(true);
      out.innerHTML = `<div class="info-box">Сохранено. ${url ? 'У всех пользователей музыка и ИИ пойдут через прокси (после обновления страницы).' : 'Прокси выключен.'}</div>`;
    }catch(e){ out.innerHTML = `<div class="error-box">Не удалось сохранить.</div>`; }
  };

  const cleanupWrap = document.createElement('div');
  cleanupWrap.style.marginTop = '22px';
  cleanupWrap.style.borderTop = '1px solid var(--border)';
  cleanupWrap.style.paddingTop = '16px';
  cleanupWrap.innerHTML = `
    <div style="font-size:calc(14px * var(--font-scale));font-weight:600;margin-bottom:4px;color:var(--danger);">Удаление неактивных аккаунтов</div>
    <p class="hint" style="margin-bottom:10px;">Аккаунты (кроме админов), которые не заходили дольше указанного срока, можно удалить. Проверка запускается автоматически при открытии этого раздела — само удаление только по кнопке ниже, с подтверждением.</p>
    <div class="field"><label>Порог, дней (0 — отключено)</label><input type="number" min="0" id="as-inactive-days" value="${(state.appConfig && state.appConfig.inactivityDeleteDays) || 0}"></div>
    <button class="btn-primary" id="as-inactive-save">Сохранить порог</button>
    <button class="btn-sm danger" id="as-inactive-run" style="margin-top:10px;">Проверить и удалить сейчас</button>
    <div id="as-inactive-msg" style="margin-top:8px;"></div>
  `;
  body.appendChild(cleanupWrap);
  document.getElementById('as-inactive-save').onclick = async ()=>{
    const btn2 = document.getElementById('as-inactive-save');
    const days = parseInt(document.getElementById('as-inactive-days').value, 10) || 0;
    btn2.disabled = true;
    try{
      await db.collection('config').doc('app').set({inactivityDeleteDays: days}, {merge:true});
      state.appConfig = Object.assign({}, state.appConfig, {inactivityDeleteDays: days});
      document.getElementById('as-inactive-msg').innerHTML = `<div class="info-box">Сохранено.</div>`;
      if(days > 0) checkInactiveAccounts();
    }catch(e){ document.getElementById('as-inactive-msg').innerHTML = `<div class="error-box">Не удалось сохранить.</div>`; }
    btn2.disabled = false;
  };
  document.getElementById('as-inactive-run').onclick = async ()=>{
    const targets = await checkInactiveAccounts();
    if(!targets.length) return;
    if(!await uiConfirm('Удалить неактивных аккаунтов: '+targets.length+'? Действие необратимо.')) return;
    let deleted = 0;
    for(const u of targets){
      try{ await adminDeleteUserRecord(u.uid, u.username, u.email); deleted++; }catch(e){}
    }
    toast('Удалено неактивных: '+deleted);
    document.getElementById('as-inactive-msg').innerHTML = `<div class="info-box">Удалено: ${deleted}.</div>`;
  };
  if((state.appConfig && state.appConfig.inactivityDeleteDays) > 0){
    checkInactiveAccounts();
  }
}
async function checkInactiveAccounts(){
  const days = (state.appConfig && state.appConfig.inactivityDeleteDays) || 0;
  const msgEl = document.getElementById('as-inactive-msg');
  if(!msgEl) return [];
  if(days <= 0){ msgEl.innerHTML = `<div class="hint">Порог не задан — введите число дней больше нуля.</div>`; return []; }
  msgEl.innerHTML = `<div class="hint">Проверяем…</div>`;
  try{
    const snap = await db.collection('users').get();
    const cutoff = Date.now() - days*86400000;
    const targets = snap.docs.map(d=>d.data()).filter(u=> !u.isAdmin && (!u.lastActive || u.lastActive < cutoff));
    msgEl.innerHTML = targets.length
      ? `<div class="error-box">Найдено неактивных (${days}+ дней): ${targets.length}.</div>`
      : `<div class="info-box">Неактивных аккаунтов не найдено.</div>`;
    return targets;
  }catch(e){
    msgEl.innerHTML = `<div class="error-box">Не удалось проверить.</div>`;
    return [];
  }
}

