document.getElementById('cf-connect').onclick = async ()=>{
  const btn = document.getElementById('cf-connect');
  firebaseConfig = {
    apiKey: document.getElementById('cf-apiKey').value.trim(),
    authDomain: document.getElementById('cf-authDomain').value.trim(),
    projectId: document.getElementById('cf-projectId').value.trim(),
    storageBucket: document.getElementById('cf-storageBucket').value.trim(),
    messagingSenderId: document.getElementById('cf-messagingSenderId').value.trim(),
    appId: document.getElementById('cf-appId').value.trim(),
  };
  if(!firebaseConfigFilled()){
    document.getElementById('config-msg').innerHTML = `<div class="error-box">Заполните минимум apiKey, authDomain, projectId и appId.</div>`;
    return;
  }
  btn.disabled = true; btn.textContent = 'Подключаемся…';
  const res = await tryInitFirebase();
  btn.disabled = false; btn.textContent = 'Подключиться';
  if(!res.ok){
    document.getElementById('config-msg').innerHTML = `<div class="error-box">${escapeHtml(res.error)}</div>`;
    return;
  }
  document.getElementById('config-screen').style.display = 'none';
  attachAuthListener();
};

