const ROUNDVIDEO_MAX_SECONDS = 60;                  // ROUND 68
let roundVideoRecorder = null;
let roundVideoChunks = [];
let roundVideoStream = null;
let roundVideoStartTime = 0;
let roundVideoTimerInterval = null;
let roundVideoBlob = null;
function stopRoundVideoTracks(){
  setMyTyping(null);
  if(roundVideoStream){ roundVideoStream.getTracks().forEach(t=>t.stop()); roundVideoStream = null; }
}
async function startRoundVideoRecording(){
  if(!state.activeChatId) return;
  if(!navigator.mediaDevices || !window.MediaRecorder){
    toast('Видеосообщения не поддерживаются в этом браузере');
    return;
  }
  try{
    roundVideoStream = await navigator.mediaDevices.getUserMedia({
      video: {facingMode:'user', width:{ideal:240}, height:{ideal:240}},
      audio: true
    });
  }catch(e){
    toast('Нет доступа к камере или микрофону');
    return;
  }
  const preview = document.getElementById('roundvideo-preview');
  preview.srcObject = roundVideoStream;
  document.getElementById('roundvideo-overlay').style.display = 'flex';
  setMyTyping('video');
  roundVideoChunks = [];
  let opts = {videoBitsPerSecond: 200000, audioBitsPerSecond: 32000};
  try{
    if(MediaRecorder.isTypeSupported('video/webm;codecs=vp8,opus')) opts.mimeType = 'video/webm;codecs=vp8,opus';
    else if(MediaRecorder.isTypeSupported('video/webm')) opts.mimeType = 'video/webm';
  }catch(e){}
  try{ roundVideoRecorder = new MediaRecorder(roundVideoStream, opts); }
  catch(e){ roundVideoRecorder = new MediaRecorder(roundVideoStream); }
  roundVideoRecorder.ondataavailable = (e)=>{ if(e.data && e.data.size>0) roundVideoChunks.push(e.data); };
  roundVideoRecorder.start();
  roundVideoStartTime = Date.now();
  roundVideoTimerInterval = setInterval(updateRoundVideoTimer, 250);
}
function updateRoundVideoTimer(){
  const secs = Math.floor((Date.now()-roundVideoStartTime)/1000);
  document.getElementById('roundvideo-timer').textContent = Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0');
  if(secs >= ROUNDVIDEO_MAX_SECONDS) stopRoundVideoRecordingAndPreview();
}
async function stopRoundVideoRecordingAndPreview(){
  if(!roundVideoRecorder){ discardRoundVideo(); return; }
  clearInterval(roundVideoTimerInterval);
  const durationSec = Math.max(1, Math.round((Date.now()-roundVideoStartTime)/1000));
  // Важно: НЕ используем полный mimeType с параметром codecs (например 'video/webm;codecs=vp8,opus')
  // для итогового blob — запятая внутри 'vp8,opus' ломает разбор data URL при конвертации через
  // FileReader.readAsDataURL(), поскольку запятая в синтаксисе data: является служебным разделителем
  // между метаданными и самими данными. Браузер и без явного codecs прекрасно определяет кодек
  // по содержимому webm-контейнера — это лишь необязательная подсказка, не требование для воспроизведения.
  const mimeType = ((roundVideoRecorder && roundVideoRecorder.mimeType) || 'video/webm').split(';')[0] || 'video/webm';
  const blob = await new Promise((resolve)=>{
    roundVideoRecorder.onstop = ()=> resolve(new Blob(roundVideoChunks, {type: mimeType}));
    try{ roundVideoRecorder.stop(); }catch(e){ resolve(new Blob(roundVideoChunks, {type: mimeType})); }
  });
  // Захватываю кадр из живого превью прямо перед остановкой камеры — проще и надёжнее,
  // чем заново декодировать сам blob отдельным видеоэлементом.
  let thumbnail = '';
  try{
    const previewEl = document.getElementById('roundvideo-preview');
    if(previewEl.videoWidth){
      const c = document.createElement('canvas');
      c.width = 160; c.height = 160;
      const ctx = c.getContext('2d');
      const side = Math.min(previewEl.videoWidth, previewEl.videoHeight);
      const sx = (previewEl.videoWidth-side)/2, sy = (previewEl.videoHeight-side)/2;
      ctx.drawImage(previewEl, sx, sy, side, side, 0, 0, 160, 160);
      thumbnail = c.toDataURL('image/jpeg', 0.6);
    }
  }catch(e){ console.error('roundvideo thumbnail capture failed', e); }
  stopRoundVideoTracks();
  document.getElementById('roundvideo-overlay').style.display = 'none';
  if(blob.size < 800){ toast('Слишком короткая запись'); return; }
  if(blob.size > MAX_FILE_BYTES){ toast('Запись слишком длинная, попробуйте покороче'); return; }
  roundVideoBlob = blob;
  roundVideoBlob.durationSec = durationSec;
  roundVideoBlob.thumbnail = thumbnail;
  const url = URL.createObjectURL(blob);
  const playback = document.getElementById('roundvideo-playback');
  playback.src = url;
  playback.play().catch(()=>{});
  document.getElementById('roundvideo-review-overlay').style.display = 'flex';
}
function discardRoundVideo(){
  clearInterval(roundVideoTimerInterval);
  try{ if(roundVideoRecorder){ roundVideoRecorder.ondataavailable = null; roundVideoRecorder.onstop = null; roundVideoRecorder.stop(); } }catch(e){}
  stopRoundVideoTracks();
  document.getElementById('roundvideo-overlay').style.display = 'none';
  document.getElementById('roundvideo-review-overlay').style.display = 'none';
  const playback = document.getElementById('roundvideo-playback');
  playback.pause(); playback.removeAttribute('src'); playback.load();
  roundVideoBlob = null;
}
document.getElementById('roundvideo-discard-btn').onclick = discardRoundVideo;
document.getElementById('roundvideo-send-btn').onclick = async ()=>{
  if(!roundVideoBlob || !state.activeChatId) return;
  const blob = roundVideoBlob;
  const durationSec = blob.durationSec || 1;
  const thumbnail = blob.thumbnail || '';
  discardRoundVideo();
  try{
    const dataUrl = await blobToDataUrl(blob);
    await sendMessage(state.activeChatId, 'roundvideo', dataUrl, null, {duration: durationSec, thumbnail});
  }catch(e){ toast('Не удалось отправить видеосообщение'); }
};
function attachHoldToRecordVideo(el){
  let holdTimer = null, isHolding = false, pressed = false;
  const HOLD_THRESHOLD = 350;
  const start = ()=>{
    if(!state.activeChatId || state.activeCallState) return;
    pressed = true;
    holdTimer = setTimeout(()=>{
      if(pressed){ isHolding = true; startRoundVideoRecording(); }
    }, HOLD_THRESHOLD);
  };
  const end = ()=>{
    if(holdTimer){ clearTimeout(holdTimer); holdTimer = null; }
    if(isHolding){ isHolding = false; stopRoundVideoRecordingAndPreview(); }
    else if(pressed){ startVoiceRecording(); }
    pressed = false;
  };
  const cancelPress = ()=>{
    if(holdTimer){ clearTimeout(holdTimer); holdTimer = null; }
    if(isHolding){ isHolding = false; discardRoundVideo(); }
    pressed = false;
  };
  el.addEventListener('touchstart', (ev)=>{ start(); }, {passive:true});
  el.addEventListener('touchend', end);
  el.addEventListener('touchcancel', cancelPress);
  el.addEventListener('mousedown', start);
  el.addEventListener('mouseup', end);
  el.addEventListener('mouseleave', ()=>{ if(isHolding || pressed) end(); });
}
/* микрофон: см. ROUND 6 — attachTgHold */
function attachDedicatedVideoButton(el){
  let pressed = false, pressStartTime = 0, tapMode = false;
  const TAP_THRESHOLD_MS = 350;
  const start = ()=>{
    if(!state.activeChatId || state.activeCallState) return;
    pressed = true; tapMode = false; pressStartTime = Date.now();
    document.getElementById('roundvideo-hint').style.display = '';
    document.getElementById('roundvideo-stop-btn').style.display = 'none';
    startRoundVideoRecording();
  };
  const end = ()=>{
    if(!pressed) return;
    const heldFor = Date.now() - pressStartTime;
    if(heldFor < TAP_THRESHOLD_MS && !tapMode){
      // Короткий тап, а не удержание — не останавливаем запись, переключаемся в режим ручной остановки
      tapMode = true;
      document.getElementById('roundvideo-hint').style.display = 'none';
      document.getElementById('roundvideo-stop-btn').style.display = 'block';
      return;
    }
    pressed = false;
    stopRoundVideoRecordingAndPreview();
  };
  const cancelPress = ()=>{
    if(pressed && !tapMode){ pressed = false; discardRoundVideo(); }
  };
  el.addEventListener('touchstart', (ev)=>{ ev.preventDefault(); start(); }, {passive:false});
  el.addEventListener('touchend', end);
  el.addEventListener('touchcancel', cancelPress);
  el.addEventListener('mousedown', start);
  el.addEventListener('mouseup', end);
  el.addEventListener('mouseleave', ()=>{ if(pressed && !tapMode) end(); });
  document.getElementById('roundvideo-stop-btn').onclick = ()=>{
    if(!pressed) return;
    pressed = false; tapMode = false;
    stopRoundVideoRecordingAndPreview();
  };
}
