document.getElementById('call-btn-header').onclick = async ()=>{
  if(!state.activeChatMeta || state.activeChatMeta.isSupport || state.activeChatMeta.isCommunity){ toast('Звонок недоступен в этом чате'); return; }
  const other = otherOf(state.activeChatMeta);
  if(other.uid === state.currentUser.uid){ toast('Нельзя позвонить самому себе'); return; }
  if(!(await canCallUser(other.uid, 'audio'))){ toast('Пользователь запретил аудиозвонки'); return; }
  const otherProfile = await getUserProfile(other.uid);
  startCall(other.uid, (otherProfile && realNameOf(otherProfile)) || other.displayName, 'audio');
};
