function toggleCallMute(){
  if(!callLocalStream) return;
  callMuted = !callMuted;
  callLocalStream.getAudioTracks().forEach(t=>{ t.enabled = !callMuted; });
  document.getElementById('call-mute-btn').classList.toggle('muted', callMuted);
  document.getElementById('call-mute-btn-dial').classList.toggle('muted', callMuted);
  document.getElementById('call-mini-mute').classList.toggle('muted', callMuted);
}
function toggleCallCamera(){
  if(!callLocalStream) return;
  callCameraOff = !callCameraOff;
  callLocalStream.getVideoTracks().forEach(t=>{ t.enabled = !callCameraOff; });
  document.getElementById('call-camera-btn').classList.toggle('muted', callCameraOff);
  document.getElementById('call-camera-btn-dial').classList.toggle('muted', callCameraOff);
  document.getElementById('call-mini-camera').classList.toggle('muted', callCameraOff);
}
async function switchCallCamera(){
  if(!callLocalStream || callType!=='video') return;
  const newFacing = callFacingMode === 'user' ? 'environment' : 'user';
  const oldFacing = callFacingMode;
  const oldTrack = callLocalStream.getVideoTracks()[0];
  // Останавливаем текущую камеру до запроса новой — иначе на большинстве мобильных
  // браузеров она считается «занятой», и запрос новой камеры отклоняется целиком.
  if(oldTrack){ callLocalStream.removeTrack(oldTrack); oldTrack.stop(); }
  let newStream;
  try{
    newStream = await navigator.mediaDevices.getUserMedia({audio:false, video:{facingMode:{exact:newFacing}}});
  }catch(e){
    try{
      newStream = await navigator.mediaDevices.getUserMedia({audio:false, video:{facingMode:newFacing}});
    }catch(e2){
      // Не получилось — пробуем вернуть прежнюю камеру, чтобы видео совсем не пропало.
      try{
        const recoverStream = await navigator.mediaDevices.getUserMedia({audio:false, video:{facingMode:oldFacing}});
        const recoverTrack = recoverStream.getVideoTracks()[0];
        if(recoverTrack){
          if(callPc){
            const sender = callPc.getSenders().find(s=>s.track && s.track.kind==='video');
            if(sender) await sender.replaceTrack(recoverTrack);
          }
          callLocalStream.addTrack(recoverTrack);
          recoverTrack.enabled = !callCameraOff;
          const el = document.getElementById('call-local-video');
          el.srcObject = null; el.srcObject = callLocalStream;
        }
      }catch(e3){}
      toast('Не удалось переключить камеру');
      return;
    }
  }
  const newTrack = newStream.getVideoTracks()[0];
  if(!newTrack) return;
  const maskActive = currentMaskType !== 'none' && maskRenderActive;
  if(callPc && !maskActive){
    // Трек заменяем в самом WebRTC-соединении только если маска не активна — если активна,
    // соединение уже отправляет поток с канваса маски и должно остаться на нём, а не на сырой камере
    const sender = callPc.getSenders().find(s=>s.track && s.track.kind==='video');
    if(sender) await sender.replaceTrack(newTrack);
  }
  callLocalStream.addTrack(newTrack);
  newTrack.enabled = !callCameraOff;
  if(!maskActive){
    const localVideoEl = document.getElementById('call-local-video');
    localVideoEl.srcObject = null;
    localVideoEl.srcObject = callLocalStream;
  }
  if(maskSourceVideoEl && currentMaskType !== 'none'){
    lastFaceLandmarks = null; // сбрасываем сразу — не должны рисовать маску по устаревшим координатам от старой камеры
    maskSourceVideoEl.srcObject = null;
    maskSourceVideoEl.srcObject = callLocalStream;
    try{ await maskSourceVideoEl.play(); }catch(e){}
    // Разрешение фронтальной и основной камеры обычно разное — пересчитываем канвас маски
    // под фактическое разрешение новой камеры, иначе нормализованные координаты лица (0..1)
    // лягут на холст неверного размера и маска перестанет совпадать с лицом
    const newSettings = newTrack.getSettings();
    const canvas = document.getElementById('call-mask-canvas');
    canvas.width = newSettings.width || maskSourceVideoEl.videoWidth || canvas.width;
    canvas.height = newSettings.height || maskSourceVideoEl.videoHeight || canvas.height;
    // Пересоздаём сам экземпляр распознавания лица — на случай, если его внутреннее состояние
    // не переносится корректно при смене источника видео другого разрешения на лету
    try{ if(faceMeshInstance && faceMeshInstance.close) faceMeshInstance.close(); }catch(e){}
    faceMeshInstance = null;
    try{ await ensureFaceMesh(); }catch(e){}
  }
  callFacingMode = newFacing;
}
