(function setupSwipeBackGesture(){
  const chatArea = document.getElementById('chat-area');
  let startX = 0, startY = 0, startTime = 0, tracking = false;
  chatArea.addEventListener('touchstart', (ev)=>{
    if(ev.touches.length !== 1 || !chatArea.classList.contains('mobile-open')) { tracking = false; return; }
    const t = ev.touches[0];
    tracking = false; // заменено: см. ROUND 8 — свайп назад по всему экрану
    startX = t.clientX; startY = t.clientY; startTime = Date.now();
  }, {passive:true});
  chatArea.addEventListener('touchend', (ev)=>{
    if(!tracking) return;
    tracking = false;
    const t = ev.changedTouches[0];
    const dx = t.clientX - startX;
    const dy = t.clientY - startY;
    const dt = Date.now() - startTime;
    if(dx > 70 && Math.abs(dy) < 60 && dt < 700) closeActiveChat();
  }, {passive:true});
})();

/* ============================================================
   СТАРТ
============================================================ */
function attachAuthListener(){
  document.getElementById('boot-screen').style.display = 'none';
  firebase.auth().onAuthStateChanged(async (fbUser)=>{
    if(fbUser){
      try{
        const snap = await db.collection('users').doc(fbUser.uid).get();
        if(snap.exists && !snap.data().blocked){
          const rec = snap.data();
          const user = {uid: fbUser.uid, email: rec.email, username: rec.username, isAdmin: !!rec.isAdmin};
          if(!rec.pinHash || rec.pinEnabled === false){
            loginSuccess(user);
            return;
          }
          document.getElementById('app-screen').style.display = 'none';
          document.getElementById('auth-screen').style.display = 'flex';
          state.pendingLoginUser = user;
          state.view = 'pin';
          renderAuth();
          return;
        }
        if(snap.exists && snap.data().blocked){ toast('Этот аккаунт заблокирован администратором.'); }
      }catch(e){}
      try{ await firebase.auth().signOut(); }catch(e){}
    }
    document.getElementById('app-screen').style.display = 'none';
    document.getElementById('auth-screen').style.display = 'flex';
    state.view = 'login';
    renderAuth();
  });
}

(async function boot(){
  document.getElementById('app-screen').style.display = 'none';
  if(!firebaseConfigFilled()){
    document.getElementById('boot-screen').style.display = 'none';
    document.getElementById('config-screen').style.display = 'flex';
    return;
  }
  const res = await tryInitFirebase();
  if(!res.ok){
    document.getElementById('boot-screen').style.display = 'none';
    document.getElementById('config-screen').style.display = 'flex';
    document.getElementById('config-msg').innerHTML = `<div class="error-box">${escapeHtml(res.error)}</div>`;
    return;
  }
  attachAuthListener();
})();

