/* ---- поиск по переписке ---- */
const chatFindBar = document.getElementById('chat-find-bar');
const chatFindInput = document.getElementById('chat-find-input');
function applyChatFind(){
  if(!chatFindBar.classList.contains('open')) return;
  const q = chatFindInput.value.trim().toLowerCase();
  const box = document.getElementById('messages');
  let hits = 0, firstHit = null;
  box.querySelectorAll('.msg-row').forEach(row=>{
    const b = row.querySelector('.bubble');
    let txt = '';
    if(b){ const c = b.cloneNode(true); c.querySelectorAll('.time').forEach(x=>x.remove()); txt = c.textContent.toLowerCase(); }
    const ok = !q || txt.includes(q);
    row.style.display = ok ? '' : 'none';
    row.classList.toggle('find-hit', !!q && ok);
    if(q && ok){ hits++; if(!firstHit) firstHit = row; }
  });
  box.querySelectorAll('.day-divider, .empty-list').forEach(d=>{ d.style.display = q ? 'none' : ''; });
  document.getElementById('chat-find-count').textContent = q ? (hits ? `Найдено: ${hits}` : 'Ничего не найдено') : '';
  return firstHit;
}
function openChatFind(){
  chatFindBar.classList.add('open');
  chatFindInput.value = '';
  document.getElementById('chat-find-count').textContent = '';
  setTimeout(()=> chatFindInput.focus(), 30);
}
function closeChatFind(){
  if(!chatFindBar.classList.contains('open')) return;
  chatFindBar.classList.remove('open');
  chatFindInput.value = '';
  const box = document.getElementById('messages');
  box.querySelectorAll('.msg-row').forEach(r=>{ r.style.display = ''; r.classList.remove('find-hit'); });
  box.querySelectorAll('.day-divider, .empty-list').forEach(d=>{ d.style.display = ''; });
  box.scrollTop = box.scrollHeight;
}
