/* ---- свайп сообщения влево = ответить (как в Telegram / WhatsApp) ---- */
(function setupSwipeToReply(){
  const box = document.getElementById('messages');
  let row = null, sx = 0, sy = 0, dx = 0, axis = null;
  box.addEventListener('touchstart', (ev)=>{
    if(state.msgSelectMode || ev.touches.length !== 1) { row = null; return; }
    row = ev.target.closest('.msg-row[data-id]');
    if(!row) return;
    const t = ev.touches[0];
    sx = t.clientX; sy = t.clientY; dx = 0; axis = null;
  }, {passive:true});
  box.addEventListener('touchmove', (ev)=>{
    if(!row) return;
    const t = ev.touches[0];
    const mx = t.clientX - sx, my = t.clientY - sy;
    if(axis === null && (Math.abs(mx) > 10 || Math.abs(my) > 10)){
      axis = (mx < 0 && Math.abs(mx) > Math.abs(my) * 1.4) ? 'x' : 'y';
    }
    if(axis !== 'x') return;
    dx = Math.max(-90, Math.min(0, mx));
    row.style.transition = 'none';
    row.style.transform = `translateX(${dx}px)`;
    row.classList.toggle('swipe-armed', dx <= -60);
  }, {passive:true});
  const end = ()=>{
    if(!row) return;
    const r = row; row = null;
    r.style.transition = '';
    r.style.transform = '';
    r.classList.remove('swipe-armed');
    if(axis === 'x' && dx <= -60){
      const m = state.currentMessages.find(x=>x.id === r.getAttribute('data-id'));
      if(m){ haptic('buttons', 10); setReplyContext(m); }
    }
  };
  box.addEventListener('touchend', end);
  box.addEventListener('touchcancel', end);
})();

/* ---- Esc закрывает верхний слой ---- */
document.addEventListener('keydown', (ev)=>{
  if(ev.key !== 'Escape') return;
  const vis = id => { const el = document.getElementById(id); return el && getComputedStyle(el).display !== 'none'; };
  if(chatHeaderMenu.classList.contains('open')){ closeChatMenu(); return; }
  if(vis('msg-action-sheet')){ closeMsgActionSheet(); return; }
  if(vis('lightbox')){ document.getElementById('lightbox-close').click(); return; }
  if(chatFindBar.classList.contains('open')){ closeChatFind(); return; }
});

/* ============================================================
   ROUND 2 — звонки: очередь ICE-кандидатов, контроль связи,
   индикатор качества, Wake Lock, картинка-в-картинке
============================================================ */
let callSessionId = null;
let pendingRemoteCandidates = [];
let callNetIssue = '';
let callNetLostTimer = null;
let callStatsTimer = null;
let callWakeLock = null;

function queueRemoteCandidate(data){
  if(!callPc || !data) return;
  // кандидаты от прошлых звонков в этом же чате помечены другим sid — пропускаем
  if(callSessionId && data.sid && data.sid !== callSessionId) return;
  const init = {candidate: data.candidate, sdpMid: data.sdpMid, sdpMLineIndex: data.sdpMLineIndex};
  if(data.usernameFragment) init.usernameFragment = data.usernameFragment;
  const remoteUfrag = getRemoteIceUfrag();
  if(callPc.remoteDescription && callPc.remoteDescription.type && (!init.usernameFragment || !remoteUfrag || init.usernameFragment === remoteUfrag)){
    callPc.addIceCandidate(new RTCIceCandidate(init)).catch(err=> console.warn('ICE-кандидат отклонён', err));
  }else{
    pendingRemoteCandidates.push(init);
  }
}
function flushRemoteCandidates(){
  if(!callPc) return;
  const list = pendingRemoteCandidates;
  pendingRemoteCandidates = [];
  list.forEach(init=> callPc.addIceCandidate(new RTCIceCandidate(init)).catch(err=> console.warn('ICE-кандидат отклонён', err)));
}
async function clearCallCandidates(chatId){
  const ref = db.collection('calls').doc(chatId);
  const job = Promise.all(['callerCandidates','calleeCandidates'].map(async name=>{
    const snap = await ref.collection(name).get();
    await Promise.all(snap.docs.map(d=> d.ref.delete().catch(()=>{})));
  })).catch(()=>{});
  await Promise.race([job, new Promise(r=> setTimeout(r, 2500))]);
}

function callMiniLabel(label){
  if(!callNetIssue) return label;
  return callNetIssue === 'Слабый сигнал' ? label + ' · слабый сигнал' : callNetIssue;
}
function setCallNetIssue(text){
  callNetIssue = text || '';
  const b = document.getElementById('call-net-banner');
  if(b){
    if(callNetIssue){
      b.innerHTML = (callNetIssue === 'Слабый сигнал' ? '<span class="net-bars"><i></i><i></i><i></i></span>' : '') + escapeHtml(callNetIssue);
      b.classList.add('show');
      b.classList.toggle('bad', callNetIssue !== 'Слабый сигнал');
    }else{
      b.classList.remove('show','bad');
    }
  }
  if(state.callMinimized && callNetIssue && callNetIssue !== 'Слабый сигнал') updateMiniWidgetStatus(callNetIssue);
}
function setupCallPcMonitoring(pc){
  let everConnected = false;
  callRestartAttempts = 0;
  const onState = ()=>{
    if(pc !== callPc) return;
    const st = pc.connectionState || pc.iceConnectionState;
    if(st === 'connected' || st === 'completed'){
      everConnected = true;
      callRestartAttempts = 0;
      if(callNetLostTimer){ clearTimeout(callNetLostTimer); callNetLostTimer = null; }
      if(callRestartTimer){ clearTimeout(callRestartTimer); callRestartTimer = null; }
      setCallNetIssue('');
      if(callType === 'video') requestCallWakeLock();
      startCallStats();
      listenCallRestart();
      updateScreenShareBtn();
    }else if(st === 'disconnected' || st === 'failed'){
      if(!everConnected){
        if(st === 'failed' && state.activeCallState === 'connected'){
          showCallEndingStatus('Не удалось соединиться — проверьте интернет', ()=> endCall('ended'));
        }
        return;
      }
      setCallNetIssue('Переподключение…');
      scheduleIceRestart(st === 'failed' ? 0 : 2500);
      if(!callNetLostTimer){
        callNetLostTimer = setTimeout(()=>{
          callNetLostTimer = null;
          if(callPc === pc && state.activeCallState === 'connected'){
            showCallEndingStatus('Связь потеряна', ()=> endCall('ended'));
          }
        }, 30000);
      }
    }
  };
  if('onconnectionstatechange' in pc) pc.addEventListener('connectionstatechange', onState);
  else pc.addEventListener('iceconnectionstatechange', onState);
}
function startCallStats(){
  if(callStatsTimer) return;
  let prev = null;
  callStatsTimer = setInterval(async ()=>{
    if(!callPc) return;
    try{
      const stats = await callPc.getStats();
      let rtt = null, lost = 0, recv = 0;
      stats.forEach(r=>{
        if(r.type === 'candidate-pair' && r.state === 'succeeded' && r.nominated && typeof r.currentRoundTripTime === 'number') rtt = r.currentRoundTripTime;
        if(r.type === 'inbound-rtp'){ lost += Math.max(0, r.packetsLost||0); recv += r.packetsReceived||0; }
      });
      let lossPct = 0;
      if(prev){ const dl = lost-prev.lost, dr = recv-prev.recv; if(dl+dr > 0) lossPct = dl/(dl+dr)*100; }
      prev = {lost, recv};
      if(callNetIssue && callNetIssue !== 'Слабый сигнал') return;
      const weak = (rtt !== null && rtt > 0.45) || lossPct > 6;
      if(weak !== (callNetIssue === 'Слабый сигнал')) setCallNetIssue(weak ? 'Слабый сигнал' : '');
    }catch(e){}
  }, 3000);
}
async function requestCallWakeLock(){
  try{
    if('wakeLock' in navigator && !callWakeLock){
      callWakeLock = await navigator.wakeLock.request('screen');
      callWakeLock.addEventListener('release', ()=>{ callWakeLock = null; });
    }
  }catch(e){}
}
document.addEventListener('visibilitychange', ()=>{
  if(document.visibilityState === 'visible' && state.activeCallState === 'connected' && callType === 'video') requestCallWakeLock();
});
function stopCallMonitoring(){
  stopIceRestartSignaling();
  stopScreenShare(true);
  if(callNetLostTimer){ clearTimeout(callNetLostTimer); callNetLostTimer = null; }
  if(callStatsTimer){ clearInterval(callStatsTimer); callStatsTimer = null; }
  if(callWakeLock){ try{ callWakeLock.release(); }catch(e){} callWakeLock = null; }
  if(document.pictureInPictureElement){ document.exitPictureInPicture().catch(()=>{}); }
  setCallNetIssue('');
  callSessionId = null;
  pendingRemoteCandidates = [];
}
cleanupCall = (function(orig){
  return function(...args){ stopCallMonitoring(); return orig.apply(this, args); };
})(cleanupCall);

/* картинка-в-картинке: при сворачивании видеозвонка собеседник остаётся в плавающем окне */
function tryCallPictureInPicture(){
  if(callType !== 'video' || state.activeCallState !== 'connected') return;
  if(!document.pictureInPictureEnabled || document.pictureInPictureElement) return;
  const swapped = document.getElementById('call-overlay').classList.contains('swapped');
  const v = document.getElementById(swapped ? 'call-local-video' : 'call-remote-video');
  if(v && v.srcObject && v.readyState >= 2){ v.requestPictureInPicture().catch(()=>{}); }
}
['call-minimize-btn','call-mini-dismiss-connected'].forEach(id=>{
  const el = document.getElementById(id);
  if(el) el.addEventListener('click', tryCallPictureInPicture, {capture:true});
});
document.getElementById('call-mini-widget').addEventListener('click', ()=>{
  if(document.pictureInPictureElement) document.exitPictureInPicture().catch(()=>{});
});

/* ============================================================
   ROUND 2 — голосовые: живой индикатор громкости, настоящая волна,
   скорость воспроизведения, автопроигрывание следующего
============================================================ */
let recMeter = null;
function buildRecBars(){
  const w = document.querySelector('#composer-recording .rec-wave');
  if(!w) return [];
  const n = Math.max(14, Math.floor((w.clientWidth || 180) / 5));
  if(w.children.length !== n) w.innerHTML = '<span></span>'.repeat(n);
  return Array.from(w.children);
}
function startRecLevelMeter(stream){
  stopRecLevelMeter();
  const bars = buildRecBars();
  const history = new Array(bars.length).fill(0);
  try{
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if(!Ctx || !stream) return;
    const ctx = new Ctx();
    const src = ctx.createMediaStreamSource(stream);
    const an = ctx.createAnalyser();
    an.fftSize = 1024;
    src.connect(an);           // только анализ громкости: в динамик и в запись ничего не подаётся
    const buf = new Uint8Array(an.fftSize);
    let smooth = 0;
    recMeter = {ctx, src, levels: [], timer: null, last: 0};
    recMeter.timer = setInterval(()=>{
      if(recIsPaused) return;
      const cur = buildRecBars();
      if(cur.length !== bars.length){
        bars.length = 0; cur.forEach(b=> bars.push(b));
        while(history.length < bars.length) history.unshift(0);
        while(history.length > bars.length) history.shift();
      }
      an.getByteTimeDomainData(buf);
      let sum = 0;
      for(let i=0;i<buf.length;i++){ const v = (buf[i]-128)/128; sum += v*v; }
      const level = Math.min(1, Math.sqrt(sum/buf.length)*4);
      smooth = smooth*0.45 + level*0.55;
      recMeter.last = smooth;
      recMeter.levels.push(level);
      history.push(Math.min(1, smooth*1.6));
      history.shift();
      for(let i=0;i<bars.length;i++) bars[i].style.height = (12 + history[i]*88) + '%';
    }, 80);
  }catch(e){ recMeter = null; }
}
function stopRecLevelMeter(){
  if(recMeter){
    clearInterval(recMeter.timer);
    try{ recMeter.src.disconnect(); }catch(e){}
    try{ recMeter.ctx.close(); }catch(e){}
    recMeter = null;
  }
  const w = document.querySelector('#composer-recording .rec-wave');
  if(w) w.querySelectorAll('span').forEach(sp=> sp.style.height = '');
}
function resampleWave(arr, n){
  const src = (arr||[]).map(v=> Number(v) || 0);
  if(!src.length) return [];
  const out = [];
  for(let i=0;i<n;i++){
    const a = Math.floor(i*src.length/n);
    const b = Math.max(a+1, Math.floor((i+1)*src.length/n));
    let m = 0;
    for(let j=a;j<b && j<src.length;j++) m = Math.max(m, src[j]);
    out.push(m);
  }
  const max = Math.max(...out, 0.0001);
  return out.map(v=> Math.max(12, Math.round(v/max*100)));
}
function getRecWaveform(){
  if(!recMeter || recMeter.levels.length < 4) return null;
  return resampleWave(recMeter.levels, 40);
}

let voicePlaybackRate = 1;
try{ const saved = parseFloat(localStorage.getItem('voicePlaybackRate')); if([1,1.5,2].includes(saved)) voicePlaybackRate = saved; }catch(e){}
function voiceRateLabel(){ return (voicePlaybackRate === 1.5 ? '1,5' : String(voicePlaybackRate)) + '×'; }
function cycleVoiceRate(){
  voicePlaybackRate = voicePlaybackRate === 1 ? 1.5 : voicePlaybackRate === 1.5 ? 2 : 1;
  try{ localStorage.setItem('voicePlaybackRate', String(voicePlaybackRate)); }catch(e){}
  if(activeVoiceAudio) activeVoiceAudio.playbackRate = voicePlaybackRate;
  document.querySelectorAll('.voice-speed-btn').forEach(b=> b.textContent = voiceRateLabel());
}
function playNextVoiceAfter(src){
  const els = Array.from(document.querySelectorAll('#messages .voice-msg'));
  const i = els.findIndex(el=> el.getAttribute('data-src') === src);
  const next = i >= 0 ? els[i+1] : null;
  if(!next) return;
  toggleVoicePlayback(next.getAttribute('data-src'), next.querySelector('.voice-play-btn'), next.querySelector('.voice-bar'), next.querySelector('.voice-time'));
}

/* ============================================================
   ROUND 2 — фото: кадрирование аватара
============================================================ */
const IMAGE_FORMAT_ERROR = 'Браузер не умеет открывать этот формат (например, HEIC). Выберите фото в JPG или PNG.';
function loadImageFromFile(file){
  return new Promise((resolve, reject)=>{
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = ()=> resolve({img, url});
    img.onerror = ()=>{ URL.revokeObjectURL(url); reject(new Error(IMAGE_FORMAT_ERROR)); };
    img.src = url;
  });
}
async function cropImageFile(file){
  const {img, url} = await loadImageFromFile(file);
  return new Promise((resolve)=>{
    const overlay = document.getElementById('crop-overlay');
    const stage = document.getElementById('crop-stage');
    const canvas = document.getElementById('crop-canvas');
    const zoom = document.getElementById('crop-zoom');
    overlay.style.display = 'flex';
    const S = Math.round(stage.getBoundingClientRect().width) || 320;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = S*dpr; canvas.height = S*dpr;
    const base = Math.max(S/img.naturalWidth, S/img.naturalHeight);
    let scale = 1, ox = 0, oy = 0;
    zoom.value = 100;
    const clamp = ()=>{
      const w = img.naturalWidth*base*scale, h = img.naturalHeight*base*scale;
      const mx = Math.max(0,(w-S)/2), my = Math.max(0,(h-S)/2);
      ox = Math.max(-mx, Math.min(mx, ox)); oy = Math.max(-my, Math.min(my, oy));
    };
    const draw = ()=>{
      clamp();
      const ctx = canvas.getContext('2d');
      ctx.setTransform(dpr,0,0,dpr,0,0);
      ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0,0,S,S);
      const w = img.naturalWidth*base*scale, h = img.naturalHeight*base*scale;
      ctx.drawImage(img, S/2+ox-w/2, S/2+oy-h/2, w, h);
    };
    const setScale = (v)=>{ scale = Math.max(1, Math.min(4, v)); zoom.value = Math.round(scale*100); draw(); };
    const pointers = new Map();
    let pinchStart = null;
    const onDown = (ev)=>{ stage.setPointerCapture(ev.pointerId); pointers.set(ev.pointerId, {x:ev.clientX, y:ev.clientY}); if(pointers.size === 2){ const [a,b] = [...pointers.values()]; pinchStart = {d: Math.hypot(a.x-b.x, a.y-b.y), s: scale}; } };
    const onMove = (ev)=>{
      if(!pointers.has(ev.pointerId)) return;
      const prev = pointers.get(ev.pointerId);
      pointers.set(ev.pointerId, {x:ev.clientX, y:ev.clientY});
      if(pointers.size === 1){ ox += ev.clientX-prev.x; oy += ev.clientY-prev.y; draw(); }
      else if(pointers.size === 2 && pinchStart){ const [a,b] = [...pointers.values()]; setScale(pinchStart.s * Math.hypot(a.x-b.x, a.y-b.y)/pinchStart.d); }
    };
    const onUp = (ev)=>{ pointers.delete(ev.pointerId); if(pointers.size < 2) pinchStart = null; };
    const onWheel = (ev)=>{ ev.preventDefault(); setScale(scale * (ev.deltaY < 0 ? 1.08 : 1/1.08)); };
    const onZoom = ()=> setScale(zoom.value/100);
    stage.addEventListener('pointerdown', onDown);
    stage.addEventListener('pointermove', onMove);
    stage.addEventListener('pointerup', onUp);
    stage.addEventListener('pointercancel', onUp);
    stage.addEventListener('wheel', onWheel, {passive:false});
    zoom.addEventListener('input', onZoom);
    const render = (N, q)=>{
      const c = document.createElement('canvas');
      c.width = N; c.height = N;
      const x = c.getContext('2d');
      x.imageSmoothingQuality = 'high';
      x.fillStyle = '#FFFFFF'; x.fillRect(0,0,N,N);
      const k = N/S;
      const w = img.naturalWidth*base*scale*k, h = img.naturalHeight*base*scale*k;
      x.drawImage(img, N/2+ox*k-w/2, N/2+oy*k-h/2, w, h);
      return c.toDataURL('image/jpeg', q);
    };
    const finish = (ok)=>{
      stage.removeEventListener('pointerdown', onDown);
      stage.removeEventListener('pointermove', onMove);
      stage.removeEventListener('pointerup', onUp);
      stage.removeEventListener('pointercancel', onUp);
      stage.removeEventListener('wheel', onWheel);
      zoom.removeEventListener('input', onZoom);
      document.removeEventListener('keydown', onKey);
      overlay.style.display = 'none';
      const result = ok ? {full: render(560, 0.9), thumb: render(320, 0.85)} : null;
      URL.revokeObjectURL(url);
      resolve(result);
    };
    const onKey = (ev)=>{ if(ev.key === 'Escape') finish(false); else if(ev.key === 'Enter') finish(true); };
    document.addEventListener('keydown', onKey);
    document.getElementById('crop-cancel').onclick = ()=> finish(false);
    document.getElementById('crop-done').onclick = ()=> finish(true);
    draw();
  });
}

/* ============================================================
   ROUND 3 — «печатает…», черновики, закреп, «без звука»,
   демонстрация экрана, перезапуск ICE, группы настроек, PWA
============================================================ */

/* ---------- «печатает…» / «записывает голосовое…» ---------- */
let myTypingKind = null, myTypingChat = null, myTypingSentAt = 0;
function setMyTyping(kind){
  try{ setMyTypingUnsafe(kind); }catch(e){ console.warn('typing indicator', e); }
}
function setMyTypingUnsafe(kind){
  if(!state.currentUser) return;
  const uid = state.currentUser.uid;
  const chatId = state.activeChatId;
  const clear = (id)=>{ if(id) db.collection('chats').doc(id).update({['typing.'+uid]: firebase.firestore.FieldValue.delete()}).catch(()=>{}); };
  if(!kind || !chatId){
    if(myTypingKind) clear(myTypingChat);
    myTypingKind = null; myTypingChat = null;
    return;
  }
  const now = Date.now();
  if(kind === myTypingKind && chatId === myTypingChat && now - myTypingSentAt < 4000) return;
  if(myTypingChat && myTypingChat !== chatId) clear(myTypingChat);
  myTypingKind = kind; myTypingChat = chatId; myTypingSentAt = now;
  db.collection('chats').doc(chatId).update({['typing.'+uid]: {k: kind, t: now}}).catch(()=>{});
}
const typingSeen = {};
function ingestTyping(meta){
  if(!meta || !meta.id || !state.currentUser) return;
  const map = meta.typing || {};
  const me = state.currentUser.uid;
  const firstSight = !typingSeen[meta.id];
  const bucket = typingSeen[meta.id] || (typingSeen[meta.id] = {});
  Object.keys(map).forEach(u=>{
    if(u === me) return;
    const v = map[u];
    if(!v || !v.k){ delete bucket[u]; return; }
    const prev = bucket[u];
    if(!prev || prev.t !== v.t){
      // при первом получении старую запись (вкладку закрыли, не успев стереть) не показываем
      const stale = firstSight && Math.abs(Date.now() - (v.t||0)) > 15000;
      bucket[u] = {t: v.t, k: v.k, seenAt: stale ? 0 : Date.now()};
    }
  });
  Object.keys(bucket).forEach(u=>{ if(!map[u]) delete bucket[u]; });
}
function activeTypers(meta){
  if(!meta || !meta.id) return [];
  const b = typingSeen[meta.id] || {};
  const now = Date.now();
  return Object.keys(b).filter(u=>{
    const v = b[u];
    if(now - v.seenAt > 6500) return false;
    if(meta.lastFrom === u && (meta.lastTimestamp||0) >= (v.t||0)) return false;
    return true;
  }).map(u=> ({uid: u, k: b[u].k}));
}
function typingLabel(meta){
  const t = activeTypers(meta);
  if(!t.length) return '';
  const verb = k=> k === 'voice' ? 'записывает голосовое' : k === 'video' ? 'записывает видео' : 'печатает';
  if(!meta.isCommunity) return verb(t[0].k) + '…';
  if(t.length > 1) return 'несколько человек печатают…';
  const name = (meta.usernames && meta.usernames[t[0].uid]) || 'Кто-то';
  return name + ' ' + verb(t[0].k) + '…';
}
const TYPING_DOTS = '<span class="typing-dots"><i></i><i></i><i></i></span>';
function renderTypingHeader(){
  const sub = document.getElementById('chat-header-sub');
  if(!sub) return;
  const label = state.activeChatMeta ? typingLabel(state.activeChatMeta) : '';
  if(label){
    if(!sub.classList.contains('typing')){ sub.dataset.presence = sub.textContent; sub.classList.add('typing'); }
    else if(sub.dataset.shown !== sub.textContent){ sub.dataset.presence = sub.textContent; }
    sub.textContent = label;
    sub.dataset.shown = label;
  }else if(sub.classList.contains('typing')){
    sub.classList.remove('typing');
    if(sub.textContent === sub.dataset.shown) sub.textContent = sub.dataset.presence || '';
    delete sub.dataset.shown;
  }
}

/* ---------- черновики ---------- */
function draftKey(chatId){ return state.currentUser ? `draft:${state.currentUser.uid}:${chatId}` : null; }
function getDraft(chatId){ try{ return localStorage.getItem(draftKey(chatId)) || ''; }catch(e){ return ''; } }
function saveDraftFor(chatId){
  if(!chatId || !state.currentUser || state.editingMessageId) return;
  const v = document.getElementById('msg-input').value;
  try{ if(v.trim()) localStorage.setItem(draftKey(chatId), v); else localStorage.removeItem(draftKey(chatId)); }catch(e){}
}
function restoreDraftFor(chatId){
  if(state.activeChatId !== chatId) return;
  const d = getDraft(chatId);
  const input = document.getElementById('msg-input');
  if(!d || input.value) return;
  input.value = d;
  input.style.height = 'auto';
  input.style.height = Math.min(input.scrollHeight, 120) + 'px';
  updateSendBtnVisibility();
}

function decorateChatListLive(){
  const list = document.getElementById('chat-list');
  if(!list || !state.chats) return;
  list.querySelectorAll('.chat-item[data-id]').forEach(row=>{
    const meta = state.chats.find(c=> c.id === row.getAttribute('data-id'));
    const prev = row.querySelector('.preview');
    if(!meta || !prev) return;
    if(prev.dataset.orig === undefined) prev.dataset.orig = prev.innerHTML;
    const dot = prev.querySelector('.unread-dot') ? '<span class="unread-dot"></span>' : '';
    const label = typingLabel(meta);
    const draft = (meta.id !== state.activeChatId) ? getDraft(meta.id) : '';
    let html;
    if(label) html = `<span class="typing-preview">${TYPING_DOTS}${escapeHtml(label)}</span>` + dot;
    else if(draft) html = `<span class="draft-label">Черновик:</span>${escapeHtml(draft.slice(0,80))}` + dot;
    else html = prev.dataset.orig;
    if(prev.innerHTML !== html) prev.innerHTML = html;
  });
}
renderChatList = (function(orig){
  return function(...args){ const r = orig.apply(this, args); try{ decorateChatListLive(); }catch(e){} return r; };
})(renderChatList);

setInterval(()=>{
  if(!state.currentUser) return;
  renderTypingHeader();
  decorateChatListLive();
}, 1000);

const msgInputEl = document.getElementById('msg-input');
let draftSaveTimer = null;
msgInputEl.addEventListener('input', ()=>{
  if(state.editingMessageId) return;
  clearTimeout(draftSaveTimer);
  const chatId = state.activeChatId;
  draftSaveTimer = setTimeout(()=> saveDraftFor(chatId), 300);
  try{ setMyTyping(msgInputEl.value.trim() ? 'text' : null); }catch(e){}
});
msgInputEl.addEventListener('blur', ()=>{ if(myTypingKind === 'text') setMyTyping(null); });
function leaveChatHousekeeping(){
  saveDraftFor(state.activeChatId);
  setMyTyping(null);
}
document.getElementById('back-btn').addEventListener('click', leaveChatHousekeeping, {capture:true});
closeActiveChat = (function(orig){
  return function(...args){ leaveChatHousekeeping(); return orig.apply(this, args); };
})(closeActiveChat);
document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState === 'hidden') leaveChatHousekeeping(); });
window.addEventListener('pagehide', leaveChatHousekeeping);

openChat = (function(orig){
  return async function(chatId, ...rest){
    if(state.activeChatId && state.activeChatId !== chatId) leaveChatHousekeeping();
    state.lastActiveMetaSig = null;
    const r = await orig.call(this, chatId, ...rest);
    restoreDraftFor(chatId);
    renderPinnedBar();
    renderTypingHeader();
    return r;
  };
})(openChat);

/* после отправки — стереть черновик и «печатает» */
document.getElementById('send-btn').addEventListener('click', ()=>{
  setTimeout(()=>{ saveDraftFor(state.activeChatId); setMyTyping(null); }, 0);
});
msgInputEl.addEventListener('keydown', (e)=>{
  if(e.key === 'Enter' && !e.shiftKey) setTimeout(()=>{ saveDraftFor(state.activeChatId); setMyTyping(null); }, 0);
});

/* ---------- закреплённое сообщение ---------- */
const ICON_PIN_UI = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 3h6l-1 6 4 4H6l4-4z"/><path d="M12 13v8"/></svg>';
function setupPinAction(m){
  const btn = document.getElementById('msg-action-pin');
  if(!btn) return;
  const meta = state.activeChatMeta || {};
  const pinned = meta.pinnedMsg && meta.pinnedMsg.id === m.id;
  btn.innerHTML = `${ICON_PIN_UI}<span>${pinned ? 'Открепить' : 'Закрепить'}</span>`;
  btn.onclick = async ()=>{
    closeMsgActionSheet();
    const ref = db.collection('chats').doc(state.activeChatId);
    try{
      if(pinned){
        await ref.update({pinnedMsg: firebase.firestore.FieldValue.delete()});
        toast('Сообщение откреплено');
      }else{
        await ref.update({pinnedMsg: {id: m.id, text: msgPreviewText(m) || 'Сообщение', from: m.from, by: state.currentUser.uid, ts: Date.now()}});
        toast('Сообщение закреплено');
      }
    }catch(e){ toast('Не удалось изменить закреп'); }
  };
}
function renderPinnedBar(){
  const bar = document.getElementById('pinned-bar');
  const meta = state.activeChatMeta;
  const pm = meta && meta.pinnedMsg;
  bar.classList.toggle('show', !!(pm && state.activeChatId));
  if(pm) document.getElementById('pinned-bar-text').textContent = pm.text || 'Сообщение';
}
function jumpToPinned(){
  const pm = state.activeChatMeta && state.activeChatMeta.pinnedMsg;
  if(!pm) return;
  const safeId = (window.CSS && CSS.escape) ? CSS.escape(pm.id) : pm.id;
  const row = document.querySelector(`#messages .msg-row[data-id="${safeId}"]`);
  if(!row){ toast('Сообщение больше недоступно — возможно, удалено'); return; }
  row.scrollIntoView({block: 'center', behavior: 'smooth'});
  row.classList.remove('pin-flash'); void row.offsetWidth; row.classList.add('pin-flash');
  setTimeout(()=> row.classList.remove('pin-flash'), 3000);
}
document.getElementById('pinned-bar').addEventListener('click', (ev)=>{ if(!ev.target.closest('#pinned-bar-close')) jumpToPinned(); });
document.getElementById('pinned-bar').addEventListener('keydown', (ev)=>{ if(ev.key === 'Enter') jumpToPinned(); });
document.getElementById('pinned-bar-close').onclick = async (ev)=>{
  ev.stopPropagation();
  if(!await uiConfirm('Открепить сообщение? Закреп пропадёт у всех участников чата.')) return;
  try{ await db.collection('chats').doc(state.activeChatId).update({pinnedMsg: firebase.firestore.FieldValue.delete()}); }
  catch(e){ toast('Не удалось открепить'); }
};

/* ---------- отправка без звука ---------- */
const sendBtnEl = document.getElementById('send-btn');
const sendPop = document.getElementById('send-options-pop');
let sendLongPressed = false;
function openSendOptions(){ sendLongPressed = true; sendPop.classList.add('open'); }
function closeSendOptions(){ sendPop.classList.remove('open'); }
attachLongPress(sendBtnEl, openSendOptions);
sendBtnEl.addEventListener('contextmenu', (ev)=>{ ev.preventDefault(); openSendOptions(); });
sendBtnEl.addEventListener('click', (ev)=>{
  if(sendLongPressed){ ev.stopImmediatePropagation(); ev.preventDefault(); sendLongPressed = false; }
}, {capture:true});
document.getElementById('send-silent-btn').onclick = async (ev)=>{
  ev.stopPropagation();
  closeSendOptions();
  state.sendSilentNow = true;
  try{ await doSend(); } finally { state.sendSilentNow = false; }
  saveDraftFor(state.activeChatId); setMyTyping(null);
  toast('Отправлено без звука');
};
document.addEventListener('click', (ev)=>{
  if(!sendPop.contains(ev.target) && ev.target !== sendBtnEl && !sendBtnEl.contains(ev.target)){ closeSendOptions(); sendLongPressed = false; }
});

/* ---------- демонстрация экрана (компьютер, видеозвонок) ---------- */
let screenShareTrack = null, screenSharePrevTrack = null, screenSharePrevLocal = null;
function screenShareSupported(){
  return !!(navigator.mediaDevices && navigator.mediaDevices.getDisplayMedia) && !/Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
}
function updateScreenShareBtn(){
  const b = document.getElementById('call-screen-btn');
  if(!b) return;
  b.style.display = (callType === 'video' && state.activeCallState === 'connected' && screenShareSupported()) ? 'flex' : 'none';
  b.classList.toggle('sharing', !!screenShareTrack);
  b.title = screenShareTrack ? 'Остановить показ экрана' : 'Показать экран';
}
async function startScreenShare(){
  if(!callPc) return;
  const sender = callPc.getSenders().find(x=> x.track && x.track.kind === 'video');
  if(!sender){ toast('Показ экрана доступен только в видеозвонке'); return; }
  let ds;
  try{ ds = await navigator.mediaDevices.getDisplayMedia({video: {frameRate: {ideal: 15, max: 30}}, audio: false}); }
  catch(e){ return; }
  const track = ds.getVideoTracks()[0];
  if(!track) return;
  try{ track.contentHint = 'detail'; }catch(e){}
  screenSharePrevTrack = sender.track;
  try{ await sender.replaceTrack(track); }
  catch(e){ track.stop(); toast('Не удалось начать показ экрана'); return; }
  screenShareTrack = track;
  const lv = document.getElementById('call-local-video');
  screenSharePrevLocal = lv.srcObject;
  lv.srcObject = new MediaStream([track]);
  lv.classList.add('screen');
  track.addEventListener('ended', ()=> stopScreenShare());
  updateScreenShareBtn();
  toast('Собеседник видит ваш экран');
}
async function stopScreenShare(silent){
  if(!screenShareTrack) return;
  const track = screenShareTrack;
  screenShareTrack = null;
  try{ track.stop(); }catch(e){}
  if(callPc){
    const sender = callPc.getSenders().find(x=> x.track === track || (x.track && x.track.kind === 'video'));
    if(sender && screenSharePrevTrack){ try{ await sender.replaceTrack(screenSharePrevTrack); }catch(e){} }
  }
  const lv = document.getElementById('call-local-video');
  lv.classList.remove('screen');
  if(screenSharePrevLocal) lv.srcObject = screenSharePrevLocal;
  screenSharePrevTrack = null; screenSharePrevLocal = null;
  updateScreenShareBtn();
  if(!silent) toast('Показ экрана остановлен');
}
document.getElementById('call-screen-btn').onclick = ()=>{ if(screenShareTrack) stopScreenShare(); else startScreenShare(); };

/* ---------- перезапуск ICE при смене сети ---------- */
let callRestartAttempts = 0, callRestartTimer = null, callRestartN = 0, unsubCallRestart = null, callRestartBusy = false;
function getRemoteIceUfrag(){
  try{ const m = callPc && callPc.remoteDescription && callPc.remoteDescription.sdp.match(/a=ice-ufrag:(\S+)/); return m ? m[1] : null; }
  catch(e){ return null; }
}
function scheduleIceRestart(delay){
  if(!callIsCaller || callRestartTimer) return;   // перезапуск всегда начинает звонивший — так нет «встречных» предложений
  callRestartTimer = setTimeout(()=>{ callRestartTimer = null; doIceRestart(); }, delay);
}
async function doIceRestart(){
  if(!callPc || !callId || !callIsCaller || callRestartBusy) return;
  const st = callPc.connectionState || callPc.iceConnectionState;
  if(st === 'connected' || st === 'completed') return;
  if(callRestartAttempts >= 4) return;
  callRestartAttempts++;
  callRestartBusy = true;
  try{
    if(callPc.signalingState === 'have-local-offer'){ await callPc.setLocalDescription({type: 'rollback'}); }
    const offer = await callPc.createOffer({iceRestart: true});
    await callPc.setLocalDescription(offer);
    callRestartN = Date.now();
    await db.collection('calls').doc(callId).update({restart: {n: callRestartN, offer: {type: offer.type, sdp: offer.sdp}, answer: null}});
  }catch(e){ console.warn('Перезапуск ICE не удался', e); }
  callRestartBusy = false;
  setTimeout(()=>{
    if(!callPc) return;
    const s2 = callPc.connectionState || callPc.iceConnectionState;
    if(s2 !== 'connected' && s2 !== 'completed') scheduleIceRestart(0);
  }, 7000);
}
function listenCallRestart(){
  if(unsubCallRestart || !callId) return;
  const myCallId = callId;
  let lastHandledN = 0;
  unsubCallRestart = db.collection('calls').doc(myCallId).onSnapshot(async (snap)=>{
    const d = snap.data();
    if(!d || !d.restart || !callPc || callId !== myCallId) return;
    const r = d.restart;
    try{
      if(!callIsCaller && r.offer && !r.answer && r.n > lastHandledN){
        lastHandledN = r.n;
        await callPc.setRemoteDescription(new RTCSessionDescription(r.offer));
        flushRemoteCandidates();
        const ans = await callPc.createAnswer();
        await callPc.setLocalDescription(ans);
        await db.collection('calls').doc(myCallId).update({'restart.answer': {type: ans.type, sdp: ans.sdp}});
      }else if(callIsCaller && r.answer && r.n === callRestartN && callPc.signalingState === 'have-local-offer'){
        await callPc.setRemoteDescription(new RTCSessionDescription(r.answer));
        flushRemoteCandidates();
      }
    }catch(e){ console.warn('Сигнализация перезапуска ICE', e); }
    setTimeout(recheckCallConnected, 1500);
  });
}
function recheckCallConnected(){
  if(!callPc) return;
  const st = callPc.connectionState || callPc.iceConnectionState;
  if(st === 'connected' || st === 'completed'){
    if(callNetLostTimer){ clearTimeout(callNetLostTimer); callNetLostTimer = null; }
    if(callNetIssue && callNetIssue !== 'Слабый сигнал') setCallNetIssue('');
  }
}
function stopIceRestartSignaling(){
  if(unsubCallRestart){ unsubCallRestart(); unsubCallRestart = null; }
  if(callRestartTimer){ clearTimeout(callRestartTimer); callRestartTimer = null; }
  callRestartAttempts = 0; callRestartN = 0; callRestartBusy = false;
}
window.addEventListener('online', ()=>{
  if(state.activeCallState !== 'connected' || !callPc) return;
  const st = callPc.connectionState || callPc.iceConnectionState;
  if(st !== 'connected' && st !== 'completed') scheduleIceRestart(500);
});

/* ---------- группы в настройках ---------- */
let deferredInstallPrompt = null;
window.addEventListener('beforeinstallprompt', (ev)=>{ ev.preventDefault(); deferredInstallPrompt = ev; });
window.addEventListener('appinstalled', ()=>{ deferredInstallPrompt = null; toast('Приложение установлено'); });
function isStandaloneApp(){ return (window.matchMedia && matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true; }
function buildInstallRow(){
  if(isStandaloneApp()) return null;
  const row = document.createElement('div');
  row.className = 'settings-row';
  row.id = 'install-app-row';
  row.innerHTML = `<div><div class="settings-row-title">Установить приложение</div><div class="settings-row-sub">Иконка на главном экране, отдельное окно без адресной строки</div></div><div class="settings-chevron">›</div>`;
  row.onclick = async ()=>{
    if(deferredInstallPrompt){
      deferredInstallPrompt.prompt();
      try{ await deferredInstallPrompt.userChoice; }catch(e){}
      deferredInstallPrompt = null;
    }else if(/iPhone|iPad|iPod/i.test(navigator.userAgent)){
      toast('В Safari: кнопка «Поделиться» → «На экран „Домой“»');
    }else{
      toast('Откройте меню браузера → «Установить приложение» или «Добавить на главный экран»');
    }
  };
  return row;
}
function groupSettings(){
  const body = document.getElementById('settings-body');
  if(!body || body.querySelector('.settings-card')) return;
  const units = [];
  let cur = null;
  Array.from(body.children).forEach(el=>{
    if(el.classList.contains('settings-row')){ cur = {row: el, els: [el]}; units.push(cur); }
    else if(cur){ cur.els.push(el); }
    else units.push({row: el, els: [el]});
  });
  const GROUPS = [
    {title: 'Конфиденциальность и безопасность', ids: ['call-restrict-toggle-row','#read-receipts-wrap','pw-toggle-row','pin-toggle-row','duress-pin-toggle-row','retention-toggle-row']},
    {title: 'Уведомления и звуки', ids: ['notif-toggle-row']},
    {title: 'Оформление', ids: ['appearance-toggle-row']},
    {title: 'Перевод и расшифровка', ids: ['ai-lang-row']},
    {title: 'Приложение', ids: ['install-app-row']},
    {title: 'Данные', ids: ['delete-all-row']},
    {title: 'Помощь', ids: ['support-row']},
    {title: 'Администрирование', ids: ['open-admin-row']},
  ];
  const installRow = buildInstallRow();
  if(installRow) units.push({row: installRow, els: [installRow]});
  const aiRow = buildAiLangRow();
  if(aiRow) units.push({row: aiRow, els: [aiRow]});
  const match = (u, key)=> key.startsWith('#') ? !!u.row.querySelector(key) : u.row.id === key;
  const used = new Set();
  const frag = document.createDocumentFragment();
  const addGroup = (title, list)=>{
    if(!list.length) return;
    const t = document.createElement('div'); t.className = 'settings-group-title'; t.textContent = title;
    const card = document.createElement('div'); card.className = 'settings-card';
    list.forEach(u=> u.els.forEach(el=> card.appendChild(el)));
    frag.appendChild(t); frag.appendChild(card);
  };
  GROUPS.forEach(g=>{
    const list = [];
    g.ids.forEach(key=>{ const u = units.find(x=> !used.has(x) && match(x, key)); if(u){ used.add(u); list.push(u); } });
    addGroup(g.title, list);
  });
  addGroup('Прочее', units.filter(u=> !used.has(u)));
  body.innerHTML = '';
  body.appendChild(frag);
}
renderSettings = (function(orig){
  return async function(...args){ const r = await orig.apply(this, args); try{ groupSettings(); }catch(e){ console.error('groupSettings', e); } return r; };
})(renderSettings);

/* ---------- Service Worker (работает, если рядом с index.html лежит sw.js) ---------- */
if('serviceWorker' in navigator && /^https?:$/.test(location.protocol)){
  window.addEventListener('load', ()=>{
    navigator.serviceWorker.register('sw.js').catch(err=> console.warn('Service Worker не зарегистрирован', err));
  });
}

/* ============================================================
   ROUND 4 — ИИ: расшифровка голосовых и перевод сообщений
   (через ваш Cloudflare Worker, адрес задаётся в админ-панели)
============================================================ */
const AI_ENDPOINT_DEFAULT = '';   // можно вписать адрес Worker'а прямо сюда вместо админ-панели
const AI_LANGS = [
  ['ru','Русский'],['en','English'],['uk','Українська'],['be','Беларуская'],['kk','Қазақша'],['uz','Oʻzbekcha'],
  ['de','Deutsch'],['fr','Français'],['es','Español'],['it','Italiano'],['pt','Português'],['pl','Polski'],
  ['tr','Türkçe'],['ar','العربية'],['zh','中文'],['ja','日本語'],['ko','한국어'],['hi','हिन्दी'],
];
function aiEndpoint(){ return String((state.appConfig && state.appConfig.aiEndpoint) || AI_ENDPOINT_DEFAULT || '').replace(/\/+$/,''); }
function aiEnabled(){ return !!aiEndpoint(); }
function aiTargetLang(){
  try{ const v = localStorage.getItem('aiTargetLang'); if(v && AI_LANGS.some(l=> l[0] === v)) return v; }catch(e){}
  const nav = String(navigator.language || 'ru').slice(0,2).toLowerCase();
  return AI_LANGS.some(l=> l[0] === nav) ? nav : 'ru';
}
const AI_ERRORS = {
  not_configured: 'Перевод и расшифровка ещё не настроены администратором',
  quota: 'Дневной бесплатный лимит ИИ исчерпан — попробуйте после 03:00 по Москве',
  rate_limited: 'Слишком много запросов подряд — подождите минуту',
  unauthorized: 'Не удалось подтвердить вход — выйдите и войдите снова',
  audio_too_large: 'Запись слишком длинная для расшифровки',
  text_too_long: 'Сообщение слишком длинное для перевода',
  no_text: 'Здесь нечего переводить',
};
async function aiCall(path, payload){
  const base = aiEndpoint();
  if(!base) throw Object.assign(new Error('not_configured'), {code: 'not_configured'});
  const user = firebase.auth().currentUser;
  if(!user) throw Object.assign(new Error('unauthorized'), {code: 'unauthorized'});
  const token = await user.getIdToken();
  let r;
  try{
    r = await fetch(base + path, {method: 'POST', headers: {'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token}, body: JSON.stringify(payload)});
  }catch(e){ throw Object.assign(new Error('network'), {code: 'network'}); }
  let j = {};
  try{ j = await r.json(); }catch(e){}
  if(!r.ok) throw Object.assign(new Error(j.error || ('http_' + r.status)), {code: j.error || 'ai_error', detail: j.detail});
  return j;
}
function aiErrorText(e){
  if(e && e.code === 'network') return 'Нет связи с сервером ИИ';
  return AI_ERRORS[e && e.code] || 'Сервис ИИ сейчас недоступен, попробуйте позже';
}

/* --- аудио → WAV 16 кГц моно (понимает любой распознаватель, в т.ч. записи с iPhone) --- */
function bytesToBase64(bytes){
  let bin = '';
  const CH = 0x8000;
  for(let i=0;i<bytes.length;i+=CH) bin += String.fromCharCode.apply(null, bytes.subarray(i, i+CH));
  return btoa(bin);
}
async function mediaToWavBase64(src){
  const buf = await (await fetch(src)).arrayBuffer();
  const Ctx = window.AudioContext || window.webkitAudioContext;
  const OffCtx = window.OfflineAudioContext || window.webkitOfflineAudioContext;
  if(!Ctx || !OffCtx) throw new Error('no_audio_api');
  const ctx = new Ctx();
  let decoded;
  try{
    decoded = await new Promise((res, rej)=>{
      const pr = ctx.decodeAudioData(buf.slice(0), res, rej);
      if(pr && pr.then) pr.then(res, rej);
    });
  }finally{ try{ ctx.close(); }catch(e){} }
  const RATE = 16000;
  const len = Math.max(1, Math.ceil(decoded.duration * RATE));
  const off = new OffCtx(1, len, RATE);
  const node = off.createBufferSource();
  node.buffer = decoded; node.connect(off.destination); node.start();
  const pcm = (await off.startRendering()).getChannelData(0);
  const out = new ArrayBuffer(44 + pcm.length*2);
  const v = new DataView(out);
  const w = (o, str)=>{ for(let i=0;i<str.length;i++) v.setUint8(o+i, str.charCodeAt(i)); };
  w(0,'RIFF'); v.setUint32(4, 36 + pcm.length*2, true); w(8,'WAVE'); w(12,'fmt ');
  v.setUint32(16,16,true); v.setUint16(20,1,true); v.setUint16(22,1,true); v.setUint32(24,RATE,true);
  v.setUint32(28,RATE*2,true); v.setUint16(32,2,true); v.setUint16(34,16,true); w(36,'data'); v.setUint32(40, pcm.length*2, true);
  for(let i=0;i<pcm.length;i++){ const x = Math.max(-1, Math.min(1, pcm[i])); v.setInt16(44+i*2, x < 0 ? x*0x8000 : x*0x7FFF, true); }
  return bytesToBase64(new Uint8Array(out));
}

/* --- кэш и состояние --- */
const aiPending = {};
const aiShownTranslations = new Set();
const aiHiddenTranscripts = new Set();
function hashText(t){ let h = 0; for(let i=0;i<t.length;i++){ h = (h*31 + t.charCodeAt(i)) | 0; } return (h >>> 0).toString(36); }
function lsGet(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }
function lsSet(k, v){ try{ localStorage.setItem(k, v); }catch(e){} }
function getTranscript(m){
  if(typeof m.transcript === 'string') return m.transcript;
  const c = lsGet('stt:' + m.id);
  return c === null ? null : c;
}
function translationSource(m){
  if(m.type === 'text') return m.content || '';
  if(m.type === 'voice' || m.type === 'roundvideo') return getTranscript(m) || '';
  return '';
}
function translationKey(m){ const src = translationSource(m); return src ? `tr:${aiTargetLang()}:${m.id}:${hashText(src)}` : null; }

async function transcribeMessage(m){
  if(!aiEnabled()) return toast(AI_ERRORS.not_configured);
  if(getTranscript(m) !== null){
    if(aiHiddenTranscripts.has(m.id)) aiHiddenTranscripts.delete(m.id); else aiHiddenTranscripts.add(m.id);
    applyAiExtras();
    return;
  }
  if(aiPending['stt:' + m.id]) return;
  aiPending['stt:' + m.id] = true;
  applyAiExtras();
  try{
    let audio;
    try{ audio = await mediaToWavBase64(m.content); }
    catch(e){ audio = String(m.content || '').replace(/^data:[^,]*,/, ''); }
    const res = await aiCall('/transcribe', {audio, language: (localStorage.getItem('sttLang') || 'ru'), task: 'transcribe'});   // ROUND 83: язык речи
    const text = String(res.text || '').trim();
    lsSet('stt:' + m.id, text);
    // Сохраняем в само сообщение, чтобы собеседнику не пришлось расшифровывать заново.
    // Требует обновлённых правил Firestore (поле transcript) — без них расшифровка останется только у вас.
    db.collection('messages').doc(m.id).update({transcript: text}).catch(err=>{
      if(!window.__transcriptRuleWarned){ window.__transcriptRuleWarned = true; console.warn('Расшифровка не сохранена в Firestore — обновите правила (поле transcript).', err); }
    });
  }catch(e){ toast(aiErrorText(e)); }
  finally{ delete aiPending['stt:' + m.id]; applyAiExtras(); }
}

async function translateMessage(m){
  if(!aiEnabled()) return toast(AI_ERRORS.not_configured);
  if(aiShownTranslations.has(m.id)){ aiShownTranslations.delete(m.id); applyAiExtras(); return; }
  if((m.type === 'voice' || m.type === 'roundvideo') && getTranscript(m) === null){
    await transcribeMessage(m);
    if(getTranscript(m) === null) return;
  }
  const src = translationSource(m);
  if(!src.trim()) return toast(AI_ERRORS.no_text);
  const key = translationKey(m);
  if(lsGet(key) !== null){ aiShownTranslations.add(m.id); applyAiExtras(); return; }
  if(aiPending['tr:' + m.id]) return;
  aiPending['tr:' + m.id] = true;
  applyAiExtras();
  try{
    const res = await aiCall('/translate', {text: src, target: aiTargetLang()});
    lsSet(key, String(res.text || '').trim());
    aiShownTranslations.add(m.id);
  }catch(e){ toast(aiErrorText(e)); }
  finally{ delete aiPending['tr:' + m.id]; applyAiExtras(); }
}

function aiBlockHtml(label, text, loading){
  return `<div class="ai-block ${loading ? 'loading' : ''}"><div class="ai-block-label">${loading ? '<span class="ai-spinner"></span>' : ''}${escapeHtml(label)}</div><div class="ai-block-text">${loading ? (label === 'Перевод' ? 'Переводим…' : 'Распознаём речь…') : escapeHtml(text)}</div></div>`;
}
function applyAiExtras(){
  const box = document.getElementById('messages');
  if(!box || !state.currentMessages) return;
  box.querySelectorAll('.msg-row[data-id]').forEach(row=>{
    row.querySelectorAll('.ai-block').forEach(b=> b.remove());
    const id = row.getAttribute('data-id');
    const m = state.currentMessages.find(x=> x.id === id);
    const bubble = row.querySelector('.bubble');
    if(!m || !bubble) return;
    const blocks = [];
    const isMedia = m.type === 'voice' || m.type === 'roundvideo';
    if(isMedia){
      const tr = getTranscript(m);
      if(aiPending['stt:' + id]) blocks.push(aiBlockHtml('Расшифровка', '', true));
      else if(tr !== null && !aiHiddenTranscripts.has(id)) blocks.push(aiBlockHtml('Расшифровка', tr || 'Речь не распознана'));
      const btn = row.querySelector('.voice-stt-btn');
      if(btn) btn.classList.toggle('on', tr !== null && !aiHiddenTranscripts.has(id));
    }
    if(aiPending['tr:' + id]) blocks.push(aiBlockHtml('Перевод', '', true));
    else if(aiShownTranslations.has(id)){
      const key = translationKey(m);
      const t = key ? lsGet(key) : null;
      if(t !== null) blocks.push(aiBlockHtml('Перевод', t));
    }
    if(!blocks.length) return;
    const html = blocks.join('');
    if(m.type === 'roundvideo'){ bubble.insertAdjacentHTML('afterend', html); return; }
    const time = bubble.querySelector(':scope > .time');
    if(time) time.insertAdjacentHTML('beforebegin', html); else bubble.insertAdjacentHTML('beforeend', html);
  });
}
new MutationObserver(()=>{ try{ applyAiExtras(); }catch(e){} })
  .observe(document.getElementById('messages'), {childList: true});

const ICON_TRANSLATE_UI = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5h9"/><path d="M8.5 3v2"/><path d="M11 5c-.8 3.6-3.3 6.4-6.5 8"/><path d="M6.5 8.5c1 1.8 2.6 3.3 4.5 4.3"/><path d="M13 21l4-9 4 9"/><path d="M14.4 18h5.2"/></svg>';
const ICON_TRANSCRIBE_UI = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="M7 9h10"/><path d="M7 13h7"/><path d="M7 17h4"/></svg>';
function setupAiActions(m){
  const tBtn = document.getElementById('msg-action-translate');
  const sBtn = document.getElementById('msg-action-transcribe');
  if(!tBtn || !sBtn) return;
  const on = aiEnabled();
  const isMedia = m.type === 'voice' || m.type === 'roundvideo';
  const canTranslate = on && ((m.type === 'text' && (m.content||'').trim()) || isMedia);
  tBtn.style.display = canTranslate ? 'flex' : 'none';
  tBtn.innerHTML = `${ICON_TRANSLATE_UI}<span>${aiShownTranslations.has(m.id) ? 'Скрыть перевод' : 'Перевести'}</span>`;
  tBtn.onclick = ()=>{ closeMsgActionSheet(); translateMessage(m); };
  const hasTr = getTranscript(m) !== null;
  sBtn.style.display = (on && isMedia) ? 'flex' : 'none';
  sBtn.innerHTML = `${ICON_TRANSCRIBE_UI}<span>${hasTr ? (aiHiddenTranscripts.has(m.id) ? 'Показать расшифровку' : 'Скрыть расшифровку') : 'Расшифровать в текст'}</span>`;
  sBtn.onclick = ()=>{ closeMsgActionSheet(); transcribeMessage(m); };
}

function buildAiLangRow(){
  if(!aiEnabled()) return null;
  const row = document.createElement('div');
  row.className = 'settings-row';
  row.id = 'ai-lang-row';
  row.style.cursor = 'default';
  const cur = aiTargetLang();
  row.innerHTML = `<div><div class="settings-row-title">Язык перевода</div><div class="settings-row-sub">На этот язык переводятся сообщения. Если сообщение уже на нём — переводится на английский.</div></div>
    <select class="ai-lang-select" id="ai-lang-select" aria-label="Язык перевода">${AI_LANGS.map(([c,n])=> `<option value="${c}" ${c===cur?'selected':''}>${n}</option>`).join('')}</select>`;
  row.querySelector('select').addEventListener('change', (ev)=>{
    lsSet('aiTargetLang', ev.target.value);
    aiShownTranslations.clear();
    applyAiExtras();
    toast('Язык перевода сохранён');
  });
  return row;
}

/* ============================================================
   ROUND 5 — длительность голосовых без «прокрутки в конец»
============================================================ */
function voiceDur(audio){
  if(isFinite(audio.duration) && audio.duration > 0) return audio.duration;
  return audio._knownDur || 0;
}
const voiceDurCache = {};
function probeVoiceDuration(src){
  if(voiceDurCache[src]) return Promise.resolve(voiceDurCache[src]);
  return new Promise(resolve=>{
    const probe = new Audio();
    probe.muted = true;
    probe.preload = 'metadata';
    const done = d=>{ if(d) voiceDurCache[src] = d; probe.removeAttribute('src'); try{ probe.load(); }catch(e){} resolve(d); };
    probe.addEventListener('loadedmetadata', ()=>{
      if(isFinite(probe.duration)) return done(probe.duration);
      probe.addEventListener('durationchange', ()=>{ if(isFinite(probe.duration)) done(probe.duration); }, {once: true});
      probe.currentTime = 1e101;   // прокручивается беззвучный пробный плеер, а не тот, что играет
    });
    probe.addEventListener('error', ()=> done(0));
    setTimeout(()=> done(0), 8000);
    probe.src = src;
  });
}

/* ============================================================
   ROUND 6 — Telegram: группировка пузырей, голосовые, звонки,
   удержание для записи, кружки, контекстное меню строк
============================================================ */

/* ---------- группировка сообщений и хвостики ---------- */
function applyTgGrouping(){
  const box = document.getElementById('messages');
  if(!box || !state.currentMessages) return;
  const byId = {};
  state.currentMessages.forEach(m=> byId[m.id] = m);
  let prev = null;          // {row, m}
  const rows = [];
  Array.from(box.children).forEach(el=>{
    if(el.classList.contains('msg-row') && el.dataset.id && byId[el.dataset.id]) rows.push({row: el, m: byId[el.dataset.id]});
    else rows.push({divider: true});
  });
  const same = (a, b)=> a && b && !a.divider && !b.divider && a.m.from === b.m.from && Math.abs((b.m.timestamp||0) - (a.m.timestamp||0)) < 5*60*1000
    && a.m.type !== 'call' && b.m.type !== 'call';
  rows.forEach((cur, i)=>{
    if(cur.divider) return;
    const before = rows[i-1], after = rows[i+1];
    const joinPrev = same(before, cur), joinNext = same(cur, after);
    const r = cur.row;
    r.classList.remove('grp-first','grp-mid','grp-last','tail');
    if(joinPrev && joinNext) r.classList.add('grp-mid');
    else if(joinPrev) r.classList.add('grp-last','tail');
    else if(joinNext) r.classList.add('grp-first');
    else r.classList.add('grp-first','tail');
  });
}

/* ---------- голосовые: точка «не прослушано», звонок из пузыря ---------- */
function playedVoiceSet(){
  try{ return new Set(JSON.parse(localStorage.getItem('voicePlayed') || '[]')); }catch(e){ return new Set(); }
}
function markVoicePlayed(id){
  if(!id) return;
  const set = playedVoiceSet();
  if(set.has(id)) return;
  set.add(id);
  try{ localStorage.setItem('voicePlayed', JSON.stringify(Array.from(set).slice(-800))); }catch(e){}
}
function applyVoiceUnplayed(){
  const set = playedVoiceSet();
  const me = state.currentUser && state.currentUser.uid;
  document.querySelectorAll('#messages .msg-row[data-id]').forEach(row=>{
    const el = row.querySelector('.voice-msg');
    if(!el) return;
    const m = (state.currentMessages||[]).find(x=> x.id === row.dataset.id);
    el.classList.toggle('unplayed', !!m && m.from !== me && !set.has(m.id));
  });
}
toggleVoicePlayback = (function(orig){
  return function(src, btn, ...rest){
    const row = btn && btn.closest('.msg-row');
    if(row){ markVoicePlayed(row.dataset.id); const v = row.querySelector('.voice-msg'); if(v) v.classList.remove('unplayed'); }
    return orig.call(this, src, btn, ...rest);
  };
})(toggleVoicePlayback);

document.getElementById('messages').addEventListener('click', (ev)=>{
  const b = ev.target.closest('.call-msg-btn[data-callback-kind]');
  if(!b) return;
  ev.stopPropagation();
  const btn = document.getElementById(b.dataset.callbackKind === 'video' ? 'videocall-btn-header' : 'call-btn-header');
  if(btn && btn.style.display !== 'none') btn.click();
  else toast('Собеседник ограничил такие звонки');
});

new MutationObserver(()=>{ try{ applyTgGrouping(); applyVoiceUnplayed(); }catch(e){} })
  .observe(document.getElementById('messages'), {childList: true});

/* ---------- удержание для записи (голосовое и кружок) ---------- */
const ICON_MIC_BIG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0"/><line x1="12" y1="18" x2="12" y2="21"/></svg>';
const ICON_CAM_BIG = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="6.5" width="13" height="11" rx="2.5"/><path d="M15.5 10.8l5-3v8.4l-5-3z"/></svg>';
const holdLayer = document.getElementById('tg-hold-layer');
const holdFab = document.getElementById('tg-hold-fab');
const holdHalo = document.getElementById('tg-hold-halo');
const holdLock = document.getElementById('tg-hold-lock');
let holdRaf = null;
function showHoldUI(kind, btn){
  const r = btn.getBoundingClientRect();
  const cx = r.left + r.width/2, cy = r.top + r.height/2;
  holdFab.style.left = cx + 'px'; holdFab.style.top = cy + 'px';
  holdLock.style.left = cx + 'px'; holdLock.style.top = (cy - 46 - 96) + 'px';
  holdLock.classList.remove('armed');
  document.getElementById('tg-hold-icon').innerHTML = kind === 'video' ? ICON_CAM_BIG : ICON_MIC_BIG;
  holdLayer.classList.add('show');
  cancelAnimationFrame(holdRaf);
  const tick = ()=>{
    const lvl = (kind === 'voice' && recMeter) ? recMeter.last || 0 : 0.15 + 0.1*Math.sin(Date.now()/260);
    holdHalo.style.transform = `scale(${1 + Math.min(1, lvl)*0.9})`;
    holdRaf = requestAnimationFrame(tick);
  };
  tick();
}
function moveHoldUI(kind, dx, dy){
  const cancelDist = Math.min(150, window.innerWidth*0.33);
  const fx = Math.max(-cancelDist, Math.min(0, dx));
  const fy = Math.max(-90, Math.min(0, dy));
  holdFab.style.transform = `translate(${fx*0.6}px, ${fy*0.4}px)`;
  holdLock.classList.toggle('armed', dy < -45);
  const hint = kind === 'video' ? document.querySelector('#roundvideo-overlay .rec-slide-hint') : document.getElementById('rec-slide-hint');
  if(hint){ hint.style.transform = `translateX(${fx*0.5}px)`; hint.style.opacity = String(1 - Math.min(0.8, -fx/cancelDist)); }
}
function hideHoldUI(){
  holdLayer.classList.remove('show');
  holdFab.style.transform = '';
  cancelAnimationFrame(holdRaf);
  document.querySelectorAll('.rec-slide-hint').forEach(h=>{ h.style.transform = ''; h.style.opacity = ''; });
}
function attachTgHold(btn, h){
  // Кнопка микрофона/камеры прячется, как только начинается запись. На телефонах браузер
  // после этого перестаёт слать ей события пальца — поэтому следим за пальцем на уровне окна
  // (события касания всегда приходят к месту, где касание началось).
  let st = null;
  const CANCEL_DIST = ()=> Math.min(150, window.innerWidth*0.33);
  btn.style.touchAction = 'none';
  btn.addEventListener('contextmenu', ev=> ev.preventDefault());
  const begin = (x, y, kind, id)=>{
    if(st || !state.activeChatId || state.activeCallState || h.isActive()) return false;
    const token = {released: false, kind: null};
    st = {kind, id, x0: x, y0: y, t0: Date.now(), token};
    h.prepare();
    showHoldUI(h.kind, btn);
    Promise.resolve(h.start()).then(ok=>{
      if(!ok){ hideHoldUI(); h.abort(); if(st && st.token === token) st = null; return; }
      if(token.released){
        // палец отпустили раньше, чем включился микрофон/камера (например, спросили разрешение)
        h.cancel();
        if(token.kind === 'lock') return;
        showHoldHint(btn, token.kind === 'tap' ? h.tapHint : h.retryHint);
      }
    });
    return true;
  };
  const move = (x, y)=>{
    if(!st) return;
    const dx = x - st.x0, dy = y - st.y0;
    moveHoldUI(h.kind, dx, dy);
    if(dx < -CANCEL_DIST()){ haptic('buttons', 12); finish('cancel'); }
    else if(dy < -90){ haptic('buttons', 12); finish('lock'); }
  };
  const release = ()=>{ if(st) finish(Date.now() - st.t0 < 350 ? 'tap' : 'send'); };
  const finish = (kind)=>{
    if(!st) return;
    const token = st.token;
    st = null;
    hideHoldUI();
    if(!h.isActive()){ token.released = true; token.kind = kind; return; }
    if(kind === 'cancel') h.cancel();
    else if(kind === 'lock') h.lock();
    else if(kind === 'tap'){ h.cancel(); showHoldHint(btn, h.tapHint); }
    else h.send();
  };
  // сенсорный экран
  btn.addEventListener('touchstart', (ev)=>{
    const t = ev.changedTouches[0];
    if(begin(t.clientX, t.clientY, 'touch', t.identifier)) ev.preventDefault();
  }, {passive: false});
  const findTouch = (list)=>{ if(!st) return null; for(const t of list) if(t.identifier === st.id) return t; return null; };
  window.addEventListener('touchmove', (ev)=>{
    if(!st || st.kind !== 'touch') return;
    const t = findTouch(ev.changedTouches);
    if(!t) return;
    if(ev.cancelable) ev.preventDefault();
    move(t.clientX, t.clientY);
  }, {passive: false, capture: true});
  window.addEventListener('touchend', (ev)=>{ if(st && st.kind === 'touch' && findTouch(ev.changedTouches)) release(); }, true);
  window.addEventListener('touchcancel', (ev)=>{ if(st && st.kind === 'touch' && findTouch(ev.changedTouches)) finish('cancel'); }, true);
  // мышь (компьютер)
  btn.addEventListener('mousedown', (ev)=>{
    if(ev.button !== 0) return;
    if(begin(ev.clientX, ev.clientY, 'mouse', 'mouse')) ev.preventDefault();
  });
  window.addEventListener('mousemove', (ev)=>{ if(st && st.kind === 'mouse') move(ev.clientX, ev.clientY); }, true);
  window.addEventListener('mouseup', ()=>{ if(st && st.kind === 'mouse') release(); }, true);
  window.addEventListener('blur', ()=>{ if(st) finish('cancel'); });
}

