const recBarEl = document.getElementById('composer-recording');
attachTgHold(document.getElementById('mic-btn'), {
  kind: 'voice',
  tapHint: 'Удерживайте, чтобы записать голосовое. Отпустите — отправится',
  retryHint: 'Микрофон готов — теперь удерживайте кнопку, чтобы записать',
  abort(){ recBarEl.classList.remove('holding'); },
  prepare(){ recBarEl.classList.add('holding'); },
  async start(){
    await startVoiceRecording();
    const ok = !!(recMediaRecorder && recMediaRecorder.state === 'recording' && recBarEl.style.display !== 'none');
    if(!ok) recBarEl.classList.remove('holding');
    return ok;
  },
  isActive(){ return !!(recMediaRecorder && recMediaRecorder.state !== 'inactive' && recBarEl.style.display !== 'none'); },
  lock(){ recBarEl.classList.remove('holding'); },
  send(){ recBarEl.classList.remove('holding'); finishRecordingAndSend(); },
  cancel(){ recBarEl.classList.remove('holding'); cancelRecording(); },
});

/* кружок */
const rvOverlay = document.getElementById('roundvideo-overlay');
const rvRing = document.getElementById('rv-ring-fg');
const RV_RING_LEN = 2*Math.PI*47;
rvRing.style.strokeDasharray = RV_RING_LEN;
rvRing.style.strokeDashoffset = RV_RING_LEN;
updateRoundVideoTimer = (function(orig){
  return function(...args){
    const ms = Date.now() - roundVideoStartTime;
    const secs = Math.floor(ms/1000);
    const t = document.getElementById('rv-timer');
    if(t) t.textContent = Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0');
    rvRing.style.strokeDashoffset = RV_RING_LEN * (1 - Math.min(1, ms/(ROUNDVIDEO_MAX_SECONDS*1000)));
    return orig.apply(this, args);
  };
})(updateRoundVideoTimer);
let rvAutoSend = false;
stopRoundVideoRecordingAndPreview = (function(orig){
  return async function(...args){
    const review = document.getElementById('roundvideo-review-overlay');
    const auto = rvAutoSend;
    rvAutoSend = false;
    if(auto) review.style.visibility = 'hidden';
    try{ await orig.apply(this, args); }
    finally{ rvOverlay.classList.remove('holding','locked'); }
    if(auto){
      if(roundVideoBlob) document.getElementById('roundvideo-send-btn').click();
      review.style.visibility = '';
    }
  };
})(stopRoundVideoRecordingAndPreview);
discardRoundVideo = (function(orig){
  return function(...args){
    rvOverlay.classList.remove('holding','locked');
    rvRing.style.strokeDashoffset = RV_RING_LEN;
    const t = document.getElementById('rv-timer'); if(t) t.textContent = '0:00';
    return orig.apply(this, args);
  };
})(discardRoundVideo);
attachTgHold(document.getElementById('roundvideo-btn'), {
  kind: 'video',
  tapHint: 'Удерживайте, чтобы записать кружок. Отпустите — отправится',
  retryHint: 'Камера готова — теперь удерживайте кнопку, чтобы записать',
  abort(){ rvOverlay.classList.remove('holding','locked'); },
  prepare(){ rvOverlay.classList.add('holding'); rvOverlay.classList.remove('locked'); rvRing.style.strokeDashoffset = RV_RING_LEN; },
  async start(){
    await startRoundVideoRecording();
    const ok = !!(roundVideoRecorder && roundVideoRecorder.state === 'recording' && rvOverlay.style.display !== 'none');
    if(!ok) rvOverlay.classList.remove('holding');
    return ok;
  },
  isActive(){ return !!(roundVideoRecorder && roundVideoRecorder.state !== 'inactive' && rvOverlay.style.display !== 'none'); },
  lock(){ rvOverlay.classList.remove('holding'); rvOverlay.classList.add('locked'); },
  send(){ rvAutoSend = true; stopRoundVideoRecordingAndPreview(); },
  cancel(){ discardRoundVideo(); },
});
document.getElementById('rv-cancel-btn').onclick = ()=> discardRoundVideo();
document.getElementById('rv-stop-btn').onclick = ()=>{ rvAutoSend = false; stopRoundVideoRecordingAndPreview(); };
document.getElementById('rv-send-btn').onclick = ()=>{ rvAutoSend = true; stopRoundVideoRecordingAndPreview(); };

