function closeRowMenu(){
  const ov = document.getElementById('row-menu-overlay');
  if(!ov) return;
  ov.classList.remove('open');
  setTimeout(()=> ov.remove(), 180);
}
function openRowMenu(row, items){
  const old = document.getElementById('row-menu-overlay');
  if(old) old.remove();
  const rect = row.getBoundingClientRect();
  const ov = document.createElement('div');
  ov.id = 'row-menu-overlay';
  const clone = row.cloneNode(true);
  clone.classList.add('row-menu-clone');
  clone.removeAttribute('id');
  clone.querySelectorAll('[id]').forEach(e=> e.removeAttribute('id'));
  Object.assign(clone.style, {position: 'fixed', left: rect.left+'px', top: rect.top+'px', width: rect.width+'px', height: rect.height+'px', margin: '0', boxSizing: 'border-box'});
  const menu = document.createElement('div');
  menu.className = 'row-menu';
  menu.setAttribute('role', 'menu');
  items.forEach(it=>{
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'row-menu-item' + (it.danger ? ' danger' : '');
    b.innerHTML = `<span>${escapeHtml(it.label)}</span>${it.icon || ''}`;
    b.onclick = (e)=>{ e.stopPropagation(); closeRowMenu(); setTimeout(()=>{ try{ it.action(); }catch(err){ console.error(err); } }, 0); };
    menu.appendChild(b);
  });
  ov.appendChild(clone);
  ov.appendChild(menu);
  document.body.appendChild(ov);
  const mh = menu.offsetHeight, mw = menu.offsetWidth, vh = window.innerHeight, vw = window.innerWidth;
  let top = rect.bottom + 8, origin = 'top';
  if(top + mh > vh - 12){
    if(rect.top - mh - 8 >= 12){ top = rect.top - mh - 8; origin = 'bottom'; }
    else{ top = Math.max(12, vh - mh - 12); }
  }
  const left = Math.min(Math.max(12, rect.left + 14), vw - mw - 12);
  menu.style.top = top + 'px';
  menu.style.left = left + 'px';
  menu.style.transformOrigin = origin + ' left';
  ov.addEventListener('click', (e)=>{ if(e.target === ov) closeRowMenu(); });
  requestAnimationFrame(()=> requestAnimationFrame(()=> ov.classList.add('open')));
}
async function openChatWithUser(uid, name){
  try{
    const p = await getUserProfile(uid);
    const meta = await ensureChat(uid, (p && p.username) || name || uid, (p && p.email) || '');
    switchTab('chats');
    if(typeof switchChatsSubtab === 'function') switchChatsSubtab('chats');
    openChat(meta.id);
  }catch(e){}
}
function rowButtonsAsItems(row, skip){
  const out = [];
  row.querySelectorAll('button[title]').forEach(b=>{
    if(b.offsetParent === null) return;
    const t = b.getAttribute('title');
    if(!t || (skip && skip.test(t))) return;
    const svg = b.querySelector('svg');
    out.push({label: t, icon: svg ? svg.outerHTML : '', action: ()=> b.click()});
  });
  return out;
}
function muteItem(meta){
  const me = state.currentUser.uid;
  const level = (meta.mutedBy && meta.mutedBy[me]) || 'none';
  const muted = level !== 'none';
  return {label: muted ? 'Включить уведомления' : 'Выключить уведомления', icon: muted ? RM_ICON.unmute : RM_ICON.mute, action: async ()=>{
    const newMutedBy = Object.assign({}, meta.mutedBy || {});
    if(muted) delete newMutedBy[me]; else newMutedBy[me] = 'all';
    meta.mutedBy = newMutedBy;
    if(state.activeChatId === meta.id && state.activeChatMeta){ state.activeChatMeta.mutedBy = newMutedBy; updateMuteIcon(); }
    try{ await db.collection('chats').doc(meta.id).update({mutedBy: newMutedBy}); toast(muted ? 'Уведомления включены' : 'Уведомления выключены'); }
    catch(e){ toast('Не удалось сохранить'); }
  }};
}
function chatRowItems(row){
  if(state.chatSelectMode) return [];
  const id = row.dataset.id;
  const meta = (state.chats||[]).find(c=> c.id === id);
  if(!meta) return [];
  const me = state.currentUser.uid;
  const pinned = (meta.pinnedBy||[]).includes(me);
  const items = [];
  if(isChatUnread(meta)) items.push({label: 'Отметить прочитанным', icon: RM_ICON.read, action: async ()=>{
    try{ await db.collection('chats').doc(id).update({['lastReadBy.'+me]: Date.now()}); }catch(e){ toast('Не удалось'); }
  }});
  items.push({label: pinned ? 'Открепить' : 'Закрепить', icon: RM_ICON.pin, action: async ()=>{
    try{
      await db.collection('chats').doc(id).update({pinnedBy: pinned ? firebase.firestore.FieldValue.arrayRemove(me) : firebase.firestore.FieldValue.arrayUnion(me)});
      toast(pinned ? 'Откреплено' : 'Закреплено');
    }catch(e){ toast('Не удалось'); }
  }});
  if(!meta.isSupport) items.push(muteItem(meta));
  if(meta.isCommunity) items.push({label: 'Участники', icon: RM_ICON.users, action: ()=> openCommunityMembers(id)});
  items.push({label: 'Выбрать', icon: RM_ICON.select, action: ()=>{ enterChatSelectMode('delete'); state.selectedChats.add(id); renderChatList(); }});
  items.push({label: 'Удалить', icon: RM_ICON.trash, danger: true, action: ()=> openDeleteActionSheet(async ()=>{ state.selectedChats = new Set([id]); await deleteSelectedChats(); })});
  return items;
}
function communityRowItems(row){
  const id = row.dataset.communityId;
  const meta = (state.chats||[]).find(c=> c.id === id);
  const items = [
    {label: 'Открыть', icon: RM_ICON.open, action: ()=> row.click()},
    {label: 'Участники', icon: RM_ICON.users, action: ()=> openCommunityMembers(id)},
  ];
  if(meta) items.push(muteItem(meta));
  items.push({label: 'Покинуть сообщество', icon: RM_ICON.leave, danger: true, action: async ()=>{
    if(!await uiConfirm('Покинуть сообщество?')) return;
    await leaveCommunity(id);
    renderCommunitiesTab();
  }});
  return items;
}
function callRowItems(row){
  if(state.callLogSelectMode) return [];
  const uid = row.dataset.uid, name = row.dataset.name, logId = row.dataset.logId;
  if(!uid) return [];
  return [
    {label: 'Аудиозвонок', icon: RM_ICON.phone, action: ()=> callBackFromLog(uid, name, 'audio')},
    {label: 'Видеозвонок', icon: RM_ICON.video, action: ()=> callBackFromLog(uid, name, 'video')},
    {label: 'Написать', icon: RM_ICON.chat, action: ()=> openChatWithUser(uid, name)},
    {label: 'Профиль', icon: RM_ICON.user, action: ()=> openUserInfo(uid)},
    {label: 'Выбрать', icon: RM_ICON.select, action: ()=>{ enterCallLogSelectMode(); state.selectedCallLogs.add(logId); renderCallsList(); }},
    {label: 'Удалить из истории', icon: RM_ICON.trash, danger: true, action: ()=> openDeleteActionSheet(async ()=>{ state.selectedCallLogs = new Set([logId]); await deleteSelectedCallLogs(); })},
  ];
}
function contactRowItems(row){
  if(state.contactSelectMode) return [];
  const uid = row.dataset.contactRow;
  const items = rowButtonsAsItems(row);
  items.push({label: 'Профиль', icon: RM_ICON.user, action: ()=> openUserInfo(uid)});
  items.push({label: 'Выбрать', icon: RM_ICON.select, action: ()=>{ enterContactSelectMode('delete'); state.selectedContacts.add(uid); renderContacts(); }});
  items.push({label: 'Удалить из контактов', icon: RM_ICON.trash, danger: true, action: ()=> openDeleteActionSheet(async ()=>{ state.selectedContacts = new Set([uid]); await deleteSelectedContacts(); })});
  return items;
}
function discoveryRowItems(row){
  const items = [];
  const uid = row.dataset.uid || (row.querySelector('[data-uid]') && row.querySelector('[data-uid]').dataset.uid)
    || (row.querySelector('[data-sender-uid]') && row.querySelector('[data-sender-uid]').dataset.senderUid);
  if(uid){
    items.push({label: 'Профиль', icon: RM_ICON.user, action: ()=> openUserInfo(uid)});
    if(uid !== state.currentUser.uid){
      const nameEl = row.querySelector('.name');
      items.push({label: 'Написать', icon: RM_ICON.chat, action: ()=> openChatWithUser(uid, nameEl ? nameEl.textContent.trim() : '')});
    }
  }
  items.push(...rowButtonsAsItems(row, /^(Профиль|Написать)$/));
  if(row.dataset.reactionId){
    items.push({label: 'Удалить', icon: RM_ICON.trash, danger: true, action: ()=> openDeleteActionSheet(async ()=>{
      try{ await db.collection(row.dataset.reactionKind).doc(row.dataset.reactionId).delete(); renderReactionsSubtab(); }
      catch(e){ toast('Не удалось удалить'); }
    })});
  }
  return items;
}
function rowMenuItems(row){
  if(row.id === 'calls-tab-incoming-row') return [];
  if(row.closest('#chat-list') && row.dataset.id) return chatRowItems(row);
  if(row.dataset.communityId) return communityRowItems(row);
  if(row.classList.contains('call-log-row')) return callRowItems(row);
  if(row.dataset.contactRow) return contactRowItems(row);
  if(row.closest('#tab-discovery')) return discoveryRowItems(row);
  return [];
}
(function setupRowLongPress(){
  const SEL = '#tab-chats .chat-item, #tab-contacts .chat-item, #tab-calls .chat-item, #tab-discovery .chat-item';
  let timer = null, row = null, sx = 0, sy = 0, fired = false, suppressUntil = 0;
  document.addEventListener('pointerdown', (e)=>{
    if(e.button > 0) return;
    const r = e.target.closest(SEL);
    if(!r || e.target.closest('input, textarea, select, .toggle-switch, .settings-expand')) return;
    row = r; sx = e.clientX; sy = e.clientY; fired = false;
    clearTimeout(timer);
    timer = setTimeout(()=>{
      if(!row) return;
      const items = rowMenuItems(row);
      if(!items.length) return;
      fired = true;
      haptic('buttons', 12);
      openRowMenu(row, items);
    }, 450);
  }, true);
  document.addEventListener('pointermove', (e)=>{
    if(row && (Math.abs(e.clientX - sx) > 10 || Math.abs(e.clientY - sy) > 10)){ clearTimeout(timer); row = null; }
  }, true);
  const end = ()=>{ clearTimeout(timer); row = null; if(fired){ fired = false; suppressUntil = Date.now() + 400; } };
  document.addEventListener('pointerup', end, true);
  document.addEventListener('pointercancel', end, true);
  document.addEventListener('click', (e)=>{
    if(Date.now() < suppressUntil && !e.target.closest('#row-menu-overlay .row-menu')){ e.stopPropagation(); e.preventDefault(); suppressUntil = 0; }
  }, true);
  document.addEventListener('contextmenu', (e)=>{
    const r = e.target.closest(SEL);
    if(!r) return;
    e.preventDefault();
    if(document.getElementById('row-menu-overlay')) return;
    const items = rowMenuItems(r);
    if(items.length) openRowMenu(r, items);
  }, true);
  document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape') closeRowMenu(); });
})();

/* ============================================================
   ROUND 7
============================================================ */
renderImgPreviews = (function(orig){ return function(...a){ const r = orig.apply(this, a); updateSendBtnVisibility(); return r; }; })(renderImgPreviews);
renderFilePreviews = (function(orig){ return function(...a){ const r = orig.apply(this, a); updateSendBtnVisibility(); return r; }; })(renderFilePreviews);

const EMOJI_ONLY_RE = /^(?:\s*(?:\p{Extended_Pictographic}|\p{Regional_Indicator}{2})(?:\uFE0F|\u200D(?:\p{Extended_Pictographic}|\uFE0F)|[\u{1F3FB}-\u{1F3FF}])*\s*){1,3}$/u;
function applyTgExtras(){
  const box = document.getElementById('messages');
  if(!box || !state.currentMessages) return;
  box.querySelectorAll('.msg-row[data-id]').forEach(row=>{
    const m = state.currentMessages.find(x=> x.id === row.dataset.id);
    const bubble = row.querySelector('.bubble');
    if(!m || !bubble) return;
    const emojiOnly = m.type === 'text' && !m.replyTo && EMOJI_ONLY_RE.test(String(m.content || ''));
    bubble.classList.toggle('emoji-only', emojiOnly);
    if(emojiOnly) bubble.classList.add('media-bubble');
    const v = row.querySelector('.voice-msg');
    if(v) v.classList.toggle('playing', !!(activeVoiceAudio && activeVoiceSrc && v.getAttribute('data-src') === activeVoiceSrc));
  });
}
new MutationObserver(()=>{ try{ applyTgExtras(); }catch(e){} })
  .observe(document.getElementById('messages'), {childList: true});
toggleVoicePlayback = (function(orig){
  return function(...args){
    const r = orig.apply(this, args);
    document.querySelectorAll('#messages .voice-msg.playing').forEach(v=> v.classList.remove('playing'));
    const btn = args[1];
    const v = btn && btn.closest('.voice-msg');
    if(v && activeVoiceAudio) v.classList.add('playing');
    return r;
  };
})(toggleVoicePlayback);
resetVoicePlayer = (function(orig){
  return function(...args){
    document.querySelectorAll('#messages .voice-msg.playing').forEach(v=> v.classList.remove('playing'));
    return orig.apply(this, args);
  };
})(resetVoicePlayer);

/* ============================================================
   ROUND 8 — логотип, острова кнопок, свайпы между вкладками и из чата
============================================================ */
const APP_NAME = 'Chat';   // название приложения в шапке (как «Telegram» в Telegram)
const TAB_ORDER = ['chats','calls','contacts','discovery','music','profile'];
const BRAND_ICON = '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 3.5c-5 0-9 3.4-9 7.7 0 2.3 1.1 4.3 3 5.7-.2 1.5-.9 2.8-1.8 3.8 2 0 3.8-.8 5.1-1.9.9.2 1.8.3 2.7.3 5 0 9-3.4 9-7.9S17 3.5 12 3.5z"/><circle cx="8.3" cy="11.3" r="1.25" fill="#7B5CFF"/><circle cx="12" cy="11.3" r="1.25" fill="#7B5CFF"/><circle cx="15.7" cy="11.3" r="1.25" fill="#7B5CFF"/></svg>';
const BRAND_HEADERS = [
  {header: '#chats-header-normal', section: ''},
  {header: '#calls-header-normal', section: 'Звонки'},
  {header: '#contacts-header-normal', section: 'Контакты'},
  {header: '#tab-discovery .tab-header-static', section: 'Общение'},
  {header: '#tab-profile .tab-header-static', section: 'Профиль'},
];
function buildBrandHeaders(){
  BRAND_HEADERS.forEach(({header, section})=>{
    const h = document.querySelector(header);
    if(!h) return;
    const title = h.querySelector('.tab-title');
    if(title && !title.classList.contains('app-brand')){
      title.classList.add('app-brand');
      title.innerHTML = `<span class="brand-mark">${BRAND_ICON}</span><span class="brand-text"><span class="brand-name">${escapeHtml(APP_NAME)}</span><span class="brand-section" data-brand-section="${escapeHtml(section)}">${escapeHtml(section)}</span></span>`;
    }
    if(!h.querySelector('.header-island')){
      const island = document.createElement('div');
      island.className = 'header-island';
      h.querySelectorAll(':scope > .icon-btn').forEach(b=> island.appendChild(b));
      h.appendChild(island);
    }
  });
  const sh = document.querySelector('#tab-settings .tab-header-static');
  if(sh && !sh.querySelector('.header-island')){
    const island = document.createElement('div');
    island.className = 'header-island';
    sh.appendChild(island);
  }
}
function updateConnectionLabel(){
  const online = navigator.onLine !== false;
  document.querySelectorAll('.brand-section').forEach(el=>{
    const base = el.getAttribute('data-brand-section') || '';
    el.innerHTML = online ? escapeHtml(base) : `<span class="brand-spinner"></span>Соединение…`;
  });
}
window.addEventListener('online', updateConnectionLabel);
window.addEventListener('offline', updateConnectionLabel);

/* колокольчик переезжает в остров активной вкладки */
function placeBellInIsland(tab){
  const bell = document.getElementById('notif-bell-btn');
  if(!bell) return;
  const panel = document.getElementById('tab-' + (tab || state.activeTab || 'chats'));
  const island = panel && panel.querySelector('.tab-header:not(.select-header) .header-island, .tab-header-static .header-island');
  if(island && bell.parentElement !== island) island.appendChild(bell);
}

/* скользящая «линза» под активной кнопкой навигации */
const navEl = document.querySelector('.bottom-nav');
const glider = document.createElement('span');
glider.className = 'nav-glider';
navEl.insertBefore(glider, navEl.firstChild);
function moveGlider(){
  const active = navEl.querySelector('.nav-btn.active') || navEl.querySelector('.nav-btn[data-tab="profile"]');
  if(!active) return;
  const inset = 3;
  glider.style.width = (active.offsetWidth - inset*2) + 'px';
  glider.style.transform = `translateX(${active.offsetLeft + inset}px)`;
}
window.addEventListener('resize', moveGlider);

/* смена вкладки: направление анимации + колокольчик + линза */
function tabIndex(tab){ const t = tab === 'settings' ? 'profile' : tab; return TAB_ORDER.indexOf(t); }
switchTab = (function(orig){
  return function(tab, ...rest){
    const prev = state.activeTab;
    const r = orig.call(this, tab, ...rest);
    const panel = document.getElementById('tab-' + tab);
    if(panel && prev && prev !== tab){
      const dir = tabIndex(tab) >= tabIndex(prev) ? 'tab-in-right' : 'tab-in-left';
      panel.classList.remove('tab-in-left','tab-in-right');
      void panel.offsetWidth;
      panel.classList.add(dir);
      setTimeout(()=> panel.classList.remove(dir), 420);
    }
    if(tab === 'settings'){
      const pn = navEl.querySelector('.nav-btn[data-tab="profile"]');
      navEl.querySelectorAll('.nav-btn').forEach(b=> b.classList.toggle('active', b === pn));
    }
    placeBellInIsland(tab);
    moveGlider();
    return r;
  };
})(switchTab);

/* ---------- свайп между вкладками ---------- */
(function setupTabSwipes(){
  const area = document.querySelector('.tabs-content');
  if(!area) return;
  const EXCLUDE = 'input, textarea, select, .contacts-subtabs, .discovery-filters, .toggle-switch, .settings-expand, .city-suggestions, #row-menu-overlay, [data-no-swipe]';
  let g = null;
  const anySelectMode = ()=> state.chatSelectMode || state.contactSelectMode || state.callLogSelectMode;
  area.addEventListener('touchstart', (ev)=>{
    g = null;
    if(ev.touches.length !== 1 || window.innerWidth > 780 || anySelectMode()) return;
    if(document.getElementById('chat-area').classList.contains('mobile-open')) return;
    if(ev.target.closest(EXCLUDE)) return;
    const panel = document.querySelector('.tab-panel.active');
    if(!panel) return;
    const t = ev.touches[0];
    g = {x0: t.clientX, y0: t.clientY, t0: Date.now(), axis: null, dx: 0, panel};
  }, {passive: true});
  area.addEventListener('touchmove', (ev)=>{
    if(!g) return;
    const t = ev.touches[0];
    const dx = t.clientX - g.x0, dy = t.clientY - g.y0;
    if(!g.axis){
      if(Math.abs(dx) < 12 && Math.abs(dy) < 12) return;
      g.axis = Math.abs(dx) > Math.abs(dy) * 1.5 ? 'x' : 'y';
      if(g.axis === 'y'){ g = null; return; }
    }
    if(ev.cancelable) ev.preventDefault();
    const idx = tabIndex(state.activeTab);
    const target = TAB_ORDER[idx + (dx < 0 ? 1 : -1)];
    const eff = target ? dx : dx * 0.25;             // у края — «резинка»
    g.dx = dx;
    g.panel.style.transition = 'none';
    g.panel.style.transform = `translateX(${eff * 0.55}px)`;
    g.panel.style.opacity = String(1 - Math.min(0.45, Math.abs(eff) / window.innerWidth * 0.8));
  }, {passive: false});
  const end = ()=>{
    if(!g) return;
    const {panel, dx, t0, axis} = g;
    g = null;
    panel.style.transition = 'transform .28s cubic-bezier(.2,.9,.3,1), opacity .2s ease';
    panel.style.transform = '';
    panel.style.opacity = '';
    setTimeout(()=>{ panel.style.transition = ''; }, 320);
    if(axis !== 'x') return;
    const v = Math.abs(dx) / Math.max(1, Date.now() - t0);
    if(Math.abs(dx) < window.innerWidth * 0.22 && !(Math.abs(dx) > 50 && v > 0.45)) return;
    const target = TAB_ORDER[tabIndex(state.activeTab) + (dx < 0 ? 1 : -1)];
    if(!target) return;
    haptic('buttons', 8);
    const btn = navEl.querySelector(`.nav-btn[data-tab="${target}"]`);
    if(btn) btn.click(); else switchTab(target);
  };
  area.addEventListener('touchend', end);
  area.addEventListener('touchcancel', end);
})();

/* ---------- свайп вправо по всему экрану чата — назад к списку (как в Telegram) ---------- */
(function setupChatSwipeBack(){
  const chatArea = document.getElementById('chat-area');
  const EXCLUDE = '#composer-recording, #mic-btn, #roundvideo-btn, .voice-bar, input, textarea, .emoji-panel, .attach-menu, #chat-header-menu, .img-preview-row, #row-menu-overlay, [data-no-swipe]';
  let g = null;
  chatArea.addEventListener('touchstart', (ev)=>{
    g = null;
    if(ev.touches.length !== 1 || window.innerWidth > 780 || !chatArea.classList.contains('mobile-open')) return;
    if(state.msgSelectMode || ev.target.closest(EXCLUDE)) return;
    const t = ev.touches[0];
    g = {x0: t.clientX, y0: t.clientY, t0: Date.now(), axis: null, dx: 0};
  }, {passive: true});
  chatArea.addEventListener('touchmove', (ev)=>{
    if(!g) return;
    const t = ev.touches[0];
    const dx = t.clientX - g.x0, dy = t.clientY - g.y0;
    if(!g.axis){
      if(Math.abs(dx) < 12 && Math.abs(dy) < 12) return;
      g.axis = (dx > 0 && Math.abs(dx) > Math.abs(dy) * 1.4) ? 'x' : 'y';
      if(g.axis === 'y'){ g = null; return; }
      chatArea.classList.add('swiping');
    }
    if(ev.cancelable) ev.preventDefault();
    g.dx = Math.max(0, dx);
    chatArea.style.transform = `translateX(${g.dx}px)`;
  }, {passive: false});
  const end = ()=>{
    if(!g) return;
    const {dx, t0, axis} = g;
    g = null;
    if(axis !== 'x') return;
    chatArea.classList.remove('swiping');
    const v = dx / Math.max(1, Date.now() - t0);
    const go = dx > window.innerWidth * 0.3 || (dx > 60 && v > 0.5);
    chatArea.style.transform = '';
    if(go){ haptic('buttons', 8); closeActiveChat(); }
  };
  chatArea.addEventListener('touchend', end);
  chatArea.addEventListener('touchcancel', end);
})();

buildBrandHeaders();
updateConnectionLabel();
placeBellInIsland(state.activeTab || 'chats');
requestAnimationFrame(moveGlider);
setTimeout(moveGlider, 400);

/* ============================================================
   ROUND 9 — держим последнее сообщение на экране; подсказки записи
============================================================ */
let msgStickBottom = true;
const msgBoxEl = document.getElementById('messages');
function stickToBottomNow(){
  if(!msgStickBottom) return;
  msgBoxEl.scrollTop = msgBoxEl.scrollHeight;
}
let stickTimers = [];
function scheduleStickToBottom(){
  stickTimers.forEach(clearTimeout);
  stickTimers = [0, 60, 180, 400, 800, 1500].map(ms=> setTimeout(stickToBottomNow, ms));
  requestAnimationFrame(stickToBottomNow);
}
// человек сам прокрутил вверх — перестаём «держать» низ
msgBoxEl.addEventListener('scroll', ()=>{
  msgStickBottom = (msgBoxEl.scrollHeight - msgBoxEl.scrollTop - msgBoxEl.clientHeight) < 90;
}, {passive: true});
// догрузились фото / кружки / голосовые — снова к низу, если мы у низа
msgBoxEl.addEventListener('load', stickToBottomNow, true);
msgBoxEl.addEventListener('loadedmetadata', stickToBottomNow, true);
new MutationObserver(()=> requestAnimationFrame(stickToBottomNow)).observe(msgBoxEl, {childList: true, subtree: true});
if(window.ResizeObserver) new ResizeObserver(()=> stickToBottomNow()).observe(msgBoxEl);
openChat = (function(orig){
  return async function(...args){
    msgStickBottom = true;
    const r = await orig.apply(this, args);
    msgStickBottom = true;
    scheduleStickToBottom();
    return r;
  };
})(openChat);
// собственная отправка любым способом — вниз
['send-btn','rec-send-btn','send-silent-btn','roundvideo-send-btn','rv-send-btn'].forEach(id=>{
  const el = document.getElementById(id);
  if(el) el.addEventListener('click', ()=>{ msgStickBottom = true; scheduleStickToBottom(); }, true);
});
document.getElementById('msg-input').addEventListener('keydown', (e)=>{
  if(e.key === 'Enter' && !e.shiftKey){ msgStickBottom = true; scheduleStickToBottom(); }
}, true);

/* подсказка над кнопкой записи: исчезает сама (~2 с), закрывается крестиком или смахиванием */
const holdHint = document.getElementById('hold-hint');
let holdHintTimer = null;
function hideHoldHint(){
  if(!holdHint.classList.contains('show')) return;
  clearTimeout(holdHintTimer);
  holdHint.classList.add('leaving');
  setTimeout(()=>{ holdHint.classList.remove('show','leaving'); holdHint.style.transform = ''; holdHint.style.opacity = ''; }, 200);
}
function showHoldHint(btn, text, ms){
  ms = ms || 2200;
  clearTimeout(holdHintTimer);
  document.getElementById('hold-hint-text').textContent = text;
  holdHint.classList.remove('leaving');
  holdHint.style.transform = ''; holdHint.style.opacity = '';
  holdHint.style.setProperty('--hint-ms', ms + 'ms');
  const bar = holdHint.querySelector('.hint-progress i');
  bar.style.animation = 'none'; void bar.offsetWidth; bar.style.animation = '';
  holdHint.classList.remove('show'); void holdHint.offsetWidth;
  holdHint.classList.add('show');
  const r = btn.getBoundingClientRect();
  const w = holdHint.offsetWidth;
  const right = Math.max(8, window.innerWidth - (r.left + r.width/2) - 26);
  holdHint.style.right = Math.min(right, window.innerWidth - w - 8) + 'px';
  holdHint.style.left = 'auto';
  holdHint.style.bottom = (window.innerHeight - r.top + 12) + 'px';
  const hintRight = parseFloat(holdHint.style.right);
  holdHint.style.setProperty('--hint-arrow', Math.max(12, Math.min(w - 24, window.innerWidth - (r.left + r.width/2) - hintRight - 6)) + 'px');
  haptic('buttons', [8, 40, 8]);
  holdHintTimer = setTimeout(hideHoldHint, ms);
}
document.getElementById('hold-hint-close').addEventListener('click', (e)=>{ e.stopPropagation(); hideHoldHint(); });
(function hintSwipe(){
  let x0 = null, dx = 0;
  holdHint.addEventListener('touchstart', (e)=>{ x0 = e.touches[0].clientX; dx = 0; clearTimeout(holdHintTimer); holdHint.style.transition = 'none'; }, {passive: true});
  holdHint.addEventListener('touchmove', (e)=>{
    if(x0 === null) return;
    dx = e.touches[0].clientX - x0;
    holdHint.style.transform = `translateX(${dx}px) rotate(${dx/40}deg)`;
    holdHint.style.opacity = String(Math.max(0, 1 - Math.abs(dx)/180));
  }, {passive: true});
  holdHint.addEventListener('touchend', ()=>{
    if(x0 === null) return;
    x0 = null;
    holdHint.style.transition = 'transform .2s ease, opacity .2s ease';
    if(Math.abs(dx) > 60){
      holdHint.style.transform = `translateX(${dx > 0 ? 420 : -420}px)`;
      holdHint.style.opacity = '0';
      setTimeout(()=>{ holdHint.classList.remove('show'); holdHint.style.transition = ''; holdHint.style.transform = ''; holdHint.style.opacity = ''; }, 200);
    }else{
      holdHint.style.transform = ''; holdHint.style.opacity = '';
      holdHintTimer = setTimeout(hideHoldHint, 1200);
    }
  });
})();
// любое нажатие мимо подсказки — прячем её
document.addEventListener('pointerdown', (e)=>{ if(holdHint.classList.contains('show') && !holdHint.contains(e.target)) hideHoldHint(); }, true);

/* ============================================================
   ROUND 10 — подвкладки: стеклянный остров, скользящая подсветка, иконки
============================================================ */
(function setupSubtabIslands(){
  const I = (d)=> `<span class="subtab-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">${d}</svg></span>`;
  const ICONS = {
    chats: I('<path d="M21 12a8 8 0 0 1-11.6 7.1L4 20.5l1.4-4.9A8 8 0 1 1 21 12z"/>'),
    communities: I('<circle cx="9" cy="8.5" r="3.2"/><path d="M3 19.5c.5-3.2 3-5.2 6-5.2s5.5 2 6 5.2"/><circle cx="17" cy="9" r="2.6"/><path d="M16.5 14.4c2.4.2 4 1.9 4.5 4.6"/>'),
    list: I('<circle cx="12" cy="8.5" r="3.6"/><path d="M5 20c.6-3.6 3.4-5.8 7-5.8s6.4 2.2 7 5.8"/>'),
    all: I('<rect x="4" y="4" width="6.5" height="6.5" rx="1.8"/><rect x="13.5" y="4" width="6.5" height="6.5" rx="1.8"/><rect x="4" y="13.5" width="6.5" height="6.5" rx="1.8"/><rect x="13.5" y="13.5" width="6.5" height="6.5" rx="1.8"/>'),
    online: '<span class="subtab-ico"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="5" fill="#2FB84F"/><circle cx="12" cy="12" r="8.5" fill="none" stroke="#2FB84F" stroke-opacity=".35" stroke-width="2"/></svg></span>',
    offline: '<span class="subtab-ico"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="5" fill="none" stroke="currentColor" stroke-width="2"/></svg></span>',
    blacklist: I('<circle cx="12" cy="12" r="8.5"/><line x1="6" y1="6" x2="18" y2="18"/>'),
    reactions: I('<path d="M12 20s-7.5-4.6-7.5-10A4.2 4.2 0 0 1 12 7.4 4.2 4.2 0 0 1 19.5 10c0 5.4-7.5 10-7.5 10z"/>'),
    friends: I('<circle cx="9" cy="8.5" r="3.2"/><path d="M3 19.5c.5-3.2 3-5.2 6-5.2 1.3 0 2.5.3 3.4.9"/><polyline points="14.5 17 16.5 19 21 14.5"/>'),
    requests: I('<circle cx="10" cy="8.5" r="3.4"/><path d="M3.5 19.5c.5-3.3 3.1-5.3 6.5-5.3 1.2 0 2.3.2 3.2.7"/><line x1="18" y1="13" x2="18" y2="20"/><line x1="14.5" y1="16.5" x2="21.5" y2="16.5"/>'),
  };
  const bars = Array.from(document.querySelectorAll('.contacts-subtabs'));
  bars.forEach(bar=>{
    const isNested = bar.getAttribute('style') && /padding-top/.test(bar.getAttribute('style'));
    if(isNested) bar.classList.add('nested');
    const btns = Array.from(bar.querySelectorAll('.subtab-btn'));
    btns.forEach(b=>{
      const key = Object.keys(b.dataset).map(k=> b.dataset[k]).find(v=> ICONS[v]);
      if(key && !b.querySelector('.subtab-ico') && !isNested) b.insertAdjacentHTML('afterbegin', ICONS[key]);
      if(key && !b.querySelector('.subtab-ico') && isNested && ICONS[key === 'list' ? 'friends' : key]) b.insertAdjacentHTML('afterbegin', ICONS[key === 'list' ? 'friends' : key]);
    });
    const glider = document.createElement('span');
    glider.className = 'subtab-glider no-anim';
    bar.insertBefore(glider, bar.firstChild);
    let first = true;
    const layout = ()=>{
      if(!bar.offsetWidth) return;                       // вкладка скрыта — пересчитаем, когда появится
      bar.classList.remove('fit', 'compact');
      const natural = ()=> btns.reduce((a, b)=> a + b.offsetWidth, 0) + (btns.length - 1) * 2 + 8;
      if(natural() <= bar.clientWidth) bar.classList.add('fit');
      else{
        bar.classList.add('compact');                    // не влезает — прячем иконки и пробуем снова
        if(natural() <= bar.clientWidth) bar.classList.add('fit');
        else bar.classList.remove('compact');            // не влезает и так — обычная прокручиваемая лента
      }
      const active = bar.querySelector('.subtab-btn.active') || btns[0];
      if(!active) return;
      glider.style.width = active.offsetWidth + 'px';
      glider.style.transform = `translateX(${active.offsetLeft}px)`;
      if(first){ first = false; requestAnimationFrame(()=> glider.classList.remove('no-anim')); }
      // активная вкладка всегда видна в прокручиваемой ленте
      const pad = 16;
      if(active.offsetLeft < bar.scrollLeft + pad) bar.scrollLeft = Math.max(0, active.offsetLeft - pad);
      else if(active.offsetLeft + active.offsetWidth > bar.scrollLeft + bar.clientWidth - pad) bar.scrollLeft = active.offsetLeft + active.offsetWidth - bar.clientWidth + pad;
    };
    new MutationObserver((muts)=>{ if(muts.some(m=> m.target !== bar && m.target !== glider)) layout(); }).observe(bar, {subtree: true, attributes: true, attributeFilter: ['class', 'style'], childList: true, characterData: true});
    if(window.ResizeObserver) new ResizeObserver(layout).observe(bar);
    btns.forEach(b=> b.addEventListener('click', ()=>{ haptic('buttons', 6); }));
    layout();
  });
})();

/* ============================================================
   ROUND 11 — ИСТОРИИ (как в Telegram)
   stories/{id}            — описание истории (кто видит, срок, превью)
   stories/{id}/chunks/{n} — сама фотография/видео частями по ~700 КБ
   stories/{id}/views/{uid}— кто посмотрел и реакция
============================================================ */
const STORY_CHUNK = 700000;
const STORY_MAX_CHUNKS = 8;
const STORY_PHOTO_MS = 6000;
const STORY_VIDEO_MAX_SEC = 30;
const storyState = {sets: {mine: [], shared: [], pub: []}, unsub: [], groups: [], byUid: {}, profiles: {}, media: {}, mediaOrder: [],
  friendUids: new Set(), started: false, rulesMissing: false, cleaned: false};

function storyLsSet(key){ try{ return new Set(JSON.parse(localStorage.getItem(key) || '[]')); }catch(e){ return new Set(); } }
function storyLsSave(key, set){ try{ localStorage.setItem(key, JSON.stringify(Array.from(set).slice(-2000))); }catch(e){} }
const storyViewed = storyLsSet('storyViewed');
const storyLiked = storyLsSet('storyLiked');

function storyPersonName(uid){
  if(state.currentUser && uid === state.currentUser.uid) return 'Вы';
  const alias = state.contactAliasMap && state.contactAliasMap[uid];
  if(alias) return alias;
  const p = storyState.profiles[uid];
  if(p){ const full = [p.firstName, p.lastName].filter(Boolean).join(' ').trim(); return full || p.username || 'Пользователь'; }
  return 'Пользователь';
}
function storyAvatarHtml(uid){
  const p = storyState.profiles[uid];
  if(p && p.avatarUrl) return `<img src="${p.avatarUrl}" alt="">`;
  return escapeHtml(initials(storyPersonName(uid) === 'Вы' ? (p && p.username) || 'Я' : storyPersonName(uid)));
}
async function storyLoadProfile(uid){
  if(storyState.profiles[uid]) return storyState.profiles[uid];
  try{ const p = await getUserProfile(uid); if(p) storyState.profiles[uid] = p; return p; }catch(e){ return null; }
}
function storyAgo(ts){
  const m = Math.max(0, Math.floor((Date.now() - ts) / 60000));
  if(m < 1) return 'только что';
  if(m < 60) return m + ' мин назад';
  const h = Math.floor(m / 60);
  return h + ' ч назад';
}

/* ---------- подписка на истории ---------- */
function stopStoriesListener(){
  storyState.unsub.forEach(u=>{ try{ u(); }catch(e){} });
  storyState.unsub = []; storyState.started = false;
  storyState.sets = {mine: [], shared: [], pub: []};
}
function startStoriesListener(){
  stopStoriesListener();
  const me = state.currentUser.uid;
  storyState.started = true;
  const handle = (key)=> (snap)=>{
    storyState.sets[key] = snap.docs.map(d=> Object.assign({id: d.id}, d.data()));
    if(key === 'mine' && !storyState.cleaned){ storyState.cleaned = true; cleanupMyExpiredStories(); }
    rebuildStories();
  };
  const fail = (err)=>{ if(err && /permission/i.test(err.code || err.message || '')) storyState.rulesMissing = true; rebuildStories(); };
  const col = db.collection('stories');
  storyState.unsub.push(col.where('authorUid', '==', me).onSnapshot(handle('mine'), fail));
  storyState.unsub.push(col.where('audience', 'array-contains', me).onSnapshot(handle('shared'), fail));
  storyState.unsub.push(col.where('audienceAll', '==', true).onSnapshot(handle('pub'), fail));
  getMyFriendUids().then(list=>{ storyState.friendUids = new Set(list); rebuildStories(); });
}
setInterval(()=>{
  if(!state.currentUser && storyState.started) stopStoriesListener();
  if(storyState.started) try{ rebuildStories(true); }catch(e){}   // раз в минуту истекают сроки и меняется «N мин назад»
}, 60000);
setInterval(()=>{
  if(state.currentUser && !storyState.started){
    try{ startStoriesListener(); }catch(e){ storyState.started = true; console.warn('stories listener', e); }
  }
}, 1500);

function storyKnownUids(){
  const set = new Set(storyState.friendUids);
  (state.contacts || []).forEach(c=> set.add(c.uid));
  (state.chats || []).forEach(c=> (c.participants || []).forEach(u=> set.add(u)));
  return set;
}
function rebuildStories(quiet){
  if(!state.currentUser) return;
  const me = state.currentUser.uid;
  const now = Date.now();
  const blocked = new Set((state.blacklist || []).map(b=> b.uid));
  const known = storyKnownUids();
  const all = {};
  [...storyState.sets.mine, ...storyState.sets.shared, ...storyState.sets.pub].forEach(st=>{
    if(!st || !st.authorUid || (st.expireAt || 0) <= now) return;
    if(st.authorUid !== me){
      if(blocked.has(st.authorUid)) return;
      if(st.audienceAll && !(st.audience || []).includes(me) && !known.has(st.authorUid)) return;   // публичные — только от знакомых
    }
    all[st.id] = st;
  });
  const byUid = {};
  Object.values(all).forEach(st=>{ (byUid[st.authorUid] = byUid[st.authorUid] || []).push(st); });
  const groups = Object.keys(byUid).map(uid=>{
    const stories = byUid[uid].sort((a, b)=> a.createdAt - b.createdAt);
    const unseen = uid !== me && stories.some(st=> !storyViewed.has(st.id));
    return {uid, stories, unseen, latest: stories[stories.length - 1].createdAt};
  });
  groups.sort((a, b)=>{
    if(a.uid === me) return -1;
    if(b.uid === me) return 1;
    if(a.unseen !== b.unseen) return a.unseen ? -1 : 1;
    return b.latest - a.latest;
  });
  storyState.groups = groups;
  storyState.byUid = {};
  groups.forEach(g=> storyState.byUid[g.uid] = g);
  const missing = [me, ...groups.map(g=> g.uid)].filter(uid=> !storyState.profiles[uid]);
  if(missing.length) Promise.all(missing.map(storyLoadProfile)).then(()=> renderStoriesRow());
  renderStoriesRow();
  decorateChatAvatarsWithStories();
}

/* ---------- лента кружков ---------- */
function renderStoriesRow(){
  const row = document.getElementById('stories-row');
  if(!row || !state.currentUser) return;
  const me = state.currentUser.uid;
  const mine = storyState.byUid[me];
  const items = [];
  items.push(`<button type="button" class="story-item mine ${mine ? '' : 'empty'}" data-story-uid="${me}" title="Моя история">
    <span class="story-ring"><span class="story-avatar">${storyAvatarHtml(me)}</span></span>
    <span class="story-add" data-story-add="1" title="Добавить историю">+</span>
    <span class="story-name">${mine ? 'Моя история' : 'Добавить'}</span></button>`);
  storyState.groups.filter(g=> g.uid !== me).forEach(g=>{
    items.push(`<button type="button" class="story-item ${g.unseen ? 'unseen' : 'seen'}" data-story-uid="${g.uid}" title="${escapeHtml(storyPersonName(g.uid))}">
      <span class="story-ring"><span class="story-avatar">${storyAvatarHtml(g.uid)}</span></span>
      <span class="story-name">${escapeHtml(storyPersonName(g.uid).split(' ')[0])}</span></button>`);
  });
  const html = items.join('');
  if(row.dataset.html !== html){ row.innerHTML = html; row.dataset.html = html; }
}
document.getElementById('stories-row').addEventListener('click', (ev)=>{
  const add = ev.target.closest('[data-story-add]');
  const item = ev.target.closest('.story-item');
  if(!item) return;
  const uid = item.dataset.storyUid;
  if(add || (uid === state.currentUser.uid && !storyState.byUid[uid])){ openStoryPicker(); return; }
  openStoryViewer(uid);
});
// лента прячется при прокрутке списка вниз и возвращается наверху — как в Telegram
document.getElementById('chat-list').addEventListener('scroll', (ev)=>{
  document.getElementById('stories-row').classList.toggle('collapsed', ev.target.scrollTop > 40);
}, {passive: true});
(function syncRowVisibility(){
  const inner = document.getElementById('tab-communities-inner');
  const sel = document.getElementById('chats-header-select');
  const upd = ()=> document.getElementById('stories-row').classList.toggle('hidden', inner.style.display === 'flex' || sel.style.display === 'flex');
  new MutationObserver(upd).observe(inner, {attributes: true, attributeFilter: ['style']});
  new MutationObserver(upd).observe(sel, {attributes: true, attributeFilter: ['style']});
  upd();
})();

/* кольцо вокруг аватара в списке чатов; нажатие на аватар открывает историю */
function decorateChatAvatarsWithStories(){
  if(!state.currentUser) return;
  const me = state.currentUser.uid;
  document.querySelectorAll('#chat-list .chat-item[data-id]').forEach(row=>{
    const meta = (state.chats || []).find(c=> c.id === row.dataset.id);
    const av = row.querySelector('.avatar');
    if(!meta || !av) return;
    const other = !meta.isCommunity && (meta.participants || []).find(u=> u !== me);
    const g = other && storyState.byUid[other];
    av.classList.toggle('story-ring-av', !!g);
    av.classList.toggle('unseen', !!(g && g.unseen));
    if(g) av.dataset.storyUid = other; else delete av.dataset.storyUid;
  });
}
renderChatList = (function(orig){ return function(...a){ const r = orig.apply(this, a); try{ decorateChatAvatarsWithStories(); }catch(e){} return r; }; })(renderChatList);
document.getElementById('chat-list').addEventListener('click', (ev)=>{
  const av = ev.target.closest('.avatar.story-ring-av');
  if(!av || state.chatSelectMode) return;
  ev.preventDefault(); ev.stopPropagation();
  openStoryViewer(av.dataset.storyUid);
}, true);

/* ---------- создание ---------- */
function openStoryPicker(){
  if(storyState.rulesMissing) toast('Истории ещё не включены: администратору нужно обновить правила Firestore (см. README)');
  document.getElementById('story-pick-sheet').style.display = 'flex';
}
document.getElementById('story-pick-sheet').addEventListener('click', (ev)=>{
  const b = ev.target.closest('[data-story-pick]');
  if(!b && ev.target.id !== 'story-pick-sheet') return;
  document.getElementById('story-pick-sheet').style.display = 'none';
  const kind = b && b.dataset.storyPick;
  if(kind === 'photo') document.getElementById('story-input-photo').click();
  else if(kind === 'video') document.getElementById('story-input-video').click();
  else if(kind === 'gallery') document.getElementById('story-input-gallery').click();
});
['story-input-photo','story-input-video','story-input-gallery'].forEach(id=>{
  document.getElementById(id).addEventListener('change', (ev)=>{
    const f = ev.target.files && ev.target.files[0];
    ev.target.value = '';
    if(f) openStoryEditor(f);
  });
});
const storyEditor = {file: null, url: null, audience: null, ttl: 24, selected: new Set()};
function storyPref(key, def){ try{ return localStorage.getItem(key) || def; }catch(e){ return def; } }
function setChip(groupId, attr, val){
  document.querySelectorAll(`#${groupId} .se-chip`).forEach(c=> c.classList.toggle('on', c.dataset[attr] === String(val)));
}
function openStoryEditor(file){
  const isVideo = /^video\//.test(file.type);
  const isImage = /^image\//.test(file.type);
  if(!isVideo && !isImage){ toast('Можно выбрать только фото или видео'); return; }
  storyEditor.file = file;
  if(storyEditor.url) URL.revokeObjectURL(storyEditor.url);
  storyEditor.url = URL.createObjectURL(file);
  const media = document.getElementById('se-media');
  media.innerHTML = isVideo ? `<video src="${storyEditor.url}" autoplay loop muted playsinline></video>` : `<img src="${storyEditor.url}" alt="">`;
  if(isImage) media.querySelector('img').onerror = ()=>{ toast(IMAGE_FORMAT_ERROR); closeStoryEditor(); };
  document.getElementById('se-caption').value = '';
  storyEditor.audience = storyPref('storyAudience', 'friends');
  storyEditor.ttl = parseInt(storyPref('storyTtl', '24'), 10) || 24;
  setChip('se-audience', 'aud', storyEditor.audience);
  setChip('se-ttl', 'ttl', storyEditor.ttl);
  document.getElementById('se-progress').style.display = 'none';
  const pub = document.getElementById('se-publish');
  pub.disabled = false; pub.textContent = 'Опубликовать историю';
  document.getElementById('story-editor').style.display = 'flex';
}
function closeStoryEditor(){
  document.getElementById('story-editor').style.display = 'none';
  document.getElementById('se-media').innerHTML = '';
  if(storyEditor.url){ URL.revokeObjectURL(storyEditor.url); storyEditor.url = null; }
  storyEditor.file = null;
}
document.getElementById('se-close').onclick = ()=>{ if(!document.getElementById('se-publish').disabled) closeStoryEditor(); };
document.getElementById('se-audience').addEventListener('click', (ev)=>{
  const c = ev.target.closest('.se-chip'); if(!c) return;
  storyEditor.audience = c.dataset.aud;
  setChip('se-audience', 'aud', storyEditor.audience);
  if(storyEditor.audience === 'selected') openStoryAudienceSheet();
});
document.getElementById('se-ttl').addEventListener('click', (ev)=>{
  const c = ev.target.closest('.se-chip'); if(!c) return;
  storyEditor.ttl = parseInt(c.dataset.ttl, 10);
  setChip('se-ttl', 'ttl', storyEditor.ttl);
});
async function openStoryAudienceSheet(){
  const sheet = document.getElementById('story-audience-sheet');
  const list = document.getElementById('story-aud-list');
  sheet.style.display = 'flex';
  list.innerHTML = '<div class="story-aud-empty">Загрузка…</div>';
  const friends = await getMyFriendUids();
  const uids = Array.from(new Set([...friends, ...(state.contacts || []).map(c=> c.uid)])).filter(u=> u && u !== state.currentUser.uid);
  await Promise.all(uids.map(storyLoadProfile));
  if(!uids.length){ list.innerHTML = '<div class="story-aud-empty">Пока нет друзей и контактов</div>'; return; }
  const fset = new Set(friends);
  list.innerHTML = uids.map(u=> `<div class="story-aud-row ${storyEditor.selected.has(u) ? 'on' : ''}" data-uid="${u}">
    <div class="avatar">${storyAvatarHtml(u)}</div><div class="nm">${escapeHtml(storyPersonName(u))}<div class="sub">${fset.has(u) ? 'Друг' : 'Контакт'}</div></div><span class="chk">✓</span></div>`).join('');
}
document.getElementById('story-aud-list').addEventListener('click', (ev)=>{
  const row = ev.target.closest('.story-aud-row'); if(!row || !row.dataset.uid) return;
  const u = row.dataset.uid;
  if(storyEditor.selected.has(u)) storyEditor.selected.delete(u); else storyEditor.selected.add(u);
  row.classList.toggle('on', storyEditor.selected.has(u));
});
document.getElementById('story-aud-done').onclick = ()=>{
  document.getElementById('story-audience-sheet').style.display = 'none';
  const n = storyEditor.selected.size;
  document.querySelector('#se-audience [data-aud="selected"]').textContent = n ? `Выбрано: ${n}` : 'Выбрать…';
};

function setStoryProgress(frac, text){
  document.getElementById('se-progress').style.display = 'flex';
  document.getElementById('se-progress-fill').style.width = Math.round(Math.max(0, Math.min(1, frac)) * 100) + '%';
  if(text) document.getElementById('se-progress-text').textContent = text;
}
function videoFrameThumb(v, size){
  const c = document.createElement('canvas');
  const k = size / Math.max(v.videoWidth || size, v.videoHeight || size);
  c.width = Math.max(1, Math.round((v.videoWidth || size) * k));
  c.height = Math.max(1, Math.round((v.videoHeight || size) * k));
  const x = c.getContext('2d'); x.fillStyle = '#000'; x.fillRect(0, 0, c.width, c.height);
  try{ x.drawImage(v, 0, 0, c.width, c.height); }catch(e){}
  return c.toDataURL('image/jpeg', 0.7);
}
async function prepareStoryVideo(file, onProgress, opts){
  const url = URL.createObjectURL(file);
  const v = document.createElement('video');
  v.src = url; v.playsInline = true; v.preload = 'auto';
  try{
    await new Promise((res, rej)=>{ v.onloadedmetadata = res; v.onerror = ()=> rej(new Error('Не удалось открыть это видео')); });
    const w = v.videoWidth || 720, h = v.videoHeight || 1280;
    const MAXSEC = (opts && opts.maxSec) || STORY_VIDEO_MAX_SEC;
    let dur = isFinite(v.duration) && v.duration > 0 ? v.duration : MAXSEC;
    v.currentTime = Math.min(0.1, dur / 2);
    await new Promise(r=>{ v.onseeked = r; setTimeout(r, 1500); });
    const thumb = videoFrameThumb(v, 220);
    const limitBytes = (opts && opts.limitBytes) || STORY_CHUNK * STORY_MAX_CHUNKS * 0.74;
    if(!(opts && opts.forceTranscode) && file.size <= limitBytes && dur <= MAXSEC + 0.5){
      return {blob: file, duration: dur, w, h, thumb};
    }
    // пережимаем прямо на телефоне: 720p, до 30 секунд, битрейт под лимит
    const useDur = Math.min(dur, MAXSEC);
    const scale = Math.min(1, 720 / Math.max(w, h));
    const cw = Math.max(2, Math.round(w * scale / 2) * 2), ch = Math.max(2, Math.round(h * scale / 2) * 2);
    const canvas = document.createElement('canvas'); canvas.width = cw; canvas.height = ch;
    const ctx = canvas.getContext('2d');
    const stream = canvas.captureStream(30);
    let ac = null;
    try{
      const AC = window.AudioContext || window.webkitAudioContext;
      ac = new AC();
      const srcNode = ac.createMediaElementSource(v);
      const dest = ac.createMediaStreamDestination();
      srcNode.connect(dest);                              // звук идёт только в запись, не в динамик
      dest.stream.getAudioTracks().forEach(t=> stream.addTrack(t));
    }catch(e){ ac = null; }
    const types = ['video/webm;codecs=vp9,opus', 'video/webm;codecs=vp8,opus', 'video/webm', 'video/mp4;codecs=avc1,mp4a', 'video/mp4'];
    const mime = types.find(t=> window.MediaRecorder && MediaRecorder.isTypeSupported(t)) || '';
    const vbps = Math.max(350000, Math.min(1400000, Math.floor(limitBytes * 8 * 0.88 / useDur) - 64000));
    const rec = new MediaRecorder(stream, mime ? {mimeType: mime, videoBitsPerSecond: vbps, audioBitsPerSecond: 64000} : {videoBitsPerSecond: vbps});
    const parts = [];
    rec.ondataavailable = (e)=>{ if(e.data && e.data.size) parts.push(e.data); };
    v.currentTime = 0;
    await new Promise(r=>{ v.onseeked = r; setTimeout(r, 1500); });
    /* ROUND 75: текст, мимоджи, отметки и фильтр истории впекаются в каждый кадр видео */
    const ovl = (opts && opts.overlayFor) ? opts.overlayFor(cw, ch) : null;
    const vf = (opts && opts.vfilter && opts.vfilter !== 'none') ? opts.vfilter : '';
    await v.play();
    rec.start(500);
    await new Promise(res=>{
      v.onended = res;
      const tick = ()=>{
        if(v.ended || v.currentTime >= useDur){ res(); return; }
        if(vf) ctx.filter = vf;
        ctx.drawImage(v, 0, 0, cw, ch);
        if(vf) ctx.filter = 'none';
        if(ovl) ctx.drawImage(ovl, 0, 0, cw, ch);
        onProgress(v.currentTime / useDur);
        requestAnimationFrame(tick);
      };
      tick();
    });
    v.pause();
    const blob = await new Promise(res=>{ rec.onstop = ()=> res(new Blob(parts, {type: ((rec.mimeType || mime || 'video/webm').split(';')[0])})); rec.stop(); });
    stream.getTracks().forEach(t=> t.stop());
    if(ac) try{ ac.close(); }catch(e){}
    return {blob, duration: useDur, w: cw, h: ch, thumb};
  }finally{ URL.revokeObjectURL(url); v.removeAttribute('src'); }
}
async function buildStoryAudience(kind){
  const me = state.currentUser.uid;
  const blocked = new Set((state.blacklist || []).map(b=> b.uid));
  let list = [];
  if(kind === 'friends') list = await getMyFriendUids();
  else if(kind === 'contacts') list = (state.contacts || []).map(c=> c.uid);
  else if(kind === 'selected') list = Array.from(storyEditor.selected);
  return Array.from(new Set(list)).filter(u=> u && u !== me && !blocked.has(u));
}
document.getElementById('se-publish').onclick = async ()=>{
  const file = storyEditor.file;
  if(!file){ if(storyEditor.music) return publishMusicOnlyStory(); return; }
  const pub = document.getElementById('se-publish');
  const kind = storyEditor.audience || 'friends';
  if(kind === 'selected' && !storyEditor.selected.size){ openStoryAudienceSheet(); return; }
  pub.disabled = true; pub.textContent = 'Публикация…';
  try{
    const isVideo = /^video\//.test(file.type);
    let dataUrl, thumb, duration = 0, w = 0, h = 0;
    if(isVideo){
      setStoryProgress(0, 'Обработка видео…');
      const prep = await prepareStoryVideo(file, f=> setStoryProgress(f * 0.85, `Обработка видео… ${Math.round(f * 100)}%`));
      dataUrl = await blobToDataUrl(prep.blob);
      thumb = prep.thumb; duration = prep.duration; w = prep.w; h = prep.h;
    }else{
      setStoryProgress(0.2, 'Сжатие фото…');
      dataUrl = await resizeImageFile(file, 1280, 0.82);
      thumb = await resizeImageFile(file, 220, 0.7);
    }
    const comma = dataUrl.indexOf(',');
    const mime = (dataUrl.slice(5, dataUrl.indexOf(';')) || (isVideo ? 'video/webm' : 'image/jpeg'));
    const b64 = dataUrl.slice(comma + 1);
    const chunkCount = Math.ceil(b64.length / STORY_CHUNK);
    if(chunkCount > STORY_MAX_CHUNKS) throw Object.assign(new Error('too_big'), {code: 'too_big'});
    const audience = kind === 'all' ? [] : await buildStoryAudience(kind);
    if(kind !== 'all' && !audience.length){
      if(!await uiConfirm('Сейчас эту историю не увидит никто, кроме вас (нет подходящих людей). Всё равно опубликовать?')){ pub.disabled = false; pub.textContent = 'Опубликовать историю'; return; }
    }
    setStoryProgress(0.9, 'Публикация…');
    const me = state.currentUser.uid;
    const ref = db.collection('stories').doc();
    const batch = db.batch();
    for(let i = 0; i < chunkCount; i++){
      batch.set(ref.collection('chunks').doc(String(i)), {authorUid: me, audience, audienceAll: kind === 'all', i, data: b64.slice(i * STORY_CHUNK, (i + 1) * STORY_CHUNK)});
    }
    const now = Date.now();
    batch.set(ref, {authorUid: me, authorName: await myDisplayName(), type: isVideo ? 'video' : 'photo', mime,
      caption: document.getElementById('se-caption').value.trim().slice(0, 200), createdAt: now, expireAt: now + storyEditor.ttl * 3600000,
      audience, audienceAll: kind === 'all', audienceKind: kind, chunkCount, duration, w, h, thumb, music: storyEditor.music || null, musicStart: storyEditor.musicStart || 0,
      poll: window.__pendingPoll || collectPoll() || null,                      // ROUND 90: опрос — прямо в истории
      musicClip: storyEditor.music && window.__musicClipP ? await window.__musicClipP : null,   // ROUND 91: фрагмент музыки — внутри истории
      videoMuted: isVideo ? !!(storyEditor.frames && storyEditor.frames[0] && storyEditor.frames[0].muteAudio) || (!!storyEditor.music && !(storyEditor.frames && storyEditor.frames[0] && storyEditor.frames[0].keepAudio)) : false});
    await batch.commit();
    try{ localStorage.setItem('storyAudience', kind); localStorage.setItem('storyTtl', String(storyEditor.ttl)); }catch(e){}
    setStoryProgress(1, 'Готово');
    closeStoryEditor();
    toast('История опубликована');
    notifyStoryAudience(kind, audience, ref.id, thumb);
  }catch(e){
    console.error('story publish', e);
    const msg = e && e.code === 'too_big' ? 'Файл слишком большой для истории — выберите видео покороче'
      : (e && /permission/i.test(e.code || e.message || '')) ? 'Нет доступа — обновите правила Firestore (раздел «Истории» в README)'
      : (e && e.message && /видео|формат/i.test(e.message)) ? e.message : 'Не удалось опубликовать историю';
    toast(msg);
    pub.disabled = false; pub.textContent = 'Опубликовать историю';
    document.getElementById('se-progress').style.display = 'none';
  }
};

/* ---------- загрузка медиа истории ---------- */
function b64ToBlob(b64, mime){
  const bin = atob(b64);
  const u = new Uint8Array(bin.length);
  for(let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
  return new Blob([u], {type: mime});
}
function getStoryMediaUrl(st){
  if(storyState.media[st.id]) return storyState.media[st.id];
  const ref = db.collection('stories').doc(st.id).collection('chunks');
  const p = Promise.all(Array.from({length: st.chunkCount || 1}, (_, i)=> ref.doc(String(i)).get()))
    .then(snaps=>{
      const b64 = snaps.map(s=> (s.exists && s.data().data) || '').join('');
      if(!b64) throw new Error('empty');
      return URL.createObjectURL(b64ToBlob(b64, st.mime || (st.type === 'video' ? 'video/webm' : 'image/jpeg')));
    });
  storyState.media[st.id] = p;
  storyState.mediaOrder.push(st.id);
  while(storyState.mediaOrder.length > 12){
    const old = storyState.mediaOrder.shift();
    const op = storyState.media[old]; delete storyState.media[old];
    if(op) op.then(u=> URL.revokeObjectURL(u)).catch(()=>{});
  }
  p.catch(()=>{ delete storyState.media[st.id]; });
  return p;
}

/* ---------- просмотр ---------- */
const sv = {groups: [], gi: 0, si: 0, el: null, dur: STORY_PHOTO_MS, elapsed: 0, last: 0, paused: 0, raf: null, token: 0, muted: false, open: false};
const svRoot = document.getElementById('story-viewer');
function openStoryViewer(uid){
  const groups = storyState.groups.filter(g=> g.stories.length);
  const gi = groups.findIndex(g=> g.uid === uid);
  if(gi < 0) return;
  sv.groups = groups; sv.gi = gi;
  const g = groups[gi];
  const firstUnseen = g.stories.findIndex(st=> !storyViewed.has(st.id));
  sv.si = (g.uid !== state.currentUser.uid && firstUnseen >= 0) ? firstUnseen : 0;
  sv.open = true; sv.paused = 0;
  svRoot.style.display = 'flex';
  svRoot.classList.remove('holding');
  document.getElementById('sv-views-sheet').classList.remove('open');
  showStory();
}
function closeStoryViewer(){
  sv.open = false;
  cancelAnimationFrame(sv.raf);
  sv.token++;
  if(sv.el && sv.el.tagName === 'VIDEO'){ try{ sv.el.pause(); }catch(e){} }
  document.getElementById('sv-media').innerHTML = '';
  document.getElementById('sv-reply').value = '';
  document.getElementById('sv-reply').blur();
  svRoot.style.display = 'none';
  rebuildStories(true);
}
function svCurrent(){ const g = sv.groups[sv.gi]; return g && g.stories[sv.si]; }
function svRenderBars(){
  const g = sv.groups[sv.gi];
  document.getElementById('sv-bars').innerHTML = g.stories.map((st, i)=> `<span class="${i < sv.si ? 'done' : ''}"><i></i></span>`).join('');
}
async function showStory(slideDir){
  const st = svCurrent();
  if(!st){ closeStoryViewer(); return; }
  const token = ++sv.token;
  const g = sv.groups[sv.gi];
  const mine = g.uid === state.currentUser.uid;
  cancelAnimationFrame(sv.raf);
  if(sv.el && sv.el.tagName === 'VIDEO'){ try{ sv.el.pause(); }catch(e){} }
  sv.el = null; sv.elapsed = 0; sv.dur = STORY_PHOTO_MS;
  svRoot.classList.toggle('is-mine', mine);
  const card = document.getElementById('sv-card');
  if(slideDir){ card.classList.remove('slide-left','slide-right'); void card.offsetWidth; card.classList.add(slideDir); }
  svRenderBars();
  storyLoadProfile(g.uid).then(()=>{
    if(token !== sv.token) return;
    document.getElementById('sv-ava').innerHTML = storyAvatarHtml(g.uid);
    document.getElementById('sv-name').textContent = mine ? 'Моя история' : storyPersonName(g.uid);
  });
  document.getElementById('sv-ava').innerHTML = storyAvatarHtml(g.uid);
  document.getElementById('sv-name').textContent = mine ? 'Моя история' : storyPersonName(g.uid);
  const audTxt = {friends: 'друзья', contacts: 'контакты', all: 'все', selected: 'выбранные'}[st.audienceKind] || '';
  document.getElementById('sv-time').textContent = storyAgo(st.createdAt) + (mine && audTxt ? ' · видят: ' + audTxt : '');
  document.getElementById('sv-caption').textContent = st.caption || '';
  document.getElementById('sv-like').classList.toggle('on', storyLiked.has(st.id));
  document.getElementById('sv-mute').style.display = (st.type === 'video' || st.music) ? 'flex' : 'none';
  document.getElementById('sv-views-count').textContent = 'Просмотры';
  const media = document.getElementById('sv-media');
  media.innerHTML = st.thumb ? `<div class="sv-blur" style="background-image:url('${st.thumb}')"></div>` : '';
  document.getElementById('sv-loading').classList.add('on');
  let url;
  if(st.type !== 'music') try{ url = await getStoryMediaUrl(st); }
  catch(e){
    if(token !== sv.token) return;
    document.getElementById('sv-loading').classList.remove('on');
    toast('Не удалось загрузить историю');
    setTimeout(()=>{ if(token === sv.token) svNext(); }, 1200);
    return;
  }
  if(token !== sv.token) return;
  let el;
  if(st.type === 'video'){
    el = document.createElement('video');
    el.src = url; el.playsInline = true; el.setAttribute('playsinline', ''); el.muted = sv.muted; el.preload = 'auto';
    el.addEventListener('ended', ()=>{ if(token === sv.token) svNext(); });
    media.appendChild(el);
    try{ await el.play(); }
    catch(e){ el.muted = true; sv.muted = true; try{ await el.play(); }catch(e2){} }
    document.getElementById('sv-mute').classList.toggle('muted', sv.muted);
    sv.dur = (st.duration || (isFinite(el.duration) ? el.duration : 15)) * 1000;
  }else if(st.type === 'music'){
    el = buildStoryMusicCard(st); media.appendChild(el);
  }else{
    el = document.createElement('img');
    el.src = url; el.alt = '';
    media.appendChild(el);
    await new Promise(r=>{ if(el.complete) r(); else { el.onload = r; el.onerror = r; } });
  }
  if(token !== sv.token) return;
  document.getElementById('sv-loading').classList.remove('on');
  sv.el = el;
  startStoryMusic(st, el);
  sv.last = performance.now();
  svMarkViewed(st);
  if(mine) svLoadViews(st, true);
  const next = g.stories[sv.si + 1] || (sv.groups[sv.gi + 1] && sv.groups[sv.gi + 1].stories[0]);
  if(next) getStoryMediaUrl(next).catch(()=>{});
  const bar = ()=> document.querySelector(`#sv-bars span:nth-child(${sv.si + 1}) i`);
  const loop = (t)=>{
    if(token !== sv.token || !sv.open) return;
    const dt = t - sv.last; sv.last = t;
    if(!sv.paused){
      if(el.tagName === 'VIDEO'){ sv.elapsed = el.currentTime * 1000; }
      else sv.elapsed += dt;
    }
    const b = bar(); if(b) b.style.width = Math.min(100, sv.elapsed / sv.dur * 100) + '%';
    if(sv.elapsed >= sv.dur && el.tagName !== 'VIDEO'){ svNext(); return; }
    sv.raf = requestAnimationFrame(loop);
  };
  sv.raf = requestAnimationFrame(loop);
}
function svPause(reason){ sv.paused++; if(sv.el && sv.el.tagName === 'VIDEO') try{ sv.el.pause(); }catch(e){} }
function svResume(){ sv.paused = Math.max(0, sv.paused - 1); if(!sv.paused && sv.el && sv.el.tagName === 'VIDEO') sv.el.play().catch(()=>{}); sv.last = performance.now(); }
function svNext(){
  const g = sv.groups[sv.gi];
  if(sv.si < g.stories.length - 1){ sv.si++; showStory(); return; }
  if(sv.gi < sv.groups.length - 1){ sv.gi++; sv.si = svFirstUnseen(sv.groups[sv.gi]); showStory('slide-left'); return; }
  closeStoryViewer();
}
function svPrev(){
  if(sv.si > 0){ sv.si--; showStory(); return; }
  if(sv.gi > 0){ sv.gi--; sv.si = 0; showStory('slide-right'); return; }
  sv.elapsed = 0; if(sv.el && sv.el.tagName === 'VIDEO') sv.el.currentTime = 0;
}
function svFirstUnseen(g){
  if(g.uid === state.currentUser.uid) return 0;
  const i = g.stories.findIndex(st=> !storyViewed.has(st.id));
  return i >= 0 ? i : 0;
}
function svMarkViewed(st){
  const me = state.currentUser.uid;
  if(st.authorUid === me || storyViewed.has(st.id)) return;
  storyViewed.add(st.id); storyLsSave('storyViewed', storyViewed);
  myDisplayName().then(name=>{
    db.collection('stories').doc(st.id).collection('views').doc(me).set({uid: me, name, ts: Date.now()}, {merge: true}).catch(()=>{});
  });
}

/* жесты: тап — вперёд/назад, удержание — пауза, свайп вниз — закрыть, вбок — другой человек */
(function svGestures(){
  const card = document.getElementById('sv-card');
  let g = null;
  const skip = (t)=> t.closest('.sv-head button, .sv-foot, .sv-views-sheet');
  card.addEventListener('pointerdown', (e)=>{
    if(skip(e.target) || document.getElementById('sv-views-sheet').classList.contains('open')) return;
    g = {x: e.clientX, y: e.clientY, t: Date.now(), holding: false, dx: 0, dy: 0};
    g.timer = setTimeout(()=>{ if(g){ g.holding = true; svPause(); svRoot.classList.add('holding'); } }, 220);
  });
  card.addEventListener('pointermove', (e)=>{
    if(!g) return;
    g.dx = e.clientX - g.x; g.dy = e.clientY - g.y;
    if(Math.abs(g.dx) > 10 || Math.abs(g.dy) > 10) clearTimeout(g.timer);
    if(g.dy > 0 && g.dy > Math.abs(g.dx)){ card.style.transition = 'none'; card.style.transform = `translateY(${g.dy}px) scale(${1 - Math.min(0.15, g.dy / 1500)})`; }
  });
  const end = (e)=>{
    if(!g) return;
    const gg = g; g = null;
    clearTimeout(gg.timer);
    card.style.transition = ''; card.style.transform = '';
    if(gg.holding){ svRoot.classList.remove('holding'); svResume(); return; }
    if(gg.dy > 110 && gg.dy > Math.abs(gg.dx)){ closeStoryViewer(); return; }
    if(Math.abs(gg.dx) > 70 && Math.abs(gg.dx) > Math.abs(gg.dy)){
      if(gg.dx < 0 && sv.gi < sv.groups.length - 1){ sv.gi++; sv.si = svFirstUnseen(sv.groups[sv.gi]); showStory('slide-left'); }
      else if(gg.dx > 0 && sv.gi > 0){ sv.gi--; sv.si = 0; showStory('slide-right'); }
      else if(gg.dx < 0) closeStoryViewer();
      return;
    }
    if(Math.abs(gg.dx) < 12 && Math.abs(gg.dy) < 12 && Date.now() - gg.t < 400){
      const r = card.getBoundingClientRect();
      if(e.clientX - r.left < r.width * 0.3) svPrev(); else svNext();
    }
  };
  card.addEventListener('pointerup', end);
  card.addEventListener('pointercancel', (e)=>{ if(g){ clearTimeout(g.timer); if(g.holding){ svRoot.classList.remove('holding'); svResume(); } g = null; card.style.transform = ''; } });
  document.addEventListener('keydown', (e)=>{
    if(!sv.open) return;
    if(e.target && e.target.id === 'sv-reply' && e.key !== 'Escape') return;
    if(e.key === 'Escape') closeStoryViewer();
    else if(e.key === 'ArrowRight') svNext();
    else if(e.key === 'ArrowLeft') svPrev();
  });
  document.addEventListener('visibilitychange', ()=>{ if(!sv.open) return; if(document.hidden) svPause(); else svResume(); });
})();

document.getElementById('sv-close').onclick = closeStoryViewer;
document.getElementById('sv-mute').onclick = (e)=>{
  if(e) e.stopPropagation();
  sv.muted = !sv.muted;
  /* ROUND 91: кнопка управляет всем звуком истории — и видео, и музыкой */
  if(sv.el && sv.el.tagName === 'VIDEO') sv.el.muted = sv.muted || (sv.el.dataset.authorMuted === '1' && !!svMusic);
  if(svMusic) svMusic.muted = sv.muted;
  document.getElementById('sv-mute').classList.toggle('muted', sv.muted);
};
/* ответ на историю — в личный чат с цитатой */
const svReply = document.getElementById('sv-reply');
svReply.addEventListener('focus', ()=> svPause());
svReply.addEventListener('blur', ()=> svResume());
svReply.addEventListener('input', ()=> document.getElementById('sv-foot-other').classList.toggle('typing', !!svReply.value.trim()));
async function sendStoryReply(){
  const text = svReply.value.trim();
  const st = svCurrent();
  if(!text || !st) return;
  const author = st.authorUid;
  try{
    const p = await storyLoadProfile(author);
    const meta = await ensureChat(author, (p && p.username) || storyPersonName(author), (p && p.email) || '');
    await sendMessage(meta.id, 'text', text, null, {replyTo: {id: 'story_' + st.id, fromUsername: storyPersonName(author), preview: (st.type === 'video' ? '🎥 ' : '📷 ') + 'История' + (st.caption ? ': ' + st.caption.slice(0, 60) : '')}});
    svReply.value = '';
    document.getElementById('sv-foot-other').classList.remove('typing');
    svReply.blur();
    toast('Ответ отправлен');
  }catch(e){ toast('Не удалось отправить ответ'); }
}
document.getElementById('sv-send').onclick = sendStoryReply;
svReply.addEventListener('keydown', (e)=>{ if(e.key === 'Enter'){ e.preventDefault(); sendStoryReply(); } });
document.getElementById('sv-like').onclick = ()=>{
  const st = svCurrent(); if(!st) return;
  const on = !storyLiked.has(st.id);
  if(on) storyLiked.add(st.id); else storyLiked.delete(st.id);
  storyLsSave('storyLiked', storyLiked);
  document.getElementById('sv-like').classList.toggle('on', on);
  if(on){ const b = document.getElementById('sv-heart-burst'); b.classList.remove('go'); void b.offsetWidth; b.classList.add('go'); haptic('buttons', 12); }
  const me = state.currentUser.uid;
  myDisplayName().then(name=> db.collection('stories').doc(st.id).collection('views').doc(me)
    .set({uid: me, name, ts: Date.now(), reaction: on ? '❤️' : null}, {merge: true}).catch(()=>{}));
};

/* просмотры своей истории */
async function svLoadViews(st, countOnly){
  try{
    const snap = await db.collection('stories').doc(st.id).collection('views').get();
    const rows = snap.docs.map(d=> d.data()).sort((a, b)=> (b.ts || 0) - (a.ts || 0));
    if(svCurrent() !== st) return rows;
    const likes = rows.filter(r=> r.reaction).length;
    document.getElementById('sv-views-count').textContent = rows.length ? `${rows.length} ${pluralViews(rows.length)}${likes ? ' · ❤️ ' + likes : ''}` : 'Пока нет просмотров';
    if(countOnly) return rows;
    const list = document.getElementById('sv-views-list');
    document.getElementById('sv-views-title').innerHTML = rows.length
      ? `Просмотры: ${rows.length}${likes ? ` · <span style="color:#FF3B5C;">❤️ ${likes}</span>` : ''}`
      : 'Просмотры';
    if(!rows.length){ list.innerHTML = '<div class="story-aud-empty">Историю ещё никто не посмотрел</div>'; return rows; }
    await Promise.all(rows.map(r=> storyLoadProfile(r.uid)));
    const nameOf = (r)=>{ const n = storyPersonName(r.uid); return (n && n !== 'Пользователь') ? n : ((r.name || '').trim() || 'Пользователь'); };
    const row = (r)=> `<div class="story-aud-row" data-view-uid="${r.uid}"><div class="avatar">${storyAvatarHtml(r.uid)}</div>
      <div class="nm">${escapeHtml(nameOf(r))}<div class="sub">${storyAgo(r.ts || Date.now())}${r.reaction ? ' · понравилось' : ''}</div></div>
      ${r.reaction ? `<span class="rx">${r.reaction}</span>` : '<span class="rx-eye">👁</span>'}</div>`;
    const liked = rows.filter(r=> r.reaction), seen = rows.filter(r=> !r.reaction);
    list.innerHTML = (liked.length ? `<div class="m-sheet-sub">❤️ Понравилось · ${liked.length}</div>` + liked.map(row).join('') : '')
      + (seen.length ? `<div class="m-sheet-sub">👁 Просмотрели · ${seen.length}</div>` + seen.map(row).join('') : '');
    return rows;
  }catch(e){ if(!countOnly) document.getElementById('sv-views-list').innerHTML = '<div class="story-aud-empty">Не удалось загрузить просмотры</div>'; return []; }
}
function pluralViews(n){ const a = n % 10, b = n % 100; if(a === 1 && b !== 11) return 'просмотр'; if(a >= 2 && a <= 4 && (b < 12 || b > 14)) return 'просмотра'; return 'просмотров'; }
document.getElementById('sv-views').onclick = ()=>{
  const st = svCurrent(); if(!st) return;
  svPause();
  document.getElementById('sv-views-list').innerHTML = '<div class="story-aud-empty">Загрузка…</div>';
  document.getElementById('sv-views-sheet').classList.add('open');
  svLoadViews(st, false);
};
document.getElementById('sv-views-list').addEventListener('click', (ev)=>{
  const r = ev.target.closest('[data-view-uid]'); if(!r) return;
  closeStoryViewer(); openUserInfo(r.dataset.viewUid);
});
svRoot.addEventListener('click', (ev)=>{
  const sheet = document.getElementById('sv-views-sheet');
  if(sheet.classList.contains('open') && !sheet.contains(ev.target) && !ev.target.closest('#sv-views')){ sheet.classList.remove('open'); svResume(); }
});
document.getElementById('sv-more').onclick = (ev)=>{
  ev.stopPropagation();
  const st = svCurrent(); if(!st) return;
  const mine = st.authorUid === state.currentUser.uid;
  svPause();
  const items = mine ? [
    {label: 'Удалить историю', icon: RM_ICON.trash, danger: true, action: async ()=>{
      if(!await uiConfirm('Удалить эту историю?')){ svResume(); return; }
      await deleteStory(st);
      toast('История удалена');
      const g = sv.groups[sv.gi];
      g.stories.splice(sv.si, 1);
      if(!g.stories.length){ sv.groups.splice(sv.gi, 1); if(!sv.groups.length){ closeStoryViewer(); return; } sv.gi = Math.min(sv.gi, sv.groups.length - 1); sv.si = 0; }
      else sv.si = Math.min(sv.si, g.stories.length - 1);
      sv.paused = 0; showStory();
    }},
  ] : [
    {label: 'Профиль', icon: RM_ICON.user, action: ()=>{ const u = st.authorUid; closeStoryViewer(); openUserInfo(u); }},
    {label: 'Написать', icon: RM_ICON.chat, action: ()=>{ const u = st.authorUid; closeStoryViewer(); openChatWithUser(u, storyPersonName(u)); }},
  ];
  const wrapped = items.map(it=> Object.assign({}, it, {action: ()=>{ sv.paused = Math.max(0, sv.paused - 1); it.action(); }}));
  openRowMenu(document.getElementById('sv-more'), wrapped);
  const ov = document.getElementById('row-menu-overlay');
  if(ov){
    ov.style.zIndex = '480';
    const cl = ov.querySelector('.row-menu-clone'); if(cl) cl.style.visibility = 'hidden';
    ov.addEventListener('click', (e)=>{ if(e.target === ov) svResume(); });
  }
};

/* удаление: части, просмотры, сама история */
async function deleteStory(st){
  const ref = db.collection('stories').doc(st.id);
  try{
    const views = await ref.collection('views').get().catch(()=> ({docs: []}));
    await Promise.all([
      ...Array.from({length: st.chunkCount || 1}, (_, i)=> ref.collection('chunks').doc(String(i)).delete().catch(()=>{})),
      ...views.docs.map(d=> d.ref.delete().catch(()=>{})),
    ]);
    await ref.delete();
  }catch(e){ console.warn('deleteStory', e); }
}
async function cleanupMyExpiredStories(){
  const now = Date.now();
  for(const st of storyState.sets.mine){ if((st.expireAt || 0) <= now) await deleteStory(st); }
}

/* ============================================================
   МУЗЫКА (v2) — по мотивам VK Музыки, Яндекс Музыки и Spotify,
   в стекле и цветах приложения.
   Треки: Audius (открытый каталог, полные треки)
   Радио: Radio Browser
   Свои файлы: только в браузере этого устройства (IndexedDB)
   Избранное и плейлисты: Firestore music/{uid} — только списки
============================================================ */
const MUSIC_APP_NAME = 'ChatMessenger';
const AUDIUS_API_KEY = '';          // необязательно: бесплатный ключ с api.audius.co/plans даёт больше запросов
const RADIO_BASES = ['https://de1.api.radio-browser.info', 'https://de2.api.radio-browser.info', 'https://fi1.api.radio-browser.info', 'https://nl1.api.radio-browser.info'];
const MI = {play: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5.5v13a1 1 0 0 0 1.5.9l10.2-6.5a1 1 0 0 0 0-1.8L9.5 4.6A1 1 0 0 0 8 5.5z"/></svg>`, pause: `<svg viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="5" width="4.2" height="14" rx="1.3"/><rect x="13.8" y="5" width="4.2" height="14" rx="1.3"/></svg>`, note: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18V5l11-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="17" cy="16" r="3"/></svg>`, heart: `<svg viewBox="0 0 24 24"><path d="M12 20.5s-8-4.9-8-10.7A4.5 4.5 0 0 1 12 7a4.5 4.5 0 0 1 8 2.8c0 5.8-8 10.7-8 10.7z"/></svg>`, next: `<svg viewBox="0 0 24 24" fill="currentColor"><path d="M5 6.2v11.6a.8.8 0 0 0 1.2.7l8.6-5.8a.8.8 0 0 0 0-1.4L6.2 5.5a.8.8 0 0 0-1.2.7z"/><rect x="16.5" y="5.5" width="2.6" height="13" rx="1"/></svg>`, shuffle: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="16 3 21 3 21 8"/><line x1="4" y1="20" x2="21" y2="3"/><polyline points="21 16 21 21 16 21"/><line x1="15" y1="15" x2="21" y2="21"/><line x1="4" y1="4" x2="9" y2="9"/></svg>`, back: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>`, x: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>`,
  more: '<svg viewBox="0 0 24 24" fill="currentColor"><circle cx="5.5" cy="12" r="1.9"/><circle cx="12" cy="12" r="1.9"/><circle cx="18.5" cy="12" r="1.9"/></svg>',
  radio: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><circle cx="12" cy="12" r="2"/><path d="M16.2 7.8a6 6 0 0 1 0 8.4"/><path d="M7.8 16.2a6 6 0 0 1 0-8.4"/><path d="M19 5a10 10 0 0 1 0 14"/><path d="M5 19A10 10 0 0 1 5 5"/></svg>'};
const MOODS = [
  {id: 'auto',   name: 'Под вас',   emoji: '✨', c: ['#5B6CFF','#9A4DFF','#FF5C9D'], genres: []},
  {id: 'energy', name: 'Бодро',     emoji: '⚡', c: ['#FF7A18','#FF3D71','#FFB800'], genres: ['Electronic','House','Drum & Bass','Hip-Hop/Rap','Techno']},
  {id: 'calm',   name: 'Спокойно',  emoji: '🌿', c: ['#2FB8A8','#3A7BD5','#8FE3CF'], genres: ['Ambient','Lo-Fi','Acoustic','Jazz','Downtempo']},
  {id: 'sad',    name: 'Грустно',   emoji: '🌧', c: ['#3B4A8A','#6D5BD0','#9AA8FF'], genres: ['Alternative','R&B/Soul','Lo-Fi','Folk']},
  {id: 'happy',  name: 'Радостно',  emoji: '☀️', c: ['#FFB300','#FF6A88','#FFE259'], genres: ['Pop','Funk','Reggae','Disco']},
  {id: 'focus',  name: 'Фокус',     emoji: '🎧', c: ['#1E3C72','#2A5298','#6DD5FA'], genres: ['Lo-Fi','Ambient','Classical','Downtempo']},
  {id: 'party',  name: 'Вечеринка', emoji: '🎉', c: ['#C850C0','#FF4E88','#FFCC70'], genres: ['House','Techno','Hip-Hop/Rap','Pop','Trap']},
];
const GENRES = [
  {g: 'Electronic', n: 'Электроника', e: '🎛', c: ['#5B6CFF','#00C6FF']}, {g: 'Hip-Hop/Rap', n: 'Хип-хоп', e: '🎤', c: ['#FF512F','#DD2476']},
  {g: 'Pop', n: 'Поп', e: '🌈', c: ['#FF6A88','#FF99AC']}, {g: 'Lo-Fi', n: 'Lo-Fi', e: '☕', c: ['#8E6E53','#C9A27E']},
  {g: 'Rock', n: 'Рок', e: '🎸', c: ['#434343','#8E0E00']}, {g: 'House', n: 'Хаус', e: '🪩', c: ['#7F00FF','#E100FF']},
  {g: 'Ambient', n: 'Эмбиент', e: '🌌', c: ['#141E30','#3A6073']}, {g: 'R&B/Soul', n: 'R&B', e: '💜', c: ['#654EA3','#EAAFC8']},
  {g: 'Jazz', n: 'Джаз', e: '🎷', c: ['#B79891','#94716B']}, {g: 'Classical', n: 'Классика', e: '🎻', c: ['#C79081','#DFA579']},
];
const RADIO_TAGS = [['', 'Популярное'], ['pop', 'Поп'], ['rock', 'Рок'], ['jazz', 'Джаз'], ['electronic', 'Электроника'], ['lofi', 'Lo-Fi'], ['news', 'Новости'], ['classical', 'Классика'], ['hiphop', 'Хип-хоп'], ['chillout', 'Чилаут']];

const music = {lib: {favorites: [], playlists: []}, libUid: null, unsubLib: null, queue: [], qi: -1, track: null, shuffle: false, repeat: 'off',
  subtab: 'mix', view: null, mood: null, cache: {}, local: [], localUrls: {}, lists: {}, contextName: '', contextKind: '', pausedByCall: false,
  saveTimer: null, radioTag: '', mixLoading: false, sleep: null};
try{ music.mood = localStorage.getItem('musicMood') || 'auto'; }catch(e){ music.mood = 'auto'; }
const musicAudio = document.getElementById('music-audio');
const trackKey = (t)=> t ? t.src + ':' + t.id : '';
const musicTime = (s)=>{ s = Math.max(0, Math.floor(s || 0)); return Math.floor(s/60) + ':' + String(s%60).padStart(2,'0'); };
const shuffleArr = (a)=>{ a = a.slice(); for(let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
const slim = (t)=>{ const o = {src: t.src, id: t.id, title: t.title, artist: t.artist || '', art: t.art || '', dur: t.dur || 0}; if(t.url) o.url = t.url; if(t.genre) o.genre = t.genre; if(t.emoji) o.emoji = t.emoji; if(t.alts) o.alts = t.alts; return o; };

/* ---------- источники ---------- */
let audiusBase = 'https://api.audius.co/v1';
function audiusQs(){ return 'app_name=' + MUSIC_APP_NAME + (AUDIUS_API_KEY ? '&api_key=' + encodeURIComponent(AUDIUS_API_KEY) : ''); }
async function audiusGet(path){
  const sep = path.includes('?') ? '&' : '?';
  try{
    const r = await fetch(audiusBase + path + sep + audiusQs());
    if(!r.ok) throw new Error('audius ' + r.status);
    return (await r.json()).data || [];
  }catch(e){
    try{
      const hosts = ((await (await fetch('https://api.audius.co')).json()).data) || [];
      if(hosts.length){
        audiusBase = hosts[Math.floor(Math.random() * hosts.length)].replace(/\/$/, '') + '/v1';
        const r2 = await fetch(audiusBase + path + sep + audiusQs());
        if(r2.ok) return (await r2.json()).data || [];
      }
    }catch(e2){}
    throw e;
  }
}
function audiusTrack(t){
  const art = t.artwork ? (t.artwork['480x480'] || t.artwork['150x150'] || t.artwork['1000x1000'] || '') : '';
  return {src: 'audius', id: String(t.id), title: t.title || 'Без названия', artist: (t.user && t.user.name) || '', art, dur: t.duration || 0, genre: t.genre || '', mood: t.mood || ''};
}
async function audiusTrending(genre, time){
  const key = 'tr:' + (genre || '') + ':' + (time || 'week');
  if(music.cache[key]) return music.cache[key];
  const raw = await audiusGet('/tracks/trending?time=' + (time || 'week') + (genre ? '&genre=' + encodeURIComponent(genre) : ''));
  return (music.cache[key] = raw.filter(t=> t && t.id && t.is_streamable !== false).map(audiusTrack));
}
async function audiusSearch(q){
  const key = 'q:' + q.toLowerCase();
  if(music.cache[key]) return music.cache[key];
  const raw = await audiusGet('/tracks/search?query=' + encodeURIComponent(q) + '&limit=40');
  return (music.cache[key] = raw.filter(t=> t && t.id && t.is_streamable !== false).map(audiusTrack));
}
async function radioGet(path){
  for(const b of RADIO_BASES){ try{ const r = await fetch(b + path); if(r.ok) return await r.json(); }catch(e){} }
  throw new Error('radio');
}
function radioTrack(st){
  const tags = (st.tags || '').split(',').map(x=> x.trim()).filter(Boolean).slice(0, 2).join(', ');
  return {src: 'radio', id: st.stationuuid, title: (st.name || 'Радио').trim(), artist: [st.country, tags].filter(Boolean).join(' · '),
    art: (st.favicon && /^https:/.test(st.favicon)) ? st.favicon : '', dur: 0, url: st.url_resolved || st.url};
}
async function radioStations(opts){
  const key = 'r:' + JSON.stringify(opts);
  if(music.cache[key]) return music.cache[key];
  let path = '/json/stations/search?hidebroken=true&is_https=true&order=clickcount&reverse=true&limit=60';
  if(opts.name) path += '&name=' + encodeURIComponent(opts.name);
  if(opts.tag) path += '&tag=' + encodeURIComponent(opts.tag);
  if(opts.country) path += '&countrycode=' + opts.country;
  const raw = await radioGet(path);
  const seen = new Set();
  const okUrl = (u)=> /^https:/.test(u) || (typeof musicViaProxy === 'function' && musicViaProxy() && u.startsWith(proxyBase()));
  return (music.cache[key] = raw.filter(st=> st && okUrl(st.url_resolved || st.url || ''))
    .filter(st=>{ const k = (st.name || '').trim().toLowerCase(); if(seen.has(k)) return false; seen.add(k); return true; }).slice(0, 50).map(radioTrack));
}
function myCountry(){ const l = (navigator.language || 'ru').slice(0, 2).toUpperCase(); return l === 'EN' ? 'US' : l === 'UK' ? 'UA' : l; }

/* ---------- свои файлы ---------- */
function musicIdb(){
  return new Promise((res, rej)=>{
    const r = indexedDB.open('chatMusic', 2);
    r.onupgradeneeded = ()=>{
      const d = r.result;
      if(!d.objectStoreNames.contains('files')) d.createObjectStore('files', {keyPath: 'id'});
      if(!d.objectStoreNames.contains('downloads')) d.createObjectStore('downloads', {keyPath: 'key'});
    };
    r.onsuccess = ()=> res(r.result); r.onerror = ()=> rej(r.error);
  });
}
async function idbTx(mode, fn){
  const d = await musicIdb();
  return new Promise((res, rej)=>{
    const tx = d.transaction('files', mode); let out;
    Promise.resolve(fn(tx.objectStore('files'))).then(v=> out = v);
    tx.oncomplete = ()=> res(out); tx.onerror = ()=> rej(tx.error);
  });
}
async function loadLocalFiles(){
  try{
    const all = await idbTx('readonly', st=> new Promise(r=>{ const q = st.getAll(); q.onsuccess = ()=> r(q.result || []); }));
    music.local = all.sort((a, b)=> b.addedAt - a.addedAt).map(f=> ({src: 'local', id: f.id, title: f.title, artist: f.artist || 'На этом устройстве', art: '', dur: f.dur || 0}));
  }catch(e){ music.local = []; }
}
async function localUrl(id){
  if(music.localUrls[id]) return music.localUrls[id];
  const rec = await idbTx('readonly', st=> new Promise(r=>{ const q = st.get(id); q.onsuccess = ()=> r(q.result); }));
  return rec ? (music.localUrls[id] = URL.createObjectURL(rec.blob)) : null;
}
function parseFileName(name){
  const base = name.replace(/\.[a-z0-9]{2,5}$/i, '').replace(/_/g, ' ').trim();
  const m = base.split(/\s+[-–—]\s+/);
  return m.length >= 2 ? {artist: m[0].trim(), title: m.slice(1).join(' - ').trim()} : {artist: '', title: base};
}
async function addLocalFiles(files){
  const list = Array.from(files || []).filter(f=> /^audio\//.test(f.type) || /\.(mp3|m4a|aac|ogg|opus|wav|flac)$/i.test(f.name));
  if(!list.length){ toast('Выберите аудиофайлы'); return; }
  try{ if(navigator.storage && navigator.storage.persist) navigator.storage.persist(); }catch(e){}
  let added = 0;
  for(const f of list){
    const dur = await new Promise(r=>{ const a = new Audio(); const u = URL.createObjectURL(f); a.preload = 'metadata'; a.onloadedmetadata = ()=>{ r(isFinite(a.duration) ? a.duration : 0); URL.revokeObjectURL(u); }; a.onerror = ()=>{ r(0); URL.revokeObjectURL(u); }; a.src = u; });
    const meta = parseFileName(f.name);
    const rec = {id: 'f' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7), title: meta.title, artist: meta.artist, type: f.type, size: f.size, blob: f, dur, addedAt: Date.now()};
    try{ await idbTx('readwrite', st=> st.put(rec)); added++; }catch(e){ toast('Не хватает места в памяти браузера'); break; }
  }
  await loadLocalFiles(); renderMusic();
  if(added) toast(added === 1 ? 'Трек добавлен на устройство' : `Добавлено треков: ${added}`);
}
document.getElementById('music-file-input').addEventListener('change', (e)=>{ addLocalFiles(e.target.files); e.target.value = ''; });

/* ---------- библиотека и история ---------- */
function libRef(){ return db.collection('music').doc(state.currentUser.uid); }
function startMusicLibrary(){
  if(!state.currentUser || music.libUid === state.currentUser.uid) return;
  if(music.unsubLib) try{ music.unsubLib(); }catch(e){}
  music.libUid = state.currentUser.uid;
  try{
    music.unsubLib = libRef().onSnapshot(snap=>{
      const d = snap.exists ? snap.data() : {};
      music.lib = {favorites: d.favorites || [], playlists: d.playlists || []};
      renderMusic(); syncPlayerUi();
    }, ()=>{});
  }catch(e){}
}
setInterval(()=>{ if(state.currentUser) startMusicLibrary(); else if(music.libUid){ music.libUid = null; if(music.unsubLib) try{ music.unsubLib(); }catch(e){} } }, 1500);
function saveLib(){
  clearTimeout(music.saveTimer);
  music.saveTimer = setTimeout(()=>{
    libRef().set({favorites: music.lib.favorites.slice(0, 2000), playlists: music.lib.playlists.slice(0, 200)}, {merge: true})
      .catch(()=> toast('Не удалось сохранить — обновите правила Firestore (раздел «Музыка»)'));
  }, 400);
}
function isFav(t){ return music.lib.favorites.some(x=> trackKey(x) === trackKey(t)); }
function toggleFav(t){
  const on = !isFav(t);
  if(on) music.lib.favorites.unshift(slim(t)); else music.lib.favorites = music.lib.favorites.filter(x=> trackKey(x) !== trackKey(t));
  saveLib(); renderMusic(); syncPlayerUi();
  haptic('likes', on ? [14, 30, 14] : 10);
  toast(on ? 'Добавлено в избранное' : 'Убрано из избранного');
}
function addToPlaylist(plId, t){
  const pl = music.lib.playlists.find(p=> p.id === plId); if(!pl) return;
  if(pl.tracks.some(x=> trackKey(x) === trackKey(t))){ toast('Уже есть в плейлисте'); return; }
  pl.tracks.push(slim(t)); pl.updatedAt = Date.now(); saveLib(); renderMusic(); toast(`Добавлено в «${pl.name}»`);
}
function createPlaylist(name, first){
  const pl = {id: 'p' + Date.now().toString(36), name: name.trim().slice(0, 60) || 'Новый плейлист', tracks: first ? [slim(first)] : [], createdAt: Date.now(), updatedAt: Date.now()};
  music.lib.playlists.unshift(pl); saveLib(); renderMusic(); return pl;
}
function historyGet(){ try{ return JSON.parse(localStorage.getItem('musicHistory') || '[]'); }catch(e){ return []; } }
function historyPush(t){
  const h = historyGet().filter(x=> trackKey(x) !== trackKey(t));
  h.unshift(slim(t));
  try{ localStorage.setItem('musicHistory', JSON.stringify(h.slice(0, 40))); }catch(e){}
}

/* ---------- «Мой микс»: бесконечный поток под настроение ---------- */
function moodById(id){ return MOODS.find(m=> m.id === id) || MOODS[0]; }
function autoGenres(){
  const count = {};
  [...music.lib.favorites, ...historyGet()].forEach(t=>{ if(t.genre) count[t.genre] = (count[t.genre] || 0) + 1; });
  const top = Object.keys(count).sort((a, b)=> count[b] - count[a]).slice(0, 3);
  return top.length ? top : ['Electronic', 'Pop', 'Hip-Hop/Rap', 'Lo-Fi'];
}
async function buildMix(moodId, exclude){
  const mood = moodById(moodId);
  const genres = shuffleArr(mood.id === 'auto' ? autoGenres() : mood.genres).slice(0, 3);
  const times = ['week', 'month', 'allTime'];
  const results = await Promise.all(genres.map((g, i)=> audiusTrending(g, times[(i + Math.floor(Math.random() * 3)) % 3]).catch(()=> [])));
  const recent = new Set([...historyGet().slice(0, 25).map(trackKey), ...(exclude || [])]);
  const seen = new Set();
  let pool = shuffleArr(results.flat()).filter(t=>{ const k = trackKey(t); if(seen.has(k) || recent.has(k)) return false; seen.add(k); return true; });
  if(pool.length < 8){ const extra = await audiusTrending('', 'week').catch(()=> []); pool = pool.concat(shuffleArr(extra).filter(t=> !seen.has(trackKey(t)))); }
  return pool.slice(0, 30);
}
async function playMix(moodId){
  if(music.mixLoading) return;
  music.mood = moodId || music.mood;
  try{ localStorage.setItem('musicMood', music.mood); }catch(e){}
  music.mixLoading = true; renderMusic();
  try{
    const list = await buildMix(music.mood);
    if(!list.length){ toast('Не удалось собрать микс — проверьте интернет'); return; }
    music.shuffle = false;
    await playQueue(list, 0, 'Мой микс · ' + moodById(music.mood).name, 'mix');
  }catch(e){ toast('Не удалось собрать микс'); }
  finally{ music.mixLoading = false; renderMusic(); }
}
async function refillMixIfNeeded(){
  if(music.contextKind !== 'mix' || music.mixLoading) return;
  if(music.queue.length - music.qi > 3) return;
  music.mixLoading = true;
  try{
    const more = await buildMix(music.mood, music.queue.map(trackKey));
    const have = new Set(music.queue.map(trackKey));
    music.queue.push(...more.filter(t=> !have.has(trackKey(t))));
  }catch(e){}
  music.mixLoading = false;
}

/* ---------- листы ---------- */
function openMusicSheet(title, html, onReady){
  document.getElementById('music-sheet-title').textContent = title;
  document.getElementById('music-sheet-body').innerHTML = html;
  document.getElementById('music-sheet').style.display = 'flex';
  if(onReady) onReady(document.getElementById('music-sheet-body'));
}
function closeMusicSheet(){ document.getElementById('music-sheet').style.display = 'none'; }
document.getElementById('music-sheet').addEventListener('click', (e)=>{ if(e.target.id === 'music-sheet') closeMusicSheet(); });
function promptPlaylistName(title, initial, cb){
  openMusicSheet(title, `<div class="music-sheet-input"><input id="music-pl-name" maxlength="60" placeholder="Название плейлиста" value="${escapeHtml(initial || '')}"><button type="button" id="music-pl-ok">Готово</button></div>`, (body)=>{
    const inp = body.querySelector('#music-pl-name');
    setTimeout(()=> inp.focus(), 80);
    const ok = ()=>{ const v = inp.value.trim(); if(!v){ inp.focus(); return; } closeMusicSheet(); cb(v); };
    body.querySelector('#music-pl-ok').onclick = ok;
    inp.addEventListener('keydown', (e)=>{ if(e.key === 'Enter') ok(); });
  });
}
function openAddToPlaylist(t){
  const rows = music.lib.playlists.map(p=> `<div class="music-sheet-row" data-pl="${p.id}">${coverHtml(p, true)}<div style="flex:1;min-width:0;"><b>${escapeHtml(p.name)}</b><div class="m-sub">${countTxt(p.tracks.length)}</div></div></div>`).join('');
  openMusicSheet('Добавить в плейлист', `<div class="music-sheet-row" data-pl="__new"><div class="m-art" style="background:var(--bubble-in);color:var(--accent);"><b style="font-size:26px;font-weight:300;">+</b></div><b style="color:var(--accent);">Новый плейлист</b></div>${rows}`, (body)=>{
    body.onclick = (e)=>{
      const r = e.target.closest('[data-pl]'); if(!r) return;
      if(r.dataset.pl === '__new') promptPlaylistName('Новый плейлист', '', (name)=>{ createPlaylist(name, t); toast(`Плейлист «${name}» создан`); });
      else { closeMusicSheet(); addToPlaylist(r.dataset.pl, t); }
    };
  });
}

/* ---------- элементы разметки ---------- */
function countTxt(n){ const a = n % 10, b = n % 100; return n + ' ' + (a === 1 && b !== 11 ? 'трек' : (a >= 2 && a <= 4 && (b < 12 || b > 14)) ? 'трека' : 'треков'); }
const isCur = (t)=> !!(music.track && trackKey(music.track) === trackKey(t));
function artInner(t){ return t.art ? `<img src="${escapeHtml(t.art)}" alt="" loading="lazy" onerror="this.remove()">` : (t.emoji ? `<span class="m-emoji">${t.emoji}</span>` : (t.src === 'radio' ? MI.radio : MI.note)); }
function artHtml(t){ return `<div class="m-art ${t.src === 'radio' ? 'radio' : t.src === 'local' ? 'local' : ''}">${artInner(t)}${isCur(t) ? `<div class="m-eq ${musicAudio.paused ? 'paused' : ''}"><i></i><i></i><i></i></div>` : ''}</div>`; }
function coverHtml(pl, small){
  const arts = pl.tracks.map(t=> t.art).filter(Boolean).slice(0, 4);
  const style = small ? 'style="width:42px;height:42px;border-radius:11px;flex-shrink:0;"' : '';
  if(!arts.length) return `<div class="m-pl-cover one" ${style}><div class="empty">${MI.note}</div></div>`;
  if(arts.length < 4) return `<div class="m-pl-cover one" ${style}><img src="${escapeHtml(arts[0])}" alt=""></div>`;
  return `<div class="m-pl-cover" ${style}>${arts.map(a=> `<img src="${escapeHtml(a)}" alt="">`).join('')}</div>`;
}
function regList(name, list){ music.lists[name] = list; return name; }
function rowsHtml(listName, list, numbered){
  regList(listName, list);
  return `<div class="m-group m-glass">${list.map((t, i)=>{
    const sub = t.src === 'radio' ? (t.artist || 'Радиостанция') : [t.artist, t.dur ? musicTime(t.dur) : ''].filter(Boolean).join(' · ');
    const selable = music.selMode && (t.src === 'local' || isDownloaded(t));
    return `<div class="m-row ${isCur(t) ? 'playing' : ''} ${selable ? 'selectable' : ''} ${selable && music.sel.has(trackKey(t)) ? 'selected' : ''}" data-list="${listName}" data-i="${i}">${selable ? `<span class="m-check">${music.sel.has(trackKey(t)) ? '✓' : ''}</span>` : ''}${numbered ? `<span class="m-num">${i + 1}</span>` : ''}${artHtml(t)}
      <div class="m-info"><div class="m-title">${dlBadge(t)}${escapeHtml(t.title)}</div><div class="m-sub">${escapeHtml(sub)}</div></div>
      <button type="button" class="m-fav ${isFav(t) ? 'on' : ''}" data-act="fav" aria-label="В избранное">${MI.heart}</button>
      <button type="button" class="m-more" data-act="more" aria-label="Ещё">${MI.more}</button></div>`;
  }).join('')}</div>`;
}
function cardsHtml(listName, list, round){
  regList(listName, list);
  return `<div class="m-carousel" data-no-swipe>${list.map((t, i)=> `<div class="m-card ${round ? 'round' : ''} ${isCur(t) ? 'playing' : ''}" data-list="${listName}" data-i="${i}">
    <div class="cv">${artInner(t)}<span class="pp">${isCur(t) && !musicAudio.paused ? MI.pause : MI.play}</span></div>
    <div class="t">${escapeHtml(t.title)}</div><div class="a">${escapeHtml(round ? (t.artist || '').split(' · ')[0] : t.artist)}</div></div>`).join('')}</div>`;
}
function tilesHtml(listName, list){
  regList(listName, list);
  return `<div class="m-tiles">${list.map((t, i)=> `<div class="m-tile m-glass ${isCur(t) ? 'playing' : ''}" data-list="${listName}" data-i="${i}">${artHtml(t)}<div class="t">${escapeHtml(t.title)}</div></div>`).join('')}</div>`;
}
const skeleton = ()=> '<div class="m-skel"><i></i><i></i><i></i></div>';
function section(title, link, act){ return `<div class="m-section"><h3>${title}</h3>${link ? `<button type="button" class="m-link" data-act="${act}">${link}</button>` : ''}</div>`; }

/* ---------- отрисовка ---------- */
function setMusicBody(html){ const b = document.getElementById('music-body'); if(b.innerHTML !== html) b.innerHTML = html; }
function renderMusic(){
  const body = document.getElementById('music-body');
  if(!body || !state.currentUser) return;
  music.lists = {};
  const q = (document.getElementById('music-search').value || '').trim();
  if(q) return renderSearch(q);
  const v = music.view;
  if(v) return renderListView(v);
  if(music.subtab === 'mix') return renderMixHome();
  if(music.subtab === 'mine') return renderMine();
  return renderRadio();
}
function renderMixHome(){
  const mood = moodById(music.mood);
  const mixPlaying = String(music.contextKind).startsWith('mix') && !musicAudio.paused;
  const hist = historyGet().slice(0, 6);
  const tr = music.cache['tr::week'];
  const radioTop = RU_STATIONS.filter(st=> st.cat === 'ru').map(stationTrack);
  let html = `<div class="m-hero ${mixPlaying ? 'playing' : ''}" id="m-hero" data-act="mix-play" style="--mg1:${mood.c[0]};--mg2:${mood.c[1]};--mg3:${mood.c[2]};">
      <div class="m-orb"><i></i><i></i><i></i></div>
      <div class="m-hero-text"><div class="m-hero-kicker">Мой микс</div><div class="m-hero-title">${mood.emoji} ${escapeHtml(mood.name)}</div>
      <div class="m-hero-sub">${music.mixLoading ? 'Собираем треки…' : mixPlaying ? 'Играет — поток пополняется сам' : 'Бесконечный поток под настроение'}</div></div>
      <button type="button" class="m-hero-play" data-act="mix-play" aria-label="Слушать микс">${music.mixLoading ? '<span class="ai-spinner" style="width:22px;height:22px;"></span>' : (mixPlaying ? MI.pause : MI.play)}</button>
    </div>
    <div class="m-moods" data-no-swipe>${MOODS.map(m=> `<button type="button" class="m-mood ${m.id === music.mood ? 'on' : ''}" data-act="mood" data-mood="${m.id}" style="--c1:${m.c[0]};--c2:${m.c[1]};">${m.emoji} ${m.name}</button>`).join('')}</div>`;
  if(music.audiusDown) html += `<div class="m-offline m-glass"><b>🌐 Каталог треков сейчас недоступен</b><span>${musicViaProxy() ? 'Прокси-сервер не отвечает или не видит каталог — проверьте его в админ-панели.' : 'В России он открывается только через VPN или через свой прокси (настраивается в админ-панели).'} Сейчас работают радио (Русское, Зайцев.FM, Хиты…) и скачанные треки — «Мой микс» сам включит радио под настроение.</span><button type="button" class="m-link" data-act="recheck">Проверить снова</button></div>`;
  const offHome = offlineTracks();
  if(offHome.length) html += section('На устройстве', 'Все', 'open-offline') + cardsHtml('dl-home', offHome.slice(0, 12));
  if(hist.length) html += section('Недавно') + tilesHtml('recent', hist);
  html += section('В тренде', 'Все', 'open-trending') + (tr ? cardsHtml('trending', tr.slice(0, 15)) : skeleton());
  html += section('Жанры') + `<div class="m-genres">${GENRES.map(g=> `<div class="m-genre" data-act="genre" data-genre="${escapeHtml(g.g)}" data-emoji="${g.e}" style="--g1:${g.c[0]};--g2:${g.c[1]};">${g.n}</div>`).join('')}</div>`;
  html += section('Радио', 'Все', 'open-radio') + (radioTop ? cardsHtml('radiotop', radioTop.slice(0, 12), true) : skeleton());
  if(music.lib.playlists.length){
    html += section('Ваши плейлисты', 'Все', 'open-mine') + `<div class="m-carousel" data-no-swipe>${music.lib.playlists.map(p=> `<div class="m-card" data-act="open-pl" data-pl="${p.id}"><div class="cv" style="background:none;">${coverHtml(p).replace('class="m-pl-cover', 'style="width:100%;height:100%;" class="m-pl-cover')}</div><div class="t">${escapeHtml(p.name)}</div><div class="a">${countTxt(p.tracks.length)}</div></div>`).join('')}</div>`;
  }
  setMusicBody(html);
  if(!tr) audiusTrending('', 'week').then(()=> music.subtab === 'mix' && !music.view && renderMusic()).catch(()=>{ music.cache['tr::week'] = []; renderMusic(); });
  bindHeroGyro();
}
function renderMine(){
  const favN = music.lib.favorites.length, pls = music.lib.playlists;
  let html = `<div class="m-fav-card" data-act="open-fav"><div class="ic">${MI.heart}</div><div class="tx"><b>Избранное</b><span>${countTxt(favN)}</span></div>${favN ? `<button type="button" class="pl" data-act="play-fav" aria-label="Слушать избранное">${MI.play}</button>` : ''}</div>`;
  html += section('Плейлисты') + `<div class="m-grid"><div class="m-new-pl m-glass" data-act="new-pl"><b>+</b>Новый плейлист</div>${pls.map(p=> `<div class="m-pl-card" data-act="open-pl" data-pl="${p.id}">${coverHtml(p)}<div class="m-pl-name">${escapeHtml(p.name)}</div><div class="m-pl-count">${countTxt(p.tracks.length)}</div></div>`).join('')}</div>`;
  const busyKeys = Object.keys(music.dlBusy || {});
  if(busyKeys.length){
    html += section('Загружается');
    html += `<div class="m-group m-glass">${busyKeys.map(k=>{
      const t = (music.dlQueue && music.dlQueue[k]) || {title: 'Трек', artist: '', src: 'audius'};
      const pc = music.dlBusy[k] || 0;
      return `<div class="m-row dl-row">${artHtml(t)}<div class="m-info"><div class="m-title">${escapeHtml(t.title)}</div>
        <div class="m-sub">${pc ? 'Скачивание · ' + pc + '%' : 'Подготовка…'}</div>
        <div class="dl-bar"><i style="width:${pc}%"></i></div></div></div>`;
    }).join('')}</div>`;
  }
  const offline = offlineTracks();
  html += section('На устройстве', offline.length > 5 ? `Все (${offline.length})` : '', 'open-offline');
  html += offline.length ? rowsHtml('offline', offline.slice(0, 5)) : '';
  html += `<div class="m-dev-actions">
      <button type="button" class="m-dev-btn primary" data-act="pickfolder">📁 Папка с музыкой</button>
      <button type="button" class="m-dev-btn" data-act="addfiles">🎵 Выбрать файлы</button>
      ${offline.length ? `<button type="button" class="m-dev-btn" data-act="open-offline">Все (${offline.length})</button>` : ''}
    </div>`;

  setMusicBody(html);
}
function renderRadio(){
  const cat = music.radioCat || 'ru';
  if(cat === 'fav'){
    const favs = (music.lib.favorites || []).filter(t=> t.src === 'radio');
    setMusicBody(`<div class="m-chips" data-no-swipe>${RADIO_CATS.map(([c, n])=> `<button type="button" class="m-chip ${cat === c ? 'on' : ''}" data-act="radiocat" data-cat="${c}">${n}</button>`).join('')}</div>`
      + (favs.length ? section('Любимые станции') + rowsHtml('radio', favs)
                     : '<div class="m-empty m-glass"><b>Пока нет любимых станций</b>Нажмите ♡ у станции — она появится здесь</div>'));
    return;
  }
  let html = `<div class="m-chips" data-no-swipe>${RADIO_CATS.map(([c, n])=> `<button type="button" class="m-chip ${cat === c ? 'on' : ''}" data-act="radiocat" data-cat="${c}">${n}</button>`).join('')}</div>`;
  if(cat !== 'world'){
    const list = RU_STATIONS.filter(st=> st.cat === cat).map(stationTrack);
    html += section({ru: 'Русское радио', hits: 'Хиты', rap: 'Рэп и фонк', dance: 'Танцевальная', chill: 'Спокойная', rock: 'Рок'}[cat] || 'Станции') + rowsHtml('radio', list)
;
    setMusicBody(html); return;
  }
  const key = {country: myCountry()};
  const data = music.cache['r:' + JSON.stringify(key)];
  if(!data){ setMusicBody(html + '<div class="m-loading"><span class="ai-spinner" style="width:26px;height:26px;"></span></div>'); radioStations(key).then(renderMusic).catch(()=>{ music.cache['r:' + JSON.stringify(key)] = null; setMusicBody(html + errBox()); }); return; }
  html += data.length ? section('Станции со всего мира') + rowsHtml('radio', data) : '<div class="m-empty"><b>Станции не найдены</b></div>';
  setMusicBody(html);
}
const errBox = ()=> '<div class="m-empty m-glass" style="margin-top:12px;"><b>Каталог сейчас недоступен</b>Проверьте интернет и попробуйте ещё раз<br><button type="button" class="m-link" data-act="retry" style="margin-top:8px;">Повторить</button></div>';
function renderSearch(q){
  const key = 'q:' + q.toLowerCase();
  const tr = music.cache[key];
  const rkey = 'r:' + JSON.stringify({name: q});
  const rs = music.cache[rkey];
  const ql = q.toLowerCase();
  const all = [...music.lib.favorites, ...music.lib.playlists.flatMap(p=> p.tracks), ...music.local];
  const seen = new Set(), mine = [];
  all.forEach(t=>{ const k = trackKey(t); if(!seen.has(k) && (t.title + ' ' + t.artist).toLowerCase().includes(ql)){ seen.add(k); mine.push(t); } });
  let html = '';
  if(mine.length) html += section('В моей музыке') + rowsHtml('s-mine', mine.slice(0, 5));
  html += section('Треки') + (tr ? (tr.length ? rowsHtml('s-tracks', tr.slice(0, 25)) : '<div class="m-empty">Ничего не найдено</div>') : '<div class="m-loading"><span class="ai-spinner" style="width:24px;height:24px;"></span></div>');
  if(rs && rs.length) html += section('Радиостанции') + rowsHtml('s-radio', rs.slice(0, 6));
  setMusicBody(html);
  if(!tr) audiusSearch(q).then(()=>{ if((document.getElementById('music-search').value || '').trim() === q) renderMusic(); }).catch(()=>{ music.cache[key] = []; renderMusic(); });
  if(!rs) radioStations({name: q}).then(()=>{ if((document.getElementById('music-search').value || '').trim() === q) renderMusic(); }).catch(()=>{ music.cache[rkey] = []; });
}
function renderListView(v){
  let name, list, cover, kind = v.kind, note = '', extraBtn = '';
  if(kind === 'offline'){ name = 'На устройстве'; list = offlineTracks(); cover = `<div class="m-genre-cover" style="--g1:#11998E;--g2:#38EF7D;">📱</div>`;
    note = `<div class="m-note m-glass">Скачанные треки и ваши файлы — всё играет без интернета. <span id="m-storage-line"></span></div>`;
    extraBtn = `<button type="button" class="ghost m-glass" data-act="addfiles" style="flex:0 0 auto;padding:0 14px;">+ Файлы</button>`;
    storageLine().then(t=>{ const el = document.getElementById('m-storage-line'); if(el) el.textContent = t; }); }
  else if(kind === 'dl'){ name = 'Скачанные'; list = music.downloads; cover = `<div class="m-genre-cover" style="--g1:#11998E;--g2:#38EF7D;">⬇️</div>`;
    note = '';
    storageLine().then(t=>{ const el = document.getElementById('m-storage-line'); if(el) el.textContent = t; }); }
  else if(kind === 'fav'){ name = 'Избранное'; list = music.lib.favorites; cover = `<div class="m-genre-cover" style="--g1:#6F8BFF;--g2:#C150D6;">❤️</div>`; }
  else if(kind === 'local'){ name = 'На этом устройстве'; list = music.local; cover = `<div class="m-genre-cover" style="--g1:#2FB8A8;--g2:#3A7BD5;">📱</div>`;
    note = '';
    extraBtn = `<button type="button" class="ghost m-glass" data-act="addfiles" style="flex:0 0 auto;padding:0 14px;">+ Файлы</button>`; }
  else if(kind === 'pl'){ const pl = music.lib.playlists.find(p=> p.id === v.id); if(!pl){ music.view = null; return renderMusic(); }
    name = pl.name; list = pl.tracks; cover = coverHtml(pl); extraBtn = `<button type="button" class="ghost m-glass" data-act="plmenu" style="flex:0 0 44px;">${MI.more}</button>`; }
  else if(kind === 'genre' || kind === 'trending'){
    const g = GENRES.find(x=> x.g === v.genre);
    name = kind === 'trending' ? 'В тренде за неделю' : (g ? g.n : v.genre);
    cover = `<div class="m-genre-cover" style="--g1:${g ? g.c[0] : '#FF7A18'};--g2:${g ? g.c[1] : '#FF3D71'};">${g ? g.e : '🔥'}</div>`;
    list = music.cache['tr:' + (v.genre || '') + ':week'];
    if(!list){ setMusicBody(`<button type="button" class="m-back" data-act="back">${MI.back}Назад</button><div class="m-loading"><span class="ai-spinner" style="width:26px;height:26px;"></span></div>`);
      audiusTrending(v.genre || '', 'week').then(renderMusic).catch(()=> setMusicBody(`<button type="button" class="m-back" data-act="back">${MI.back}Назад</button>` + errBox())); return; }
  }
  const backTo = music.subtab === 'mix' ? 'Микс' : music.subtab === 'radio' ? 'Радио' : 'Моя музыка';
  const numbered = kind === 'genre' || kind === 'trending';
  setMusicBody(`<button type="button" class="m-back" data-act="back">${MI.back}${backTo}</button>
    <div class="m-pl-head">${cover}<div style="min-width:0;"><h2>${escapeHtml(name)}</h2><div class="cnt">${countTxt(list.length)}</div></div></div>
    <div class="m-actions"><button type="button" class="primary" data-act="playall">${MI.play}Слушать</button><button type="button" class="ghost m-glass" data-act="shuffleall">${MI.shuffle}Перемешать</button>${extraBtn}${kind !== 'dl' && kind !== 'local' && list.some(t=> t.src === 'audius') ? `<button type="button" class="ghost m-glass" data-act="dl-all" title="Скачать всё для офлайна" style="flex:0 0 44px;">⬇</button>` : ''}</div>
    ${(kind === 'dl' || kind === 'local' || kind === 'offline') && list.length ? `<div class="m-sel-bar">
        <button type="button" class="m-dev-btn" data-act="selmode">${music.selMode ? 'Отменить выбор' : 'Выбрать'}</button>
        ${music.selMode ? `<button type="button" class="m-dev-btn danger" data-act="delsel">Удалить выбранные (${music.sel.size})</button>` : ''}
        <button type="button" class="m-dev-btn danger" data-act="delall">Удалить все</button>
      </div>` : ''}
    ${note}${list.length ? rowsHtml('view', list, numbered) : `<div class="m-empty m-glass"><b>Пока пусто</b>${kind === 'fav' ? 'Нажмите ♡ у любого трека' : kind === 'local' ? 'Добавьте треки кнопкой «+ Файлы»' : 'Добавляйте треки через ⋯ → «Добавить в плейлист»'}</div>`}`);
}
function viewName(){
  const v = music.view;
  if(!v) return music.subtab === 'radio' ? 'Радио' : music.subtab === 'mine' ? 'Моя музыка' : 'Микс';
  if(v.kind === 'offline') return 'На устройстве';
  if(v.kind === 'dl') return 'Скачанные';
  if(v.kind === 'fav') return 'Избранное';
  if(v.kind === 'local') return 'На этом устройстве';
  if(v.kind === 'pl'){ const pl = music.lib.playlists.find(p=> p.id === v.id); return pl ? pl.name : 'Плейлист'; }
  if(v.kind === 'trending') return 'В тренде';
  const g = GENRES.find(x=> x.g === v.genre); return g ? g.n : 'Жанр';
}

/* ---------- гироскоп: шар микса следует за наклоном телефона (как в VK Музыке) ---------- */
let gyroBound = false, gyroAsked = false;
function applyTilt(x, y){
  const hero = document.getElementById('m-hero'); if(!hero) return;
  hero.style.setProperty('--tx', (x * 18).toFixed(1) + 'px');
  hero.style.setProperty('--ty', (y * 14).toFixed(1) + 'px');
}
function bindHeroGyro(){
  if(gyroBound) return;
  gyroBound = true;
  window.addEventListener('deviceorientation', (e)=>{
    if(state.activeTab !== 'music' || e.gamma == null) return;
    applyTilt(Math.max(-1, Math.min(1, e.gamma / 30)), Math.max(-1, Math.min(1, ((e.beta || 45) - 45) / 30)));
  });
  document.getElementById('music-body').addEventListener('pointermove', (e)=>{
    const hero = e.target.closest && e.target.closest('#m-hero'); if(!hero || e.pointerType !== 'mouse') return;
    const r = hero.getBoundingClientRect();
    applyTilt((e.clientX - r.left) / r.width * 2 - 1, (e.clientY - r.top) / r.height * 2 - 1);
  });
}
function askGyroPermission(){
  if(gyroAsked) return; gyroAsked = true;
  try{ if(window.DeviceOrientationEvent && typeof DeviceOrientationEvent.requestPermission === 'function') DeviceOrientationEvent.requestPermission().catch(()=>{}); }catch(e){}
}

/* ---------- действия во вкладке ---------- */
document.getElementById('music-subtabs').addEventListener('click', (e)=>{
  const b = e.target.closest('[data-msubtab]'); if(!b) return;
  music.subtab = b.dataset.msubtab; music.view = null;
  document.querySelectorAll('#music-subtabs .subtab-btn').forEach(x=> x.classList.toggle('active', x === b));
  document.getElementById('music-search').value = '';
  renderMusic(); document.getElementById('music-body').scrollTop = 0;
});
function setSubtab(name){ const b = document.querySelector(`#music-subtabs [data-msubtab="${name}"]`); if(b) b.click(); }
let musicSearchTimer = null;
document.getElementById('music-search').addEventListener('input', ()=>{ clearTimeout(musicSearchTimer); musicSearchTimer = setTimeout(renderMusic, 450); });
document.getElementById('music-body').addEventListener('click', (e)=>{
  const act = e.target.closest('[data-act]');
  const a = act && act.dataset.act;
  if(a === 'mix-play'){
    askGyroPermission();
    if(String(music.contextKind).startsWith('mix') && music.track){ musicToggle(); renderMusic(); } else playMix(music.mood);
    return;
  }
  if(a === 'mood'){ const id = act.dataset.mood; if(id === music.mood && String(music.contextKind).startsWith('mix')){ musicToggle(); return; } playMix(id); return; }
  if(a === 'back'){ music.view = null; renderMusic(); return; }
  if(a === 'play-fav'){ e.stopPropagation(); if(music.lib.favorites.length) playQueue(music.lib.favorites, 0, 'Избранное', 'fav'); return; }
  if(a === 'open-fav'){ music.view = {kind: 'fav'}; renderMusic(); return; }
  if(a === 'open-local'){ music.view = {kind: 'local'}; renderMusic(); return; }
  if(a === 'open-dl'){ music.view = {kind: 'dl'}; renderMusic(); return; }
  if(a === 'open-offline'){ music.view = {kind: 'offline'}; renderMusic(); return; }
  if(a === 'dl-all'){ downloadMany(music.lists.view || []); return; }
  if(a === 'radiocat'){ music.radioCat = act.dataset.cat; renderMusic(); return; }
  if(a === 'recheck'){ audiusReachable(true).then(()=>{ music.cache = {}; renderMusic(); }); return; }
  if(a === 'open-pl'){ if(music.subtab !== 'mine') setSubtab('mine'); music.view = {kind: 'pl', id: act.dataset.pl}; renderMusic(); return; }
  if(a === 'open-mine'){ setSubtab('mine'); return; }
  if(a === 'open-radio'){ setSubtab('radio'); return; }
  if(a === 'open-trending'){ music.view = {kind: 'trending', genre: ''}; renderMusic(); return; }
  if(a === 'genre'){ music.view = {kind: 'genre', genre: act.dataset.genre}; renderMusic(); document.getElementById('music-body').scrollTop = 0; return; }
  if(a === 'radiotag'){ music.radioTag = act.dataset.tag; renderMusic(); return; }
  if(a === 'new-pl'){ promptPlaylistName('Новый плейлист', '', (name)=>{ const pl = createPlaylist(name); music.view = {kind: 'pl', id: pl.id}; renderMusic(); }); return; }
  if(a === 'addfiles'){ document.getElementById('music-file-input').click(); return; }
  if(a === 'retry'){ music.cache = {}; renderMusic(); return; }
  if(a === 'playall' || a === 'shuffleall'){
    const list = music.lists.view || []; if(!list.length) return;
    music.shuffle = a === 'shuffleall';
    playQueue(list, music.shuffle ? Math.floor(Math.random() * list.length) : 0, viewName(), music.view ? music.view.kind : '');
    return;
  }
  if(a === 'plmenu'){
    const pl = music.lib.playlists.find(p=> music.view && p.id === music.view.id); if(!pl) return;
    openRowMenu(act, [
      {label: 'Переименовать', icon: RM_ICON.select, action: ()=> promptPlaylistName('Переименовать', pl.name, (name)=>{ pl.name = name; saveLib(); renderMusic(); })},
      {label: 'Отправить в чат', icon: RM_ICON.chat, action: ()=> shareTracksToChat(pl.tracks.filter(t=> t.src !== 'local').slice(0, 1), pl.name)},
      {label: 'Удалить плейлист', icon: RM_ICON.trash, danger: true, action: async ()=>{ if(!await uiConfirm(`Удалить плейлист «${pl.name}»?`)) return; music.lib.playlists = music.lib.playlists.filter(p=> p !== pl); music.view = null; saveLib(); renderMusic(); }},
    ]);
    return;
  }
  const item = e.target.closest('[data-list][data-i]');
  if(!item) return;
  const list = music.lists[item.dataset.list] || [];
  const i = +item.dataset.i, t = list[i];
  if(!t) return;
  if(a === 'fav'){ e.stopPropagation(); toggleFav(t); return; }
  if(a === 'more'){ e.stopPropagation(); openTrackMenu(item, t); return; }
  if(isCur(t)){ if(item.classList.contains('m-card') || item.classList.contains('m-tile')) musicToggle(); else openFullPlayer(); return; }
  const ctx = {recent: 'Недавно', trending: 'В тренде', radiotop: 'Радио', radio: 'Радио', local: 'На этом устройстве', 's-mine': 'Поиск', 's-tracks': 'Поиск', 's-radio': 'Поиск'}[item.dataset.list] || viewName();
  playQueue(list, i, ctx, item.dataset.list);
});
function openTrackMenu(anchor, t){
  const heart = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 20.5s-8-4.9-8-10.7A4.5 4.5 0 0 1 12 7a4.5 4.5 0 0 1 8 2.8c0 5.8-8 10.7-8 10.7z"/></svg>';
  const nextIco = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><line x1="4" y1="7" x2="14" y2="7"/><line x1="4" y1="12" x2="14" y2="12"/><path d="M17 10v8l4-4z" fill="currentColor"/><line x1="4" y1="17" x2="10" y2="17"/></svg>`;
  const items = [];
  if(t.src !== 'radio' && music.track){
    items.push({label: 'Играть следующим', icon: nextIco, action: ()=> queueInsert(t, true)});
    items.push({label: 'В конец очереди', icon: nextIco, action: ()=> queueInsert(t, false)});
  }
  items.push({label: isFav(t) ? 'Убрать из избранного' : 'В избранное', icon: heart, action: ()=> toggleFav(t)});
  items.push({label: 'Добавить в плейлист', icon: RM_ICON.select, action: ()=> openAddToPlaylist(t)});
  if(t.src !== 'local') items.push({label: 'Отправить в чат', icon: RM_ICON.chat, action: ()=> shareTracksToChat([t])});
  if(t.src === 'audius' && t.artist) items.push({label: 'Ещё от ' + t.artist.slice(0, 24), icon: RM_ICON.users, action: ()=>{ const s = document.getElementById('music-search'); s.value = t.artist; renderMusic(); }});
  const v = music.view;
  if(v && v.kind === 'pl'){
    const pl = music.lib.playlists.find(p=> p.id === v.id);
    const idx = pl ? pl.tracks.findIndex(x=> trackKey(x) === trackKey(t)) : -1;
    if(pl && idx > 0) items.push({label: 'Выше', icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 15 12 9 18 15"/></svg>', action: ()=>{ [pl.tracks[idx - 1], pl.tracks[idx]] = [pl.tracks[idx], pl.tracks[idx - 1]]; saveLib(); renderMusic(); }});
    if(pl && idx >= 0 && idx < pl.tracks.length - 1) items.push({label: 'Ниже', icon: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="6 9 12 15 18 9"/></svg>', action: ()=>{ [pl.tracks[idx + 1], pl.tracks[idx]] = [pl.tracks[idx], pl.tracks[idx + 1]]; saveLib(); renderMusic(); }});
    if(pl) items.push({label: 'Убрать из плейлиста', icon: RM_ICON.trash, danger: true, action: ()=>{ pl.tracks = pl.tracks.filter(x=> trackKey(x) !== trackKey(t)); saveLib(); renderMusic(); }});
  }
  if(t.src === 'audius'){
    const dlIco = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v11"/><polyline points="7 10 12 15 17 10"/><path d="M5 20h14"/></svg>';
    if(isDownloaded(t)) items.push({label: 'Удалить загрузку', icon: dlIco, danger: true, action: ()=> removeDownload(t)});
    else items.push({label: 'Скачать для офлайна', icon: dlIco, action: ()=> downloadTrack(t)});
  }
  if(t.src === 'local') items.push({label: 'Удалить с устройства', icon: RM_ICON.trash, danger: true, action: async ()=>{
    if(!await uiConfirm('Удалить этот файл из памяти браузера?')) return;
    try{ await idbTx('readwrite', st=> st.delete(t.id)); }catch(e){}
    if(music.localUrls[t.id]){ URL.revokeObjectURL(music.localUrls[t.id]); delete music.localUrls[t.id]; }
    await loadLocalFiles(); renderMusic();
  }});
  openRowMenu(anchor, items);
}

/* ---------- очередь ---------- */
function queueInsert(t, next){
  const k = trackKey(t);
  const at = music.queue.findIndex((x, i)=> i > music.qi && trackKey(x) === k);
  if(at >= 0) music.queue.splice(at, 1);
  if(next) music.queue.splice(music.qi + 1, 0, slim(t)); else music.queue.push(slim(t));
  toast(next ? 'Заиграет следующим' : 'Добавлено в конец очереди');
}
function openQueueSheet(){
  const render = ()=>{
    const q = music.queue;
    const after = q.slice(music.qi + 1);
    const row = (t, i)=> `<div class="music-sheet-row ${i === music.qi ? 'current' : ''}" data-qi="${i}">${artHtml(t)}<div style="flex:1;min-width:0;"><div class="m-title">${escapeHtml(t.title)}</div><div class="m-sub">${escapeHtml(t.artist || '')}</div></div>${i !== music.qi ? `<button type="button" class="x" data-qdel="${i}" aria-label="Убрать">${MI.x}</button>` : ''}</div>`;
    return (music.track ? '<div class="m-sheet-sub">Сейчас играет</div>' + row(q[music.qi], music.qi) : '')
      + (after.length ? `<div class="m-sheet-sub">Далее · ${after.length}</div>` + after.slice(0, 60).map((t, j)=> row(t, music.qi + 1 + j)).join('') : '<div class="story-aud-empty">Очередь пуста</div>')
      + (music.contextKind === 'mix' ? '<div class="story-aud-empty">Микс пополняется новыми треками сам</div>' : '');
  };
  openMusicSheet('Очередь', render(), (body)=>{
    body.onclick = (e)=>{
      const del = e.target.closest('[data-qdel]');
      if(del){ e.stopPropagation(); music.queue.splice(+del.dataset.qdel, 1); body.innerHTML = render(); return; }
      const r = e.target.closest('[data-qi]'); if(!r) return;
      const i = +r.dataset.qi; if(i === music.qi) return;
      music.qi = i; loadCurrent(true); body.innerHTML = render();
    };
  });
}

/* ---------- таймер сна ---------- */
function setSleep(mode, minutes){
  if(music.sleep && music.sleep.timer) clearTimeout(music.sleep.timer);
  if(music.sleep && music.sleep.tick) clearInterval(music.sleep.tick);
  music.sleep = null;
  if(mode === 'off'){ syncPlayerUi(); toast('Таймер сна выключен'); return; }
  if(mode === 'track'){ music.sleep = {mode: 'track'}; syncPlayerUi(); toast('Остановится после этого трека'); return; }
  const until = Date.now() + minutes * 60000;
  music.sleep = {mode: 'time', until};
  music.sleep.timer = setTimeout(sleepFadeOut, minutes * 60000 - 8000);
  music.sleep.tick = setInterval(syncPlayerUi, 20000);
  syncPlayerUi(); toast(`Музыка выключится через ${minutes} мин`);
}
function sleepFadeOut(){
  const start = musicAudio.volume || 1;
  let step = 0;
  const iv = setInterval(()=>{
    step++; musicAudio.volume = Math.max(0, start * (1 - step / 16));
    if(step >= 16){ clearInterval(iv); musicAudio.pause(); musicAudio.volume = start; if(music.sleep && music.sleep.tick) clearInterval(music.sleep.tick); music.sleep = null; syncPlayerUi(); }
  }, 500);
}
function openSleepSheet(){
  const opts = [[15, '15 минут'], [30, '30 минут'], [45, '45 минут'], [60, '1 час'], [90, '1,5 часа']];
  openMusicSheet('Таймер сна', opts.map(([m, n])=> `<div class="music-sheet-row" data-sleep="${m}">🌙 ${n}</div>`).join('')
    + `<div class="music-sheet-row" data-sleep="track">🎵 До конца трека</div>` + (music.sleep ? `<div class="music-sheet-row" data-sleep="off" style="color:var(--danger);">Выключить таймер</div>` : ''), (body)=>{
    body.onclick = (e)=>{ const r = e.target.closest('[data-sleep]'); if(!r) return; closeMusicSheet();
      const v = r.dataset.sleep; if(v === 'off') setSleep('off'); else if(v === 'track') setSleep('track'); else setSleep('time', +v); };
  });
}

/* ---------- поделиться треком в чате (как в VK) ---------- */
function shareTracksToChat(tracks, title){
  const list = (tracks || []).filter(t=> t && t.src !== 'local');
  if(!list.length){ toast('Файлы с устройства нельзя отправить — их нет на сервере'); return; }
  const t = list[0];
  openChatPicker(title ? 'Отправить: ' + title : 'Отправить трек', async (chatIds)=>{
    let ok = 0;
    for(const chatId of chatIds){
      try{ await sendMessage(chatId, 'text', `🎵 ${t.title}${t.artist ? ' — ' + t.artist : ''}`, null, {music: slim(t)}); ok++; }catch(e){}
    }
    toast(ok ? 'Трек отправлен' : 'Не удалось отправить');
  });
}
function applyMusicCards(){
  const box = document.getElementById('messages');
  if(!box || !state.currentMessages) return;
  box.querySelectorAll('.msg-row[data-id]').forEach(row=>{
    const m = state.currentMessages.find(x=> x.id === row.dataset.id);
    if(!m || !m.music || !m.music.src) return;
    const bubble = row.querySelector('.bubble'); if(!bubble) return;
    const t = m.music;
    const cur = isCur(t) && !musicAudio.paused;
    let card = bubble.querySelector('.msg-music');
    if(!card){
      const time = bubble.querySelector(':scope > .time');
      bubble.classList.add('music-bubble');
      Array.from(bubble.childNodes).forEach(n=>{ if(n !== time && !(n.classList && (n.classList.contains('reply-quote') || n.classList.contains('ai-block')))) n.remove(); });
      card = document.createElement('div'); card.className = 'msg-music'; card.dataset.musicMsg = m.id;
      bubble.insertBefore(card, time || null);
    }
    card.innerHTML = `<div class="cv">${artInner(t)}<span class="pp">${cur ? MI.pause : MI.play}</span></div><div class="tx"><div class="tt">${escapeHtml(t.title)}</div><div class="ar">${escapeHtml(t.artist || '')}</div>
      <div class="src">${t.src === 'radio' ? '📻 Радио' : '🎵 Музыка'}</div></div>`;
  });
}
new MutationObserver(()=>{ try{ applyMusicCards(); }catch(e){} }).observe(document.getElementById('messages'), {childList: true});
document.getElementById('messages').addEventListener('click', (e)=>{
  const card = e.target.closest('.msg-music'); if(!card) return;
  e.stopPropagation();
  const m = (state.currentMessages || []).find(x=> x.id === card.dataset.musicMsg);
  if(!m || !m.music) return;
  if(isCur(m.music)){ musicToggle(); return; }
  playQueue([m.music], 0, 'Из чата', 'chat');
});

/* ---------- плеер ---------- */
async function streamUrlFor(t){
  if(t && t.src === 'radio' && t.alts && t.alts.length){ const u = await pickStationUrl(t); if(u) return u; }
  if(t && t.src === 'audius' && typeof isDownloaded === 'function' && isDownloaded(t)){ const u = await downloadedUrl(t); if(u) return u; }
  if(t.src === 'audius') return `${audiusBase}/tracks/${encodeURIComponent(t.id)}/stream?${audiusQs()}`;
  if(t.src === 'radio') return t.url;
  if(t.src === 'local') return await localUrl(t.id);
  return null;
}
async function playQueue(list, index, contextName, contextKind){
  music.queue = list.map(slim);
  music.qi = Math.max(0, Math.min(index, music.queue.length - 1));
  music.contextName = contextName || '';
  music.contextKind = contextKind || '';
  await loadCurrent(true);
}
let lastArtDir = '';
async function loadCurrent(autoplay){
  const t = music.queue[music.qi];
  if(!t) return;
  music.track = t;
  const url = await streamUrlFor(t);
  if(!url){ toast('Этот трек сохранён на другом устройстве'); return musicNext(true); }
  musicAudio.src = url;
  if(autoplay){ try{ await musicAudio.play(); }catch(e){ if(e && e.name !== 'AbortError') toast('Не удалось включить: нажмите ▶ ещё раз'); } }
  historyPush(t);
  updateMediaSession(); syncPlayerUi(); renderMusic(); applyMusicCards();
  refillMixIfNeeded();
  const art = document.getElementById('mpl-art');
  if(lastArtDir){ art.classList.remove('slide-l', 'slide-r'); void art.offsetWidth; art.classList.add(lastArtDir); lastArtDir = ''; }
}
function musicToggle(){
  if(!music.track) return;
  if(musicAudio.paused){ musicAudio.play().catch(()=>{}); music.pausedByCall = false; } else musicAudio.pause();
}
function nextIndex(){
  if(!music.queue.length) return -1;
  if(music.shuffle && music.queue.length > 1){ let n; do{ n = Math.floor(Math.random() * music.queue.length); }while(n === music.qi); return n; }
  if(music.qi < music.queue.length - 1) return music.qi + 1;
  return music.repeat === 'all' ? 0 : -1;
}
async function musicNext(auto){
  if(music.track && music.track.src === 'radio' && music.queue.length <= 1) return;
  if(music.contextKind === 'mix') await refillMixIfNeeded();
  const n = nextIndex();
  if(n < 0){ if(auto){ musicAudio.pause(); musicAudio.currentTime = 0; syncPlayerUi(); } return; }
  lastArtDir = 'slide-l'; music.qi = n; loadCurrent(true);
}
function musicPrev(){
  if(musicAudio.currentTime > 3 && music.track && music.track.src !== 'radio'){ musicAudio.currentTime = 0; return; }
  if(music.qi > 0){ lastArtDir = 'slide-r'; music.qi--; loadCurrent(true); } else musicAudio.currentTime = 0;
}
musicAudio.addEventListener('ended', ()=>{
  if(music.sleep && music.sleep.mode === 'track'){ music.sleep = null; syncPlayerUi(); toast('Таймер сна: музыка остановлена'); return; }
  if(music.repeat === 'one'){ musicAudio.currentTime = 0; musicAudio.play().catch(()=>{}); return; }
  musicNext(true);
});
let musicErrorCount = 0;
musicAudio.addEventListener('error', ()=>{
  if(!music.track || !musicAudio.src) return;
  toast(music.track.src === 'radio' ? 'Станция сейчас не отвечает' : 'Трек недоступен — включаю следующий');
  if(music.track.src !== 'radio' && ++musicErrorCount < 4) setTimeout(()=> musicNext(true), 900);
});
musicAudio.addEventListener('playing', ()=>{ musicErrorCount = 0; });
['play','pause','playing'].forEach(ev=> musicAudio.addEventListener(ev, ()=>{
  syncPlayerUi();
  if('mediaSession' in navigator) navigator.mediaSession.playbackState = musicAudio.paused ? 'paused' : 'playing';
  document.querySelectorAll('#music-body .m-eq').forEach(q=> q.classList.toggle('paused', musicAudio.paused));
  document.querySelectorAll('#music-body .m-card.playing .pp').forEach(pp=> pp.innerHTML = musicAudio.paused ? MI.play : MI.pause);
  const hero = document.getElementById('m-hero');
  if(hero){ const on = String(music.contextKind).startsWith('mix') && !musicAudio.paused; hero.classList.toggle('playing', on); const hb = hero.querySelector('.m-hero-play'); if(hb && !music.mixLoading) hb.innerHTML = on ? MI.pause : MI.play; }
  applyMusicCards();
}));
let lastPosUpdate = 0, seekDragging = false;
musicAudio.addEventListener('timeupdate', ()=>{
  const d = musicAudio.duration, c = musicAudio.currentTime;
  const frac = isFinite(d) && d > 0 ? c / d : 0;
  document.getElementById('mp-progress').style.width = (music.track && music.track.src === 'radio' ? 100 : frac * 100) + '%';
  if(!seekDragging && document.getElementById('music-player').style.display !== 'none'){
    const seek = document.getElementById('mpl-seek');
    seek.value = Math.round(frac * 1000); seek.style.setProperty('--p', (frac * 100) + '%');
    document.getElementById('mpl-cur').textContent = musicTime(c);
    document.getElementById('mpl-dur').textContent = isFinite(d) ? musicTime(d) : musicTime(music.track && music.track.dur);
  }
  if('mediaSession' in navigator && navigator.mediaSession.setPositionState && isFinite(d) && d > 0 && Date.now() - lastPosUpdate > 1000){
    lastPosUpdate = Date.now();
    try{ navigator.mediaSession.setPositionState({duration: d, playbackRate: musicAudio.playbackRate || 1, position: Math.min(c, d)}); }catch(e){}
  }
});

/* ---------- экран блокировки / наушники / часы ---------- */
function updateMediaSession(){
  if(!('mediaSession' in navigator) || !music.track) return;
  const t = music.track;
  const artwork = t.art ? [{src: t.art, sizes: '480x480', type: 'image/jpeg'}] : [{src: 'icon-512.png', sizes: '512x512', type: 'image/png'}];
  try{ navigator.mediaSession.metadata = new MediaMetadata({title: t.title, artist: t.artist || (t.src === 'radio' ? 'Радио' : ''), album: music.contextName || APP_NAME, artwork}); }catch(e){}
  const set = (a, fn)=>{ try{ navigator.mediaSession.setActionHandler(a, fn); }catch(e){} };
  const live = t.src === 'radio';
  set('play', ()=> musicAudio.play().catch(()=>{}));
  set('pause', ()=> musicAudio.pause());
  set('stop', ()=> musicAudio.pause());
  set('previoustrack', live ? null : ()=> musicPrev());
  set('nexttrack', (live && music.queue.length <= 1) ? null : ()=> musicNext());
  set('seekto', live ? null : (d)=>{ if(d && isFinite(d.seekTime)) musicAudio.currentTime = d.seekTime; });
  set('seekbackward', live ? null : (d)=>{ musicAudio.currentTime = Math.max(0, musicAudio.currentTime - ((d && d.seekOffset) || 10)); });
  set('seekforward', live ? null : (d)=>{ musicAudio.currentTime = Math.min(musicAudio.duration || 0, musicAudio.currentTime + ((d && d.seekOffset) || 10)); });
}

/* ---------- мини-плеер, полный плеер, «живой» фон ---------- */
function cssUrl(u){ return u ? `url("${String(u).replace(/"/g, '%22')}")` : ''; }
function syncPlayerUi(){
  const t = music.track;
  const mini = document.getElementById('mini-player');
  const tabs = document.querySelector('.tabs-content');
  const amb = document.getElementById('music-ambient-art');
  if(!t){ mini.style.display = 'none'; tabs.classList.remove('with-mini'); document.body.classList.remove('with-mini-toast'); amb.classList.remove('on'); return; }
  mini.style.display = 'flex'; tabs.classList.add('with-mini'); document.body.classList.add('with-mini-toast');
  document.getElementById('mp-art').innerHTML = artInner(t);
  document.getElementById('mp-bgart').style.backgroundImage = cssUrl(t.art);
  amb.style.backgroundImage = cssUrl(t.art); amb.classList.toggle('on', !!t.art);
  document.getElementById('mp-title').textContent = t.title;
  document.getElementById('mp-artist').textContent = t.src === 'radio' ? '● Прямой эфир' : (t.artist || '');
  const playIcon = musicAudio.paused ? MI.play : MI.pause;
  document.getElementById('mp-play').innerHTML = playIcon;
  document.getElementById('mp-next').style.display = (t.src === 'radio' && music.queue.length <= 1) ? 'none' : 'flex';
  const pl = document.getElementById('music-player');
  pl.classList.toggle('paused', musicAudio.paused);
  pl.classList.toggle('radio', t.src === 'radio');
  document.getElementById('mpl-play').innerHTML = playIcon;
  document.getElementById('mpl-title').textContent = t.title;
  document.getElementById('mpl-artist').textContent = t.artist || (t.src === 'radio' ? 'Радиостанция' : '');
  document.getElementById('mpl-context').textContent = music.contextName || 'Музыка';
  const art = document.getElementById('mpl-art');
  const artHtmlNow = artInner(t);
  if(art.dataset.key !== trackKey(t)){ art.innerHTML = artHtmlNow; art.dataset.key = trackKey(t); }
  const bg = t.art ? cssUrl(t.art) : 'linear-gradient(135deg,#3a2f7a,#7b3f8f)';
  document.getElementById('mpl-bg-a').style.backgroundImage = bg;
  document.getElementById('mpl-bg-b').style.backgroundImage = bg;
  document.getElementById('mpl-heart').classList.toggle('on', isFav(t));
  document.getElementById('mpl-shuffle').classList.toggle('on', music.shuffle);
  const rp = document.getElementById('mpl-repeat');
  rp.classList.toggle('on', music.repeat !== 'off'); rp.classList.toggle('one', music.repeat === 'one');
  const sl = document.getElementById('mpl-sleep');
  sl.classList.toggle('on', !!music.sleep);
  document.getElementById('mpl-sleep-label').textContent = !music.sleep ? 'Таймер' : music.sleep.mode === 'track' ? 'После трека' : Math.max(1, Math.ceil((music.sleep.until - Date.now()) / 60000)) + ' мин';
  document.getElementById('mpl-share').style.opacity = t.src === 'local' ? '.35' : '';
}
function openFullPlayer(){ if(!music.track) return; document.getElementById('music-player').style.display = 'block'; syncPlayerUi(); musicAudio.dispatchEvent(new Event('timeupdate')); }
function closeFullPlayer(){ document.getElementById('music-player').style.display = 'none'; }
function closeMusic(){
  musicAudio.pause(); musicAudio.removeAttribute('src'); musicAudio.load();
  music.track = null; music.queue = []; music.contextKind = ''; syncPlayerUi(); renderMusic();
  if('mediaSession' in navigator){ try{ navigator.mediaSession.metadata = null; navigator.mediaSession.playbackState = 'none'; }catch(err){} }
}
(function miniPlayerGestures(){
  const mini = document.getElementById('mini-player');
  const info = mini.querySelector('.mp-info');
  let g = null;
  mini.addEventListener('touchstart', (e)=>{ if(e.target.closest('button')) return; const t = e.touches[0]; g = {x: t.clientX, y: t.clientY, dx: 0, dy: 0}; info.style.transition = 'none'; }, {passive: true});
  mini.addEventListener('touchmove', (e)=>{ if(!g) return; const t = e.touches[0]; g.dx = t.clientX - g.x; g.dy = t.clientY - g.y;
    if(Math.abs(g.dx) > Math.abs(g.dy)){ info.style.transform = `translateX(${g.dx * 0.6}px)`; info.style.opacity = String(1 - Math.min(0.7, Math.abs(g.dx) / 200)); } }, {passive: true});
  mini.addEventListener('touchend', ()=>{
    if(!g) return; const {dx, dy} = g; g = null;
    info.style.transition = ''; info.style.transform = ''; info.style.opacity = '';
    if(dy < -40 && Math.abs(dy) > Math.abs(dx)){ openFullPlayer(); return; }
    if(Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy)){ mini.dataset.swiped = '1'; setTimeout(()=> delete mini.dataset.swiped, 400); if(dx < 0) musicNext(); else musicPrev(); }
  });
  mini.addEventListener('click', (e)=>{
    if(mini.dataset.swiped) return;
    if(e.target.closest('#mp-play')){ e.stopPropagation(); musicToggle(); return; }
    if(e.target.closest('#mp-next')){ e.stopPropagation(); musicNext(); return; }
    if(e.target.closest('#mp-close')){ e.stopPropagation(); closeMusic(); return; }
    openFullPlayer();
  });
})();
(function playerGestures(){
  const inner = document.getElementById('mpl-inner');
  const artWrap = inner.querySelector('.mpl-art-wrap');
  let g = null;
  inner.addEventListener('touchstart', (e)=>{ if(e.target.closest('input, button')) return; const t = e.touches[0]; g = {x: t.clientX, y: t.clientY, dx: 0, dy: 0, onArt: !!e.target.closest('.mpl-art-wrap')}; inner.style.transition = 'none'; }, {passive: true});
  inner.addEventListener('touchmove', (e)=>{ if(!g) return; const t = e.touches[0]; g.dx = t.clientX - g.x; g.dy = t.clientY - g.y;
    if(g.dy > 0 && g.dy > Math.abs(g.dx)) inner.style.transform = `translateY(${g.dy}px)`;
    else if(g.onArt && Math.abs(g.dx) > Math.abs(g.dy)) document.getElementById('mpl-art').style.transform = `translateX(${g.dx * 0.5}px) rotate(${g.dx / 40}deg)`; }, {passive: true});
  inner.addEventListener('touchend', ()=>{
    if(!g) return; const {dx, dy, onArt} = g; g = null;
    inner.style.transition = ''; inner.style.transform = ''; document.getElementById('mpl-art').style.transform = '';
    if(dy > 120 && dy > Math.abs(dx)){ closeFullPlayer(); return; }
    if(onArt && Math.abs(dx) > 70 && Math.abs(dx) > Math.abs(dy)){ if(dx < 0) musicNext(); else musicPrev(); }
  });
})();
document.getElementById('mpl-close').onclick = closeFullPlayer;
document.getElementById('mpl-play').onclick = musicToggle;
document.getElementById('mpl-next').onclick = ()=> musicNext();
document.getElementById('mpl-prev').onclick = musicPrev;
document.getElementById('mpl-heart').onclick = ()=>{ if(music.track) toggleFav(music.track); };
document.getElementById('mpl-addlist').onclick = ()=>{ if(music.track) openAddToPlaylist(music.track); };
document.getElementById('mpl-queue').onclick = openQueueSheet;
document.getElementById('mpl-sleep').onclick = openSleepSheet;
document.getElementById('mpl-share').onclick = ()=>{ if(music.track) shareTracksToChat([music.track]); };
document.getElementById('mpl-more').onclick = (e)=>{ if(music.track) openTrackMenu(e.currentTarget, music.track); const ov = document.getElementById('row-menu-overlay'); if(ov){ ov.style.zIndex = '450'; const cl = ov.querySelector('.row-menu-clone'); if(cl) cl.style.visibility = 'hidden'; } };
document.getElementById('mpl-shuffle').onclick = ()=>{ music.shuffle = !music.shuffle; syncPlayerUi(); toast(music.shuffle ? 'Перемешивание включено' : 'Перемешивание выключено'); };
document.getElementById('mpl-repeat').onclick = ()=>{
  music.repeat = music.repeat === 'off' ? 'all' : music.repeat === 'all' ? 'one' : 'off';
  syncPlayerUi(); toast({off: 'Повтор выключен', all: 'Повтор всего списка', one: 'Повтор одного трека'}[music.repeat]);
};
const seekEl = document.getElementById('mpl-seek');
seekEl.addEventListener('input', ()=>{ seekDragging = true; seekEl.style.setProperty('--p', (seekEl.value / 10) + '%'); const d = musicAudio.duration; if(isFinite(d)) document.getElementById('mpl-cur').textContent = musicTime(d * seekEl.value / 1000); });
seekEl.addEventListener('change', ()=>{ const d = musicAudio.duration; if(isFinite(d) && d > 0) musicAudio.currentTime = d * seekEl.value / 1000; seekDragging = false; });
document.addEventListener('keydown', (e)=>{
  if(document.getElementById('music-player').style.display === 'none') return;
  if(e.key === 'Escape') closeFullPlayer();
  else if(e.key === ' ' && !e.target.closest('input, textarea')){ e.preventDefault(); musicToggle(); }
  else if(e.key === 'ArrowRight' && !e.target.closest('input')) musicNext();
  else if(e.key === 'ArrowLeft' && !e.target.closest('input')) musicPrev();
});

/* ---------- музыка уступает звонкам, голосовым и записи ---------- */
setInterval(()=>{
  const busy = !!state.activeCallState || (typeof recMediaRecorder !== 'undefined' && recMediaRecorder && recMediaRecorder.state === 'recording')
    || (typeof roundVideoRecorder !== 'undefined' && roundVideoRecorder && roundVideoRecorder.state === 'recording');
  if(busy && music.track && !musicAudio.paused){ musicAudio.pause(); music.pausedByCall = !!state.activeCallState; }
  else if(!busy && music.pausedByCall){ music.pausedByCall = false; musicAudio.play().catch(()=>{}); }
}, 700);
toggleVoicePlayback = (function(orig){ return function(...a){ if(music.track && !musicAudio.paused) musicAudio.pause(); return orig.apply(this, a); }; })(toggleVoicePlayback);
switchTab = (function(orig){
  return function(tab, ...rest){
    const r = orig.call(this, tab, ...rest);
    if(tab === 'music'){ loadLocalFiles().then(renderMusic); renderMusic(); }
    return r;
  };
})(switchTab);

/* каркас приложения никогда не должен прокручиваться вбок (браузер иногда делает это сам при фокусе на элементе за краем экрана) */
(function lockShellScroll(){
  const shell = document.querySelector('.app-shell');
  if(!shell) return;
  shell.addEventListener('scroll', ()=>{ if(shell.scrollLeft || shell.scrollTop) { shell.scrollLeft = 0; shell.scrollTop = 0; } }, {passive: true});
})();

/* ============================================================
   ROUND 13 — «островок» музыки (как Dynamic Island на iPhone)
============================================================ */
const island = document.getElementById('music-island');
const miState = {expanded: false, user: false, timer: null, lastKey: '', pressTimer: null, longPressed: false};
const MI_W = 200;
function islandBlocked(){
  return !music.track
    || document.getElementById('music-player').style.display !== 'none'
    || !!state.activeCallState
    || document.getElementById('story-viewer').style.display === 'flex'
    || document.getElementById('story-editor').style.display === 'flex'
    || document.getElementById('app-screen').style.display === 'none';
}
function islandAnchor(){
  const sb = document.querySelector('.sidebar').getBoundingClientRect();
  const mobile = window.innerWidth <= 780;
  const chatOpen = mobile && document.getElementById('chat-area').classList.contains('mobile-open');
  const cx = mobile ? window.innerWidth / 2 : sb.left + sb.width / 2;
  const wx = Math.min(370, (mobile ? window.innerWidth : sb.width) - 20);
  if(chatOpen){
    const hdr = document.querySelector('#active-chat-block .chat-header');
    const b = hdr ? hdr.getBoundingClientRect().bottom : 62;
    return {x: window.innerWidth / 2, y: b + 8, w: MI_W, wx, below: true};
  }
  const panel = document.querySelector('.tab-panel.active');
  const header = panel && Array.from(panel.querySelectorAll('.tab-header, .tab-header-static')).find(h=> h.offsetParent !== null);
  if(header){
    const hr = header.getBoundingClientRect();
    const brand = header.querySelector('.brand-text') || header.querySelector('.tab-title');
    const isl = header.querySelector('.header-island');
    const left = brand ? brand.getBoundingClientRect().right : hr.left;
    const right = (isl && isl.offsetParent !== null && isl.children.length) ? isl.getBoundingClientRect().left : hr.right - 14;
    const cy = brand ? (brand.getBoundingClientRect().top + brand.getBoundingClientRect().height / 2) : hr.top + hr.height / 2;
    const gap = right - left - 14;
    if(gap >= MI_W + 14){
      const w = MI_W;
      // как на iPhone: строго по центру экрана, если там свободно; иначе — по центру свободного места
      const x = (cx - w / 2 >= left + 7 && cx + w / 2 <= right - 7) ? cx : (left + right) / 2;
      return {x, y: cy - 17, w, wx, cx};
    }
    return {x: cx, y: hr.bottom + 6, w: MI_W, wx, cx, below: true};
  }
  return {x: cx, y: 12, w: MI_W, wx, cx};
}
function placeIsland(){
  if(islandBlocked()){ if(island.style.display !== 'none'){ island.style.display = 'none'; collapseIsland(); } return; }
  const a = islandAnchor();
  const expanded = island.classList.contains('expanded');
  island.style.setProperty('--mi-x', (expanded ? (a.cx || a.x) : a.x) + 'px');
  island.style.setProperty('--mi-y', Math.max(6, a.y) + 'px');
  island.style.setProperty('--mi-w', a.w + 'px');
  document.querySelector('.tabs-content').classList.toggle('mi-below', !!a.below && !island.classList.contains('expanded'));
  island.style.setProperty('--mi-wx', a.wx + 'px');
  if(island.style.display === 'none') island.style.display = 'block';
}
function islandFill(){
  const t = music.track; if(!t) return;
  const inner = artInner(t);
  const key = trackKey(t);
  if(miState.lastKey !== key){
    document.getElementById('mi-art').innerHTML = inner;
    document.getElementById('mi-art-big').innerHTML = inner;
    miState.lastKey = key;
  }
  document.getElementById('mi-title').textContent = t.title;
  document.getElementById('mi-artist').textContent = t.src === 'radio' ? '● Прямой эфир' : (t.artist || '');
  document.getElementById('mi-play').innerHTML = musicAudio.paused ? MI.play : MI.pause;
  document.getElementById('mi-ctitle').textContent = t.title;
  island.classList.toggle('paused', musicAudio.paused);
  island.classList.toggle('radio', t.src === 'radio');
  island.classList.toggle('single', t.src === 'radio' && music.queue.length <= 1);
}
function expandIsland(byUser, ms){
  if(islandBlocked()) return;
  miState.user = !!byUser;
  island.classList.add('expanded');
  placeIsland();
  clearTimeout(miState.timer);
  miState.timer = setTimeout(collapseIsland, ms || (byUser ? 6000 : 2800));
  if(navigator.vibrate && byUser) navigator.vibrate(8);
}
function collapseIsland(){
  clearTimeout(miState.timer);
  if(!island.classList.contains('expanded')) return;
  island.classList.remove('expanded');
  miState.user = false;
  placeIsland();
}
function touchIslandTimer(){ if(island.classList.contains('expanded')){ clearTimeout(miState.timer); miState.timer = setTimeout(collapseIsland, 6000); } }
island.addEventListener('click', (e)=>{
  if(miState.longPressed){ miState.longPressed = false; return; }
  if(!island.classList.contains('expanded')){ expandIsland(true); return; }
  touchIslandTimer();
  const b = e.target.closest('button');
  if(b){
    e.stopPropagation();
    if(b.id === 'mi-play') musicToggle();
    else if(b.id === 'mi-next') musicNext();
    else if(b.id === 'mi-prev') musicPrev();
    else if(b.id === 'mi-open'){ collapseIsland(); openFullPlayer(); }
    else if(b.id === 'mi-close'){ collapseIsland(); closeMusic(); }
    return;
  }
  if(e.target.closest('.mi-row')){ collapseIsland(); openFullPlayer(); }
});
// удержание компактного островка — сразу полный плеер; свайп вверх по развёрнутому — свернуть
(function islandTouch(){
  let y0 = null, x0 = null;
  island.addEventListener('pointerdown', (e)=>{
    y0 = e.clientY; x0 = e.clientX; miState.longPressed = false;
    if(!island.classList.contains('expanded')){
      clearTimeout(miState.pressTimer);
      miState.pressTimer = setTimeout(()=>{ miState.longPressed = true; haptic('buttons', 12); openFullPlayer(); }, 480);
    }
  });
  island.addEventListener('pointermove', (e)=>{ if(y0 !== null && (Math.abs(e.clientY - y0) > 8 || Math.abs(e.clientX - x0) > 8)) clearTimeout(miState.pressTimer); });
  const end = (e)=>{
    clearTimeout(miState.pressTimer);
    if(y0 === null) return;
    const dy = e.clientY - y0, dx = e.clientX - x0; y0 = null;
    if(island.classList.contains('expanded') && dy < -30 && Math.abs(dy) > Math.abs(dx)){ collapseIsland(); miState.longPressed = true; setTimeout(()=> miState.longPressed = false, 300); }
    else if(!island.classList.contains('expanded') && dy > 24 && Math.abs(dy) > Math.abs(dx)){ expandIsland(true); miState.longPressed = true; setTimeout(()=> miState.longPressed = false, 300); }
    else if(island.classList.contains('expanded') && Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) && !e.target.closest('button')){
      if(dx < 0) musicNext(); else musicPrev(); touchIslandTimer(); miState.longPressed = true; setTimeout(()=> miState.longPressed = false, 300);
    }
  };
  island.addEventListener('pointerup', end);
  island.addEventListener('pointercancel', ()=>{ clearTimeout(miState.pressTimer); y0 = null; });
})();
document.addEventListener('pointerdown', (e)=>{ if(island.classList.contains('expanded') && !island.contains(e.target)) collapseIsland(); }, true);

musicAudio.addEventListener('timeupdate', ()=>{
  if(!island.classList.contains('expanded')) return;
  const d = musicAudio.duration, c = musicAudio.currentTime;
  document.getElementById('mi-bar').style.width = (isFinite(d) && d > 0 ? c / d * 100 : 0) + '%';
  document.getElementById('mi-cur').textContent = musicTime(c);
  document.getElementById('mi-dur').textContent = isFinite(d) ? musicTime(d) : musicTime(music.track && music.track.dur);
});
['play','pause'].forEach(ev=> musicAudio.addEventListener(ev, islandFill));

/* интеграция с плеером */
syncPlayerUi = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    document.querySelector('.tabs-content').classList.remove('with-mini');
    document.body.classList.remove('with-mini-toast');
    if(music.track){ islandFill(); placeIsland(); } else { island.style.display = 'none'; collapseIsland(); }
    return r;
  };
})(syncPlayerUi);
loadCurrent = (function(orig){
  return async function(...a){
    const prev = music.track ? trackKey(music.track) : '';
    const r = await orig.apply(this, a);
    if(music.track && trackKey(music.track) !== prev && !miState.user && document.getElementById('music-player').style.display === 'none'){
      placeIsland(); if(island.style.display !== 'none') expandIsland(false, 2600);   // новый трек — островок «выглядывает»
    }
    return r;
  };
})(loadCurrent);
function setIslandClipVars(){
  const pl = document.getElementById('music-player');
  const a = islandAnchor();
  const w = a.w, h = 34, vw = window.innerWidth, vh = window.innerHeight;
  pl.style.setProperty('--it', Math.max(0, a.y) + 'px');
  pl.style.setProperty('--il', Math.max(0, a.x - w / 2) + 'px');
  pl.style.setProperty('--ir', Math.max(0, vw - (a.x + w / 2)) + 'px');
  pl.style.setProperty('--ib', Math.max(0, vh - (a.y + h)) + 'px');
}
openFullPlayer = (function(orig){
  return function(...a){
    if(!music.track) return;
    collapseIsland();
    setIslandClipVars();
    const pl = document.getElementById('music-player');
    pl.classList.remove('to-island'); pl.classList.add('from-island');
    const r = orig.apply(this, a);
    island.style.display = 'none';
    setTimeout(()=> pl.classList.remove('from-island'), 520);
    return r;
  };
})(openFullPlayer);
closeFullPlayer = (function(orig){
  return function(...a){
    const pl = document.getElementById('music-player');
    if(pl.style.display === 'none' || pl.classList.contains('to-island')) return orig.apply(this, a);
    if(!music.track) return orig.apply(this, a);
    setIslandClipVars();
    pl.classList.remove('from-island'); pl.classList.add('to-island');
    setTimeout(()=>{
      pl.classList.remove('to-island');
      orig.apply(this, a);
      placeIsland();
      island.classList.remove('bump'); void island.offsetWidth; island.classList.add('bump');
      setTimeout(()=> island.classList.remove('bump'), 520);
    }, 330);
  };
})(closeFullPlayer);
document.getElementById('mpl-close').onclick = ()=> closeFullPlayer();
switchTab = (function(orig){ return function(...a){ const r = orig.apply(this, a); requestAnimationFrame(placeIsland); return r; }; })(switchTab);
window.addEventListener('resize', ()=> placeIsland());
setInterval(()=>{ if(music.track) placeIsland(); }, 400);

