function stationTrack(st){ const t = {src: 'radio', id: 'rec_' + st.url.split('/').pop().replace(/[^a-z0-9]/gi, '_'), title: st.name, artist: st.sub, art: '', dur: 0, url: st.url, emoji: st.e}; if(st.alts) t.alts = st.alts; return t; }
