/* ---------- доступен ли каталог Audius (без VPN в России — обычно нет) ---------- */
let audiusCheck = {at: 0, ok: null, pending: null};
async function audiusReachable(force){
  if(!force && audiusCheck.ok !== null && Date.now() - audiusCheck.at < 5 * 60000) return audiusCheck.ok;
  if(audiusCheck.pending) return audiusCheck.pending;
  audiusCheck.pending = (async ()=>{
    const ctl = new AbortController();
    const t = setTimeout(()=> ctl.abort(), 6000);
    let ok = false;
    try{ const r = await fetch(audiusBase + '/tracks/trending?time=week&limit=1&' + audiusQs(), {signal: ctl.signal}); ok = r.ok; }catch(e){ ok = false; }
    clearTimeout(t);
    audiusCheck = {at: Date.now(), ok, pending: null};
    music.audiusDown = !ok;
    return ok;
  })();
  return audiusCheck.pending;
}
playMix = (function(orig){
  return async function(moodId){
    const ok = await audiusReachable();
    if(!ok){ renderMusic(); playMoodRadio(moodId || music.mood); return; }
    return orig.call(this, moodId);
  };
})(playMix);

/* ---------- скачивание для офлайна ---------- */
music.downloads = [];
music.dlSet = new Set();
music.dlBusy = {};
async function loadDownloads(){
  try{
    const all = await idbTxStore('downloads', 'readonly', st=> new Promise(r=>{ const q = st.getAll(); q.onsuccess = ()=> r(q.result || []); }));
    all.sort((a, b)=> b.at - a.at);
    music.downloads = all.map(d=> d.track);
    music.dlSet = new Set(all.map(d=> d.key));
  }catch(e){ music.downloads = []; music.dlSet = new Set(); }
}
async function idbTxStore(store, mode, fn){
  const d = await musicIdb();
  return new Promise((res, rej)=>{
    const tx = d.transaction(store, mode); let out;
    Promise.resolve(fn(tx.objectStore(store))).then(v=> out = v);
    tx.oncomplete = ()=> res(out); tx.onerror = ()=> rej(tx.error);
  });
}
const isDownloaded = (t)=> !!(t && music.dlSet.has(trackKey(t)));
async function downloadedUrl(t){
  const key = trackKey(t);
  if(music.localUrls['dl:' + key]) return music.localUrls['dl:' + key];
  const rec = await idbTxStore('downloads', 'readonly', st=> new Promise(r=>{ const q = st.get(key); q.onsuccess = ()=> r(q.result); }));
  return rec ? (music.localUrls['dl:' + key] = URL.createObjectURL(rec.blob)) : null;
}
async function downloadTrack(t, quiet){
  if(!t || t.src !== 'audius'){ toast('Скачать можно только треки из каталога'); return false; }
  const key = trackKey(t);
  if(music.dlSet.has(key)){ if(!quiet) toast('Уже скачано'); return true; }
  if(music.dlBusy[key]) return false;
  music.dlQueue = music.dlQueue || {};
  music.dlQueue[key] = slim(t);
  music.dlBusy[key] = 0; renderMusic();
  try{
    const url = `${audiusBase}/tracks/${encodeURIComponent(t.id)}/stream?${audiusQs()}`;
    const r = await fetch(url);
    if(!r.ok || !r.body) throw new Error('http ' + r.status);
    const total = +r.headers.get('content-length') || 0;
    const reader = r.body.getReader(); const parts = []; let got = 0, lastUi = 0;
    for(;;){
      const {done, value} = await reader.read(); if(done) break;
      parts.push(value); got += value.length;
      if(total && Date.now() - lastUi > 350){ lastUi = Date.now(); music.dlBusy[key] = Math.round(got / total * 100); updateDlBadges(); if(music.subtab === 'mine' && !music.view) renderMusic(); }
    }
    const blob = new Blob(parts, {type: r.headers.get('content-type') || 'audio/mpeg'});
    if(blob.size < 10000) throw new Error('too small');
    try{ if(navigator.storage && navigator.storage.persist) navigator.storage.persist(); }catch(e){}
    await idbTxStore('downloads', 'readwrite', st=> st.put({key, track: slim(t), blob, size: blob.size, at: Date.now()}));
    delete music.dlBusy[key];
    if(music.dlQueue) delete music.dlQueue[key];
    await loadDownloads(); renderMusic(); syncPlayerUi();
    haptic('music', [12, 40, 12]);
    if(!quiet) toast('Скачано — доступно без интернета');
    return true;
  }catch(e){
    delete music.dlBusy[key];
    if(music.dlQueue) delete music.dlQueue[key];
    renderMusic();
    if(!quiet) toast(navigator.onLine ? 'Не удалось скачать — каталог недоступен (включите VPN)' : 'Нет интернета');
    return false;
  }
}
async function removeDownload(t){
  const key = trackKey(t);
  try{ await idbTxStore('downloads', 'readwrite', st=> st.delete(key)); }catch(e){}
  if(music.localUrls['dl:' + key]){ URL.revokeObjectURL(music.localUrls['dl:' + key]); delete music.localUrls['dl:' + key]; }
  await loadDownloads(); renderMusic(); syncPlayerUi(); toast('Загрузка удалена');
}
async function downloadMany(list){
  const todo = list.filter(t=> t.src === 'audius' && !isDownloaded(t));
  if(!todo.length){ toast('Всё уже скачано'); return; }
  toast(`Скачиваю ${todo.length} ${countTxt(todo.length).split(' ')[1]}…`);
  let ok = 0;
  for(const t of todo){ if(await downloadTrack(t, true)) ok++; }
  toast(ok ? `Скачано: ${ok} из ${todo.length}` : 'Не удалось скачать — каталог недоступен (включите VPN)');
}
function updateDlBadges(){
  document.querySelectorAll('#music-body [data-list][data-i]').forEach(el=>{
    const list = music.lists[el.dataset.list] || []; const t = list[+el.dataset.i]; if(!t) return;
    const b = el.querySelector('.m-dl'); const p = music.dlBusy[trackKey(t)];
    if(b && p !== undefined) b.textContent = p ? p + '%' : '…';
  });
}
function dlBadge(t){
  const p = music.dlBusy[trackKey(t)];
  if(p !== undefined) return `<span class="m-dl busy">${p ? p + '%' : '…'}</span>`;
  return isDownloaded(t) ? '<span class="m-dl" title="Скачано">⬇</span>' : '';
}
async function storageLine(){
  try{
    const e = await navigator.storage.estimate();
    const mb = (x)=> (x / 1048576).toFixed(0);
    return `Занято: ${mb(e.usage || 0)} МБ из доступных ~${mb(e.quota || 0)} МБ`;
  }catch(e){ return ''; }
}

/* ---------- восстановление плеера после перезагрузки ---------- */
let musicSaveT = 0;
function saveMusicState(force){
  if(!force && Date.now() - musicSaveT < 3000) return;
  musicSaveT = Date.now();
  try{
    if(!music.track){ localStorage.removeItem('musicState'); return; }
    const from = Math.max(0, music.qi - 20);
    localStorage.setItem('musicState', JSON.stringify({queue: music.queue.slice(from, from + 120).map(slim), qi: music.qi - from,
      pos: music.track.src === 'radio' ? 0 : Math.floor(musicAudio.currentTime || 0), ctx: music.contextName, kind: music.contextKind,
      shuffle: music.shuffle, repeat: music.repeat, playing: !musicAudio.paused, at: Date.now()}));
  }catch(e){}
}
['pause','play'].forEach(ev=> musicAudio.addEventListener(ev, ()=> saveMusicState(true)));
musicAudio.addEventListener('timeupdate', ()=> saveMusicState(false));
window.addEventListener('pagehide', ()=> saveMusicState(true));
document.addEventListener('visibilitychange', ()=>{ if(document.hidden) saveMusicState(true); });
let musicRestored = false;
async function restoreMusicState(){
  if(musicRestored || !state.currentUser) return;
  musicRestored = true;
  let st; try{ st = JSON.parse(localStorage.getItem('musicState') || 'null'); }catch(e){ st = null; }
  if(!st || !st.queue || !st.queue.length || Date.now() - (st.at || 0) > 3 * 86400000) return;
  await loadDownloads();
  music.queue = st.queue; music.qi = Math.min(st.qi || 0, st.queue.length - 1);
  music.contextName = st.ctx || ''; music.contextKind = st.kind || ''; music.shuffle = !!st.shuffle; music.repeat = st.repeat || 'off';
  music.track = music.queue[music.qi];
  try{
    const url = await streamUrlFor(music.track);
    if(url){
      musicAudio.src = url;
      if(st.pos) musicAudio.addEventListener('loadedmetadata', ()=>{ try{ musicAudio.currentTime = st.pos; }catch(e){} }, {once: true});
      if(st.playing){ musicAudio.play().catch(()=>{}); }   // браузер может не дать включить звук без нажатия — тогда островок на паузе
    }
  }catch(e){}
  updateMediaSession(); syncPlayerUi(); renderMusic();
}
setInterval(()=>{ if(state.currentUser && !musicRestored && document.getElementById('app-screen').style.display !== 'none') restoreMusicState(); }, 1200);

/* ---------- музыка в историях ---------- */
storyEditor.music = null; storyEditor.musicStart = 0;
