  if(!t){ sel.style.display = 'none'; btn.style.display = ''; btn.textContent = storyEditor.file ? '🎵 Добавить музыку' : '🎵 Выбрать трек'; return; }
  btn.style.display = 'none'; sel.style.display = 'flex';
