  sel.innerHTML = `<div class="se-mcard"><div class="se-mart">${artInner(t)}</div><div class="se-minfo"><b>${escapeHtml(t.title)}</b><span>${escapeHtml(t.artist || '')}</span></div>
      <button type="button" class="se-mplay" id="se-music-play" aria-label="Прослушать">▶</button><button type="button" class="se-mx" id="se-music-x" aria-label="Убрать">✕</button></div>
    ${maxStart > 0 ? `<div class="se-mrange"><span>Фрагмент с <b id="se-music-from">${musicTime(storyEditor.musicStart)}</b></span><input type="range" id="se-music-start" min="0" max="${maxStart}" value="${storyEditor.musicStart}"></div>` : ''}`;
