/* ---------- уведомления о новой истории ---------- */
async function notifyStoryAudience(kind, audience, storyId, thumb){
  try{
    const me = state.currentUser.uid;
    const blocked = new Set((state.blacklist || []).map(b=> b.uid));
    let to = kind === 'all' ? [...new Set([...(await getMyFriendUids()), ...(state.contacts || []).map(c=> c.uid)])] : audience.slice();
    to = to.filter(u=> u && u !== me && !blocked.has(u)).slice(0, 200);
    if(!to.length) return;
    const fromName = await myDisplayName();
    const data = {fromUid: me, fromName, storyId};
    if(thumb && thumb.length < 20000) data.photoUrl = thumb;
    to.forEach(uid=> pushNotification(uid, 'new_story', data));
  }catch(e){}
}
notifTypeInfo = (function(orig){
  return function(n){
    if(n.type === 'new_story') return {icon: '📸', text: `${escapeHtml((n.data && n.data.fromName) || 'Пользователь')} опубликовал(а) новую историю — нажмите, чтобы посмотреть`};
    return orig(n);
  };
})(notifTypeInfo);
renderNotifPanel = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    document.querySelectorAll('#notif-panel-list .notif-row[data-notif-id]').forEach(row=>{
      const n = allNotifications.find(x=> x.id === row.dataset.notifId);
      if(!n || n.type !== 'new_story') return;
      row.style.cursor = 'pointer';
      row.addEventListener('click', (ev)=>{
        if(ev.target.closest('[data-notif-del]')) return;
        ev.stopPropagation(); ev.preventDefault();
        closeNotifPanel(); openStoryFromNotif(n);
      }, true);
    });
    return r;
  };
})(renderNotifPanel);
async function openStoryFromNotif(n){
  const uid = n.data && n.data.fromUid, sid = n.data && n.data.storyId;
  if(!uid) return;
  if(document.getElementById('chat-area').classList.contains('mobile-open')) closeActiveChat();
  switchTab('chats');
  for(let i = 0; i < 20 && !(storyState.byUid[uid] && (!sid || storyState.byUid[uid].stories.some(s=> s.id === sid))); i++) await new Promise(r=> setTimeout(r, 200));
  const g = storyState.byUid[uid];
  if(!g){ toast('История уже недоступна — возможно, её удалили или истёк срок'); return; }
  openStoryViewer(uid);
  const i = sid ? g.stories.findIndex(s=> s.id === sid) : -1;
  if(i >= 0 && i !== sv.si){ sv.si = i; showStory(); }
}
/* всплывающий баннер, когда история появилась, пока приложение открыто */
const seenStoryNotifs = new Set();
let storyNotifInit = false;
setInterval(()=>{
  if(!state.currentUser || typeof allNotifications === 'undefined') return;
  const fresh = allNotifications.filter(n=> n.type === 'new_story' && !n.read);
  if(!storyNotifInit){
    if(typeof notifFirstSnapshot !== 'undefined' && notifFirstSnapshot) return;   // ждём первую загрузку уведомлений
    fresh.forEach(n=> seenStoryNotifs.add(n.id)); storyNotifInit = true; return;
  }
  const n = fresh.find(x=> !seenStoryNotifs.has(x.id));
  if(!n) return;
  seenStoryNotifs.add(n.id);
  showStoryBanner(n);
  if(document.hidden) try{ showBrowserNotification('Новая история', `${(n.data && n.data.fromName) || 'Друг'} опубликовал(а) историю`); }catch(e){}
}, 1500);
function showStoryBanner(n){
  const b = document.getElementById('story-banner');
  const name = (n.data && n.data.fromName) || 'Пользователь';
  const photo = n.data && n.data.photoUrl;
  b.innerHTML = `<div class="sb-ring">${photo ? `<img src="${escapeHtml(photo)}" alt="">` : '<span>📸</span>'}</div><div class="sb-text"><b>${escapeHtml(name)}</b><span>опубликовал(а) новую историю</span></div><button type="button" class="sb-btn">Смотреть</button>`;
  b.classList.remove('show'); void b.offsetWidth; b.classList.add('show');
  b.onclick = ()=>{ b.classList.remove('show'); db.collection('notifications').doc(n.id).update({read: true}).catch(()=>{}); openStoryFromNotif(n); };
  clearTimeout(showStoryBanner.t); showStoryBanner.t = setTimeout(()=> b.classList.remove('show'), 6000);
}
(function bannerSwipe(){
  const b = document.getElementById('story-banner'); let y0 = null;
  b.addEventListener('touchstart', (e)=>{ y0 = e.touches[0].clientY; }, {passive: true});
  b.addEventListener('touchmove', (e)=>{ if(y0 !== null && e.touches[0].clientY - y0 < -25){ b.classList.remove('show'); y0 = null; } }, {passive: true});
})();

/* ---------- единые стеклянные диалоги вместо системных await uiConfirm() ---------- */
const uiDialogQueue = [];
function uiConfirm(message, opts){
  return new Promise(resolve=>{ uiDialogQueue.push({message: String(message || ''), opts: opts || {}, resolve}); if(uiDialogQueue.length === 1) showNextDialog(); });
}
function showNextDialog(){
  const d = uiDialogQueue[0]; if(!d) return;
  const ov = document.getElementById('ui-dialog');
  const msg = d.message;
  const danger = d.opts.danger !== undefined ? d.opts.danger : /^(Удалить|Покинуть|Заблокировать|Точно|Отключить|Убрать|Отменить)/i.test(msg);
  const verb = d.opts.okText || (/^Удалить/i.test(msg) ? 'Удалить' : /^Покинуть/i.test(msg) ? 'Покинуть' : /^Заблокировать/i.test(msg) ? 'Заблокировать' : /^Отправить/i.test(msg) ? 'Отправить' : /^Убрать/i.test(msg) ? 'Убрать' : /^Открепить/i.test(msg) ? 'Открепить' : 'Да');
  const icon = danger ? '⚠️' : /^Отправить/i.test(msg) ? '📨' : '❓';
  const parts = msg.split(/(?<=[?!.])\s+/);
  const title = parts.length > 1 && parts[0].length < 90 ? parts[0] : msg;
  const text = parts.length > 1 && parts[0].length < 90 ? parts.slice(1).join(' ') : '';
  ov.innerHTML = `<div class="ui-dlg" role="alertdialog" aria-modal="true"><div class="ui-dlg-ico ${danger ? 'danger' : ''}">${icon}</div>
    <div class="ui-dlg-title">${escapeHtml(title)}</div>${text ? `<div class="ui-dlg-text">${escapeHtml(text)}</div>` : ''}
    <div class="ui-dlg-btns"><button type="button" class="ui-btn ghost" data-r="0">${escapeHtml(d.opts.cancelText || 'Отмена')}</button><button type="button" class="ui-btn ${danger ? 'danger' : 'primary'}" data-r="1">${escapeHtml(verb)}</button></div></div>`;
  ov.classList.add('show');
  const done = (val)=>{ ov.classList.remove('show'); document.removeEventListener('keydown', onKey, true); uiDialogQueue.shift(); d.resolve(val); setTimeout(showNextDialog, 180); };
  const onKey = (e)=>{ if(e.key === 'Escape'){ e.stopPropagation(); done(false); } else if(e.key === 'Enter'){ e.preventDefault(); done(true); } };
  document.addEventListener('keydown', onKey, true);
  ov.onclick = (e)=>{ const b = e.target.closest('[data-r]'); if(b) done(b.dataset.r === '1'); else if(e.target === ov) done(false); };
  setTimeout(()=>{ const b = ov.querySelector('[data-r="1"]'); if(b) b.focus(); }, 60);
}

/* ============================================================
   ROUND 15 — проверка потоков с запасными адресами (Зайцев.FM)
============================================================ */
const streamProbe = (()=>{ try{ return JSON.parse(localStorage.getItem('streamProbe') || '{}'); }catch(e){ return {}; } })();
function saveProbe(){ try{ localStorage.setItem('streamProbe', JSON.stringify(streamProbe)); }catch(e){} }
const PROBE_TTL = 24 * 3600000;
function probeOne(url){
  const c = streamProbe[url];
  if(c && Date.now() - c.at < PROBE_TTL) return Promise.resolve(c.ok);
  return new Promise(resolve=>{
    const a = new Audio(); let done = false;
    const fin = (ok)=>{ if(done) return; done = true; a.removeAttribute('src'); try{ a.load(); }catch(e){} streamProbe[url] = {ok, at: Date.now()}; saveProbe(); resolve(ok); };
    a.preload = 'metadata'; a.muted = true;
    a.addEventListener('loadedmetadata', ()=> fin(true));
    a.addEventListener('canplay', ()=> fin(true));
    a.addEventListener('error', ()=> fin(false));
    setTimeout(()=> fin(false), 3500);   // не ждём долго: быстрее переходим к запасному адресу
    a.src = url;
  });
}
async function resolveStreamUrl(alts){
  for(const u of alts){ if(await probeOne(u)) return u; }
  return null;
}
function streamProbeDead(alts){
  // скрываем, только если ВСЕ варианты недавно проверены и не ответили
  return alts.every(u=>{ const c = streamProbe[u]; return c && !c.ok && Date.now() - c.at < PROBE_TTL; });
}
let probeRunning = false;
async function probeStationsInBackground(list){
  if(probeRunning) return; probeRunning = true;
  let changed = false;
  for(const st of list){
    const before = streamProbeDead(st.alts);
    const u = await resolveStreamUrl(st.alts);
    if(u && st.url !== u){ st.url = u; }
    if(streamProbeDead(st.alts) !== before) changed = true;
  }
  probeRunning = false;
  if(changed && music.subtab === 'radio') renderMusic();
}

/* ============================================================
   ROUND 16 — прокси для музыки и ИИ (адрес задаётся в админ-панели)
============================================================ */
function proxyBase(){ return String((state.appConfig && state.appConfig.proxyUrl) || '').replace(/\/+$/, ''); }
function musicViaProxy(){ return !!proxyBase() && !(state.appConfig && state.appConfig.proxyMusic === false); }
function aiViaProxy(){ return !!proxyBase() && !(state.appConfig && state.appConfig.proxyAi === false); }
let proxySig = null;
function applyProxyRouting(force){
  const sig = JSON.stringify([proxyBase(), musicViaProxy(), aiViaProxy()]);
  if(!force && sig === proxySig) return;
  proxySig = sig;
  audiusBase = musicViaProxy() ? proxyBase() + '/audius/v1' : 'https://api.audius.co/v1';
  audiusCheck = {at: 0, ok: null, pending: null};
  music.cache = {};
  music.audiusDown = false;
  if(state.activeTab === 'music') renderMusic();
}
setInterval(()=>{ if(state.currentUser) applyProxyRouting(false); }, 1500);
// каталог радио «Мир» — тоже через прокси
radioGet = (function(orig){
  return async function(path){
    if(musicViaProxy()){
      try{ const r = await fetch(proxyBase() + '/radio' + path); if(r.ok) return await r.json(); }catch(e){}
    }
    return orig.call(this, path);
  };
})(radioGet);
// запасной поиск серверов Audius не нужен, когда работаем через прокси
audiusGet = (function(orig){
  return async function(path){
    if(!musicViaProxy()) return orig.call(this, path);
    const sep = path.includes('?') ? '&' : '?';
    const r = await fetch(audiusBase + path + sep + audiusQs());
    if(!r.ok) throw new Error('proxy ' + r.status);
    return (await r.json()).data || [];
  };
})(audiusGet);
// ИИ: через прокси, если включено
aiEndpoint = (function(orig){
  return function(){ return aiViaProxy() ? proxyBase() + '/ai' : orig(); };
})(aiEndpoint);

/* ============================================================
   ROUND 17 — поиск по кнопке, уведомления, просмотры, подгрузка сообщений
============================================================ */
/* ---------- выдвижной поиск вместо постоянной строки ---------- */
const SEARCH_BLOCKS = [
  {tab: 'chats', sel: '#tab-chats .chat-search-wrap', input: '#chat-list-search'},
  {tab: 'calls', sel: '#tab-calls .chat-search-wrap', input: '#calls-search-input'},
  {tab: 'contacts', sel: '#tab-contacts .search-wrap', input: '#contact-search-input'},
];
const SEARCH_ICO = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"/><path d="M20 20l-4.2-4.2"/></svg>';
function searchBlockFor(tab){ const b = SEARCH_BLOCKS.find(x=> x.tab === tab); return b ? document.querySelector(b.sel) : null; }
function closeHeaderSearch(clear){
  SEARCH_BLOCKS.forEach(b=>{
    const el = document.querySelector(b.sel);
    if(!el || !el.classList.contains('open')) return;
    clearTimeout(el._doneT);
    el.classList.remove('done');
    void el.offsetHeight;
    el.classList.remove('open');
    const inp = document.querySelector(b.input);
    if(inp && clear !== false && inp.value){ inp.value = ''; inp.dispatchEvent(new Event('input')); }
    if(inp) inp.blur();
  });
  document.querySelectorAll('.header-search-btn').forEach(b=> b.classList.remove('on'));
}
function toggleHeaderSearch(tab, btn){
  const el = searchBlockFor(tab);
  if(!el) return;
  const willOpen = !el.classList.contains('open');
  closeHeaderSearch();
  if(!willOpen) return;
  el.classList.add('open');
  btn.classList.add('on');
  clearTimeout(el._doneT);
  el._doneT = setTimeout(()=> el.classList.add('done'), 420);   // после анимации снимаем ограничение высоты
  const inp = document.querySelector((SEARCH_BLOCKS.find(x=> x.tab === tab) || {}).input);
  setTimeout(()=>{ if(inp) inp.focus(); }, 260);
  haptic('buttons', 6);
}
(function setupHeaderSearch(){
  SEARCH_BLOCKS.forEach(b=>{
    const el = document.querySelector(b.sel);
    if(el) el.classList.add('search-collapsible');
    const panel = document.getElementById('tab-' + b.tab);
    const header = panel && panel.querySelector('.tab-header:not(.select-header)');
    const island = header && header.querySelector('.header-island');
    if(!island || island.querySelector('.header-search-btn')) return;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'icon-btn header-search-btn';
    btn.title = 'Поиск';
    btn.setAttribute('aria-label', 'Поиск');
    btn.innerHTML = SEARCH_ICO;
    btn.onclick = (e)=>{ e.stopPropagation(); toggleHeaderSearch(b.tab, btn); };
    island.insertBefore(btn, island.firstChild);
  });
  document.addEventListener('pointerdown', (e)=>{
    if(e.target.closest('.search-collapsible, .header-search-btn')) return;
    closeHeaderSearch();
  }, true);
  document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape') closeHeaderSearch(); });
})();
switchTab = (function(orig){ return function(...a){ closeHeaderSearch(); return orig.apply(this, a); }; })(switchTab);
// клавиатура меняет высоту экрана — открытый поиск не должен обрезаться
window.addEventListener('resize', ()=> document.querySelectorAll('.search-collapsible.open').forEach(el=> el.classList.add('done')));

