showIncomingCall = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    clearInterval(showIncomingCall._t);
    showIncomingCall._t = setInterval(()=>{
      if(state.activeCallState !== 'incoming'){ clearInterval(showIncomingCall._t); return; }
      haptic('calls', [400, 200, 400, 900]);
    }, 2200);
    haptic('calls', [400, 200, 400]);
    return r;
  };
})(showIncomingCall);
setInterval(()=>{ if(state.activeCallState !== 'incoming' && showIncomingCall._t){ clearInterval(showIncomingCall._t); showIncomingCall._t = null; } }, 1500);
playNotificationSound = (function(orig){ return function(...a){ haptic('notifications', [14, 60, 14]); return orig.apply(this, a); }; })(typeof playNotificationSound === 'function' ? playNotificationSound : function(){});

/* ---------- настройки: раздел «Тактильная отдача» ---------- */
function buildHapticSettings(){
  const body = document.getElementById('settings-body');
  if(!body || document.getElementById('haptic-card')) return;
  const card = document.createElement('div');
  card.className = 'settings-card haptic-card';
  card.id = 'haptic-card';
  card.innerHTML = `
    <div class="settings-row">
      <div class="settings-row-main"><div class="settings-row-title">📳 Тактильная отдача</div>
      <div class="settings-row-sub">Короткая вибрация при нажатиях</div></div>
      <label class="toggle-switch"><input type="checkbox" id="haptic-main" ${hapticPrefs.on ? 'checked' : ''}><span class="toggle-slider"></span></label>
    </div>
    <div id="haptic-list">
      ${HAPTIC_KINDS.map(k=> `<div class="settings-row">
        <div class="settings-row-main"><div class="settings-row-title">${k.icon} ${k.name}</div></div>
        <label class="toggle-switch"><input type="checkbox" data-haptic="${k.id}" ${hapticPrefs[k.id] !== false ? 'checked' : ''}><span class="toggle-slider"></span></label>
      </div>`).join('')}
    </div>
    <div class="haptic-note" id="haptic-note"></div>`;
  const anchor = body.querySelector('.settings-card');
  if(anchor && anchor.nextSibling) body.insertBefore(card, anchor.nextSibling); else body.appendChild(card);
  const note = card.querySelector('#haptic-note');
  note.textContent = hapticSupported()
    ? 'Нажмите любой переключатель — телефон коротко откликнется.'
    : 'Этот браузер не умеет вибрировать. На iPhone вибрация в браузере недоступна — она работает на Android.';
  const list = card.querySelector('#haptic-list');
  const syncList = ()=>{ list.style.opacity = hapticPrefs.on ? '1' : '.45'; list.style.pointerEvents = hapticPrefs.on ? '' : 'none'; };
  syncList();
  card.querySelector('#haptic-main').onchange = (e)=>{ hapticPrefs.on = e.target.checked; saveHaptics(); syncList(); if(e.target.checked) haptic('buttons', [14, 40, 14]); };
  card.querySelectorAll('[data-haptic]').forEach(inp=>{
    inp.onchange = (e)=>{ hapticPrefs[inp.dataset.haptic] = e.target.checked; saveHaptics(); if(e.target.checked) haptic(inp.dataset.haptic, [14, 40, 14]); };
  });
}
switchTab = (function(orig){ return function(tab, ...rest){ const r = orig.call(this, tab, ...rest); if(tab === 'settings') setTimeout(buildHapticSettings, 60); return r; }; })(switchTab);

/* ---------- радио: подбираем рабочий адрес при включении ---------- */
async function pickStationUrl(t){
  const alts = t.alts || [t.url];
  const good = alts.find(u=>{ const c = streamProbe[u]; return c && c.ok && Date.now() - c.at < PROBE_TTL; });
  if(good) return good;
  for(const u of alts){
    const c = streamProbe[u];
    if(c && !c.ok && Date.now() - c.at < 10 * 60000) continue;       // недавно не ответил — пропускаем
    if(await probeOne(u)) return u;
  }
  return alts[0];                                                     // ничего не проверилось — пробуем как есть
}
// если станция не заиграла, пробуем следующий адрес того же канала
musicAudio.addEventListener('error', async ()=>{
  const t = music.track;
  if(!t || t.src !== 'radio' || !t.alts || !t.alts.length) return;
  const cur = decodeURIComponent(musicAudio.src || '');
  const idx = t.alts.findIndex(u=> cur.endsWith(u.split('/').pop()));
  const next = t.alts[idx + 1];
  if(!next) return;
  streamProbe[cur] = {ok: false, at: Date.now()}; saveProbe();
  musicAudio.src = next;
  musicAudio.play().catch(()=>{});
}, true);

/* ============================================================
   ROUND 20 — громкость, «скачать всё», широкие вкладки,
   папка с музыкой, выбор и удаление, лайк в островке
============================================================ */
/* ---------- громкость ---------- */
(function volumeControl(){
  const slider = document.getElementById('mpl-volume');
  const val = document.getElementById('mpl-volume-val');
  const btn = document.getElementById('mpl-mute');
  const ICON_ON = document.getElementById('mpl-mute').innerHTML;
  const ICON_OFF = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><polygon points="4 9 8 9 12 5 12 19 8 15 4 15 4 9"/><line x1="17" y1="9" x2="22" y2="15"/><line x1="22" y1="9" x2="17" y2="15"/></svg>`;
  let last = 1;
  try{ const v = parseFloat(localStorage.getItem('musicVolume')); if(isFinite(v)) musicAudio.volume = Math.min(1, Math.max(0, v)); }catch(e){}
  const sync = ()=>{
    const v = Math.round(musicAudio.volume * 100);
    slider.value = v; slider.style.setProperty('--v', v + '%');
    val.textContent = v + '%';
    btn.innerHTML = (musicAudio.muted || v === 0) ? ICON_OFF : ICON_ON;
  };
  slider.addEventListener('input', ()=>{
    musicAudio.muted = false;
    musicAudio.volume = slider.value / 100;
    try{ localStorage.setItem('musicVolume', String(musicAudio.volume)); }catch(e){}
    sync();
  });
  btn.onclick = ()=>{
    if(musicAudio.muted || musicAudio.volume === 0){ musicAudio.muted = false; musicAudio.volume = last || 0.7; }
    else { last = musicAudio.volume; musicAudio.muted = true; }
    haptic('music', 10); sync();
  };
  musicAudio.addEventListener('volumechange', sync);
  sync();
  // на телефоне громкость регулируется кнопками устройства — предупреждаем один раз
  document.getElementById('mpl-volume-row').addEventListener('pointerdown', ()=>{
    const before = musicAudio.volume;
    setTimeout(()=>{
      if(Math.abs(musicAudio.volume - before) < 0.001 && slider.value / 100 !== before && !volumeControl._warned){
        volumeControl._warned = true;
        toast('Этот телефон не даёт менять громкость из браузера — пользуйтесь кнопками громкости');
      }
    }, 600);
  });
})();
