/* ---------- папка с музыкой и массовое добавление ---------- */
music.sel = new Set();
music.selMode = false;
const AUDIO_RE = /\.(mp3|m4a|aac|ogg|opus|wav|flac|wma)$/i;
function importProgress(done, total){
  const body = document.getElementById('music-body');
  let el = document.getElementById('m-import');
  if(!el){
    el = document.createElement('div');
    el.className = 'm-import'; el.id = 'm-import';
    body.prepend(el);
  }
  el.innerHTML = `<span>Добавляю треки… ${done} из ${total}</span><span class="bar"><i style="width:${Math.round(done / Math.max(1, total) * 100)}%"></i></span>`;
  if(done >= total) setTimeout(()=>{ const e = document.getElementById('m-import'); if(e) e.remove(); }, 1200);
}
async function importFiles(files){
  const list = Array.from(files || []).filter(f=> /^audio\//.test(f.type) || AUDIO_RE.test(f.name));
  if(!list.length){ toast('В этой папке не нашлось аудиофайлов'); return; }
  const have = new Set(music.local.map(t=> (t.artist + ' — ' + t.title).toLowerCase()));
  let done = 0, added = 0;
  importProgress(0, list.length);
  for(const f of list){
    const meta = parseFileName(f.name);
    const key = (meta.artist + ' — ' + meta.title).toLowerCase();
    if(!have.has(key)){
      await addLocalFiles([f]);
      have.add(key); added++;
    }
    importProgress(++done, list.length);
  }
  haptic('music', [12, 40, 12]);
  toast(added ? `Добавлено треков: ${added}` : 'Все эти треки уже есть');
}
async function pickMusicFolder(){
  haptic('buttons', 10);
  if(window.showDirectoryPicker){
    try{
      const dir = await window.showDirectoryPicker({id: 'music', mode: 'read'});
      const files = [];
      const walk = async (handle, depth)=>{
        if(depth > 4) return;
        for await (const [name, h] of handle.entries()){
          if(h.kind === 'file' && AUDIO_RE.test(name)){ try{ files.push(await h.getFile()); }catch(e){} }
          else if(h.kind === 'directory'){ await walk(h, depth + 1); }
        }
      };
      toast('Просматриваю папку…');
      await walk(dir, 0);
      await importFiles(files);
      return;
    }catch(e){ if(e && e.name === 'AbortError') return; }
  }
  document.getElementById('music-folder-input').click();   // запасной путь: выбор папки системным окном
}
(function folderInput(){
  if(document.getElementById('music-folder-input')) return;
  const inp = document.createElement('input');
  inp.type = 'file'; inp.id = 'music-folder-input'; inp.multiple = true; inp.style.display = 'none';
  inp.setAttribute('webkitdirectory', ''); inp.setAttribute('directory', '');
  inp.addEventListener('change', (e)=>{ importFiles(e.target.files); e.target.value = ''; });
  document.body.appendChild(inp);
})();

/* ---------- выбор и удаление треков ---------- */
async function deleteTracks(list){
  for(const t of list){
    if(t.src === 'local'){
      try{ await idbTxStore('files', 'readwrite', st=> st.delete(t.id)); }catch(e){}
      if(music.localUrls[t.id]){ URL.revokeObjectURL(music.localUrls[t.id]); delete music.localUrls[t.id]; }
    }else if(isDownloaded(t)){
      const key = trackKey(t);
      try{ await idbTxStore('downloads', 'readwrite', st=> st.delete(key)); }catch(e){}
      if(music.localUrls['dl:' + key]){ URL.revokeObjectURL(music.localUrls['dl:' + key]); delete music.localUrls['dl:' + key]; }
    }
  }
  await loadLocalFiles(); await loadDownloads();
  music.sel.clear(); music.selMode = false;
  renderMusic();
  haptic('buttons', [10, 40, 10]);
  toast(list.length === 1 ? 'Трек удалён' : `Удалено треков: ${list.length}`);
}
document.getElementById('music-body').addEventListener('click', async (e)=>{
  const act = e.target.closest('[data-act]');
  const a = act && act.dataset.act;
  if(a === 'pickfolder'){ e.stopPropagation(); pickMusicFolder(); return; }
  if(a === 'selmode'){ e.stopPropagation(); music.selMode = !music.selMode; music.sel.clear(); renderMusic(); return; }
  if(a === 'delsel'){
    e.stopPropagation();
    const list = (music.lists.view || []).filter(t=> music.sel.has(trackKey(t)));
    if(!list.length){ toast('Ничего не выбрано'); return; }
    if(await uiConfirm(`Удалить выбранные треки (${list.length})? Файлы удалятся с этого устройства.`)) deleteTracks(list);
    return;
  }
  if(a === 'delall'){
    e.stopPropagation();
    const list = (music.lists.view || []).slice();
    if(!list.length) return;
    if(await uiConfirm(`Удалить все треки из этого раздела (${list.length})? Файлы удалятся с этого устройства.`)) deleteTracks(list);
    return;
  }
  if(music.selMode){
    const row = e.target.closest('.m-row.selectable');
    if(row){
      e.stopPropagation(); e.preventDefault();
      const t = (music.lists[row.dataset.list] || [])[+row.dataset.i];
      if(t){
        const k = trackKey(t);
        if(music.sel.has(k)) music.sel.delete(k); else music.sel.add(k);
        haptic('buttons', 8);
        renderMusic();
      }
    }
  }
}, true);

/* ---------- радио: показываем только те станции, что реально отвечают ---------- */
async function verifyStations(cat){
  const list = RU_STATIONS.filter(st=> st.cat === cat && st.alts);
  let changed = false;
  for(const st of list){
    const u = await pickStationUrl({alts: st.alts, url: st.url});
    if(u && u !== st.url){ st.url = u; changed = true; }
  }
  if(changed && music.subtab === 'radio') renderMusic();
}
renderRadio = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    const cat = music.radioCat || 'ru';
    verifyStations._done = verifyStations._done || {};
    if(cat !== 'world' && !verifyStations._done[cat]){ verifyStations._done[cat] = true; verifyStations(cat); }
    return r;
  };
})(renderRadio);

/* ============================================================
   ROUND 21 — кольцо загрузки вокруг отправляемых вложений
============================================================ */
const UP_R = 26, UP_LEN = 2 * Math.PI * UP_R;
function upRingFor(kind, i){
  const row = document.getElementById(kind === 'image' ? 'img-preview-row' : 'file-preview-row');
  if(!row) return null;
  const item = row.children[i];
  if(!item) return null;
  if(kind === 'file'){
    item.classList.add('uploading');
    let line = item.querySelector('.up-line');
    if(!line){ line = document.createElement('i'); line.className = 'up-line'; item.appendChild(line); }
    return {file: true, item, line};
  }
  let ring = item.querySelector('.up-ring');
  if(!ring){
    ring = document.createElement('div');
    ring.className = 'up-ring';
    ring.innerHTML = `<svg viewBox="0 0 64 64"><circle class="bg" cx="32" cy="32" r="${UP_R}"/>
      <circle class="fg" cx="32" cy="32" r="${UP_R}" stroke-dasharray="${UP_LEN}" stroke-dashoffset="${UP_LEN}"/></svg><span class="pc">0%</span>`;
    item.appendChild(ring);
  }
  return {item, ring, fg: ring.querySelector('.fg'), pc: ring.querySelector('.pc')};
}
function upSet(h, pct){
  if(!h) return;
  const v = Math.max(0, Math.min(100, Math.round(pct)));
  if(h.file){ h.line.style.width = v + '%'; return; }
  h.fg.style.strokeDashoffset = String(UP_LEN * (1 - v / 100));
  h.pc.textContent = v + '%';
}
function upFinish(h, ok){
  if(!h) return;
  if(h.file){ upSet(h, 100); h.item.classList.remove('uploading'); return; }
  upSet(h, ok ? 100 : 0);
  h.ring.classList.add(ok ? 'done' : 'fail');
  h.pc.textContent = ok ? '✓' : '!';
}
/* пока файл уходит, кольцо плавно наполняется: скорость — по размеру файла */
function upAnimate(h, bytes){
  const dur = Math.max(700, Math.min(9000, (bytes || 200000) / 90));   // примерная оценка
  const t0 = performance.now();
  const tick = ()=>{
    if(!h || h.stopped) return;
    const k = Math.min(1, (performance.now() - t0) / dur);
    upSet(h, 6 + k * 84);                                             // до 90 %, остальное — по факту отправки
    if(k < 1) h.raf = requestAnimationFrame(tick);
  };
  h.raf = requestAnimationFrame(tick);
  return h;
}
doSend = (function(orig){
  return async function(...args){
    const imgs = (state.pendingImages || []).length + (state.pendingVideos || []).length, fls = (state.pendingFiles || []).length;
    if(!imgs && !fls) return orig.apply(this, args);
    const handles = [];
    for(let i = 0; i < imgs; i++){ const h = upRingFor('image', i); if(h){ handles.push(h); upSet(h, 4); } }
    for(let i = 0; i < fls; i++){ const h = upRingFor('file', i); if(h){ handles.push(h); upSet(h, 4); } }
    let iImg = 0, iFile = 0;
    const realSend = sendMessage;
    sendMessage = async function(chatId, type, content, name, extra){
      if(type !== 'image' && type !== 'file' && type !== 'video') return realSend.call(this, chatId, type, content, name, extra);
      const h = upRingFor(type === 'image' || type === 'video' ? 'image' : 'file', (type === 'image' || type === 'video') ? iImg++ : iFile++);
      if(h){ handles.push(h); upAnimate(h, (content || '').length * 0.75); }
      try{
        const r = await realSend.call(this, chatId, type, content, name, extra);
        if(h){ h.stopped = true; cancelAnimationFrame(h.raf); upFinish(h, true); }
        haptic('buttons', 8);
        return r;
      }catch(e){
        if(h){ h.stopped = true; cancelAnimationFrame(h.raf); upFinish(h, false); }
        throw e;
      }
    };
    try{
      return await orig.apply(this, args);
    }finally{
      sendMessage = realSend;
      setTimeout(()=> handles.forEach(h=>{ if(h && h.ring) h.ring.remove(); if(h && h.line) h.line.remove(); }), 600);
    }
  };
})(doSend);

/* ============================================================
   ROUND 22 — отправка видео в переписку
============================================================ */
state.pendingVideos = [];
const CHAT_VIDEO_MAX_SEC = 60;                     // ROUND 68: видео режется на части, лимит документа больше не мешает
const CHAT_VIDEO_LIMIT = 3.6 * 1024 * 1024;          // ROUND 68: хранится частями в mediaChunks
document.getElementById('attach-video-opt').onclick = ()=>{
  document.getElementById('attach-menu').style.display = 'none';
  haptic('buttons', 8);
  document.getElementById('chat-video-input').click();
};
document.getElementById('chat-video-input').addEventListener('change', async (e)=>{
  const f = e.target.files && e.target.files[0];
  e.target.value = '';
  if(!f) return;
  if(state.pendingVideos.length){ toast('За раз можно отправить одно видео'); return; }
  const row = document.getElementById('img-preview-row');
  const ph = document.createElement('div');
  ph.className = 'img-preview video-preview';
  ph.innerHTML = `<div class="up-ring"><svg viewBox="0 0 64 64"><circle class="bg" cx="32" cy="32" r="26"/>
    <circle class="fg" cx="32" cy="32" r="26" stroke-dasharray="${UP_LEN}" stroke-dashoffset="${UP_LEN}"/></svg><span class="pc">0%</span></div>`;
  row.appendChild(ph);
  const h = {item: ph, ring: ph.querySelector('.up-ring'), fg: ph.querySelector('.fg'), pc: ph.querySelector('.pc')};
  try{
    const prep = await prepareStoryVideo(f, (k)=> upSet(h, k * 96), {forceTranscode: false, maxSec: CHAT_VIDEO_MAX_SEC, limitBytes: CHAT_VIDEO_LIMIT});
    const dataUrl = await blobToDataUrl(prep.blob);
    if(dataUrl.length * 0.75 > CHAT_VIDEO_LIMIT * 1.35){ throw new Error('too_big'); }
    state.pendingVideos.push({dataUrl, name: f.name.replace(/\.[^.]+$/, '') + '.webm', dur: Math.round(prep.duration || 0), thumb: prep.thumb || ''});
    ph.remove();
    renderImgPreviews();
    updateSendBtnVisibility();
    haptic('buttons', 10);
  }catch(err){
    ph.remove();
    toast(err && err.message === 'too_big' ? 'Видео слишком большое — выберите ролик покороче' : 'Не удалось обработать видео');
  }
});
/* превью видео стоит рядом с фото */
renderImgPreviews = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    const row = document.getElementById('img-preview-row');
    (state.pendingVideos || []).forEach((v, i)=>{
      const el = document.createElement('div');
      el.className = 'img-preview video-preview';
      el.innerHTML = `<video src="${v.dataUrl}" muted playsinline preload="metadata" ${v.thumb ? `poster="${v.thumb}"` : ''}></video>
        <span class="vp-badge">🎬 ${Math.floor(v.dur / 60)}:${String(v.dur % 60).padStart(2, '0')}</span><div class="rm" data-vidx="${i}">✕</div>`;
      el.querySelector('.rm').onclick = ()=>{ state.pendingVideos.splice(i, 1); renderImgPreviews(); updateSendBtnVisibility(); };
      row.appendChild(el);
    });
    return r;
  };
})(renderImgPreviews);
updateSendBtnVisibility = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    if((state.pendingVideos || []).length){
      document.getElementById('composer-normal').classList.add('has-content');
      const sb = document.getElementById('send-btn'); if(sb) sb.style.display = 'flex';
      const mic = document.getElementById('mic-btn'); if(mic) mic.style.display = 'none';
    }
    return r;
  };
})(updateSendBtnVisibility);
doSend = (function(orig){
  return async function(...args){
    const vids = (state.pendingVideos || []).slice();
    if(!vids.length) return orig.apply(this, args);
    const r = await orig.apply(this, args);                     // фото, файлы и текст уходят как обычно
    for(const v of vids){
      try{ await sendMessage(state.activeChatId, 'video', v.dataUrl, v.name, {duration: v.dur, thumbnail: v.thumb}); }
      catch(e){ toast('Не удалось отправить видео'); }
    }
    state.pendingVideos = [];
    renderImgPreviews(); updateSendBtnVisibility();
    return r;
  };
})(doSend);
/* подпись в списке чатов */
msgPreviewText = (function(orig){
  return function(m, ...rest){ if(m && m.type === 'video') return '🎬 Видео'; return orig.call(this, m, ...rest); };
})(msgPreviewText);

/* ============================================================
   ROUND 23 — вложение уходит сразу, кольцо крутится на сообщении
============================================================ */
state.outgoing = [];
const outRing = {};
function outgoingAsMessages(){
  const me = state.currentUser ? state.currentUser.uid : 'me';
  return state.outgoing.map(o=> ({id: o.id, from: me, chatId: o.chatId, type: o.type, content: o.content,
    fileName: o.fileName, duration: o.dur, thumbnail: o.thumb, timestamp: o.ts, reactions: [], hiddenFor: []}));
}
renderMessages = (function(orig){
  return function(msgs, ...rest){
    const extra = state.outgoing.filter(o=> o.chatId === state.activeChatId);
    if(!extra.length) return orig.call(this, msgs, ...rest);
    const r = orig.call(this, (msgs || []).concat(outgoingAsMessages().filter(m=> m.chatId === state.activeChatId)), ...rest);
    decorateOutgoing();
    return r;
  };
})(renderMessages);
function decorateOutgoing(){
  state.outgoing.forEach(o=>{
    const row = document.querySelector(`#messages .msg-row[data-id="${o.id}"]`);
    if(!row) return;
    row.classList.add('sending');
    const bubble = row.querySelector('.bubble');
    if(!bubble) return;
    let ring = bubble.querySelector('.msg-ring');
    if(!ring){
      ring = document.createElement('div');
      ring.className = 'msg-ring';
      ring.innerHTML = `<svg viewBox="0 0 64 64"><circle class="bg" cx="32" cy="32" r="26"/>
        <circle class="fg" cx="32" cy="32" r="26" stroke-dasharray="${UP_LEN}" stroke-dashoffset="${UP_LEN}"/></svg><span class="pc">0%</span>`;
      bubble.appendChild(ring);
    }
    outRing[o.id] = {fg: ring.querySelector('.fg'), pc: ring.querySelector('.pc'), ring};
    setOutProgress(o.id, o.progress || 4);
  });
}
function setOutProgress(id, pct){
  const h = outRing[id];
  const o = state.outgoing.find(x=> x.id === id);
  if(o) o.progress = pct;
  if(!h) return;
  const v = Math.max(0, Math.min(100, Math.round(pct)));
  h.fg.style.strokeDashoffset = String(UP_LEN * (1 - v / 100));
  h.pc.textContent = v + '%';
}
function finishOutgoing(id, ok){
  const h = outRing[id];
  if(h){
    setOutProgress(id, ok ? 100 : 0);
    h.ring.classList.add('done');
    h.pc.textContent = ok ? '✓' : '!';
  }
  setTimeout(()=>{
    state.outgoing = state.outgoing.filter(o=> o.id !== id);
    delete outRing[id];
    if(state.activeChatId) renderMessages(state.currentMessages || []);
  }, ok ? 60 : 1800);
}
/* отправка вложений: превью исчезают сразу, кольцо — уже в переписке */
doSend = (function(orig){
  return async function(...args){
    if(!state.activeChatId) return;
    const imgs = (state.pendingImages || []).slice();
    const fls = (state.pendingFiles || []).slice();
    const vids = (state.pendingVideos || []).slice();
    if(!imgs.length && !fls.length && !vids.length) return orig.apply(this, args);
    const input = document.getElementById('msg-input');
    const text = input.value.trim();
    const chatId = state.activeChatId;
    let replyExtra = state.replyingTo ? {replyTo: state.replyingTo} : undefined;
    // 1) очищаем поле ввода и вложения — как в мессенджерах
    state.pendingImages = []; state.pendingFiles = []; state.pendingVideos = [];
    renderImgPreviews(); renderFilePreviews();
    input.value = ''; input.style.height = 'auto';
    updateSendBtnVisibility();
    if(typeof clearReplyContext === 'function') clearReplyContext();
    haptic('buttons', 10);
    // 2) кладём сообщения в ленту сразу, с кольцом загрузки
    const queue = [];
    if(text) queue.push({type: 'text', content: text});
    imgs.forEach(im=> queue.push({type: 'image', content: im.dataUrl, fileName: im.name}));
    vids.forEach(v=> queue.push({type: 'video', content: v.dataUrl, fileName: v.name, dur: v.dur, thumb: v.thumb}));
    fls.forEach(f=> queue.push({type: 'file', content: f.dataUrl, fileName: f.name}));
    const items = queue.map((q, i)=> Object.assign({}, q, {id: 'tmp_' + Date.now() + '_' + i, chatId, ts: Date.now() + i, progress: 4}));
    state.outgoing.push(...items);
    msgStickBottom = true;
    renderMessages(state.currentMessages || []);
    scheduleStickToBottom();
    // 3) отправляем по очереди, наполняя кольцо
    for(const it of items){
      const bytes = (it.content || '').length * 0.75;
      const dur = Math.max(600, Math.min(9000, bytes / 90));
      const t0 = performance.now();
      let raf = 0;
      const tick = ()=>{
        const k = Math.min(1, (performance.now() - t0) / dur);
        setOutProgress(it.id, 6 + k * 84);
        if(k < 1 && state.outgoing.some(o=> o.id === it.id)) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
      try{
        const extra = Object.assign({}, replyExtra || {});
        if(it.type === 'video'){ extra.duration = it.dur; extra.thumbnail = it.thumb; }
        await sendMessage(chatId, it.type, it.content, it.fileName || null, Object.keys(extra).length ? extra : undefined);
        replyExtra = undefined;
        cancelAnimationFrame(raf);
        finishOutgoing(it.id, true);
      }catch(e){
        cancelAnimationFrame(raf);
        finishOutgoing(it.id, false);
        toast('Не удалось отправить вложение');
      }
    }
  };
})(doSend);
document.getElementById('send-btn').onclick = ()=> doSend();

/* ============================================================
   ROUND 24 — всплывающие уведомления и плеер видео в переписке
============================================================ */
/* ---------- единый баннер ---------- */
const appBanner = document.getElementById('app-banner');
let abTimer = null;
function showAppBanner({icon, avatar, thumb, title, sub, btn, onClick}){
  appBanner.innerHTML = `<span class="ab-ava">${avatar ? `<img src="${escapeHtml(avatar)}" alt="">` : (icon || '🔔')}</span>
    <span class="ab-text"><span class="ab-title">${escapeHtml(title || '')}</span><span class="ab-sub">${escapeHtml(sub || '')}</span></span>
    ${thumb ? `<img class="ab-thumb" src="${escapeHtml(thumb)}" alt="">` : ''}
    <button type="button" class="ab-btn">${escapeHtml(btn || 'Открыть')}</button>`;
  appBanner.classList.remove('show'); void appBanner.offsetWidth; appBanner.classList.add('show');
  haptic('notifications', [12, 50, 12]);
  appBanner.onclick = ()=>{ appBanner.classList.remove('show'); if(onClick) try{ onClick(); }catch(e){} };
  clearTimeout(abTimer);
  abTimer = setTimeout(()=> appBanner.classList.remove('show'), 5500);
}
(function bannerSwipeUp(){
  let y0 = null;
  appBanner.addEventListener('touchstart', (e)=>{ y0 = e.touches[0].clientY; }, {passive: true});
  appBanner.addEventListener('touchmove', (e)=>{ if(y0 !== null && e.touches[0].clientY - y0 < -25){ appBanner.classList.remove('show'); y0 = null; } }, {passive: true});
})();
/* новые сообщения */
checkForNewMessageNotifications = (function(orig){
  return function(chats){
    const before = Object.assign({}, knownChatLastTimestamps);
    const r = orig.call(this, chats);
    if(!state.currentUser) return r;
    const me = state.currentUser.uid;
    (chats || []).forEach(meta=>{
      const prev = before[meta.id];
      if(prev === undefined || !meta.lastTimestamp || meta.lastTimestamp <= prev) return;
      if(meta.lastFrom === me) return;
      if(state.activeChatId === meta.id && !document.hidden) return;         // чат открыт — баннер не нужен
      const muteLevel = (meta.mutedBy && meta.mutedBy[me]) || 'none';
      if(muteLevel === 'all') return;
      const info = chatNotifInfo(meta);
      showAppBanner({
        icon: info.icon, avatar: info.avatar,
        title: info.title,
        sub: info.body,
        btn: 'Открыть',
        onClick: ()=>{ switchTab('chats'); openChat(meta.id); },
      });
      if(!info.avatar && info.uid) loadNotifAvatar(info.uid);
    });
    return r;
  };
})(checkForNewMessageNotifications);
/* лайки, заявки в друзья, смена статуса и фото, истории */
const bannerSeen = new Set();
let bannerReady = false;
setInterval(()=>{
  if(!state.currentUser || typeof allNotifications === 'undefined') return;
  const fresh = allNotifications.filter(n=> !n.read);
  if(!bannerReady){
    if(typeof notifFirstSnapshot !== 'undefined' && notifFirstSnapshot) return;
    fresh.forEach(n=> bannerSeen.add(n.id));
    bannerReady = true;
    return;
  }
  const n = fresh.find(x=> !bannerSeen.has(x.id));
  if(!n) return;
  bannerSeen.add(n.id);
  if(n.type === 'new_story') return;                                          // у историй свой баннер
  const info = notifTypeInfo(n);
  const name = (n.data && n.data.fromName) || '';
  const plain = String(info.text || '').replace(/<[^>]*>/g, '');
  showAppBanner({
    icon: info.icon || '🔔',
    avatar: n.data && n.data.photoUrl && /^data:image|^https?:/.test(n.data.photoUrl) ? n.data.photoUrl : null,
    title: name || 'Уведомление',
    sub: plain.replace(name, '').trim() || plain,
    btn: 'Открыть',
    onClick: ()=>{
      db.collection('notifications').doc(n.id).update({read: true}).catch(()=>{});
      if((n.type === 'story_reply' || n.type === 'story_like') && n.data && n.data.storyId && window.openOwnStoryTab) window.openOwnStoryTab(n.data.storyId, n.type === 'story_reply' ? 'comments' : 'views');
      else if(n.data && n.data.fromUid) openUserInfo(n.data.fromUid);
      else openNotifPanel();
    },
  });
  if(document.hidden) try{ showBrowserNotification(name || 'Уведомление', plain); }catch(e){}
}, 1500);

/* ---------- плеер видео в переписке ---------- */
(function chatVideoPlayer(){
  const box = document.getElementById('messages');
  let current = null;
  function collapse(){
    if(!current) return;
    const v = current.querySelector('video');
    if(v){ try{ v.pause(); }catch(e){} }
    current.classList.remove('playing');
    current = null;
  }
  box.addEventListener('click', (e)=>{
    const wrap = e.target.closest('.mv-wrap');
    if(!wrap){ collapse(); return; }
    const v = wrap.querySelector('video');
    const btn = e.target.closest('[data-mv]');
    const act = btn && btn.dataset.mv;
    e.stopPropagation();
    if(act === 'full'){
      haptic('buttons', 8);
      v.controls = true;
      const req = v.requestFullscreen || v.webkitEnterFullscreen || v.webkitRequestFullscreen;
      if(req) try{ req.call(v); }catch(err){}
      v.play().catch(()=>{});
      const off = ()=>{ if(!document.fullscreenElement){ v.controls = false; document.removeEventListener('fullscreenchange', off); } };
      document.addEventListener('fullscreenchange', off);
      return;
    }
    if(act === 'dl'){
      haptic('buttons', 8);
      const a = document.createElement('a');
      a.href = v.src; a.download = 'video_' + Date.now() + '.webm';
      document.body.appendChild(a); a.click(); a.remove();
      toast('Видео сохраняется в загрузки');
      return;
    }
    if(current && current !== wrap) collapse();
    if(v.paused){
      current = wrap;
      wrap.classList.add('playing');
      msgStickBottom = false;
      v.play().catch(()=>{});
      haptic('buttons', 8);
    }else{
      v.pause();
    }
  }, true);
  // тап в любом другом месте — видео сворачивается
  document.addEventListener('pointerdown', (e)=>{ if(current && !e.target.closest('.mv-wrap')) collapse(); }, true);
  // полоса воспроизведения и возврат к превью в конце
  box.addEventListener('timeupdate', (e)=>{
    const v = e.target;
    if(!v.classList || !v.classList.contains('msg-video')) return;
    const wrap = v.closest('.mv-wrap');
    const bar = wrap && wrap.querySelector('.mv-bar i');
    if(bar && isFinite(v.duration) && v.duration > 0) bar.style.width = (v.currentTime / v.duration * 100) + '%';
  }, true);
  box.addEventListener('ended', (e)=>{
    const v = e.target;
    if(!v.classList || !v.classList.contains('msg-video')) return;
    const wrap = v.closest('.mv-wrap');
    if(wrap){ wrap.classList.remove('playing'); const bar = wrap.querySelector('.mv-bar i'); if(bar) bar.style.width = '0'; }
    v.currentTime = 0;
    if(current === wrap) current = null;
  }, true);
})();

/* ============================================================
   ROUND 25 — имена в пересылке, свёрнутая тактильная отдача,
   общий офлайн-список, одна анимация плеера
============================================================ */
/* ---------- имя и фамилия вместо ника в окнах «Переслать» и «Поделиться» ---------- */
function humanNameFor(uid, fallback){
  const alias = state.contactAliasMap && state.contactAliasMap[uid];
  if(alias) return alias;
  const p = (typeof storyState !== 'undefined' && storyState.profiles && storyState.profiles[uid]) || null;
  if(p){
    const full = [p.firstName, p.lastName].filter(Boolean).join(' ').trim();
    if(full) return full;
    if(p.username) return p.username;
  }
  const c = (state.contacts || []).find(x=> x.uid === uid);
  if(c){
    const full = [c.firstName, c.lastName].filter(Boolean).join(' ').trim();
    if(full) return full;
  }
  return fallback || 'Пользователь';
}
renderSharePickerList = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    const list = document.getElementById('share-contact-list');
    if(!list) return r;
    const uids = [];
    list.querySelectorAll('.chat-item[data-chat-id]').forEach(row=>{
      const av = row.querySelector('.avatar[data-avatar-uid]');
      const uid = av && av.dataset.avatarUid;
      if(!uid) return;
      uids.push(uid);
      const nameEl = row.querySelector('.name');
      const nice = humanNameFor(uid, nameEl ? nameEl.textContent : '');
      if(nameEl && nice) nameEl.textContent = nice;
      if(av && !av.querySelector('img')) av.textContent = initials(nice);
    });
    // подтягиваем профили, которых ещё нет, и обновляем подписи
    const missing = uids.filter(u=> !(storyState.profiles && storyState.profiles[u]));
    if(missing.length){
      Promise.all(missing.map(u=> storyLoadProfile(u))).then(()=>{
        list.querySelectorAll('.chat-item[data-chat-id]').forEach(row=>{
          const av = row.querySelector('.avatar[data-avatar-uid]');
          const uid = av && av.dataset.avatarUid;
          const nameEl = row.querySelector('.name');
          if(uid && nameEl) nameEl.textContent = humanNameFor(uid, nameEl.textContent);
        });
      });
    }
    return r;
  };
})(renderSharePickerList);

/* ---------- раздел «Тактильная отдача» сворачивается ---------- */
buildHapticSettings = (function(orig){
  return function(...a){
    const existed = !!document.getElementById('haptic-card');
    const r = orig.apply(this, a);
    const card = document.getElementById('haptic-card');
    if(!card || existed) return r;
    const head = card.querySelector('.settings-row');
    head.classList.add('head');
    const main = head.querySelector('.settings-row-main');
    if(main && !head.querySelector('.chev')){
      const chev = document.createElement('span');
      chev.className = 'chev';
      chev.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" style="width:20px;height:20px;"><polyline points="6 9 12 15 18 9"/></svg>';
      head.insertBefore(chev, head.querySelector('.toggle-switch'));
    }
    head.addEventListener('click', (e)=>{
      if(e.target.closest('.toggle-switch')) return;      // сам выключатель не сворачивает
      card.classList.toggle('open');
      haptic('buttons', 8);
    });
    return r;
  };
})(buildHapticSettings);

/* ---------- скачанное и файлы устройства играют одним списком ---------- */
function offlineTracks(){
  const seen = new Set();
  const out = [];
  [...(music.downloads || []), ...(music.local || [])].forEach(t=>{
    const k = trackKey(t);
    if(seen.has(k)) return;
    seen.add(k);
    out.push(t);
  });
  return out;
}

/* ============================================================
   ROUND 26 — свайпы у баннера, тумблер, кадры и текст в историях,
   выбор участка трека с прослушкой
============================================================ */
/* ---------- баннер: смахивание в стороны и выключатель ---------- */
let bannersOn = (()=>{ try{ return localStorage.getItem('bannersOff') !== '1'; }catch(e){ return true; } })();
showAppBanner = (function(orig){ return function(...a){ if(!bannersOn) return; return orig.apply(this, a); }; })(showAppBanner);
showStoryBanner = (function(orig){ return function(...a){ if(!bannersOn) return; return orig.apply(this, a); }; })(showStoryBanner);
(function bannerSwipes(){
  [document.getElementById('app-banner'), document.getElementById('story-banner')].forEach(el=>{
    if(!el) return;
    let x0 = null, y0 = null, dx = 0;
    el.addEventListener('touchstart', (e)=>{ x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; dx = 0; el.classList.add('dragging'); }, {passive: true});
    el.addEventListener('touchmove', (e)=>{
      if(x0 === null) return;
      dx = e.touches[0].clientX - x0;
      const dy = e.touches[0].clientY - y0;
      if(dy < -25 && Math.abs(dy) > Math.abs(dx)){ el.classList.remove('show', 'dragging'); x0 = null; return; }
      el.style.transform = `translate(calc(-50% + ${dx}px), 0) rotate(${dx / 60}deg)`;
      el.style.opacity = String(Math.max(0, 1 - Math.abs(dx) / 220));
    }, {passive: true});
    el.addEventListener('touchend', ()=>{
      if(x0 === null) return;
      x0 = null;
      el.classList.remove('dragging');
      if(Math.abs(dx) > 70){
        el.style.transform = `translate(calc(-50% + ${dx > 0 ? 500 : -500}px), 0)`;
        el.style.opacity = '0';
        setTimeout(()=>{ el.classList.remove('show'); el.style.transform = ''; el.style.opacity = ''; }, 220);
        haptic('buttons', 8);
      }else{ el.style.transform = ''; el.style.opacity = ''; }
    });
  });
})();
function buildBannerSetting(tries){
  if(document.getElementById('banner-enabled-switch')) return;
  const sw = document.getElementById('notif-enabled-switch');
  const row = sw && sw.closest('.settings-row');
  if(!row){
    if((tries || 0) < 6){ setTimeout(()=> buildBannerSetting((tries || 0) + 1), 500); return; }
    const body = document.getElementById('settings-body');       // настройки ещё не готовы — ставим отдельной карточкой
    if(!body) return;
    const card = document.createElement('div');
    card.className = 'settings-card';
    body.insertBefore(card, body.firstChild);
    card.innerHTML = `<div class="settings-row"><div class="settings-row-main"><div class="settings-row-title">🔔 Всплывающие уведомления</div>
      <div class="settings-row-sub">Баннер сверху о сообщениях, лайках и историях</div></div>
      <label class="toggle-switch"><input type="checkbox" id="banner-enabled-switch" ${bannersOn ? 'checked' : ''}><span class="toggle-slider"></span></label></div>`;
    card.querySelector('#banner-enabled-switch').onchange = (e)=>{
      bannersOn = e.target.checked;
      try{ localStorage.setItem('bannersOff', bannersOn ? '0' : '1'); }catch(err){}
      haptic('buttons', 10);
      toast(bannersOn ? 'Всплывающие уведомления включены' : 'Всплывающие уведомления выключены');
    };
    return;
  }
  const my = document.createElement('div');
  my.className = 'settings-row';
  my.innerHTML = `<div class="settings-row-main"><div class="settings-row-title">🔔 Всплывающие уведомления</div>
    <div class="settings-row-sub">Баннер сверху о сообщениях, лайках и историях</div></div>
    <label class="toggle-switch"><input type="checkbox" id="banner-enabled-switch" ${bannersOn ? 'checked' : ''}><span class="toggle-slider"></span></label>`;
  row.parentNode.insertBefore(my, row.nextSibling);
  my.querySelector('#banner-enabled-switch').onchange = (e)=>{
    bannersOn = e.target.checked;
    try{ localStorage.setItem('bannersOff', bannersOn ? '0' : '1'); }catch(err){}
    haptic('buttons', 10);
    toast(bannersOn ? 'Всплывающие уведомления включены' : 'Всплывающие уведомления выключены');
  };
}
switchTab = (function(orig){ return function(tab, ...rest){ const r = orig.call(this, tab, ...rest); if(tab === 'settings') setTimeout(()=> buildBannerSetting(0), 80); return r; }; })(switchTab);

/* ---------- редактор историй: кадры и текст ---------- */
storyEditor.frames = [];        // [{kind:'photo'|'video', file, url, texts:[{t,x,y,size,color,boxed}]}]
storyEditor.cur = 0;
const SE_COLORS = ['#ffffff', '#111318', '#FF3B5C', '#FFB300', '#2FB8A8', '#6F8BFF', '#C150D6'];
let seTextSel = null;
function seFrame(){ return storyEditor.frames[storyEditor.cur]; }
function renderFrames(){
  const box = document.getElementById('se-frames');
  if(storyEditor.frames.length < 2){ box.innerHTML = ''; return; }
  box.innerHTML = storyEditor.frames.map((f, i)=> `<div class="se-frame ${i === storyEditor.cur ? 'on' : ''}" data-fi="${i}">
    ${f.kind === 'video' ? `<video src="${f.url}" muted preload="metadata"></video>` : `<img src="${f.url}" alt="">`}
    <span class="x" data-fdel="${i}">✕</span></div>`).join('');
}
document.getElementById('se-frames').onclick = (e)=>{
  const del = e.target.closest('[data-fdel]');
  if(del){
    e.stopPropagation();
    const i = +del.dataset.fdel;
    URL.revokeObjectURL(storyEditor.frames[i].url);
    storyEditor.frames.splice(i, 1);
    storyEditor.cur = Math.max(0, Math.min(storyEditor.cur, storyEditor.frames.length - 1));
    if(!storyEditor.frames.length){ closeStoryEditor(); return; }
    showFrame(storyEditor.cur);
    return;
  }
  const f = e.target.closest('[data-fi]');
  if(f) showFrame(+f.dataset.fi);
};
function showFrame(i){
  storyEditor.cur = i;
  const f = seFrame();
  if(!f) return;
  storyEditor.file = f.file;
  const media = document.getElementById('se-media');
  media.innerHTML = f.kind === 'video' ? `<video src="${f.url}" autoplay loop muted playsinline></video>` : `<img src="${f.url}" alt="">`;
  renderTexts();
  renderFrames();
  haptic('buttons', 6);
}
function renderTexts(){
  const layer = document.getElementById('se-text-layer');
  const f = seFrame();
  layer.innerHTML = '';
  if(!f) return;
  (f.texts || []).forEach((t, i)=>{
    const el = document.createElement('div');
    el.className = 'se-txt' + (t.boxed ? ' boxed' : '');
    el.contentEditable = 'false';
    el.textContent = t.t;
    el.style.left = t.x + '%';
    el.style.top = t.y + '%';
    el.style.transform = 'translate(-50%,-50%)';
    el.style.fontSize = t.size + 'px';
    el.style.color = t.color;
    el.dataset.ti = String(i);
    layer.appendChild(el);
    makeDraggable(el, t);
  });
}
function makeDraggable(el, t){
  let sx = 0, sy = 0, ox = 0, oy = 0, moved = false;
  el.addEventListener('pointerdown', (e)=>{
    e.stopPropagation();
    el.setPointerCapture(e.pointerId);
    sx = e.clientX; sy = e.clientY; ox = t.x; oy = t.y; moved = false;
  });
  el.addEventListener('pointermove', (e)=>{
    if(!el.hasPointerCapture || !el.hasPointerCapture(e.pointerId)) return;
    const box = document.getElementById('se-text-layer').getBoundingClientRect();
    t.x = Math.max(6, Math.min(94, ox + (e.clientX - sx) / box.width * 100));
    t.y = Math.max(6, Math.min(94, oy + (e.clientY - sy) / box.height * 100));
    el.style.left = t.x + '%'; el.style.top = t.y + '%';
    if(Math.abs(e.clientX - sx) > 4 || Math.abs(e.clientY - sy) > 4) moved = true;
  });
  el.addEventListener('pointerup', (e)=>{
    try{ el.releasePointerCapture(e.pointerId); }catch(err){}
    if(!moved) openTextEditor(t, el);
  });
}
function openTextEditor(t, el){
  seTextSel = {t, el};
  el.classList.add('editing');
  el.contentEditable = 'true';
  el.focus();
  const ed = document.getElementById('se-text-editor');
  const colors = document.getElementById('se-te-colors');
  colors.innerHTML = SE_COLORS.map(c=> `<button type="button" data-c="${c}" class="${c === t.color ? 'on' : ''}" style="background:${c}"></button>`).join('')
    + `<button type="button" data-box="1" class="${t.boxed ? 'on' : ''}" style="background:rgba(255,255,255,.25);color:#fff;font-weight:800;">A</button>`;
  document.getElementById('se-te-size').value = t.size;
  ed.style.display = 'flex';
  document.getElementById('se-tools').style.display = 'none';
}
function closeTextEditor(){
  if(seTextSel){
    seTextSel.t.t = seTextSel.el.textContent.trim();
    seTextSel.el.classList.remove('editing');
    seTextSel.el.contentEditable = 'false';
    const f = seFrame();
    if(f && !seTextSel.t.t) f.texts = f.texts.filter(x=> x !== seTextSel.t);
    seTextSel = null;
    renderTexts();
  }
  document.getElementById('se-text-editor').style.display = 'none';
  document.getElementById('se-tools').style.display = '';
}
