/* впечатываем текст в фото перед публикацией */
async function renderFrameToDataUrl(frame){
  if(!frame.texts || !frame.texts.length) return null;
  const img = new Image();
  img.src = frame.url;
  await new Promise(r=>{ if(img.complete) r(); else { img.onload = r; img.onerror = r; } });
  const w = Math.min(1280, img.naturalWidth || 1080);
  const k = w / (img.naturalWidth || w);
  const h = Math.round((img.naturalHeight || 1920) * k);
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  ctx.drawImage(img, 0, 0, w, h);
  const layer = document.getElementById('se-text-layer').getBoundingClientRect();
  const scale = w / Math.max(1, layer.width);
  frame.texts.forEach(t=>{
    const size = Math.round(t.size * scale);
    ctx.font = `800 ${size}px system-ui, -apple-system, "Segoe UI", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const x = w * t.x / 100, y = h * t.y / 100;
    const tw = ctx.measureText(t.t).width;
    if(t.boxed){
      ctx.fillStyle = 'rgba(0,0,0,.45)';
      const padX = size * 0.4, padY = size * 0.25;
      const rx = x - tw / 2 - padX, ry = y - size / 2 - padY, rw = tw + padX * 2, rh = size + padY * 2, r = size * 0.35;
      ctx.beginPath();
      ctx.moveTo(rx + r, ry); ctx.arcTo(rx + rw, ry, rx + rw, ry + rh, r); ctx.arcTo(rx + rw, ry + rh, rx, ry + rh, r);
      ctx.arcTo(rx, ry + rh, rx, ry, r); ctx.arcTo(rx, ry, rx + rw, ry, r); ctx.fill();
    }else{
      ctx.shadowColor = 'rgba(0,0,0,.5)'; ctx.shadowBlur = size * 0.35; ctx.shadowOffsetY = size * 0.06;
    }
    ctx.fillStyle = t.color;
    ctx.fillText(t.t, x, y);
    ctx.shadowBlur = 0;
  });
  return c.toDataURL('image/jpeg', 0.85);
}
/* публикация: сначала текущий кадр, затем остальные */
document.getElementById('se-publish').addEventListener('click', ()=>{ closeTextEditor(); }, true);

