/* ============================================================
   ROUND 29 — регистрация устройства для push-уведомлений
============================================================ */
let pushMessaging = null;
let pushToken = null;
async function loadMessagingSdk(){
  if(window.firebase && firebase.messaging) return true;
  return new Promise((res)=>{
    const sc = document.createElement('script');
    sc.src = 'https://www.gstatic.com/firebasejs/10.12.2/firebase-messaging-compat.js';
    sc.onload = ()=> res(true);
    sc.onerror = ()=> res(false);
    document.head.appendChild(sc);
  });
}
async function registerPushToken(interactive){
  try{
    const key = (state.appConfig && state.appConfig.vapidKey) || '';
    if(!key) return {ok: false, error: 'Не задан ключ Web Push в админ-панели'};
    if(!('serviceWorker' in navigator)) return {ok: false, error: 'Браузер не поддерживает фоновые уведомления'};
    if(Notification.permission !== 'granted'){
      if(!interactive) return {ok: false, error: 'Нет разрешения на уведомления'};
      const perm = await Notification.requestPermission();
      if(perm !== 'granted') return {ok: false, error: 'Вы не разрешили уведомления'};
    }
    if(!(await loadMessagingSdk())) return {ok: false, error: 'Не удалось загрузить модуль уведомлений'};
    // отдельный обработчик для фона: конфиг передаём параметрами, он его не знает
    const q = new URLSearchParams({
      apiKey: firebaseConfig.apiKey || '', projectId: firebaseConfig.projectId || '',
      appId: firebaseConfig.appId || '', senderId: firebaseConfig.messagingSenderId || '',
    }).toString();
    const reg = await navigator.serviceWorker.register('./firebase-messaging-sw.js?' + q);
    await navigator.serviceWorker.ready;
    pushMessaging = pushMessaging || firebase.messaging();
    const token = await pushMessaging.getToken({vapidKey: key, serviceWorkerRegistration: reg});
    if(!token) return {ok: false, error: 'Токен не выдан — проверьте ключ Web Push'};
    pushToken = token;
    await db.collection('users').doc(state.currentUser.uid).update({
      fcmTokens: firebase.firestore.FieldValue.arrayUnion(token),
    });
    // сообщения, пришедшие при открытом приложении, показываем своими баннерами
    try{ pushMessaging.onMessage(()=>{}); }catch(e){}
    return {ok: true, token};
  }catch(e){
    console.error('push', e);
    const msg = String(e && (e.message || e.code) || e);
    return {ok: false, error: /permission|denied/i.test(msg) ? 'Уведомления запрещены в настройках браузера'
      : /applicationServerKey|vapid/i.test(msg) ? 'Неверный ключ Web Push'
      : /rules|permission-denied/i.test(msg) ? 'Нет доступа к профилю — обновите правила Firestore (поле fcmTokens)'
      : 'Не удалось зарегистрировать устройство: ' + msg};
  }
}
/* тихая попытка при входе — если ключ задан и разрешение уже есть */
let pushTried = false;
setInterval(()=>{
  if(pushTried || !state.currentUser || !state.appConfig || !state.appConfig.vapidKey) return;
  if(Notification.permission !== 'granted') return;
  pushTried = true;
  registerPushToken(false);
}, 3000);
/* при выходе убираем токен этого устройства */
if(typeof logout === 'function'){
  logout = (function(orig){
    return async function(...a){
      try{
        if(pushToken && state.currentUser) await db.collection('users').doc(state.currentUser.uid)
          .update({fcmTokens: firebase.firestore.FieldValue.arrayRemove(pushToken)});
      }catch(e){}
      return orig.apply(this, a);
    };
  })(logout);
}

/* ============================================================
   ROUND 30 — просим сервер отправить push (вариант с Worker)
============================================================ */
async function askPush(path, payload){
  try{
    const base = (typeof aiEndpoint === 'function') ? aiEndpoint() : '';
    if(!base || !state.currentUser) return;
    const token = await firebase.auth().currentUser.getIdToken();
    const ctl = new AbortController();
    setTimeout(()=> ctl.abort(), 12000);
    await fetch(base.replace(/\/+$/, '') + path, {
      method: 'POST', signal: ctl.signal,
      headers: {'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token},
      body: JSON.stringify(payload),
    });
  }catch(e){}                                   // push — дело фоновое, ошибки не мешают работе
}
sendMessage = (function(orig){
  return async function(chatId, type, content, fileName, extra){
    const r = await orig.call(this, chatId, type, content, fileName, extra);
    const preview = type === 'text' ? String(content || '').slice(0, 120) : '';
    askPush('/push/message', {chatId, type, preview});     // ROUND 87: запись теперь параллельная — пуш уходит раньше
    return r;
  };
})(sendMessage);
pushNotification = (function(orig){
  return async function(toUid, type, data){
    const r = await orig.call(this, toUid, type, data);
    askPush('/push/notify', {toUid, type, fromName: (data && data.fromName) || ''});
    return r;
  };
})(pushNotification);
if(typeof startCall === 'function'){
  startCall = (function(orig){
    return async function(...a){
      const r = await orig.apply(this, a);
      if(state.activeChatId) setTimeout(()=> askPush('/push/call', {chatId: state.activeChatId}), 600);
      return r;
    };
  })(startCall);
}

/* ============================================================
   ROUND 31 — отступ сверху, масштаб приложения, размеры виджета музыки
============================================================ */
const uiPrefs = (()=>{
  const def = {topInset: null, uiZoom: 100, miWidth: 200, miScale: 100};
  try{ return Object.assign(def, JSON.parse(localStorage.getItem('uiPrefs') || '{}')); }catch(e){ return def; }
})();
function isPackagedApp(){
  try{
    return window.matchMedia('(display-mode: standalone)').matches
      || window.navigator.standalone === true
      || /wv\)|; wv|Median|GoNative|WebViewApp/i.test(navigator.userAgent);
  }catch(e){ return false; }
}
function applyUiPrefs(){
  const root = document.documentElement;
  const top = uiPrefs.topInset === null ? (isPackagedApp() ? 26 : 0) : uiPrefs.topInset;
  root.style.setProperty('--top-inset', top + 'px');
  root.style.setProperty('--ui-zoom', (uiPrefs.uiZoom || 100) / 100);
  root.style.setProperty('--mi-w-user', (uiPrefs.miWidth || 200) + 'px');
  root.style.setProperty('--mi-scale', (uiPrefs.miScale || 100) / 100);
  document.body.classList.toggle('app-zoom', (uiPrefs.uiZoom || 100) !== 100);
  if(typeof placeIsland === 'function') placeIsland();
}
function saveUiPrefs(){ try{ localStorage.setItem('uiPrefs', JSON.stringify(uiPrefs)); }catch(e){} applyUiPrefs(); }
applyUiPrefs();
