switchTab = (function(orig){ return function(tab, ...rest){ const r = orig.call(this, tab, ...rest); if(tab === 'settings') setTimeout(buildScaleSettings, 120); return r; }; })(switchTab);

/* ============================================================
   ROUND 32 — скачивание файлов, фоновый режим, починка музыки
============================================================ */
/* ---------- надёжное сохранение файла (в APK ссылка download не работает) ---------- */
function saveDataUrl(dataUrl, name){
  try{
    let blob;
    if(/^data:/.test(dataUrl)){
      const [head, b64] = dataUrl.split(',');
      const mime = (head.match(/data:([^;]+)/) || [])[1] || 'application/octet-stream';
      const bin = atob(b64);
      const arr = new Uint8Array(bin.length);
      for(let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      blob = new Blob([arr], {type: mime});
    }else{
      blob = null;
    }
    const url = blob ? URL.createObjectURL(blob) : dataUrl;
    const a = document.createElement('a');
    a.href = url;
    a.download = name || ('file_' + Date.now());
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    a.remove();
    if(blob) setTimeout(()=> URL.revokeObjectURL(url), 20000);
    haptic('buttons', 10);
    toast('Файл сохраняется в загрузки');
  }catch(e){
    try{ window.open(dataUrl, '_blank'); }catch(err){ toast('Не удалось сохранить файл'); }
  }
}
/* кнопка скачивания у файловых сообщений */
