/* рисуем мимоджи и даём менять размер щипком */
renderTexts = (function(orig){
  return function(){
    const r = orig.apply(this, arguments);
    const layer = document.getElementById('se-text-layer');
    const f = seFrame();
    if(!f) return r;
    // текст с выбранным шрифтом и градиентом
    (f.texts || []).forEach((t, i)=>{
      const el = layer.querySelector(`.se-txt[data-ti="${i}"]`);
      if(!el) return;
      el.style.font = fontCss(t.font || 'sys', t.size);
      el.style.fontSize = t.size + 'px';
      if(t.grad){
        const g = SE_GRADS.find(x=> x.id === t.grad);
        if(g){ el.style.background = `linear-gradient(135deg,${g.from},${g.to})`; el.style.webkitBackgroundClip = 'text'; el.style.backgroundClip = 'text'; el.style.color = 'transparent'; }
      }
    });
    (f.stickers || []).forEach((st, i)=>{
      const el = document.createElement('div');
      el.className = 'se-sticker';
      el.textContent = st.e;
      el.style.left = st.x + '%';
      el.style.top = st.y + '%';
      el.style.fontSize = st.size + 'px';
      el.style.transform = 'translate(-50%,-50%)';
      el.dataset.si = String(i);
      layer.appendChild(el);
      makeStickerInteractive(el, st, f);
    });
    return r;
  };
})(renderTexts);
function makeStickerInteractive(el, st, frame){
  const pts = new Map();
  let base = null;
  el.addEventListener('pointerdown', (e)=>{
    e.stopPropagation();
    el.setPointerCapture(e.pointerId);
    pts.set(e.pointerId, {x: e.clientX, y: e.clientY});
    el.classList.add('active');
    if(pts.size === 2){
      const [a, b] = [...pts.values()];
      base = {d: Math.hypot(a.x - b.x, a.y - b.y), size: st.size};
    }
  });
  el.addEventListener('pointermove', (e)=>{
    if(!pts.has(e.pointerId)) return;
    const prev = pts.get(e.pointerId);
    pts.set(e.pointerId, {x: e.clientX, y: e.clientY});
    const box = document.getElementById('se-text-layer').getBoundingClientRect();
    if(pts.size === 2 && base){
      const [a, b] = [...pts.values()];
      const d = Math.hypot(a.x - b.x, a.y - b.y);
      st.size = Math.max(28, Math.min(280, Math.round(base.size * d / base.d)));
      el.style.fontSize = st.size + 'px';
      return;
    }
    st.x = Math.max(4, Math.min(96, st.x + (e.clientX - prev.x) / box.width * 100));
    st.y = Math.max(4, Math.min(96, st.y + (e.clientY - prev.y) / box.height * 100));
    el.style.left = st.x + '%';
    el.style.top = st.y + '%';
  });
  const up = (e)=>{
    pts.delete(e.pointerId);
    if(!pts.size){
      base = null;
      el.classList.remove('active');
    }
  };
  el.addEventListener('pointerup', up);
  el.addEventListener('pointercancel', up);
  el.addEventListener('dblclick', (e)=>{      // двойное нажатие убирает
    e.stopPropagation();
    frame.stickers = frame.stickers.filter(x=> x !== st);
    renderTexts();
    haptic('buttons', 10);
  });
}
/* впекаем фильтр, шрифты, градиенты и мимоджи в фото */
renderFrameToDataUrl = (function(){
  return async function(frame){
    const hasText = frame.texts && frame.texts.length;
    const hasSticker = frame.stickers && frame.stickers.length;
    const hasFilter = frame.filter && frame.filter !== 'none';
    if(!hasText && !hasSticker && !hasFilter) return null;
    const img = new Image();
    img.src = frame.url;
    await new Promise(r=>{ if(img.complete) r(); else { img.onload = r; img.onerror = r; } });
    const w = Math.min(1280, img.naturalWidth || 1080);
    const k = w / (img.naturalWidth || w);
    const h = Math.round((img.naturalHeight || 1920) * k);
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    const ctx = c.getContext('2d');
    if(hasFilter) ctx.filter = filterCss(frame.filter);
    ctx.drawImage(img, 0, 0, w, h);
    ctx.filter = 'none';
    const layer = document.getElementById('se-text-layer').getBoundingClientRect();
    const scale = w / Math.max(1, layer.width);
    (frame.texts || []).forEach(t=>{
      const size = Math.round(t.size * scale);
      ctx.font = fontCss(t.font || 'sys', size);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      const x = w * t.x / 100, y = h * t.y / 100;
      const tw = ctx.measureText(t.t).width;
      if(t.boxed){
        ctx.fillStyle = 'rgba(0,0,0,.45)';
        const padX = size * 0.4, padY = size * 0.25;
        const rx = x - tw / 2 - padX, ry = y - size / 2 - padY, rw = tw + padX * 2, rh = size + padY * 2, rr = size * 0.35;
        ctx.beginPath();
        ctx.moveTo(rx + rr, ry); ctx.arcTo(rx + rw, ry, rx + rw, ry + rh, rr); ctx.arcTo(rx + rw, ry + rh, rx, ry + rh, rr);
        ctx.arcTo(rx, ry + rh, rx, ry, rr); ctx.arcTo(rx, ry, rx + rw, ry, rr); ctx.fill();
      }else{
        ctx.shadowColor = 'rgba(0,0,0,.5)'; ctx.shadowBlur = size * 0.35; ctx.shadowOffsetY = size * 0.06;
      }
      if(t.grad){
        const g = SE_GRADS.find(x=> x.id === t.grad);
        const grad = ctx.createLinearGradient(x - tw / 2, y - size / 2, x + tw / 2, y + size / 2);
        grad.addColorStop(0, g ? g.from : '#fff');
        grad.addColorStop(1, g ? g.to : '#fff');
        ctx.fillStyle = grad;
      }else{
        ctx.fillStyle = t.color;
      }
      ctx.fillText(t.t, x, y);
      ctx.shadowBlur = 0;
    });
    (frame.stickers || []).forEach(st=>{
      const size = Math.round(st.size * scale);
      ctx.font = `${size}px system-ui, "Apple Color Emoji", "Segoe UI Emoji", sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = 'rgba(0,0,0,.35)'; ctx.shadowBlur = size * 0.2; ctx.shadowOffsetY = size * 0.05;
      ctx.fillText(st.e, w * st.x / 100, h * st.y / 100);
      ctx.shadowBlur = 0;
    });
    return c.toDataURL('image/jpeg', 0.85);
  };
})();
/* при добавлении кадра панели сбрасываются */
showFrame = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    const bar = document.getElementById('se-filter-bar');
    if(bar.style.display !== 'none'){ document.getElementById('se-filters').click(); document.getElementById('se-filters').click(); }
    return r;
  };
})(showFrame);

/* ============================================================
   ROUND 41 — поворот и масштаб пальцами, удаление элементов, больше шрифтов
============================================================ */
SE_FONTS.push(
  {id: 'hand', name: 'От руки', css: '700 {S}px "Segoe Script", "Bradley Hand", "Comic Sans MS", cursive'},
  {id: 'tech', name: 'Техно', css: '800 {S}px "Consolas", "SF Mono", ui-monospace, monospace'},
  {id: 'elegant', name: 'Тонкий', css: '300 {S}px "Didot", Georgia, serif'},
  {id: 'bold', name: 'Жирный', css: '900 {S}px system-ui, -apple-system, sans-serif'},
  {id: 'caps', name: 'Капитель', css: '800 {S}px "Trebuchet MS", system-ui, sans-serif'},
);
/* общий обработчик жестов: перетаскивание, щипок и поворот */
function attachGestures(el, obj, frame, kind){
  const pts = new Map();
  let base = null;
  const layer = ()=> document.getElementById('se-text-layer').getBoundingClientRect();
  const paint = ()=>{
    el.style.left = obj.x + '%';
    el.style.top = obj.y + '%';
    el.style.transform = `translate(-50%,-50%) rotate(${obj.rot || 0}deg)`;
    if(kind === 'sticker') el.style.fontSize = obj.size + 'px';
    else { el.style.font = fontCss(obj.font || 'sys', obj.size); el.style.fontSize = obj.size + 'px'; }
    placeDelBtn();
  };
  let del = null;
  function placeDelBtn(){
    if(!del) return;
    const b = el.getBoundingClientRect();
    const p = document.getElementById('story-editor').getBoundingClientRect();
    del.style.left = (b.right - p.left - 12) + 'px';
    del.style.top = (b.top - p.top - 12) + 'px';
  }
  function showDel(){
    if(del) return;
    del = document.createElement('div');
    del.className = 'se-del-btn';
    del.textContent = '✕';
    del.onclick = (e)=>{
      e.stopPropagation();
      if(kind === 'sticker') frame.stickers = frame.stickers.filter(x=> x !== obj);
      else frame.texts = frame.texts.filter(x=> x !== obj);
      hideDel();
      renderTexts();
      haptic('buttons', 12);
      toast(kind === 'sticker' ? 'Мимоджи убран' : 'Текст убран');
    };
    document.getElementById('story-editor').appendChild(del);
    placeDelBtn();
    el.classList.add('active');
  }
  function hideDel(){ if(del){ del.remove(); del = null; } el.classList.remove('active'); }
  el._hideDel = hideDel;
  el.addEventListener('pointerdown', (e)=>{
    e.stopPropagation();
    el.setPointerCapture(e.pointerId);
    pts.set(e.pointerId, {x: e.clientX, y: e.clientY});
    document.querySelectorAll('.se-txt, .se-sticker').forEach(o=>{ if(o !== el && o._hideDel) o._hideDel(); });
    showDel();
    if(pts.size === 2){
      const [a, b] = [...pts.values()];
      base = {d: Math.hypot(a.x - b.x, a.y - b.y), size: obj.size,
              ang: Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI, rot: obj.rot || 0};
      showGestureHint('Двумя пальцами: поворот и размер');
    }
  });
  el.addEventListener('pointermove', (e)=>{
    if(!pts.has(e.pointerId)) return;
    const prev = pts.get(e.pointerId);
    pts.set(e.pointerId, {x: e.clientX, y: e.clientY});
    if(pts.size === 2 && base){
      const [a, b] = [...pts.values()];
      const d = Math.hypot(a.x - b.x, a.y - b.y);
      const ang = Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI;
      obj.size = Math.max(14, Math.min(300, Math.round(base.size * d / base.d)));
      obj.rot = Math.round(base.rot + (ang - base.ang));
      paint();
      return;
    }
    const box = layer();
    obj.x = Math.max(3, Math.min(97, obj.x + (e.clientX - prev.x) / box.width * 100));
    obj.y = Math.max(3, Math.min(97, obj.y + (e.clientY - prev.y) / box.height * 100));
    paint();
  });
  const up = (e)=>{ pts.delete(e.pointerId); if(!pts.size) base = null; };
  el.addEventListener('pointerup', up);
  el.addEventListener('pointercancel', up);
  paint();
}
function showGestureHint(text){
  let h = document.getElementById('se-gesture-hint');
  if(!h){
    h = document.createElement('div');
    h.className = 'se-hint-gesture';
    h.id = 'se-gesture-hint';
    document.getElementById('story-editor').appendChild(h);
  }
  h.textContent = text;
  h.classList.add('on');
  clearTimeout(showGestureHint._t);
  showGestureHint._t = setTimeout(()=> h.classList.remove('on'), 2200);
}
/* применяем жесты к тексту и мимоджи */
renderTexts = (function(orig){
  return function(){
    const r = orig.apply(this, arguments);
    const f = seFrame();
    if(!f) return r;
    document.querySelectorAll('#story-editor .se-del-btn').forEach(x=> x.remove());
    (f.texts || []).forEach((t, i)=>{
      const el = document.querySelector(`#se-text-layer .se-txt[data-ti="${i}"]`);
      if(el) attachGestures(el, t, f, 'text');
    });
    (f.stickers || []).forEach((st, i)=>{
      const el = document.querySelector(`#se-text-layer .se-sticker[data-si="${i}"]`);
      if(el) attachGestures(el, st, f, 'sticker');
    });
    return r;
  };
})(renderTexts);
/* нажатие мимо снимает выделение */
document.getElementById('se-media').addEventListener('pointerdown', ()=>{
  document.querySelectorAll('.se-txt, .se-sticker').forEach(o=>{ if(o._hideDel) o._hideDel(); });
}, true);
/* настройки не теряются при переключении кадров */
showFrame = (function(orig){
  return function(...a){
    const r = orig.apply(this, a);
    renderSeMusic();                                  // карточка трека и фрагмент остаются на месте
    applyFrameFilter();
    return r;
  };
})(showFrame);
/* при впекании учитываем поворот */
renderFrameToDataUrl = (function(orig){
  return async function(frame){
    const rotated = (frame.texts || []).some(t=> t.rot) || (frame.stickers || []).some(s=> s.rot);
    if(!rotated) return orig.call(this, frame);
    const img = new Image();
    img.src = frame.url;
    await new Promise(r=>{ if(img.complete) r(); else { img.onload = r; img.onerror = r; } });
    const w = Math.min(1280, img.naturalWidth || 1080);
    const k = w / (img.naturalWidth || w);
    const h = Math.round((img.naturalHeight || 1920) * k);
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    const ctx = c.getContext('2d');
    if(frame.filter && frame.filter !== 'none') ctx.filter = filterCss(frame.filter);
    ctx.drawImage(img, 0, 0, w, h);
    ctx.filter = 'none';
    const layer = document.getElementById('se-text-layer').getBoundingClientRect();
    const scale = w / Math.max(1, layer.width);
    const draw = (item, isSticker)=>{
      const size = Math.round(item.size * scale);
      ctx.save();
      ctx.translate(w * item.x / 100, h * item.y / 100);
      ctx.rotate((item.rot || 0) * Math.PI / 180);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.shadowColor = 'rgba(0,0,0,.45)';
      ctx.shadowBlur = size * 0.25;
      if(isSticker){
        ctx.font = `${size}px system-ui, "Apple Color Emoji", "Segoe UI Emoji", sans-serif`;
        ctx.fillText(item.e, 0, 0);
      }else{
        ctx.font = fontCss(item.font || 'sys', size);
        const tw = ctx.measureText(item.t).width;
        if(item.boxed){
          ctx.shadowBlur = 0;
          ctx.fillStyle = 'rgba(0,0,0,.45)';
          const padX = size * 0.4, padY = size * 0.25;
          ctx.fillRect(-tw / 2 - padX, -size / 2 - padY, tw + padX * 2, size + padY * 2);
        }
        if(item.grad){
          const g = SE_GRADS.find(x=> x.id === item.grad);
          const grad = ctx.createLinearGradient(-tw / 2, -size / 2, tw / 2, size / 2);
          grad.addColorStop(0, g ? g.from : '#fff');
          grad.addColorStop(1, g ? g.to : '#fff');
          ctx.fillStyle = grad;
        }else ctx.fillStyle = item.color;
        ctx.fillText(item.t, 0, 0);
      }
      ctx.restore();
    };
    (frame.texts || []).forEach(t=> draw(t, false));
    (frame.stickers || []).forEach(st=> draw(st, true));
    return c.toDataURL('image/jpeg', 0.85);
  };
})(renderFrameToDataUrl);

