/* 5. смена ника в настройках профиля */
function buildNickSetting(){
  const body = document.getElementById('profile-body') || document.getElementById('settings-body');
  if(!body || document.getElementById('nick-change-card')) return;
  const card = document.createElement('div');
  card.className = 'settings-card';
  card.id = 'nick-change-card';
  card.innerHTML = `<div class="settings-row"><div class="settings-row-main"><div class="settings-row-title">🔤 Ник</div>
      <div class="settings-row-sub">Латиница, цифры и знак подчёркивания, от 3 до 20 символов</div></div></div>
    <div style="padding:0 14px 14px 14px;">
      <div class="nick-row"><input id="nick-input" value="${escapeHtml((state.currentUser && state.currentUser.username) || '')}" maxlength="20" autocomplete="off">
        <button class="btn-primary" id="nick-save" style="margin:0;padding:0 16px;height:44px;">Сменить</button></div>
      <div id="nick-msg" style="margin-top:8px;"></div>
    </div>`;
  body.insertBefore(card, body.firstChild);
  document.getElementById('nick-save').onclick = async ()=>{
    const out = document.getElementById('nick-msg');
    const val = document.getElementById('nick-input').value.trim().toLowerCase();
    const old = (state.currentUser.username || '').toLowerCase();
    if(val === old){ out.innerHTML = '<div class="info-box">Это ваш текущий ник.</div>'; return; }
    if(!/^[a-z0-9_]{3,20}$/.test(val)){ out.innerHTML = '<div class="error-box">Можно латиницу, цифры и «_», от 3 до 20 символов.</div>'; return; }
    out.innerHTML = '<div class="info-box">Проверяю, свободен ли ник…</div>';
    try{
      const taken = await db.collection('usernames').doc(val).get();
      if(taken.exists){ out.innerHTML = '<div class="error-box">Этот ник уже занят — придумайте другой.</div>'; return; }
      await db.collection('usernames').doc(val).set({uid: state.currentUser.uid});
      await db.collection('users').doc(state.currentUser.uid).update({username: val});
      if(old) await db.collection('usernames').doc(old).delete().catch(()=>{});
      state.currentUser.username = val;
      if(state.profile) state.profile.username = val;
      document.querySelectorAll('.profile-username, #profile-username, [data-profile-username]').forEach(el=> el.textContent = val);
      try{
        const pb = document.getElementById('profile-body');
        if(pb) [...pb.querySelectorAll('*')].forEach(el=>{ if(!el.children.length && el.textContent.trim() === old) el.textContent = val; });
      }catch(e){}
      setTimeout(()=>{ try{ if(typeof renderProfile === 'function') renderProfile(); }catch(e){} }, 800);
      haptic('buttons', [12, 40, 12]);
      out.innerHTML = '<div class="info-box">Готово! Теперь ваш ник @' + escapeHtml(val) + '</div>';
      toast('Ник изменён');
    }catch(e){
      out.innerHTML = '<div class="error-box">' + (/permission/i.test(String(e && (e.code || e.message))) ? 'Нет доступа — обновите правила Firestore (поле username).' : 'Не удалось сменить ник.') + '</div>';
    }
  };
}
