/* ============================================================
   ROUND 45 — перезагрузка тройным нажатием, точка офлайн,
   поворот ползунком, длина видео с камеры, выбор папки
============================================================ */
/* тройное нажатие на логотип — перезапуск приложения */
(function tripleTapReload(){
  let taps = [], t = null;
  document.addEventListener('click', (e)=>{
    if(!e.target.closest('.brand-mark, .app-brand, .tab-title')) return;
    const now = Date.now();
    taps = taps.filter(x=> now - x < 900);
    taps.push(now);
    clearTimeout(t);
    if(taps.length >= 3){
      taps = [];
      haptic('buttons', [16, 50, 16]);
      toast('Перезапускаю приложение…');
      setTimeout(()=> location.reload(), 350);
    }else{
      t = setTimeout(()=> taps = [], 900);
    }
  }, true);
})();
/* красная точка офлайн во вкладке «Общение» */
(function offlineDots(){
  const paint = ()=>{
    const panel = document.getElementById('tab-discovery');
    if(!panel || state.activeTab !== 'discovery') return;
    panel.querySelectorAll('.avatar[data-avatar-uid]').forEach(av=>{
      const uid = av.dataset.avatarUid;
      const p = (typeof storyState !== 'undefined' && storyState.profiles && storyState.profiles[uid]) || null;
      const online = p && p.lastActive && (Date.now() - p.lastActive < 5 * 60000) && p.showOnline !== false;
      if(av.querySelector('.online-dot')) return;
      let dot = av.querySelector('.offline-dot');
      if(online){ if(dot) dot.remove(); return; }
      if(!dot){
        dot = document.createElement('span');
        dot.className = 'offline-dot';
        av.style.position = 'relative';
        av.appendChild(dot);
      }
    });
  };
  setInterval(paint, 2500);
})();
