      ctx.save(); ctx.rotate(i * TAU / 6);
      const g = ctx.createRadialGradient(0, -s * 0.55, s * 0.05, 0, -s * 0.5, s * 0.6);
      g.addColorStop(0, '#fff'); g.addColorStop(0.35, petal[0]); g.addColorStop(1, petal[1]);
