      const g = ctx.createRadialGradient(0, 0, 2, 0, 0, f.u * 0.55); g.addColorStop(0, '#2b2b31'); g.addColorStop(1, '#101014');
      ctx.fillStyle = g; ctx.beginPath(); ctx.ellipse(0, 0, f.u * 0.42, f.u * 0.56, 0, 0, TAU); ctx.fill(); ctx.restore();
